import type { GameState } from '../game/types';
import { t, type MessageKey } from '../i18n';
import { button, el } from './dom';

/**
 * Didacticiel (retour du propriétaire) : un guide pas à pas jusqu'au premier achat, au premier
 * locataire (premier loyer offert) et au premier remboursement. Chaque étape se valide d'elle-même
 * d'après la partie : rien à cocher.
 */
export type TutorialStep = 'clients' | 'visit' | 'commission' | 'buy' | 'lease' | 'repay';

export const TUTORIAL_STEPS: readonly TutorialStep[] = [
  'clients',
  'visit',
  'commission',
  'buy',
  'lease',
  'repay',
];

/** Ce que le joueur a déjà fait, déduit de la partie (et de l'onglet Clients ouvert une fois). */
function done(step: TutorialStep, state: GameState, seenClients: boolean): boolean {
  const owned = state.player.properties.length > 0;
  const leased = Object.values(state.tenancy).some((t) => t.tenant !== null);
  switch (step) {
    case 'clients':
      return seenClients || state.visited.length > 0 || state.ledger.commissions > 0;
    case 'visit':
      return state.visited.length > 0 || state.ledger.commissions > 0;
    case 'commission':
      return state.ledger.commissions > 0 || owned;
    case 'buy':
      return owned;
    case 'lease':
      return leased || state.firstLeaseBonus === true;
    case 'repay':
      return state.player.creditLevel > 0;
  }
}

/** Étape en cours, ou null quand le guide est fini. */
export function currentStep(state: GameState, seenClients: boolean): TutorialStep | null {
  return TUTORIAL_STEPS.find((step) => !done(step, state, seenClients)) ?? null;
}

export interface TutorialActions {
  openClients: () => void;
  openListings: () => void;
  openBank: () => void;
  openProperties: () => void;
  hide: () => void;
}

/** Petite plaque de verre en bas de la carte : l'étape, une explication, un raccourci. */
export function renderTutorial(
  host: HTMLElement,
  step: TutorialStep,
  actions: TutorialActions,
): void {
  const index = TUTORIAL_STEPS.indexOf(step) + 1;
  const head = el('div', 'doc-row');
  head.append(
    el('span', 'ref', t('tuto.ref', { n: index, total: TUTORIAL_STEPS.length })),
    button('tuto-hide', t('tuto.hide'), actions.hide),
  );
  const shortcut: Partial<Record<TutorialStep, [MessageKey, () => void]>> = {
    clients: ['tuto.go.clients', actions.openClients],
    visit: ['tuto.go.listings', actions.openListings],
    commission: ['tuto.go.clients', actions.openClients],
    buy: ['tuto.go.listings', actions.openListings],
    lease: ['tuto.go.properties', actions.openProperties],
    repay: ['tuto.go.bank', actions.openBank],
  };
  const items: HTMLElement[] = [
    head,
    el('b', 'tuto-title', t(`tuto.${step}.title`)),
    el('p', 'tuto-body', t(`tuto.${step}.body`)),
  ];
  const go = shortcut[step];
  if (go) items.push(button('primary tuto-go', t(go[0]), go[1]));
  host.replaceChildren(...items);
}
