import { CALM_MARKET, growth, type Market } from './market';
import { RULES, type EconomyRules } from './rules';
import { bracketTax } from './tax';
import type {
  AccountLoan,
  CreditTerms,
  DayReport,
  Loan,
  Offer,
  OwnedProperty,
  PlayerState,
} from './types';

export function newPlayer(rules: EconomyRules = RULES): PlayerState {
  return { day: 0, cash: rules.startingCash, creditLevel: 0, properties: [], loans: [] };
}

/** Prêts du joueur ; reprend aussi les prêts d'une ancienne sauvegarde, rangés dans les biens. */
export function loansOf(state: PlayerState): AccountLoan[] {
  const legacy: AccountLoan[] = state.properties
    .filter((p) => p.loan)
    .map((p) => ({ ...p.loan!, id: p.id, propertyId: p.id }));
  return [...(state.loans ?? []), ...legacy];
}

/** Range les prêts d'une ancienne sauvegarde sur le compte. */
export function migrateLoans(state: PlayerState): PlayerState {
  if (!state.properties.some((p) => p.loan) && state.loans) return state;
  return {
    ...state,
    loans: loansOf(state),
    properties: state.properties.map((p) => {
      if (!('loan' in p)) return p;
      const { loan: _loan, ...rest } = p;
      void _loan;
      return rest;
    }),
  };
}

/** Conditions de prêt offertes par la banque à un niveau de crédit donné. */
export function creditTerms(level: number, rules: EconomyRules = RULES): CreditTerms {
  const l = Math.max(0, Math.min(rules.loan.maxCreditLevel, Math.floor(level)));
  return {
    downPaymentRate: rules.loan.downPaymentBase - rules.loan.downPaymentPerLevel * l,
    feeRate: rules.loan.feeBase - rules.loan.feePerLevel * l,
    maxLoans: rules.loan.simultaneousBase + Math.floor(l / rules.loan.levelsPerExtraLoan),
  };
}

export function createLoan(price: number, terms: CreditTerms, rules: EconomyRules = RULES): Loan {
  const remaining = price * (1 - terms.downPaymentRate) * (1 + terms.feeRate);
  return {
    remaining,
    dailyPayment: remaining / rules.loan.durationDays,
    daysLeft: rules.loan.durationDays,
  };
}

export function propertyValue(
  p: OwnedProperty,
  day: number,
  market: Market = CALM_MARKET,
  rules: EconomyRules = RULES,
): number {
  return p.baseValue * growth(day - p.buyDay, rules) * market.price;
}

export function propertyRent(
  p: OwnedProperty,
  day: number,
  market: Market = CALM_MARKET,
  rules: EconomyRules = RULES,
): number {
  return p.baseRent * growth(day - p.buyDay, rules) * market.rent;
}

export function portfolioValue(
  state: PlayerState,
  market: Market = CALM_MARKET,
  rules: EconomyRules = RULES,
): number {
  return state.properties.reduce((sum, p) => sum + propertyValue(p, state.day, market, rules), 0);
}

export function totalDebt(state: PlayerState): number {
  return loansOf(state).reduce((sum, l) => sum + l.remaining, 0);
}

export function activeLoans(state: PlayerState): number {
  return loansOf(state).length;
}

/** Patrimoine net : trésorerie + valeur des biens − dettes. */
export function netWorth(
  state: PlayerState,
  market: Market = CALM_MARKET,
  rules: EconomyRules = RULES,
): number {
  return state.cash + portfolioValue(state, market, rules) - totalDebt(state);
}

export type BuyRefusal = 'cash' | 'loans';

export function canBuy(
  state: PlayerState,
  offer: Offer,
  rules: EconomyRules = RULES,
  /** Vrai : achat comptant, sans prêt. */
  cash = false,
): BuyRefusal | null {
  if (cash) return state.cash < offer.price ? 'cash' : null;
  const terms = creditTerms(state.creditLevel, rules);
  if (activeLoans(state) >= terms.maxLoans) return 'loans';
  if (state.cash < offer.price * terms.downPaymentRate) return 'cash';
  return null;
}

/**
 * Achète un bien. Avec un prêt, le joueur paie l'apport et la banque prête le reste ;
 * comptant, il paie tout le prix et ne doit rien à personne.
 */
export function buyProperty(
  state: PlayerState,
  offer: Offer,
  market: Market = CALM_MARKET,
  rules: EconomyRules = RULES,
  cash = false,
): PlayerState {
  const refusal = canBuy(state, offer, rules, cash);
  if (refusal) throw new Error(`Achat refusé : ${refusal}`);
  const terms = creditTerms(state.creditLevel, rules);
  const current = migrateLoans(state);
  const property: OwnedProperty = {
    id: offer.id,
    buyDay: state.day,
    baseValue: (offer.fairValue ?? offer.price) / market.price,
    baseRent: (offer.price * offer.rentRate) / market.rent,
  };
  // Avec un prêt : la banque crédite le compte, la dette reste au joueur quoi qu'il arrive au bien.
  const loans = cash
    ? (current.loans ?? [])
    : [
        ...(current.loans ?? []),
        {
          ...createLoan(offer.price, terms, rules),
          id: `${offer.id}@${state.day}`,
          propertyId: offer.id,
        },
      ];
  return {
    ...current,
    cash: state.cash - (cash ? offer.price : offer.price * terms.downPaymentRate),
    properties: [...current.properties, property],
    loans,
  };
}

function raiseCredit(level: number, rules: EconomyRules): number {
  return Math.min(rules.loan.maxCreditLevel, level + 1);
}

/** Retrouve un prêt par son identifiant, ou par le bien qu'il a servi à acheter. */
export function findLoan(state: PlayerState, idOrProperty: string): AccountLoan | undefined {
  const loans = loansOf(state);
  return (
    loans.find((l) => l.id === idOrProperty) ?? loans.find((l) => l.propertyId === idOrProperty)
  );
}

/** Rembourse d'un coup le reste d'un prêt. Fait monter la note de crédit. */
export function repayLoanEarly(
  state: PlayerState,
  loanId: string,
  rules: EconomyRules = RULES,
): PlayerState {
  const current = migrateLoans(state);
  const loan = findLoan(current, loanId);
  if (!loan) throw new Error('Aucun prêt en cours');
  if (current.cash < loan.remaining) throw new Error('Trésorerie insuffisante');
  return {
    ...current,
    cash: current.cash - loan.remaining,
    creditLevel: raiseCredit(current.creditLevel, rules),
    loans: (current.loans ?? []).filter((l) => l.id !== loan.id),
  };
}

/** Ajoute une somme à la trésorerie (commission, prime). */
export function addCash(state: PlayerState, amount: number): PlayerState {
  return { ...state, cash: state.cash + amount };
}

/** Vend un bien : le joueur touche sa valeur du jour moins ce qu'il doit encore. */
export function sellProperty(
  state: PlayerState,
  propertyId: string,
  market: Market = CALM_MARKET,
  rules: EconomyRules = RULES,
): PlayerState {
  const property = state.properties.find((p) => p.id === propertyId);
  if (!property) throw new Error('Bien introuvable');
  // Le prêt reste sur le compte : la vente rapporte toute la valeur du bien.
  const current = migrateLoans(state);
  return {
    ...current,
    cash: current.cash + propertyValue(property, state.day, market, rules),
    properties: current.properties.filter((p) => p.id !== propertyId),
  };
}

export interface DayInputs {
  /** Commissions de chasse touchées dans la journée. */
  commissions?: number;
  /** Multiplicateur des loyers dû aux incidents (1 = aucun incident). */
  rentModifier?: number;
  /** Multiplicateur propre à certains biens (clé = identifiant) : 0 = bien fermé. */
  rentModifiers?: Record<string, number>;
  market?: Market;
}

/**
 * Fait passer une journée : commissions, loyers, charges, agence, mensualités, impôts,
 * puis saisies si la trésorerie est négative. Fonction pure : l'état reçu n'est pas modifié.
 */
export function advanceDay(
  state: PlayerState,
  inputs: DayInputs = {},
  rules: EconomyRules = RULES,
): { state: PlayerState; report: DayReport } {
  const start = migrateLoans(state);
  const day = state.day + 1;
  const market = inputs.market ?? CALM_MARKET;
  const commissions = inputs.commissions ?? 0;
  const rentModifier = inputs.rentModifier ?? 1;

  let rent = 0;
  let value = 0;
  let loanPayments = 0;
  let creditLevel = state.creditLevel;
  const loansRepaid: string[] = [];
  let properties = start.properties;
  for (const p of properties) {
    rent +=
      propertyRent(p, day, market, rules) * rentModifier * (inputs.rentModifiers?.[p.id] ?? 1);
    value += propertyValue(p, day, market, rules);
  }
  const loans: AccountLoan[] = [];
  for (const loan of start.loans ?? []) {
    loanPayments += loan.dailyPayment;
    const daysLeft = loan.daysLeft - 1;
    if (daysLeft <= 0) {
      loansRepaid.push(loan.propertyId ?? loan.id);
      creditLevel = raiseCredit(creditLevel, rules);
      continue;
    }
    loans.push({ ...loan, daysLeft, remaining: loan.remaining - loan.dailyPayment });
  }

  const charges = rent * rules.chargesRate;
  const agency = properties.length >= rules.agencyFromProperties ? rent * rules.agencyRate : 0;
  const netRent = rent - charges - agency;
  const incomeTax = bracketTax(Math.max(0, netRent), rules.incomeTax);
  const wealthTax = bracketTax(value, rules.wealthTax);
  const net = commissions + netRent - incomeTax - wealthTax - loanPayments;
  let cash = state.cash + net;

  // Impayé : la banque patiente quelques jours (relances), puis saisit les biens, du plus récent
  // au plus ancien, et les revend : la vente couvre le découvert. Les prêts, eux, restent sur le
  // compte (décision du propriétaire : le prêt ne « colle » pas à la maison).
  const seized: string[] = [];
  let overdueDays = cash < 0 ? (state.overdueDays ?? 0) + 1 : 0;
  if (cash < 0 && overdueDays > rules.seizureGraceDays) {
    while (cash < 0 && properties.length > 0) {
      const target = properties[properties.length - 1]!;
      cash += propertyValue(target, day, market, rules) * rules.seizureRecovery;
      creditLevel = Math.max(0, creditLevel - rules.loan.defaultPenaltyLevels);
      properties = properties.filter((p) => p.id !== target.id);
      seized.push(target.id);
    }
    if (cash >= 0) overdueDays = 0;
  }

  return {
    state: { day, cash, creditLevel, properties, loans, overdueDays },
    report: {
      day,
      commissions,
      rent,
      charges,
      agency,
      incomeTax,
      wealthTax,
      loanPayments,
      net,
      loansRepaid,
      seized,
      overdueDays,
    },
  };
}
