import type { City } from '../city/model';
import {
  auctionTick,
  clockDay,
  createGame,
  DEFAULT_MS_PER_DAY,
  finishVisit,
  nextDay,
  withDefaults,
} from './game';
import { seedRivals } from './dirty';
import { settleTravel } from './travel';
import type { GameState } from './types';

const SAVE_KEY = 'main-basse-save-v1';
const MAX_CATCH_UP_DAYS = 30;

export type Listener = (state: GameState, previous: GameState) => void;

function load(): GameState | null {
  try {
    const raw = localStorage.getItem(SAVE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as GameState;
    return parsed.version === 1 ? withDefaults(parsed) : null;
  } catch {
    return null;
  }
}

/** État vivant de la partie : horloge, sauvegarde locale et abonnés. */
export class GameStore {
  state: GameState;
  private readonly listeners = new Set<Listener>();
  private timer = 0;

  constructor(
    readonly city: City,
    private readonly seed: number,
    private readonly msPerDay: number = DEFAULT_MS_PER_DAY,
  ) {
    // Une sauvegarde d'avant les coups bas n'a pas de concurrents : on les lui attribue.
    this.state = seedRivals(load() ?? createGame(city, seed, Date.now(), msPerDay), city);
    if (this.state.clock.msPerDay !== msPerDay) this.rebaseClock(Date.now());
  }

  subscribe(listener: Listener): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  update(change: (state: GameState) => GameState): void {
    const previous = this.state;
    const next = change(previous);
    if (next === previous) return;
    this.state = next;
    this.save();
    this.listeners.forEach((fn) => fn(next, previous));
  }

  start(): void {
    this.tick();
    this.timer = window.setInterval(() => this.tick(), 250);
  }

  stop(): void {
    window.clearInterval(this.timer);
  }

  reset(): void {
    this.update(() => createGame(this.city, this.seed, Date.now(), this.msPerDay));
  }

  /** Avancement dans le jour en cours, de 0 à 1. */
  dayProgress(nowMs: number = Date.now()): number {
    const { startMs, msPerDay } = this.state.clock;
    const elapsed = Math.max(0, nowMs - startMs);
    return (elapsed % msPerDay) / msPerDay;
  }

  private tick(): void {
    const now = Date.now();
    this.update((state) => auctionTick(finishVisit(settleTravel(state, now), now), this.city, now));
    let due = clockDay(this.state, now) - this.state.player.day;
    if (due > MAX_CATCH_UP_DAYS) {
      // Longue absence : on rattrape un mois au plus, puis l'horloge repart d'ici.
      due = MAX_CATCH_UP_DAYS;
      this.update((state) => {
        let next = state;
        for (let i = 0; i < due; i++) next = nextDay(next, this.city);
        return next;
      });
      this.rebaseClock(now);
      return;
    }
    if (due > 0) {
      this.update((state) => {
        let next = state;
        for (let i = 0; i < due; i++) next = nextDay(next, this.city);
        return next;
      });
    }
  }

  /** Recale l'horloge pour que le jour en cours commence maintenant. */
  private rebaseClock(nowMs: number): void {
    this.update((state) => ({
      ...state,
      clock: { startMs: nowMs - state.player.day * this.msPerDay, msPerDay: this.msPerDay },
    }));
  }

  private save(): void {
    try {
      localStorage.setItem(SAVE_KEY, JSON.stringify(this.state));
    } catch {
      // Sauvegarde impossible (stockage bloqué) : la partie continue sans être mémorisée.
    }
  }
}
