import { districtDef } from '../city/data/layout';
import type { Building, City } from '../city/model';
import type { Rng } from '../city/gen/rng';
import { roll } from './facts';
import type { DirtyKind, Effect, GameState, Incident, Letter, LetterKind, Rival } from './types';
import { addMessage } from './messages';

/** Règles des coups bas. Chaque attaque a un coût, un effet, un risque et une parade. */
export const DIRTY: Record<
  DirtyKind,
  {
    /** Coût fixe (complices, avocat, discrétion). */
    baseCost: number;
    /** Le coût s'ajoute de ce multiple du loyer que la cible perd : on paie toujours plus qu'on ne détruit. */
    damageMultiple: number;
    /** Probabilité de base de laisser des preuves. */
    evidence: number;
    /** Durée de l'effet, en jours. */
    days: number;
    /** Part du loyer conservée pendant l'effet (0 = bien fermé). */
    rentFactor: number;
    /** Pression ajoutée sur le bien visé. */
    pressure: number;
  }
> = {
  review: {
    baseCost: 15_000,
    damageMultiple: 2,
    evidence: 0.3,
    days: 3,
    rentFactor: 0.7,
    pressure: 1,
  },
  inspection: {
    baseCost: 40_000,
    damageMultiple: 2,
    evidence: 0.45,
    days: 2,
    rentFactor: 0,
    pressure: 2,
  },
  // Débaucher le locataire : on lui fait une offre ailleurs. Parade : un locataire satisfait reste.
  poach: {
    baseCost: 20_000,
    damageMultiple: 2,
    evidence: 0.25,
    days: 5,
    rentFactor: 0,
    pressure: 1,
  },
  // Rumeur dans la Gazette. Parade : un démenti publié.
  rumor: {
    baseCost: 10_000,
    damageMultiple: 2,
    evidence: 0.2,
    days: 6,
    rentFactor: 0.85,
    pressure: 2,
  },
};

export const DIRTY_KINDS: readonly DirtyKind[] = ['review', 'inspection', 'poach', 'rumor'];
/** Un locataire au moins aussi satisfait refuse l'offre d'un concurrent. */
export const POACH_RESIST = 70;
/** Prix d'un démenti dans la Gazette. */
export const DENIAL_COST = 5_000;

/** Loyer que la cible perd à cause du coup bas. */
export function dirtyDamage(kind: DirtyKind, dailyRent: number): number {
  const rule = DIRTY[kind];
  return Math.round(dailyRent * (1 - rule.rentFactor) * rule.days);
}

/** Ce qu'il faut savoir du bien visé pour chiffrer un coup bas. */
export interface DirtyTarget {
  /** Loyer quotidien. */
  rent: number;
  /** Prix demandé. */
  value: number;
}

/**
 * Prix du coup bas : un fixe, deux fois le loyer que la cible perd, et une part de la valeur du bien
 * par point de pression. Ainsi, pousser un concurrent à brader coûte plus que le rabais obtenu.
 */
export function dirtyCost(kind: DirtyKind, target: DirtyTarget): number {
  const rule = DIRTY[kind];
  return Math.round(
    rule.baseCost +
      rule.damageMultiple * dirtyDamage(kind, target.rent) +
      VALUE_SHARE_PER_PRESSURE * rule.pressure * target.value,
  );
}

/** Amende si le joueur est pris. */
export function dirtyFine(cost: number): number {
  return cost * FINE_MULTIPLE + FINE_BASE;
}

export const IMMUNITY_DAYS = 3;
export const COMPLAINT_COST = 3000;
export const CAMERA_COST = 5000;
/** Les caméras augmentent les chances de confondre un attaquant, et le découragent. */
export const CAMERA_EVIDENCE_BONUS = 0.3;
export const FORCED_SALE_PRESSURE = 3;
export const FORCED_SALE_DISCOUNT = 0.25;
/** Part de la valeur du bien payée par point de pression : 3 points coûtent 30 %, plus que le rabais. */
const VALUE_SHARE_PER_PRESSURE = 0.1;
export const SUSPICION_PER_COUP = 25;
export const SUSPICION_WHEN_CAUGHT = 40;
export const SUSPICION_DECAY_PER_DAY = 3;
/** Au-delà de ce soupçon, la banque ne prête plus. */
export const SUSPICION_LOAN_BLOCK = 60;
/** Niveaux de note de crédit perdus à chaque condamnation. */
export const CREDIT_LOST_WHEN_CAUGHT = 2;
const FINE_MULTIPLE = 3;
const FINE_BASE = 25_000;
const DAMAGES_BASE = 5000;
const RIVAL_NAMES = [
  'Foncière du Levant',
  'Cabinet Vauquelin',
  'Groupe Horizon',
  'Maison Delorme',
  'Consortium Atlas',
] as const;
const BUILDINGS_PER_RIVAL = 9;
const MAX_INCIDENTS = 12;

type LetterAdder = (state: GameState, kind: LetterKind, params?: Letter['params']) => GameState;

/** Répartit des biens entre les concurrents, de façon stable pour une graine donnée. */
export function seedRivals(state: GameState, city: City): GameState {
  if (state.rivals.length > 0) return state;
  const taken = new Set<number>([
    ...state.listings,
    ...state.player.properties.map((p) => Number(p.id)),
  ]);
  // La Résidence Premier Pas est réservée aux nouveaux joueurs : aucun concurrent n'y possède rien.
  const candidates = city.buildings
    .filter((b) => !taken.has(b.id) && b.district !== 'premierpas')
    .map((b) => ({ id: b.id, order: roll(state.seed, b.id, 77) }))
    .sort((a, b) => a.order - b.order)
    .map((entry) => entry.id);
  const rivals: Rival[] = RIVAL_NAMES.map((name, index) => ({
    id: index + 1,
    name,
    buildings: candidates.slice(index * BUILDINGS_PER_RIVAL, (index + 1) * BUILDINGS_PER_RIVAL),
  }));
  return { ...state, rivals };
}

export function rivalOf(state: GameState, buildingId: number): Rival | undefined {
  return state.rivals.find((r) => r.buildings.includes(buildingId));
}

export function activeEffect(
  state: GameState,
  buildingId: number,
  day: number,
): Effect | undefined {
  return state.effects.find((e) => e.buildingId === buildingId && e.untilDay >= day);
}

export function hasCamera(state: GameState, buildingId: number): boolean {
  return state.cameras.includes(buildingId);
}

export function pressureOn(state: GameState, buildingId: number): number {
  return state.pressure[String(buildingId)] ?? 0;
}

export function isImmune(state: GameState): boolean {
  return state.player.day <= IMMUNITY_DAYS;
}

/** Risque de se faire prendre en commettant ce coup bas aujourd'hui. */
export function catchRisk(state: GameState, kind: DirtyKind): number {
  return Math.min(0.95, DIRTY[kind].evidence + state.suspicion * 0.005);
}

export type DirtyRefusal = 'not_rival' | 'not_visited' | 'not_here' | 'no_cash' | 'already';

export function canCommit(
  state: GameState,
  buildingId: number,
  kind: DirtyKind,
  target: DirtyTarget,
  /** Bien d'un autre joueur (en ligne). */
  player = false,
): DirtyRefusal | null {
  if (!player && !rivalOf(state, buildingId)) return 'not_rival';
  if (!state.visited.includes(buildingId)) return 'not_visited';
  if (activeEffect(state, buildingId, state.player.day + 1)) return 'already';
  if (state.player.cash < dirtyCost(kind, target)) return 'no_cash';
  return null;
}

/** Le joueur commet un coup bas contre le bien d'un concurrent. */
/** Coup bas contre un autre joueur : ce que sa victime recevra. */
export interface PlayerAttack {
  buildingId: number;
  kind: DirtyKind;
  evidence: boolean;
  clues: number;
  lostRent: number;
}

/**
 * Coup bas contre le bien d'un autre joueur (en ligne). Le joueur paie et devient suspect ; s'il
 * laisse des preuves, c'est sa victime qui pourra porter plainte et le faire condamner.
 */
export function commitDirtyOnPlayer(
  state: GameState,
  city: City,
  buildingId: number,
  kind: DirtyKind,
  target: DirtyTarget,
  ownerName: string,
  addLetter: LetterAdder,
): { state: GameState; attack: PlayerAttack } {
  const refusal = canCommit(state, buildingId, kind, target, true);
  const building = city.buildings[buildingId];
  if (refusal || !building) throw new Error(`Coup bas refusé : ${refusal}`);
  const cost = dirtyCost(kind, target);
  const day = state.player.day;
  const evidence =
    roll(state.seed, buildingId, 1000 + day * 7 + DIRTY_KINDS.indexOf(kind)) <
    catchRisk(state, kind);
  const clues = evidence ? 2 + (day % 2) : day % 2;
  let next: GameState = {
    ...state,
    player: { ...state.player, cash: state.player.cash - cost },
    ledger: { ...state.ledger, dirty: state.ledger.dirty + cost },
    effects: [...state.effects, { buildingId, kind, untilDay: day + DIRTY[kind].days }],
    suspicion: Math.min(100, state.suspicion + SUSPICION_PER_COUP),
  };
  next = addLetter(next, 'dirtyDone', { ref: building.ref, kind, rival: ownerName });
  return {
    state: next,
    attack: { buildingId, kind, evidence, clues, lostRent: dirtyDamage(kind, target.rent) },
  };
}

/**
 * La victime reçoit le coup bas d'un autre joueur, à son passage suivant. Un locataire satisfait
 * refuse d'être débauché.
 */
export function receiveAttack(
  state: GameState,
  city: City,
  attack: PlayerAttack & { id: number; attacker: string },
  addLetter: LetterAdder,
): GameState {
  const building = city.buildings[attack.buildingId];
  const id = String(attack.buildingId);
  if (!building || !state.player.properties.some((p) => p.id === id)) return state;
  let next = state;
  if (attack.kind === 'poach') {
    const tenancy = next.tenancy[id];
    if (!tenancy?.tenant) return next;
    if ((tenancy.satisfaction ?? 70) >= POACH_RESIST)
      return addMessage(next, id, tenancy.tenant, 'poachRefused', { ref: building.ref });
    next = addMessage(next, id, tenancy.tenant, 'poached', { ref: building.ref });
    next = { ...next, tenancy: { ...next.tenancy, [id]: { tenant: null, candidates: [] } } };
  }
  const day = next.player.day;
  const rule = DIRTY[attack.kind];
  const incident: Incident = {
    id: next.nextIncidentId,
    buildingId: attack.buildingId,
    kind: attack.kind,
    day,
    rivalId: 0,
    evidence: attack.evidence,
    clues: attack.clues,
    lostRent: attack.lostRent,
    status: 'open',
    attacker: attack.attacker,
    attackId: attack.id,
  };
  next = {
    ...next,
    nextIncidentId: next.nextIncidentId + 1,
    effects: [
      ...next.effects,
      { buildingId: attack.buildingId, kind: attack.kind, untilDay: day + rule.days },
    ],
    incidents: [incident, ...next.incidents].slice(0, MAX_INCIDENTS),
  };
  return addLetter(next, 'incident', {
    ref: building.ref,
    kind: attack.kind,
    clues: attack.clues,
    days: rule.days,
  });
}

/** Condamnation obtenue par la victime d'un coup bas : appliquée à l'attaquant le lendemain. */
export function receivePenalty(
  state: GameState,
  penalty: { buildingId: number; kind: DirtyKind; fine: number },
): GameState {
  return {
    ...state,
    trials: [
      ...state.trials,
      {
        dueDay: state.player.day,
        buildingId: penalty.buildingId,
        kind: penalty.kind,
        rivalId: 0,
        fine: penalty.fine,
      },
    ],
  };
}

/** Amende demandée à l'attaquant quand sa victime gagne sa plainte. */
export function playerFine(incident: Incident): number {
  return dirtyFine(DIRTY[incident.kind].baseCost + 2 * incident.lostRent);
}

export function commitDirty(
  state: GameState,
  city: City,
  buildingId: number,
  kind: DirtyKind,
  target: DirtyTarget,
  addLetter: LetterAdder,
): GameState {
  const refusal = canCommit(state, buildingId, kind, target);
  const rival = rivalOf(state, buildingId);
  const building = city.buildings[buildingId];
  if (refusal || !rival || !building) throw new Error(`Coup bas refusé : ${refusal}`);
  const rule = DIRTY[kind];
  const cost = dirtyCost(kind, target);
  const day = state.player.day;
  const caught =
    roll(state.seed, buildingId, 1000 + day * 7 + DIRTY_KINDS.indexOf(kind)) <
    catchRisk(state, kind);
  const pressure = pressureOn(state, buildingId) + rule.pressure;
  let next: GameState = {
    ...state,
    player: { ...state.player, cash: state.player.cash - cost },
    ledger: { ...state.ledger, dirty: state.ledger.dirty + cost },
    effects: [...state.effects, { buildingId, kind, untilDay: day + rule.days }],
    pressure: { ...state.pressure, [String(buildingId)]: pressure },
    suspicion: Math.min(100, state.suspicion + SUSPICION_PER_COUP),
    trials: caught
      ? [
          ...state.trials,
          { dueDay: day + 1, buildingId, kind, rivalId: rival.id, fine: dirtyFine(cost) },
        ]
      : state.trials,
  };
  next = addLetter(next, 'dirtyDone', { ref: building.ref, kind, rival: rival.name });

  // Sous la pression, le concurrent finit par brader son bien.
  if (pressure >= FORCED_SALE_PRESSURE && !next.listings.includes(buildingId)) {
    next = {
      ...next,
      listings: [...next.listings, buildingId],
      discounts: { ...next.discounts, [String(buildingId)]: FORCED_SALE_DISCOUNT },
    };
    next = addLetter(next, 'forcedSale', { ref: building.ref, rival: rival.name });
  }
  return next;
}

/** Multiplicateurs de loyer des biens du joueur touchés par un coup bas, pour un jour donné. */
export function rentModifiers(state: GameState, rentDay: number): Record<string, number> {
  const modifiers: Record<string, number> = {};
  for (const property of state.player.properties) {
    const effect = activeEffect(state, Number(property.id), rentDay);
    if (effect) modifiers[property.id] = DIRTY[effect.kind].rentFactor;
  }
  return modifiers;
}

/**
 * Suite quotidienne des coups bas : procès du joueur s'il s'est fait prendre, baisse du soupçon,
 * fin des effets, et attaques des concurrents une fois l'immunité passée.
 */
export function dailyDirty(
  state: GameState,
  city: City,
  rng: Rng,
  rentOf: (building: Building) => number,
  addLetter: LetterAdder,
): GameState {
  const day = state.player.day;
  let next = state;

  for (const trial of state.trials.filter((t) => t.dueDay <= day)) {
    const fine = trial.fine ?? dirtyFine(DIRTY[trial.kind].baseCost);
    next = {
      ...next,
      player: {
        ...next.player,
        cash: next.player.cash - fine,
        creditLevel: Math.max(0, next.player.creditLevel - CREDIT_LOST_WHEN_CAUGHT),
      },
      ledger: { ...next.ledger, fines: next.ledger.fines + fine },
      suspicion: Math.min(100, next.suspicion + SUSPICION_WHEN_CAUGHT),
    };
    next = addLetter(next, 'trial', {
      ref: city.buildings[trial.buildingId]?.ref ?? '',
      amount: fine,
      kind: trial.kind,
    });
  }
  next = {
    ...next,
    trials: next.trials.filter((t) => t.dueDay > day),
    suspicion: Math.max(0, next.suspicion - SUSPICION_DECAY_PER_DAY),
    effects: next.effects.filter((e) => e.untilDay >= day),
  };

  if (day <= IMMUNITY_DAYS || next.rivals.length === 0) return next;
  for (const property of next.player.properties) {
    const id = Number(property.id);
    const building = city.buildings[id];
    if (!building || activeEffect(next, id, day + 1)) continue;
    const guarded = hasCamera(next, id);
    const chance = (districtDef(building.district).risk / 5) * 0.06 * (guarded ? 0.5 : 1);
    if (rng() >= chance) continue;
    const pick = rng();
    const kind: DirtyKind =
      pick < 0.45 ? 'review' : pick < 0.65 ? 'inspection' : pick < 0.85 ? 'poach' : 'rumor';
    const rule = DIRTY[kind];
    const rival = next.rivals[Math.floor(rng() * next.rivals.length)]!;
    if (kind === 'poach') {
      // Débauchage : seul un locataire en place peut partir, et un locataire satisfait refuse.
      const tenancy = next.tenancy[property.id];
      if (!tenancy?.tenant) continue;
      if ((tenancy.satisfaction ?? 70) >= POACH_RESIST) {
        next = addMessage(next, property.id, tenancy.tenant, 'poachRefused', { ref: building.ref });
        continue;
      }
      next = addMessage(next, property.id, tenancy.tenant, 'poached', { ref: building.ref });
      next = {
        ...next,
        tenancy: { ...next.tenancy, [property.id]: { tenant: null, candidates: [] } },
      };
    }
    const evidence = rng() < rule.evidence + (guarded ? CAMERA_EVIDENCE_BONUS : 0);
    const clues = evidence ? 2 + Math.floor(rng() * 2) : Math.floor(rng() * 2);
    const incident: Incident = {
      id: next.nextIncidentId,
      buildingId: id,
      kind,
      day,
      rivalId: rival.id,
      evidence,
      clues,
      lostRent: dirtyDamage(kind, rentOf(building)),
      status: 'open',
    };
    next = {
      ...next,
      nextIncidentId: next.nextIncidentId + 1,
      effects: [...next.effects, { buildingId: id, kind, untilDay: day + rule.days }],
      incidents: [incident, ...next.incidents].slice(0, MAX_INCIDENTS),
    };
    next = addLetter(next, 'incident', { ref: building.ref, kind, clues, days: rule.days });
  }
  return next;
}

export function openIncident(state: GameState, buildingId: number): Incident | undefined {
  return state.incidents.find((i) => i.buildingId === buildingId && i.status === 'open');
}

/** Dommages obtenus si la plainte aboutit. */
export function damagesFor(incident: Incident): number {
  return DAMAGES_BASE + incident.lostRent * 2;
}

/** Le joueur porte plainte : il paie l'avocat, et gagne seulement s'il existe des preuves. */
export function complain(
  state: GameState,
  city: City,
  incidentId: number,
  addLetter: LetterAdder,
): GameState {
  const incident = state.incidents.find((i) => i.id === incidentId && i.status === 'open');
  if (!incident) throw new Error('Incident introuvable');
  if (state.player.cash < COMPLAINT_COST) throw new Error('Trésorerie insuffisante');
  const rival = state.rivals.find((r) => r.id === incident.rivalId);
  const ref = city.buildings[incident.buildingId]?.ref ?? '';
  const won = incident.evidence;
  const damages = won ? damagesFor(incident) : 0;
  const next: GameState = {
    ...state,
    player: { ...state.player, cash: state.player.cash - COMPLAINT_COST + damages },
    ledger: {
      ...state.ledger,
      legal: state.ledger.legal + COMPLAINT_COST,
      damages: state.ledger.damages + damages,
    },
    incidents: state.incidents.map((i) =>
      i.id === incidentId ? { ...i, status: won ? 'won' : 'lost' } : i,
    ),
  };
  return addLetter(next, won ? 'complaintWon' : 'complaintLost', {
    ref,
    amount: damages,
    rival: rival?.name ?? '',
  });
}

export function installCamera(state: GameState, buildingId: number): GameState {
  const owned = state.player.properties.some((p) => p.id === String(buildingId));
  if (!owned || hasCamera(state, buildingId)) throw new Error('Caméras impossibles ici');
  if (state.player.cash < CAMERA_COST) throw new Error('Trésorerie insuffisante');
  return {
    ...state,
    player: { ...state.player, cash: state.player.cash - CAMERA_COST },
    ledger: { ...state.ledger, security: state.ledger.security + CAMERA_COST },
    cameras: [...state.cameras, buildingId],
  };
}

/** Démenti d'une rumeur : l'effet cesse aussitôt ; la plainte reste possible. */
export function denyRumor(state: GameState, incidentId: number): GameState {
  const incident = state.incidents.find((i) => i.id === incidentId && i.kind === 'rumor');
  if (!incident || incident.denied) throw new Error('Rien à démentir');
  if (state.player.cash < DENIAL_COST) throw new Error('Trésorerie insuffisante');
  return {
    ...state,
    player: { ...state.player, cash: state.player.cash - DENIAL_COST },
    ledger: { ...state.ledger, legal: state.ledger.legal + DENIAL_COST },
    effects: state.effects.filter(
      (e) => !(e.buildingId === incident.buildingId && e.kind === 'rumor'),
    ),
    incidents: state.incidents.map((i) => (i.id === incidentId ? { ...i, denied: true } : i)),
  };
}
