import { CITY_SCALE } from '../data/layout';

export type Lod = 0 | 1 | 2;
export type ZoomLevel = 'city' | 'district' | 'street';

/** Vue « Ville » : la caméra recule d'autant que la ville est agrandie. */
export const DIST_MIN = 12;
export const DIST_MAX = 400 * CITY_SCALE;
export const PRESET_DIST: Record<ZoomLevel, number> = {
  city: 330 * CITY_SCALE,
  district: 75,
  street: 28,
};

export function clamp(value: number, min: number, max: number): number {
  return Math.max(min, Math.min(max, value));
}

export function smoothstep(t: number): number {
  const c = clamp(t, 0, 1);
  return c * c * (3 - 2 * c);
}

export function lerp(a: number, b: number, t: number): number {
  return a + (b - a) * t;
}

/** Distance au-delà de laquelle on passe en vue Ville (silhouettes). */
export const QUARTER_MAX = 80;

/** Niveau de détail selon la distance de la caméra : 0 = ville, 1 = quartier, 2 = rue. */
export function lodForDistance(dist: number): Lod {
  // Vue Quartier raccourcie (décision du propriétaire, pour la fluidité) : au-delà, vue Ville.
  if (dist > QUARTER_MAX) return 0;
  if (dist > 60) return 1;
  return 2;
}

export function levelForLod(lod: Lod): ZoomLevel {
  return lod === 0 ? 'city' : lod === 1 ? 'district' : 'street';
}

/** Hauteur relative des bâtiments : presque à plat de loin, hauteur réelle de près. */
export function heightScale(dist: number): number {
  return lerp(0.2, 1, smoothstep((230 - dist) / (230 - 80)));
}

/** Inclinaison de la caméra depuis la verticale, en radians : plus rasante de près. */
export function tiltAngle(dist: number): number {
  return (lerp(30, 72, smoothstep((200 - dist) / (200 - 14))) * Math.PI) / 180;
}

/** Opacité des détails de rue (fenêtres, marquages, mobilier) : apparition progressive. */
export function detailAlpha(dist: number): number {
  return smoothstep((72 - dist) / 26);
}

export interface CameraState {
  tx: number;
  tz: number;
  dist: number;
  az: number;
}

interface Pointer {
  x: number;
  y: number;
}

/** Déplacement, zoom et rotation au doigt, à la souris et à la molette, avec inertie douce. */
export class CameraControls {
  readonly current: CameraState;
  readonly goal: CameraState;
  private readonly pointers = new Map<number, Pointer>();
  private pinch = 0;
  private twist: number | null = null;
  private moved = 0;
  private rotating = false;
  private readonly cleanup: (() => void)[] = [];

  constructor(
    private readonly element: HTMLElement,
    start: CameraState,
    private readonly limits: { x: [number, number]; z: [number, number] },
    private readonly onTap: (clientX: number, clientY: number) => void,
  ) {
    this.current = { ...start };
    this.goal = { ...start };
    const listen = <K extends keyof HTMLElementEventMap>(
      type: K,
      handler: (event: HTMLElementEventMap[K]) => void,
      options?: AddEventListenerOptions,
    ) => {
      element.addEventListener(type, handler, options);
      this.cleanup.push(() => element.removeEventListener(type, handler, options));
    };
    listen('contextmenu', (e) => e.preventDefault());
    listen('pointerdown', (e) => this.down(e));
    listen('pointermove', (e) => this.move(e));
    listen('pointerup', (e) => this.up(e, true));
    listen('pointercancel', (e) => this.up(e, false));
    listen('wheel', (e) => this.wheel(e), { passive: false });
  }

  dispose(): void {
    this.cleanup.forEach((fn) => fn());
  }

  zoomBy(factor: number): void {
    this.goal.dist = clamp(this.goal.dist * factor, DIST_MIN, DIST_MAX);
  }

  zoomTo(dist: number, focus?: { x: number; z: number }): void {
    this.goal.dist = clamp(dist, DIST_MIN, DIST_MAX);
    if (focus) this.panTo(focus.x, focus.z);
  }

  rotateBy(angle: number): void {
    this.goal.az += angle;
  }

  panTo(x: number, z: number): void {
    this.goal.tx = clamp(x, this.limits.x[0], this.limits.x[1]);
    this.goal.tz = clamp(z, this.limits.z[0], this.limits.z[1]);
  }

  /** Rapproche l'état courant de l'état visé. `dt` en secondes. */
  update(dt: number): void {
    const k = 1 - Math.pow(0.0015, dt);
    this.current.tx = lerp(this.current.tx, this.goal.tx, k);
    this.current.tz = lerp(this.current.tz, this.goal.tz, k);
    this.current.dist = lerp(this.current.dist, this.goal.dist, k);
    this.current.az = lerp(this.current.az, this.goal.az, k);
  }

  private down(e: PointerEvent): void {
    this.element.setPointerCapture(e.pointerId);
    this.pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
    this.moved = 0;
    this.rotating = e.button === 2 || e.ctrlKey;
    if (this.pointers.size === 2) {
      this.pinch = this.pinchDistance();
      this.twist = this.pinchAngle();
    }
  }

  private move(e: PointerEvent): void {
    const previous = this.pointers.get(e.pointerId);
    if (!previous) return;
    const dx = e.clientX - previous.x;
    const dy = e.clientY - previous.y;
    this.pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
    this.moved += Math.abs(dx) + Math.abs(dy);
    if (this.pointers.size === 2) {
      const distance = this.pinchDistance();
      if (this.pinch > 0 && distance > 0) this.zoomBy(this.pinch / distance);
      this.pinch = distance;
      // Pivoter avec deux doigts : l'angle entre les doigts fait tourner la ville.
      const angle = this.pinchAngle();
      if (this.twist !== null && angle !== null) {
        let delta = angle - this.twist;
        if (delta > Math.PI) delta -= 2 * Math.PI;
        if (delta < -Math.PI) delta += 2 * Math.PI;
        this.goal.az += delta;
      }
      this.twist = angle;
      return;
    }
    if (this.rotating) {
      this.goal.az -= dx * 0.006;
      return;
    }
    const scale = (this.goal.dist / this.element.clientHeight) * 1.1;
    const cos = Math.cos(this.goal.az);
    const sin = Math.sin(this.goal.az);
    this.panTo(
      this.goal.tx - (dx * cos + dy * sin * 1.4) * scale,
      this.goal.tz - (-dx * sin + dy * cos * 1.4) * scale,
    );
  }

  private up(e: PointerEvent, completed: boolean): void {
    if (completed && this.pointers.size === 1 && this.moved < 6 && e.button !== 2) {
      this.onTap(e.clientX, e.clientY);
    }
    this.pointers.delete(e.pointerId);
    if (this.pointers.size < 2) {
      this.pinch = 0;
      this.twist = null;
    }
  }

  private wheel(e: WheelEvent): void {
    e.preventDefault();
    this.zoomBy(Math.exp(e.deltaY * 0.0012));
  }

  /** Angle de la ligne qui relie les deux doigts, ou rien s'il n'y en a pas deux. */
  private pinchAngle(): number | null {
    const [a, b] = [...this.pointers.values()];
    return a && b ? Math.atan2(b.y - a.y, b.x - a.x) : null;
  }

  private pinchDistance(): number {
    const [a, b] = [...this.pointers.values()];
    return a && b ? Math.hypot(a.x - b.x, a.y - b.y) : 0;
  }
}
