import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import { RoomEnvironment } from 'three/examples/jsm/environments/RoomEnvironment.js';

/**
 * Maquette 3D d'un bien (application Biens) : un seul moteur de rendu, partagé entre les vignettes
 * de la liste et la maquette qu'on fait tourner du doigt. Lumière laiteuse façon Liquid Glass.
 */
let shared: {
  renderer: THREE.WebGLRenderer;
  scene: THREE.Scene;
  camera: THREE.PerspectiveCamera;
} | null = null;

function engine(): NonNullable<typeof shared> {
  if (shared) return shared;
  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.05;
  renderer.setClearColor(0x000000, 0);
  const scene = new THREE.Scene();
  const pmrem = new THREE.PMREMGenerator(renderer);
  scene.environment = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
  scene.environmentIntensity = 0.35;
  pmrem.dispose();
  scene.add(new THREE.HemisphereLight(0xeef4ff, 0x97a2c6, 1.9));
  const sun = new THREE.DirectionalLight(0xfff0d6, 2.6);
  sun.position.set(-3, 5, 4);
  scene.add(sun);
  const camera = new THREE.PerspectiveCamera(32, 1, 0.01, 100);
  shared = { renderer, scene, camera };
  return shared;
}

/** Cadre la caméra sur l'objet, vu de trois quarts face. */
function frame(object: THREE.Object3D, camera: THREE.PerspectiveCamera): THREE.Vector3 {
  object.updateMatrixWorld(true);
  const box = new THREE.Box3().setFromObject(object);
  const sphere = box.getBoundingSphere(new THREE.Sphere());
  const distance = (sphere.radius / Math.sin(THREE.MathUtils.degToRad(camera.fov / 2))) * 1.05;
  const dir = new THREE.Vector3(0.55, 0.45, 1).normalize();
  camera.position.copy(sphere.center).addScaledVector(dir, distance);
  camera.near = distance / 50;
  camera.far = distance * 10;
  camera.lookAt(sphere.center);
  camera.updateProjectionMatrix();
  return sphere.center;
}

const thumbs = new Map<string, string>();

/** Vignette d'un bien (image), mise en cache. */
export function thumbnail(key: string, make: () => THREE.Object3D, size = 160): string {
  const cached = thumbs.get(key);
  if (cached) return cached;
  const { renderer, scene, camera } = engine();
  const object = make();
  scene.add(object);
  renderer.setSize(size, size, false);
  camera.aspect = 1;
  frame(object, camera);
  renderer.render(scene, camera);
  const url = renderer.domElement.toDataURL('image/png');
  scene.remove(object);
  thumbs.set(key, url);
  return url;
}

/** Oublie les vignettes (après un achat, une vente ou un changement de graphismes). */
export function clearThumbnails(): void {
  thumbs.clear();
}

/** Maquette qu'on fait tourner du doigt ; renvoie de quoi l'arrêter. */
export function mountViewer(container: HTMLElement, object: THREE.Object3D): () => void {
  const { renderer, scene, camera } = engine();
  const canvas = renderer.domElement;
  container.replaceChildren(canvas);
  scene.add(object);
  const resize = (): void => {
    const w = Math.max(1, container.clientWidth);
    const h = Math.max(1, container.clientHeight);
    renderer.setSize(w, h, false);
    canvas.style.width = '100%';
    canvas.style.height = '100%';
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
  };
  resize();
  const center = frame(object, camera);
  const controls = new OrbitControls(camera, canvas);
  controls.target.copy(center);
  controls.enableDamping = true;
  controls.enablePan = false;
  controls.autoRotate = true;
  controls.autoRotateSpeed = 1.2;
  controls.minPolarAngle = 0.2;
  controls.maxPolarAngle = Math.PI / 2 - 0.05;
  const distance = camera.position.distanceTo(center);
  controls.minDistance = distance * 0.45;
  controls.maxDistance = distance * 1.8;
  controls.addEventListener('start', () => (controls.autoRotate = false));
  controls.update();
  const observer = new ResizeObserver(resize);
  observer.observe(container);
  let frameId = 0;
  const loop = (): void => {
    frameId = requestAnimationFrame(loop);
    if (!canvas.isConnected) return;
    controls.update();
    renderer.render(scene, camera);
  };
  loop();
  return () => {
    cancelAnimationFrame(frameId);
    observer.disconnect();
    controls.dispose();
    scene.remove(object);
    if (canvas.parentElement === container) canvas.remove();
  };
}
