import { createRng, type Rng } from '../city/gen/rng';
import { propertyRent } from '../economy';
import type {
  GameState,
  Letter,
  LetterKind,
  Reliability,
  Tenancy,
  TenantCandidate,
  TenantProfile,
  Title,
  MessageKind,
  IssueKind,
} from './types';
import { addMessage } from './messages';
import {
  BASE_SATISFACTION,
  ISSUE_DAYS,
  ISSUE_KINDS,
  LEAVE_BELOW,
  RENEW_AT,
  SATISFACTION_EFFECT,
  bestCandidate,
  clampSatisfaction,
  repairCost,
  satisfactionOf,
  unpaidFactor,
} from './management';

/**
 * Locataires (demande du propriétaire) : un bien acheté est vide. Chaque jour, des candidats se
 * présentent et s'accumulent ; le joueur négocie, signe un bail, et le loyer ne tombe qu'ensuite.
 * À la fin du bail, le bien se vide et d'autres candidats arrivent. Les valeurs ci-dessous sont
 * des réglages par défaut (voir docs/QUESTIONS.md).
 */

/** Candidats en attente au plus, par bien. */
export const MAX_CANDIDATES = 8;
/** Jours pendant lesquels un candidat attend une réponse. */
export const CANDIDATE_DAYS = 5;
/** Hausse demandée quand on négocie, et chance que le candidat l'accepte. */
export const HAGGLE_RAISE = 0.1;
export const HAGGLE_ODDS: Record<Reliability, number> = { solid: 0.45, fair: 0.6, risky: 0.75 };
/** Chance qu'un locataire ne paie pas son loyer du jour. */
export const UNPAID_ODDS: Record<Reliability, number> = { solid: 0, fair: 0.03, risky: 0.12 };
/**
 * Chance qu'un locataire en retard règle tout son retard le jour suivant (les deux loyers), quand
 * il paie le loyer du jour (retour du propriétaire : un impayé peut être rattrapé).
 */
export const CATCH_UP_ODDS: Record<Reliability, number> = { solid: 1, fair: 0.75, risky: 0.45 };
/** Chance par jour qu'un locataire écrive pour un petit souci du quotidien. */
export const CHAT_ODDS = 0.04;
const CHATS: readonly MessageKind[] = ['leak', 'noise', 'heating', 'thanks'];

const PROFILES: readonly TenantProfile[] = ['student', 'family', 'worker', 'company', 'retired'];
const SURNAMES = [
  'Arnaud',
  'Barbier',
  'Carpentier',
  'Delmas',
  'Esnault',
  'Fabre',
  'Gautier',
  'Hamon',
  'Imbert',
  'Joly',
  'Leclerc',
  'Marchal',
  'Noël',
  'Perrot',
  'Renard',
  'Tessier',
  'Vasseur',
];

type LetterAdder = (state: GameState, kind: LetterKind, params?: Letter['params']) => GameState;

/** Tirage stable à partir de quelques nombres : même partie, même jour, même résultat. */
function chance(...parts: number[]): number {
  let h = 2166136261;
  for (const p of parts) {
    h ^= Math.floor(p) >>> 0;
    h = Math.imul(h, 16777619) >>> 0;
  }
  return createRng(h)();
}

/** Bail du bien ; un bien acheté avant cette règle garde son locataire, sans fin de bail. */
export function tenancyOf(state: GameState, id: string): Tenancy | null {
  return state.tenancy[id] ?? null;
}

export function vacantTenancy(): Tenancy {
  return { tenant: null, candidates: [] };
}

/** Loyer qu'un candidat propose, au cours du jour. */
export function offeredRent(state: GameState, id: string, factor: number): number {
  const property = state.player.properties.find((p) => p.id === id);
  return property ? propertyRent(property, state.player.day) * factor : 0;
}

function unpaid(state: GameState, id: string, day: number): boolean {
  const entry = state.tenancy[id];
  const tenant = entry?.tenant;
  if (!tenant) return false;
  const odds = UNPAID_ODDS[tenant.reliability] * unpaidFactor(satisfactionOf(entry));
  return chance(state.seed, day, Number(id), tenant.id) < odds;
}

/** Part du loyer perçue par bien : 0 si vide ou impayé, sinon le loyer négocié. */
export function tenancyRentModifiers(state: GameState, rentDay: number): Record<string, number> {
  const modifiers: Record<string, number> = {};
  for (const [id, tenancy] of Object.entries(state.tenancy)) {
    if (!tenancy.tenant || tenancy.tenant.untilDay < rentDay) modifiers[id] = 0;
    else modifiers[id] = unpaid(state, id, rentDay) ? 0 : tenancy.tenant.factor;
  }
  return modifiers;
}

function newCandidate(state: GameState, rng: Rng, id: number): TenantCandidate {
  const day = state.player.day;
  const profile = PROFILES[Math.floor(rng() * PROFILES.length)]!;
  const roll = rng();
  const reliability: Reliability =
    profile === 'company' || profile === 'retired'
      ? roll < 0.75
        ? 'solid'
        : 'fair'
      : profile === 'student'
        ? roll < 0.45
          ? 'risky'
          : 'fair'
        : roll < 0.45
          ? 'solid'
          : roll < 0.85
            ? 'fair'
            : 'risky';
  // Un candidat risqué propose plus pour être choisi ; une entreprise signe plus longtemps.
  const base = 0.86 + rng() * 0.2 + (reliability === 'risky' ? 0.06 : 0);
  const title: Title = rng() < 0.5 ? 'mr' : 'mrs';
  return {
    id,
    title,
    surname: SURNAMES[Math.floor(rng() * SURNAMES.length)]!,
    profile,
    factor: Math.round(base * 100) / 100,
    reliability,
    leaseDays: (profile === 'company' ? 20 : 10) + Math.floor(rng() * 15),
    arrivedDay: day,
    expiresDay: day + CANDIDATE_DAYS,
    haggled: false,
  };
}

/** Suite quotidienne : fin des baux, impayés, départ des candidats lassés, nouveaux candidats. */
export function dailyTenancy(
  state: GameState,
  rng: Rng,
  addLetter: LetterAdder,
  refOf: (id: string) => string,
): GameState {
  const day = state.player.day;
  const owned = new Set(state.player.properties.map((p) => p.id));
  let nextId = state.nextCandidateId;
  let next: GameState = state;
  const tenancy: Record<string, Tenancy> = {};
  for (const [id, entry] of Object.entries(state.tenancy)) {
    if (!owned.has(id)) continue;
    let current = entry;
    const satisfaction = satisfactionOf(current);
    // Souci resté sans réponse : le locataire se sent ignoré.
    if (current.tenant && current.issue && day - current.issue.day >= ISSUE_DAYS) {
      next = addMessage(next, id, current.tenant, 'angry', { ref: refOf(id) });
      current = {
        ...current,
        issue: null,
        satisfaction: clampSatisfaction(satisfaction + SATISFACTION_EFFECT.expired),
      };
    }
    if (current.tenant && current.tenant.untilDay < day && satisfaction >= RENEW_AT) {
      // Locataire satisfait : il renouvelle son bail.
      const tenant = current.tenant;
      current = { ...current, tenant: { ...tenant, untilDay: day + tenant.leaseDays } };
      next = addMessage(next, id, tenant, 'renew', { ref: refOf(id), days: tenant.leaseDays });
    } else if (
      current.tenant &&
      (current.tenant.untilDay < day ||
        (satisfactionOf(current) < LEAVE_BELOW && (current.owed ?? 0) === 0))
    ) {
      if (current.tenant.untilDay >= day)
        next = addMessage(next, id, current.tenant, 'leaving', { ref: refOf(id) });
      next = addLetter(next, 'leaseEnded', {
        ref: refOf(id),
        surname: current.tenant.surname,
        title: current.tenant.title,
      });
      current = vacantTenancy();
    } else if (current.tenant && unpaid(state, id, day)) {
      const tenant = current.tenant;
      const rent = offeredRent(state, id, tenant.factor);
      const again = (current.owed ?? 0) > 0;
      // L'impayé s'ajoute à la dette du locataire (rattrapable le mois suivant, ou par un procès).
      current = {
        ...current,
        owed: (current.owed ?? 0) + rent,
        unpaidDays: (current.unpaidDays ?? 0) + 1,
      };
      // Le locataire prévient lui-même, par message.
      next = addMessage(next, id, tenant, again ? 'lateAgain' : 'late', {
        ref: refOf(id),
        amount: Math.round(current.owed ?? 0),
      });
    } else if (current.tenant && (current.owed ?? 0) > 0) {
      // Il paie le loyer du jour : peut-être aussi son retard.
      const tenant = current.tenant;
      const roll = chance(state.seed, day, Number(id), tenant.id, 13);
      if (roll < CATCH_UP_ODDS[tenant.reliability]) {
        const owed = Math.round(current.owed ?? 0);
        next = {
          ...next,
          player: { ...next.player, cash: next.player.cash + owed },
          ledger: { ...next.ledger, rent: next.ledger.rent + owed },
          propertyStats: {
            ...next.propertyStats,
            [id]: {
              paid: next.propertyStats[id]?.paid ?? 0,
              rent: (next.propertyStats[id]?.rent ?? 0) + owed,
            },
          },
        };
        current = { ...current, owed: 0, unpaidDays: 0 };
        next = addMessage(next, id, tenant, 'repaid', { ref: refOf(id), amount: owed });
      }
    } else if (current.tenant && rng() < CHAT_ODDS) {
      // Petits soucis du quotidien : une fuite, du bruit ou le chauffage demandent une réponse.
      let kind = CHATS[Math.floor(rng() * CHATS.length)]!;
      if (current.issue && kind !== 'thanks') kind = 'thanks';
      next = addMessage(next, id, current.tenant, kind, { ref: refOf(id) });
      if ((ISSUE_KINDS as readonly string[]).includes(kind))
        current = { ...current, issue: { kind: kind as IssueKind, day } };
    } else if (current.tenant && !current.issue && satisfactionOf(current) < BASE_SATISFACTION) {
      // Sans souci, la satisfaction remonte doucement.
      current = { ...current, satisfaction: satisfactionOf(current) + 1 };
    }
    let candidates = current.candidates.filter((c) => c.expiresDay >= day);
    if (!current.tenant) {
      const arrivals = 1 + (rng() < 0.5 ? 1 : 0);
      for (let i = 0; i < arrivals && candidates.length < MAX_CANDIDATES; i++) {
        candidates = [...candidates, newCandidate(next, rng, nextId++)];
      }
    }
    tenancy[id] = { ...current, candidates };
  }
  next = { ...next, tenancy, nextCandidateId: nextId };
  return state.agency ? agencyDay(next, addLetter, refOf) : next;
}

/** L'agence de gestion : répare les soucis et signe le meilleur candidat des biens vides. */
function agencyDay(
  state: GameState,
  addLetter: LetterAdder,
  refOf: (id: string) => string,
): GameState {
  let next = state;
  for (const [id, entry] of Object.entries(state.tenancy)) {
    if (entry.tenant && entry.issue) {
      const cost = repairCost(next, id);
      if (next.player.cash < cost) continue;
      const tenant = entry.tenant;
      next = {
        ...next,
        player: { ...next.player, cash: next.player.cash - cost },
        ledger: { ...next.ledger, renovation: next.ledger.renovation + cost },
        tenancy: {
          ...next.tenancy,
          [id]: {
            ...entry,
            issue: null,
            satisfaction: clampSatisfaction(satisfactionOf(entry) + SATISFACTION_EFFECT.repair),
          },
        },
      };
      next = addMessage(next, id, tenant, 'agencyFixed', { ref: refOf(id), amount: cost });
    } else if (!entry.tenant && entry.candidates.length > 0) {
      const best = bestCandidate(entry.candidates);
      if (best) next = answerCandidate(next, id, best.id, 'accept', addLetter, refOf(id)).state;
    }
  }
  return next;
}

export type TenantChoice = 'accept' | 'haggle' | 'reject';

/** Répond à un candidat : signer le bail, négocier une seule fois, ou l'écarter. */
export function answerCandidate(
  state: GameState,
  id: string,
  candidateId: number,
  choice: TenantChoice,
  addLetter: LetterAdder,
  ref: string,
): { state: GameState; accepted: boolean } {
  const entry = state.tenancy[id];
  const candidate = entry?.candidates.find((c) => c.id === candidateId);
  if (!entry || !candidate || entry.tenant) throw new Error('Candidat introuvable');
  const others = entry.candidates.filter((c) => c.id !== candidateId);
  const put = (tenancy: Tenancy): GameState => ({
    ...state,
    tenancy: { ...state.tenancy, [id]: tenancy },
  });
  if (choice === 'reject') return { state: put({ ...entry, candidates: others }), accepted: false };
  if (choice === 'haggle') {
    if (candidate.haggled) throw new Error('Déjà négocié');
    const roll = chance(state.seed, state.player.day, Number(id), candidate.id, 7);
    if (roll >= HAGGLE_ODDS[candidate.reliability]) {
      return { state: put({ ...entry, candidates: others }), accepted: false };
    }
    const raised = {
      ...candidate,
      factor: Math.round(candidate.factor * (1 + HAGGLE_RAISE) * 100) / 100,
      haggled: true,
    };
    return {
      state: put({
        ...entry,
        candidates: entry.candidates.map((c) => (c.id === candidateId ? raised : c)),
      }),
      accepted: true,
    };
  }
  // Bail signé : les autres candidats repartent, le loyer tombe dès le lendemain.
  const rent = offeredRent(state, id, candidate.factor);
  let signed = put({
    tenant: { ...candidate, untilDay: state.player.day + candidate.leaseDays },
    candidates: [],
    satisfaction: BASE_SATISFACTION,
    issue: null,
  });
  signed = addMessage(signed, id, candidate, 'hello', { ref });
  signed = addLetter(signed, 'leaseSigned', {
    ref,
    surname: candidate.surname,
    title: candidate.title,
    days: candidate.leaseDays,
    amount: rent,
  });
  // Didacticiel : le tout premier bail est récompensé par un loyer versé tout de suite.
  if (!state.firstLeaseBonus) {
    signed = {
      ...signed,
      firstLeaseBonus: true,
      player: { ...signed.player, cash: signed.player.cash + rent },
      ledger: { ...signed.ledger, rent: signed.ledger.rent + rent },
      propertyStats: {
        ...signed.propertyStats,
        [id]: {
          paid: signed.propertyStats[id]?.paid ?? 0,
          rent: (signed.propertyStats[id]?.rent ?? 0) + rent,
        },
      },
    };
    signed = addLetter(signed, 'firstRent', { ref, amount: rent });
  }
  return { state: signed, accepted: true };
}

/** Candidats en attente sur tous les biens vides (pour la pastille de l'onglet). */
export function waitingCandidates(state: GameState): number {
  let count = 0;
  for (const entry of Object.values(state.tenancy))
    if (!entry.tenant) count += entry.candidates.length;
  return count;
}

/** Pour les écrans : un bien est-il loué ? (ancien bien sans suivi : oui) */
export function isLet(state: GameState, id: string): boolean {
  const entry = state.tenancy[id];
  return !entry || entry.tenant !== null;
}
