import { propertyRent } from '../economy';
import { addMessage } from './messages';
import type { GameState, IssueKind, Tenancy, TenantCandidate } from './types';

/**
 * Gestion locative (grosse mise à jour, point 4) : le joueur répond aux soucis de ses locataires,
 * la satisfaction du locataire change ses impayés et son envie de rester, et une agence de gestion
 * peut tout faire à sa place. Valeurs par défaut, voir docs/QUESTIONS.md.
 */

export type IssueChoice = 'repair' | 'discount' | 'ignore';

/** Satisfaction d'un nouveau locataire. */
export const BASE_SATISFACTION = 70;
/** Jours pour répondre à un souci ; ensuite, il est considéré comme ignoré (en pire). */
export const ISSUE_DAYS = 3;
/** Prix d'une intervention, en jours de loyer, et au moins REPAIR_MIN ducats. */
export const REPAIR_DAYS_OF_RENT: Record<IssueKind, number> = { leak: 2, heating: 1.5, noise: 0.5 };
export const REPAIR_MIN = 300;
/** Geste commercial : baisse du loyer jusqu'à la fin du bail. */
export const DISCOUNT = 0.92;
/** Effet de chaque réponse sur la satisfaction. */
export const SATISFACTION_EFFECT = { repair: 15, discount: 10, ignore: -20, expired: -25 };
/** Au-dessus : le locataire renouvelle son bail. En dessous : il part sans attendre la fin. */
export const RENEW_AT = 75;
export const LEAVE_BELOW = 15;
/** Agence de gestion : 8 % des loyers (règle de l'économie), déjà payés à partir du 6e bien. */
export const AGENCY_RATE = 0.08;

export const ISSUE_KINDS: readonly IssueKind[] = ['leak', 'noise', 'heating'];

export function satisfactionOf(tenancy: Tenancy | null | undefined): number {
  return tenancy?.satisfaction ?? BASE_SATISFACTION;
}

export function clampSatisfaction(value: number): number {
  return Math.max(0, Math.min(100, Math.round(value)));
}

/** Multiplicateur de la chance d'impayé : un locataire mécontent paie moins bien. */
export function unpaidFactor(satisfaction: number): number {
  if (satisfaction < 40) return 2;
  if (satisfaction >= 80) return 0.5;
  return 1;
}

/** Loyer du jour payé par le locataire en place. */
function tenantRent(state: GameState, id: string): number {
  const property = state.player.properties.find((p) => p.id === id);
  const tenant = state.tenancy[id]?.tenant;
  if (!property || !tenant) return 0;
  return propertyRent(property, state.player.day) * tenant.factor;
}

/** Prix d'une intervention pour le souci en cours. */
export function repairCost(state: GameState, id: string): number {
  const issue = state.tenancy[id]?.issue;
  if (!issue) return 0;
  return Math.round(Math.max(REPAIR_MIN, tenantRent(state, id) * REPAIR_DAYS_OF_RENT[issue.kind]));
}

/** L'agence est-elle déjà payée par la règle des 8 % à partir du 6e bien ? */
export function agencyIncluded(state: GameState, fromProperties = 6): boolean {
  return state.player.properties.length >= fromProperties;
}

/** Répond au souci signalé par le locataire d'un bien. */
export function answerIssue(
  state: GameState,
  id: string,
  choice: IssueChoice,
  ref: string,
): GameState {
  const entry = state.tenancy[id];
  const tenant = entry?.tenant;
  if (!entry || !tenant || !entry.issue) throw new Error('Aucun souci en attente');
  const satisfaction = satisfactionOf(entry);
  let next = state;
  let updated: Tenancy = { ...entry, issue: null };
  if (choice === 'repair') {
    const cost = repairCost(state, id);
    if (state.player.cash < cost) throw new Error('Trésorerie insuffisante');
    next = {
      ...next,
      player: { ...next.player, cash: next.player.cash - cost },
      ledger: { ...next.ledger, renovation: next.ledger.renovation + cost },
    };
    updated = {
      ...updated,
      satisfaction: clampSatisfaction(satisfaction + SATISFACTION_EFFECT.repair),
    };
    next = { ...next, tenancy: { ...next.tenancy, [id]: updated } };
    return addMessage(next, id, tenant, 'fixed', { ref, amount: cost });
  }
  if (choice === 'discount') {
    updated = {
      ...updated,
      tenant: { ...tenant, factor: Math.round(tenant.factor * DISCOUNT * 100) / 100 },
      satisfaction: clampSatisfaction(satisfaction + SATISFACTION_EFFECT.discount),
    };
    next = { ...next, tenancy: { ...next.tenancy, [id]: updated } };
    return addMessage(next, id, tenant, 'discounted', { ref });
  }
  updated = {
    ...updated,
    satisfaction: clampSatisfaction(satisfaction + SATISFACTION_EFFECT.ignore),
  };
  next = { ...next, tenancy: { ...next.tenancy, [id]: updated } };
  return addMessage(next, id, tenant, 'ignored', { ref });
}

/** Le meilleur candidat pour l'agence : fiable d'abord, puis le loyer le plus haut. */
export function bestCandidate(candidates: readonly TenantCandidate[]): TenantCandidate | null {
  const rank = { solid: 2, fair: 1, risky: 0 } as const;
  let best: TenantCandidate | null = null;
  for (const c of candidates) {
    if (
      !best ||
      rank[c.reliability] > rank[best.reliability] ||
      (rank[c.reliability] === rank[best.reliability] && c.factor > best.factor)
    )
      best = c;
  }
  return best;
}

export function setAgency(state: GameState, on: boolean): GameState {
  return { ...state, agency: on };
}
