import { createRng } from '../city/gen/rng';
import { addCash } from '../economy';
import { districtDef } from '../city/data/layout';
import type { BuildingType, DistrictId } from '../city/model';
import type { GameState, Letter, LetterKind } from './types';

/**
 * Procès contre un locataire qui ne paie pas (demande du propriétaire). Le joueur compose son
 * dossier : trois articles du Code de la location et trois pièces parmi six de chaque. Chaque bon
 * choix augmente ses chances. Un avocat, payé d'avance, signale les bons choix et plaide mieux.
 * Gagné : le locataire rembourse ses impayés et quitte les lieux. Perdu : frais de justice, et il
 * faut attendre avant de recommencer. Valeurs par défaut, voir docs/QUESTIONS.md.
 */

export type Article = 'rent' | 'termination' | 'recovery' | 'noise' | 'pets' | 'works';
export type Evidence = 'lease' | 'statement' | 'reminders' | 'facade' | 'invoice' | 'neighbour';

/** Les bons choix pour un loyer impayé. */
export const GOOD_ARTICLES: readonly Article[] = ['rent', 'termination', 'recovery'];
export const GOOD_EVIDENCE: readonly Evidence[] = ['lease', 'statement', 'reminders'];
const ARTICLES: readonly Article[] = ['rent', 'termination', 'recovery', 'noise', 'pets', 'works'];
const EVIDENCE: readonly Evidence[] = [
  'lease',
  'statement',
  'reminders',
  'facade',
  'invoice',
  'neighbour',
];
export const PICKS = 3;

/**
 * Honoraires de l'avocat (retour du propriétaire : il doit coûter cher) : une part des impayés
 * selon le type de bien, majorée dans les quartiers chers, plus une provision d'un jour de loyer.
 * Plafond : si le procès est gagné, le joueur garde au moins 40 % des impayés.
 */
export const LAWYER_RATE: Record<BuildingType, number> = {
  pavillon: 0.3,
  villa: 0.4,
  residence: 0.3,
  immeuble: 0.35,
  motel: 0.35,
  entrepot: 0.3,
  hotel: 0.45,
  tour: 0.5,
};
export const MIN_KEPT = 0.4;
export function lawyerFee(
  owed: number,
  type: BuildingType,
  district: DistrictId,
  dailyRent: number,
): number {
  const zone = 0.85 + 0.1 * districtDef(district).priceMult;
  const fee = owed * LAWYER_RATE[type] * zone + dailyRent;
  return Math.round(Math.min(fee, owed * (1 - MIN_KEPT)) / 100) * 100;
}
/** Jours d'impayés (un jour de jeu = un mois de loyer) avant de pouvoir attaquer. */
export const MIN_UNPAID_DAYS = 2;

/** Frais de justice, payés si l'on perd : 15 % des impayés, 1 500 ducats au moins. */
export function courtFee(owed: number): number {
  return Math.max(1500, Math.round((owed * 0.15) / 100) * 100);
}
/** Jours d'attente après un procès perdu. */
export const RETRY_DAYS = 3;

/** Chance de gagner : 20 %, +12 % par bon choix, +10 % avec avocat, 95 % au plus. */
export function winChance(good: number, lawyer: boolean): number {
  return Math.min(0.95, 0.2 + good * 0.12 + (lawyer ? 0.1 : 0));
}

function hash(...parts: number[]): number {
  let h = 2166136261;
  for (const p of parts) {
    h ^= Math.floor(p) >>> 0;
    h = Math.imul(h, 16777619) >>> 0;
  }
  return createRng(h)();
}

function shuffled<T>(items: readonly T[], seed: number): T[] {
  const rng = createRng(seed >>> 0);
  const out = [...items];
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [out[i], out[j]] = [out[j]!, out[i]!];
  }
  return out;
}

/** Ce qui est dû et si l'on peut attaquer. */
export function lawsuitStatus(
  state: GameState,
  id: string,
): { owed: number; unpaidDays: number; canSue: boolean; waitUntil: number | null } {
  const tenancy = state.tenancy[id];
  const owed = tenancy?.tenant ? Math.round(tenancy.owed ?? 0) : 0;
  const unpaidDays = tenancy?.tenant ? (tenancy.unpaidDays ?? 0) : 0;
  const wait = tenancy?.suedAfter ?? null;
  const blocked = wait !== null && state.player.day < wait;
  return {
    owed,
    unpaidDays,
    canSue: owed > 0 && unpaidDays >= MIN_UNPAID_DAYS && !blocked,
    waitUntil: blocked ? wait : null,
  };
}

/** Articles et pièces proposés pour ce dossier, dans un ordre propre au locataire. */
export function caseFile(
  state: GameState,
  id: string,
): { articles: Article[]; evidence: Evidence[] } {
  const tenantId = state.tenancy[id]?.tenant?.id ?? 0;
  return {
    articles: shuffled(ARTICLES, state.seed ^ (Number(id) * 31 + tenantId)),
    evidence: shuffled(EVIDENCE, state.seed ^ (Number(id) * 17 + tenantId * 7)),
  };
}

type LetterAdder = (state: GameState, kind: LetterKind, params?: Letter['params']) => GameState;

/** Lance le procès. */
export function sueTenant(
  state: GameState,
  id: string,
  articles: readonly Article[],
  evidence: readonly Evidence[],
  lawyer: boolean,
  addLetter: LetterAdder,
  ref: string,
  fee: number,
): { state: GameState; won: boolean } {
  const tenancy = state.tenancy[id];
  const tenant = tenancy?.tenant;
  const { owed, canSue } = lawsuitStatus(state, id);
  if (!tenancy || !tenant || !canSue) throw new Error('Procès impossible');
  const uniqueA = [...new Set(articles)].filter((a) => ARTICLES.includes(a));
  const uniqueE = [...new Set(evidence)].filter((e) => EVIDENCE.includes(e));
  if (uniqueA.length !== PICKS || uniqueE.length !== PICKS) throw new Error('Dossier incomplet');
  if (!lawyer) fee = 0;
  if (state.player.cash < fee) throw new Error('Fonds insuffisants');
  const good =
    uniqueA.filter((a) => GOOD_ARTICLES.includes(a)).length +
    uniqueE.filter((e) => GOOD_EVIDENCE.includes(e)).length;
  const won =
    hash(state.seed, state.player.day, Number(id), tenant.id, 41) < winChance(good, lawyer);
  const params = { ref, surname: tenant.surname, title: tenant.title };
  let next: GameState;
  if (won) {
    next = {
      ...state,
      player: addCash(state.player, owed - fee),
      ledger: {
        ...state.ledger,
        legal: state.ledger.legal + fee,
        damages: state.ledger.damages + owed,
      },
      // Expulsion : le bien redevient vacant, les candidats reviennent.
      tenancy: { ...state.tenancy, [id]: { tenant: null, candidates: tenancy.candidates } },
    };
    return { state: addLetter(next, 'lawsuitWon', { ...params, amount: owed }), won };
  }
  const cost = fee + courtFee(owed);
  next = {
    ...state,
    player: addCash(state.player, -cost),
    ledger: { ...state.ledger, legal: state.ledger.legal + cost },
    tenancy: {
      ...state.tenancy,
      [id]: { ...tenancy, suedAfter: state.player.day + RETRY_DAYS },
    },
  };
  return { state: addLetter(next, 'lawsuitLost', { ...params, amount: cost }), won };
}
