import type { EconomyRules } from './rules';

/** État du marché un jour donné : multiplicateurs appliqués aux prix et aux loyers. */
export interface Market {
  price: number;
  rent: number;
}

export const CALM_MARKET: Market = { price: 1, rent: 1 };

/** Effet d'un krach commencé au jour `crashDay` : chute, plancher, puis reprise. */
export function crashMarket(day: number, crashDay: number, rules: EconomyRules): Market {
  const { priceDrop, rentDrop, fallDays, floorDays, recoveryDays } = rules.crash;
  const elapsed = day - crashDay;
  if (elapsed < 0) return CALM_MARKET;
  if (elapsed < fallDays) {
    const t = elapsed / fallDays;
    return { price: 1 - priceDrop * t, rent: 1 - rentDrop * t };
  }
  if (elapsed < fallDays + floorDays) return { price: 1 - priceDrop, rent: 1 - rentDrop };
  if (elapsed < fallDays + floorDays + recoveryDays) {
    const t = (elapsed - fallDays - floorDays) / recoveryDays;
    return { price: 1 - priceDrop * (1 - t), rent: 1 - rentDrop * (1 - t) };
  }
  return CALM_MARKET;
}

/** Hausse cumulée des prix et des loyers sur un nombre de jours. */
export function growth(days: number, rules: EconomyRules): number {
  return Math.pow(1 + rules.dailyGrowth, days);
}
