/** Une tranche d'impôt : `rate` s'applique à la part du montant située sous `upTo`. */
export interface Bracket {
  upTo: number;
  rate: number;
}

/** Toutes les règles chiffrées de l'économie. Montants en ducats, durées en jours réels. */
export interface EconomyRules {
  startingCash: number;
  /** Charges (taxe foncière, entretien, assurance), en part des loyers. */
  chargesRate: number;
  /** Part des loyers prise par l'agence de gestion, et nombre de biens qui la déclenche. */
  agencyRate: number;
  agencyFromProperties: number;
  /** Impôt quotidien sur les loyers nets, par tranches. */
  incomeTax: Bracket[];
  /** Impôt quotidien sur la valeur totale des biens, par tranches. */
  wealthTax: Bracket[];
  /** Hausse quotidienne des prix et des loyers, hors krach. */
  dailyGrowth: number;
  loan: {
    durationDays: number;
    maxCreditLevel: number;
    /** Apport demandé au niveau 0, et baisse par niveau de crédit. */
    downPaymentBase: number;
    downPaymentPerLevel: number;
    /** Frais fixes au niveau 0, et baisse par niveau de crédit. */
    feeBase: number;
    feePerLevel: number;
    /** Prêts simultanés au niveau 0, et niveaux nécessaires pour un prêt de plus. */
    simultaneousBase: number;
    levelsPerExtraLoan: number;
    /** Niveaux de crédit perdus après une saisie. */
    defaultPenaltyLevels: number;
  };
  /** Part de la valeur récupérée quand un bien saisi est vendu aux enchères. */
  seizureRecovery: number;
  /** Jours de solde négatif tolérés avant que la banque saisisse un bien financé. */
  seizureGraceDays: number;
  hunting: {
    /** Commission moyenne d'une mission au départ, et à pleine réputation. */
    commissionStart: number;
    commissionFull: number;
    daysToFullReputation: number;
    /** Part du prix de vente touchée par le chasseur, au départ et à pleine réputation. */
    rateStart: number;
    rateFull: number;
  };
  crash: {
    priceDrop: number;
    rentDrop: number;
    fallDays: number;
    floorDays: number;
    recoveryDays: number;
  };
}

