import { el } from './dom';

/**
 * Animations qui donnent envie de jouer (retour du propriétaire) : icône ducat, solde qui défile,
 * pièces qui volent vers le solde, éclair rouge quand on paie. Rien de tout ça quand l'appareil
 * demande moins d'animations.
 */
const reduced = (): boolean =>
  typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches;

const SVG = 'http://www.w3.org/2000/svg';

/** Pièce de ducat : disque doré, liseré, fronton à colonnes, reflet. Aucune lettre. */
export function ducatIcon(className = 'ducat'): SVGSVGElement {
  const svg = document.createElementNS(SVG, 'svg');
  svg.setAttribute('viewBox', '0 0 24 24');
  svg.setAttribute('aria-hidden', 'true');
  svg.classList.add(className);
  svg.innerHTML =
    '<defs><linearGradient id="dg" x1="0" y1="0" x2="0" y2="1">' +
    '<stop offset="0" stop-color="#ffe9a3"/><stop offset=".5" stop-color="#f4c542"/>' +
    '<stop offset="1" stop-color="#c8901c"/></linearGradient></defs>' +
    '<circle cx="12" cy="12" r="10.5" fill="url(#dg)" stroke="#a87510" stroke-width="1"/>' +
    '<circle cx="12" cy="12" r="7.2" fill="none" stroke="#a87510" stroke-width="1" opacity=".7"/>' +
    '<path d="M7.5 10.2 12 7.6l4.5 2.6M8.6 11v4.4M11 11v4.4M13 11v4.4M15.4 11v4.4M7.6 16.2h8.8" fill="none" stroke="#8a5f0c" stroke-width="1.3" stroke-linecap="round" stroke-linejoin="round"/>' +
    '<ellipse cx="9" cy="7" rx="4" ry="2" fill="#fff" opacity=".45"/>';
  return svg;
}

/** Fait défiler un montant affiché de sa valeur actuelle à la nouvelle. */
export function rollAmount(
  target: HTMLElement,
  from: number,
  to: number,
  format: (n: number) => string,
): void {
  if (reduced() || from === to || !Number.isFinite(from)) {
    target.textContent = format(to);
    return;
  }
  const start = performance.now();
  const duration = Math.min(900, 350 + Math.log10(Math.abs(to - from) + 1) * 90);
  const token = String(start);
  target.dataset.roll = token;
  const step = (now: number): void => {
    if (target.dataset.roll !== token) return;
    const k = Math.min(1, (now - start) / duration);
    const eased = 1 - Math.pow(1 - k, 3);
    target.textContent = format(from + (to - from) * eased);
    if (k < 1) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);
}

/** Des pièces partent du milieu de l'écran et volent jusqu'au solde ; le solde s'illumine. */
export function coinBurst(stage: HTMLElement, wallet: HTMLElement, gain: boolean): void {
  wallet.classList.remove('gain', 'loss');
  void wallet.offsetWidth;
  wallet.classList.add(gain ? 'gain' : 'loss');
  if (!gain || reduced()) return;
  const box = stage.getBoundingClientRect();
  const to = wallet.getBoundingClientRect();
  const tx = to.left + to.width - 30 - box.left;
  const ty = to.top + to.height / 2 - box.top;
  for (let i = 0; i < 7; i++) {
    const coin = el('div', 'flying-coin');
    coin.append(ducatIcon('flying-ducat'));
    const sx = box.width / 2 + (Math.random() - 0.5) * 120;
    const sy = box.height * 0.55 + (Math.random() - 0.5) * 80;
    coin.style.left = `${sx}px`;
    coin.style.top = `${sy}px`;
    coin.style.setProperty('--dx', `${tx - sx}px`);
    coin.style.setProperty('--dy', `${ty - sy}px`);
    coin.style.animationDelay = `${i * 55}ms`;
    coin.addEventListener('animationend', () => coin.remove());
    stage.append(coin);
  }
}
