/** Une partie en cours, hors ligne (sur l'appareil) ou en ligne (sur le serveur). */
export interface GameSession {
  readonly online: boolean;
  readonly state: GameState;
  subscribe(listener: Listener): () => void;
  act(action: Action): Promise<ActResult>;
  /** Avancement dans le jour en cours, de 0 à 1. */
  dayProgress(): number;
  start(): void;
  /** Recommencer la partie : possible seulement hors ligne. */
  reset?: () => void;
  /** Créditer la trésorerie pour les essais : possible seulement hors ligne. */
  grant?: (amount: number) => void;
  /** Essais seulement (hors ligne) : modifie la partie directement. */
  patch?: (change: (state: GameState) => GameState) => void;
  /** Commandes d'administration du propriétaire, pour tester : seulement hors ligne. */
  admin?: (command: AdminCommand) => void;
  /** Placer le joueur devant un bâtiment, pour les essais : possible seulement hors ligne. */
  teleport?: (buildingId: number) => void;
  /** Classement des fortunes et amis. */
  social(): Promise<Social | null>;
  /** Onglet Admin : temps, événements, tests. Renvoie null si refusé. */
  adminApi?: (op: AdminOp) => Promise<AdminStatus | null>;
  /** En ligne : le code Admin est demandé avant d'ouvrir l'onglet. */
  needsAdminCode?: boolean;
  setAdminCode?: (code: string) => void;
  /** Signaler un problème au propriétaire du jeu : seulement en ligne. */
  report?: (category: string, message: string) => Promise<boolean>;
}

/** État affiché par l'onglet Admin. */
export interface AdminStatus {
  day: number;
  /** Avancement dans la journée, de 0 à 1. */
  progress: number;
  msPerDay: number;
  players?: number;
  /** Événements créés par l'Admin. */
  events: CityEvent[];
  eventsOff?: boolean;
  reports?: { created_at: string; category: string; message: string }[];
  inactivity?: boolean;
}

export type AdminOp =
  | { type: 'status' }
  | { type: 'speed'; msPerDay: number }
  | { type: 'jump'; days: number }
  | { type: 'addEvent'; kind: EventKind; district: DistrictId | null; inDays: number; days: number }
  | { type: 'cancelEvent'; id: string }
  | { type: 'grant'; amount: number }
  | { type: 'eventsOff'; off: boolean }
  | { type: 'auctionNow' }
  | { type: 'inactivity'; on: boolean };

/** Commandes de l'onglet Admin. */
export type AdminCommand =
  | { type: 'cash'; amount: number }
  | { type: 'days'; count: number }
  | { type: 'reputation'; missions: number }
  | { type: 'credit' }
  | { type: 'clean' }
  | { type: 'arrive' };

/** Partie hors ligne : les règles s'appliquent sur l'appareil, la sauvegarde est locale. */
export class LocalSession implements GameSession {
  readonly online = false;
  private readonly store: GameStore;

  constructor(
    private readonly city: City,
    seed: number,
    msPerDay: number = DEFAULT_MS_PER_DAY,
  ) {
    this.store = new GameStore(city, seed, msPerDay);
  }

  get state(): GameState {
    return this.store.state;
  }

  subscribe(listener: Listener): () => void {
    return this.store.subscribe(listener);
  }

  dayProgress(): number {
    return this.store.dayProgress();
  }

  start(): void {
    this.store.start();
  }

  reset = (): void => this.store.reset();

  patch = (change: (state: GameState) => GameState): void => this.store.update(change);

  grant = (amount: number): void =>
    this.store.update((s) => ({ ...s, player: addCash(s.player, amount) }));

  adminApi = (op: AdminOp): Promise<AdminStatus | null> => {
    const now = Date.now();
    const s0 = this.store.state;
    const progress = (now - s0.clock.startMs) / s0.clock.msPerDay;
    switch (op.type) {
      case 'speed':
        this.store.update((s) => ({
          ...s,
          clock: { startMs: now - progress * op.msPerDay, msPerDay: op.msPerDay },
        }));
        break;
      case 'jump':
        this.admin({ type: 'days', count: op.days });
        break;
      case 'grant':
        this.grant(op.amount);
        break;
      case 'eventsOff':
        this.store.update((s) => ({ ...s, eventsOff: op.off }));
        break;
      case 'auctionNow':
        this.store.update((s) => ({ ...s, auctionDay: -1 }));
        break;
      case 'cancelEvent':
        this.store.update((s) => ({
          ...s,
          adminEvents: (s.adminEvents ?? []).filter((e) => e.id !== op.id),
        }));
        break;
      case 'addEvent': {
        const spec = EVENT_KINDS[op.kind];
        const day = Math.floor(progress);
        const startDay = day + op.inDays;
        const event: CityEvent = {
          id: `local-${now}`,
          kind: op.kind,
          district: spec.city ? null : op.district,
          announceDay: Math.min(day, startDay - spec.notice),
          startDay,
          endDay: startDay + Math.max(1, op.days) - 1,
          price: spec.price,
          rent: spec.rent,
          source: 'admin',
        };
        this.store.update((s) => ({ ...s, adminEvents: [...(s.adminEvents ?? []), event] }));
        break;
      }
    }
    const s = this.store.state;
    const p = (Date.now() - s.clock.startMs) / s.clock.msPerDay;
    return Promise.resolve({
      day: Math.floor(p),
      progress: p - Math.floor(p),
      msPerDay: s.clock.msPerDay,
      events: s.adminEvents ?? [],
      eventsOff: s.eventsOff ?? false,
    });
  };

  admin = (command: AdminCommand): void => {
    const now = Date.now();
    switch (command.type) {
      case 'cash':
        this.store.update((s) => ({ ...s, player: addCash(s.player, command.amount) }));
        return;
      case 'days':
        // On recule le début de l'horloge : les jours passent aussitôt, loyers et impôts compris.
        this.store.update((s) => ({
          ...s,
          clock: { ...s.clock, startMs: s.clock.startMs - command.count * s.clock.msPerDay },
        }));
        return;
      case 'reputation':
        this.store.update((s) => ({ ...s, reputation: s.reputation + command.missions }));
        return;
      case 'credit':
        this.store.update((s) => ({
          ...s,
          player: { ...s.player, creditLevel: Math.min(10, s.player.creditLevel + 1) },
        }));
        return;
      case 'clean':
        this.store.update((s) => ({ ...s, suspicion: 0, trials: [], incidents: [], effects: [] }));
        return;
      case 'arrive':
        this.store.update((s) => ({
          ...s,
          travel: s.travel ? { ...s.travel, departMs: now - 1, arriveMs: now } : null,
          visiting: s.visiting ? { ...s.visiting, readyAtMs: now } : null,
        }));
        return;
    }
  };

  teleport = (buildingId: number): void => {
    const b = this.city.buildings[buildingId];
    if (!b) return;
    this.store.update((s) => ({ ...s, travel: null, position: { x: b.x, z: b.z, buildingId } }));
  };

  social(): Promise<Social | null> {
    return Promise.resolve(localSocial(this.store.state, this.city, ''));
  }

  act(action: Action): Promise<ActResult> {
    const result: ActResult = {};
    const now = Date.now();
    try {
      this.store.update((s) => {
        switch (action.type) {
          case 'visit':
            return startVisit(settleTravel(s, now), action.buildingId, now);
          case 'propose': {
            const outcome = propose(s, this.city, action.clientId, action.buildingId);
            result.accepted = outcome.result.accepted;
            return outcome.state;
          }
          case 'buy':
            return buy(s, this.city, action.buildingId, action.cash === true);
          case 'sell':
            return sell(s, this.city, action.buildingId);
          case 'repay':
            return repayEarly(s, this.city, action.buildingId);
          case 'read':
            return markLettersRead(s);
          case 'readThread':
            return readThread(s, action.key);
          case 'deleteThread':
            return deleteThread(s, action.key);
          case 'grant':
            return { ...s, player: { ...s.player, cash: s.player.cash + action.amount } };
          case 'dirty':
            return dirty(s, this.city, action.buildingId, action.kind);
          case 'deny':
            return denyRumor(s, action.incidentId);
          case 'complain':
            return fileComplaint(s, this.city, action.incidentId);
          case 'camera':
            return addCamera(s, action.buildingId);
          case 'travel':
            return startTravel(
              settleTravel(s, now),
              this.city,
              action.buildingId,
              action.mode,
              now,
            );
          case 'buyPlot':
            return purchasePlot(s, this.city, action.plot);
          case 'build':
            return build(s, this.city, action.plot, action.kind);
          case 'renovate':
            return renovateProperty(s, this.city, action.buildingId);
          case 'sue': {
            const outcome = sue(
              s,
              this.city,
              action.buildingId,
              action.articles,
              action.evidence,
              action.lawyer,
            );
            result.accepted = outcome.won;
            return outcome.state;
          }
          case 'tenant': {
            const outcome = answerTenant(
              s,
              this.city,
              action.buildingId,
              action.candidateId,
              action.choice,
            );
            result.accepted = outcome.accepted;
            return outcome.state;
          }
          case 'issue':
            return answerTenantIssue(s, this.city, action.buildingId, action.choice);
          case 'agency':
            return setAgency(s, action.on);
          case 'bid':
            return bidLocal(s, action.auctionId, action.amount, now);
          case 'claimQuest':
            return claimQuest(s, this.city, worth(s, this.city), action.id);
          case 'claimDaily':
            return claimDaily(s, now);
          case 'stop':
            return stopTravel(s, now);
          case 'vehicle':
            return buyVehicle(s, action.vehicle);
          case 'friend':
            return action.add ? addFriend(s, action.code) : removeFriend(s, action.code);
          default:
            return s;
        }
      });
    } catch {
      result.error = 'refused';
    }
    return Promise.resolve(result);
  }
}

const SECRET_KEY = 'main-basse-secret-v1';
const POLL_MS = 5000;
const REQUEST_TIMEOUT_MS = 8000;

function deviceSecret(): string {
  try {
    const saved = localStorage.getItem(SECRET_KEY);
    if (saved && /^[A-Za-z0-9_-]{32,128}$/.test(saved)) return saved;
  } catch {
    // Stockage indisponible : le secret ne vivra que le temps de la session.
  }
  const bytes = crypto.getRandomValues(new Uint8Array(32));
  const secret = btoa(String.fromCharCode(...bytes))
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/, '');
  try {
    localStorage.setItem(SECRET_KEY, secret);
  } catch {
    // Voir plus haut.
  }
  return secret;
}

interface ServerReply {
  state?: GameState;
  proposal?: { accepted: boolean } | null;
  nowMs?: number;
  error?: ErrorCode;
}

/**
 * Partie en ligne : chaque action est envoyée au serveur, qui décide et renvoie le nouvel état.
 * L'application n'applique aucune règle d'argent elle-même.
 */
const ADMIN_CODE_KEY = 'mb-admin-code';
function readAdminCode(): string {
  try {
    return localStorage.getItem(ADMIN_CODE_KEY) ?? '';
  } catch {
    return '';
  }
}

export class OnlineSession implements GameSession {
  readonly online = true;
  private current: GameState | null = null;
  private readonly listeners = new Set<Listener>();
  private readonly secret = deviceSecret();
  /** Écart entre l'heure du serveur et celle de l'appareil. */
  private clockOffset = 0;
  private busy = false;
  private adminCode = readAdminCode();
  readonly needsAdminCode = true;

  setAdminCode = (code: string): void => {
    this.adminCode = code;
    try {
      localStorage.setItem(ADMIN_CODE_KEY, code);
    } catch {
      /* mémoire du navigateur indisponible */
    }
  };

  adminApi = async (op: AdminOp): Promise<AdminStatus | null> => {
    if (!this.adminCode) return null;
    const command =
      op.type === 'cancelEvent'
        ? { type: 'cancelEvent', id: Number(op.id.replace('admin-', '')) }
        : op;
    if (op.type === 'eventsOff') return null;
    const send = async (cmd: unknown): Promise<{ admin?: AdminStatus } | null> => {
      try {
        const response = await fetch(`${this.url}/functions/v1/game`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            apikey: this.key,
            Authorization: `Bearer ${this.key}`,
          },
          body: JSON.stringify({
            secret: this.secret,
            token: await accessToken(),
            action: { type: 'admin', code: this.adminCode, command: cmd },
          }),
        });
        return response.ok ? ((await response.json()) as { admin?: AdminStatus }) : null;
      } catch {
        return null;
      }
    };
    const first = await send(command);
    if (!first) return null;
    // Toute commande change la partie (horloge, événements, solde) : on se resynchronise.
    if (op.type !== 'status') await this.act({ type: 'sync' });
    if (first.admin) return first.admin;
    const status = await send({ type: 'status' });
    return status?.admin ?? null;
  };

  constructor(
    private readonly url: string,
    private readonly key: string,
  ) {}

  get state(): GameState {
    if (!this.current) throw new Error('Partie en ligne non connectée');
    return this.current;
  }

  /** Première synchronisation. Renvoie faux si le serveur ne répond pas. */
  async connect(): Promise<boolean> {
    const result = await this.act({ type: 'sync' });
    return !result.error && this.current !== null;
  }

  subscribe(listener: Listener): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  dayProgress(): number {
    if (!this.current) return 0;
    const { startMs, msPerDay } = this.current.clock;
    const elapsed = Math.max(0, Date.now() + this.clockOffset - startMs);
    return (elapsed % msPerDay) / msPerDay;
  }

  start(): void {
    window.setInterval(() => {
      if (!this.busy && !document.hidden) void this.act({ type: 'sync' });
    }, POLL_MS);
  }

  /** Classement et amis : lecture seule, sans changer la partie. */
  report = async (category: string, message: string): Promise<boolean> => {
    try {
      const response = await fetch(`${this.url}/functions/v1/game`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          apikey: this.key,
          Authorization: `Bearer ${this.key}`,
        },
        body: JSON.stringify({
          secret: this.secret,
          token: await accessToken(),
          action: { type: 'report', category, message },
        }),
      });
      return response.ok;
    } catch {
      return false;
    }
  };

  async social(): Promise<Social | null> {
    try {
      const response = await fetch(`${this.url}/functions/v1/game`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          apikey: this.key,
          Authorization: `Bearer ${this.key}`,
        },
        body: JSON.stringify({
          secret: this.secret,
          token: await accessToken(),
          action: { type: 'social' },
        }),
      });
      const reply = (await response.json()) as { social?: Social };
      return response.ok && reply.social ? reply.social : null;
    } catch {
      return null;
    }
  }

  /** Une action refusée parce que trop rapprochée de la précédente est simplement rejouée. */
  async act(action: Action): Promise<ActResult> {
    for (let attempt = 0; ; attempt++) {
      const result = await this.actOnce(action);
      if (result.error !== 'too_fast' || attempt >= 4) return result;
      await new Promise((resolve) => window.setTimeout(resolve, 200 + attempt * 150));
    }
  }

  private async actOnce(action: Action): Promise<ActResult> {
    this.busy = true;
    const controller = new AbortController();
    const timer = window.setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);
    try {
      const response = await fetch(`${this.url}/functions/v1/game`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          apikey: this.key,
          Authorization: `Bearer ${this.key}`,
        },
        body: JSON.stringify({ secret: this.secret, token: await accessToken(), action }),
        signal: controller.signal,
      });
      const reply = (await response.json()) as ServerReply;
      // Session expirée ou compte déconnecté : retour à la page d'accueil.
      if (reply.error === 'auth_required') window.dispatchEvent(new Event('mb-auth-required'));
      if (!response.ok || !reply.state) return { error: reply.error ?? 'server' };
      if (typeof reply.nowMs === 'number') this.clockOffset = reply.nowMs - Date.now();
      const previous = this.current ?? reply.state;
      // Les heures de fin de visite et d'arrivée viennent du serveur : on la ramène à l'horloge de l'appareil.
      const visiting = reply.state.visiting
        ? {
            ...reply.state.visiting,
            readyAtMs: reply.state.visiting.readyAtMs - this.clockOffset,
          }
        : null;
      const travel = reply.state.travel
        ? {
            ...reply.state.travel,
            departMs: reply.state.travel.departMs - this.clockOffset,
            arriveMs: reply.state.travel.arriveMs - this.clockOffset,
          }
        : null;
      this.current = { ...reply.state, visiting, travel };
      const next = this.current;
      this.listeners.forEach((fn) => fn(next, previous));
      return { accepted: reply.proposal?.accepted };
    } catch {
      return { error: 'offline' };
    } finally {
      window.clearTimeout(timer);
      this.busy = false;
    }
  }
}

export interface SessionOptions {
  seed: number;
  msPerDay?: number;
  /** Forcer le jeu hors ligne, même si un serveur est configuré. */
  forceLocal?: boolean;
}

/** Ouvre une partie en ligne si un serveur est configuré et répond, sinon une partie hors ligne. */
export async function openSession(city: City, options: SessionOptions): Promise<GameSession> {
  const url = import.meta.env.VITE_MB_URL ?? '';
  const key = import.meta.env.VITE_MB_KEY ?? '';
  if (url && key && !options.forceLocal) {
    const online = new OnlineSession(url, key);
    if (await online.connect()) return online;
  }
  return new LocalSession(city, options.seed, options.msPerDay);
}
