import * as THREE from 'three';
import type { Building, BuildingPart, City } from '../model';
import { Batch } from './batch';
import { withGrain } from './grain';
import { CELL, lookOf } from './facadeMaterial';
import { DISTRICT_STYLE, pickFor, type CityPalette } from './palette';
import { roofHeight } from './staticScene';

/**
 * Garniture des bâtiments, visible dès le niveau « Quartier » : cheminées, corniches, lucarnes,
 * auvents, coursives, enseignes muettes, acrotères… Chaque type a sa silhouette, un peu exagérée,
 * comme une maquette d'architecte qui aurait de l'humour. Construite par tuile autour de la caméra.
 */

/** Côté d'une tuile de garniture, en unités : partagé avec les graphismes haut. */
export const TILE = 32;
const MAX_VISIBLE = 36;
const MAX_CACHED = 60;
const MAX_BUILDS_PER_UPDATE = 3;

/** Hachage déterministe en [0, 1[. */
function hash(a: number, b: number): number {
  let h = (a * 374761393 + b * 668265263) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}

interface Tile {
  mesh: THREE.Mesh | null;
  lastUsed: number;
}

export class BuildingDressing {
  readonly group = new THREE.Group();
  private readonly index = new Map<string, Building[]>();
  private readonly loaded = new Map<string, Tile>();
  private readonly material: THREE.MeshLambertMaterial;
  private tick = 0;
  /** Tuiles habillées par les graphismes haut : leur garniture simple s'efface. */
  private hidden = new Set<string>();

  constructor(
    city: City,
    private readonly palette: CityPalette,
  ) {
    const material = new THREE.MeshLambertMaterial({ vertexColors: true, side: THREE.DoubleSide });
    // Rendu réaliste : grain de matière sur les acrotères, cages d'escalier, réservoirs.
    this.material = palette.lush ? withGrain(material, 3, 0.45, 'dressing') : material;
    for (const b of city.buildings) {
      const key = `${Math.floor(b.x / TILE)}:${Math.floor(b.z / TILE)}`;
      const list = this.index.get(key);
      if (list) list.push(b);
      else this.index.set(key, [b]);
    }
  }

  get loadedTileCount(): number {
    let n = 0;
    this.loaded.forEach((t) => {
      if (t.mesh?.visible) n++;
    });
    return n;
  }

  /** Charge les tuiles proches du point visé ; `show` à faux masque toute la garniture. */
  update(x: number, z: number, radius: number, show: boolean): void {
    this.tick++;
    this.group.visible = show;
    if (!show) return;
    const reach = Math.ceil(radius / TILE);
    const cx = Math.floor(x / TILE);
    const cz = Math.floor(z / TILE);
    const wanted: { key: string; d: number }[] = [];
    for (let tx = cx - reach; tx <= cx + reach; tx++) {
      for (let tz = cz - reach; tz <= cz + reach; tz++) {
        const key = `${tx}:${tz}`;
        if (!this.index.has(key)) continue;
        const d = Math.hypot((tx + 0.5) * TILE - x, (tz + 0.5) * TILE - z);
        if (d <= radius + TILE * 0.7) wanted.push({ key, d });
      }
    }
    wanted.sort((a, b) => a.d - b.d);
    const keep = new Set(wanted.slice(0, MAX_VISIBLE).map((w) => w.key));
    let built = 0;
    for (const w of wanted.slice(0, MAX_VISIBLE)) {
      let tile = this.loaded.get(w.key);
      if (!tile && built < MAX_BUILDS_PER_UPDATE) {
        tile = { mesh: this.build(this.index.get(w.key)!), lastUsed: this.tick };
        if (tile.mesh) this.group.add(tile.mesh);
        this.loaded.set(w.key, tile);
        built++;
      }
      if (tile) tile.lastUsed = this.tick;
    }
    this.loaded.forEach((tile, key) => {
      if (tile.mesh) tile.mesh.visible = keep.has(key) && !this.hidden.has(key);
    });
    if (this.loaded.size > MAX_CACHED) {
      const oldest = [...this.loaded.entries()].sort((a, b) => a[1].lastUsed - b[1].lastUsed);
      for (const [key, tile] of oldest.slice(0, this.loaded.size - MAX_CACHED)) {
        if (tile.mesh) {
          this.group.remove(tile.mesh);
          tile.mesh.geometry.dispose();
        }
        this.loaded.delete(key);
      }
    }
  }

  setHidden(keys: Set<string>): void {
    this.hidden = keys;
  }

  dispose(): void {
    this.loaded.forEach((tile) => tile.mesh?.geometry.dispose());
    this.loaded.clear();
    this.material.dispose();
  }

  private build(buildings: Building[]): THREE.Mesh | null {
    const batch = new Batch();
    for (const b of buildings) dress(batch, b, this.palette);
    if (batch.isEmpty) return null;
    const geometry = batch.toGeometry();
    geometry.computeVertexNormals();
    geometry.computeBoundingSphere();
    return new THREE.Mesh(geometry, this.material);
  }
}

/** Repère de façade : côté rue, et sens vers la rue (−1 vers le nord, +1 vers le sud). */
function front(b: Building): { z: number; s: number } {
  const s = b.facing === 'north' ? -1 : 1;
  return { z: b.z + (s * b.d) / 2, s };
}

/** Rebord en haut d'un volume : quatre lisses fines, un peu plus larges que les murs. */
function parapet(batch: Batch, p: BuildingPart, hex: number, h = 0.07, t = 0.05): void {
  const top = p.y0 + p.h;
  batch.box(p.x, top, p.z - p.d / 2 + t / 2, p.w + 0.02, h, t, hex);
  batch.box(p.x, top, p.z + p.d / 2 - t / 2, p.w + 0.02, h, t, hex);
  batch.box(p.x - p.w / 2 + t / 2, top, p.z, t, h, p.d, hex);
  batch.box(p.x + p.w / 2 - t / 2, top, p.z, t, h, p.d, hex);
}

/** Petit pignon (lucarne, auvent) : base carrée et toit à deux pans, faîtage vers la rue. */
function gablet(
  batch: Batch,
  x: number,
  y: number,
  z: number,
  w: number,
  h: number,
  d: number,
  wall: number,
  roof: number,
): void {
  batch.box(x, y, z, w, h, d, wall);
  const y1 = y + h;
  const peak = y1 + w * 0.45;
  const z0 = z - d / 2 - 0.01;
  const z1 = z + d / 2 + 0.01;
  const x0 = x - w / 2 - 0.02;
  const x1 = x + w / 2 + 0.02;
  batch.freeQuad([x0, y1, z0], [x, peak, z0], [x, peak, z1], [x0, y1, z1], roof);
  batch.freeQuad([x1, y1, z0], [x1, y1, z1], [x, peak, z1], [x, peak, z0], roof);
  batch.freeQuad([x0, y1, z0], [x1, y1, z0], [x, peak, z0], [x, peak, z0], wall);
  batch.freeQuad([x0, y1, z1], [x, peak, z1], [x, peak, z1], [x1, y1, z1], wall);
}

/** Cheminée trapue avec son chapeau, posée de y0 à y1. */
function chimney(
  batch: Batch,
  x: number,
  z: number,
  y0: number,
  y1: number,
  size: number,
  p: CityPalette,
): void {
  batch.box(x, y0, z, size, y1 - y0, size, p.brick);
  batch.box(x, y1, z, size * 1.35, 0.035, size * 1.35, p.stone);
}

/** Toit-jardin du rendu coloré : pelouse, rangée de buissons. */
function roofGarden(batch: Batch, part: BuildingPart, p: CityPalette, seed: number): void {
  const top = part.y0 + part.h;
  batch.box(part.x, top, part.z, part.w - 0.16, 0.04, part.d - 0.16, p.yard);
  const n = Math.max(2, Math.floor(part.w / 0.45));
  const z = part.z + (hash(seed, 31) < 0.5 ? -1 : 1) * (part.d / 2 - 0.2);
  for (let i = 0; i < n; i++) {
    const x = part.x - part.w / 2 + 0.2 + (i * (part.w - 0.4)) / Math.max(1, n - 1);
    batch.ball(x, top + 0.12, z, 0.1, i % 2 ? p.tree : p.park);
  }
}

/** Couleur moyenne d'une façade, pour les acrotères et cages d'escalier dessinés sans texture. */
function wallAverage(b: Building, p: CityPalette): number {
  const look = lookOf(b);
  if (look.painted) return pickFor(DISTRICT_STYLE[b.district].walls, b.id, 3) ?? 0xd9d2c4;
  const average: Partial<Record<number, number>> = {
    [CELL.redBrick]: 0x8a4a3a,
    [CELL.ochreBrick]: 0xb5875a,
    [CELL.darkBrick]: 0x4e322a,
    [CELL.blondStone]: 0xc9a978,
    [CELL.paintBrick]: 0xd8d0c4,
  };
  const hex = average[look.wall] ?? p.stone;
  return p.litRatio > 0 ? new THREE.Color(hex).multiplyScalar(0.35).getHex() : hex;
}

function dress(batch: Batch, b: Building, pal: CityPalette): void {
  const toon = pal.style === 'toon';
  // Rendu coloré : la pierre et le métal deviennent blancs, comme les menuiseries.
  const p: CityPalette = toon ? { ...pal, stone: pal.trim, quay: pal.trim } : pal;
  const r = (k: number): number => hash(b.id, k);
  const floorH = b.h / b.floors;
  const f = front(b);
  const shutter = p.shutters[Math.floor(r(1) * p.shutters.length)] ?? p.shutters[0]!;
  const top = b.parts[b.parts.length - 1]!;

  switch (b.type) {
    case 'pavillon': {
      const roofH = roofHeight(b);
      const ridgeAlongX = b.w >= b.d;
      // Cheminée sur le faîtage, d'un côté ou de l'autre.
      const side = r(2) < 0.5 ? -1 : 1;
      const cx = ridgeAlongX ? b.x + side * b.w * 0.28 : b.x;
      const cz = ridgeAlongX ? b.z : b.z + side * b.d * 0.28;
      chimney(batch, cx, cz, b.h + roofH * 0.35, b.h + roofH * 1.12, 0.17, p);
      // Auvent au-dessus de la porte, porté par deux poteaux.
      const ax = b.x + (r(3) - 0.5) * b.w * 0.3;
      const az = f.z + f.s * 0.16;
      batch.box(ax, floorH * 0.78, az, 0.5, 0.045, 0.34, shutter);
      for (const dx of [-0.21, 0.21])
        batch.box(ax + dx, 0, az + f.s * 0.13, 0.035, floorH * 0.78, 0.035, p.trim);
      // Marche devant la porte, haie basse au bord du jardin.
      batch.box(ax, 0, f.z + f.s * 0.08, 0.3, 0.05, 0.16, p.stone);
      const hz = f.z + f.s * 0.42;
      if (pal.lush) {
        // Clôture blanche à barreaux, de part et d'autre de l'allée.
        for (const [x0, x1] of [
          [b.x - b.w * 0.55, ax - 0.12],
          [ax + 0.12, b.x + b.w * 0.55],
        ] as const) {
          if (x1 <= x0) continue;
          batch.box((x0 + x1) / 2, 0.06, hz, x1 - x0, 0.012, 0.012, p.trim);
          for (let x = x0; x <= x1 + 1e-6; x += 0.09)
            batch.box(x, 0, hz, 0.012, 0.095, 0.012, p.trim);
        }
        batch.box(b.x - b.w * 0.45, 0, hz - f.s * 0.12, 0.2, 0.08, 0.08, p.tree);
      } else {
        batch.box(b.x - b.w * 0.3, 0, hz, b.w * 0.42, 0.13, 0.1, p.tree);
        batch.box(b.x + b.w * 0.33, 0, hz, b.w * 0.36, 0.13, 0.1, p.tree);
      }
      // Une maison sur trois a une véranda ou un appentis à l'arrière.
      if (r(4) < 0.35) {
        const bz = b.z - (f.s * b.d) / 2 - f.s * 0.22;
        batch.box(b.x + side * b.w * 0.18, 0, bz, b.w * 0.45, floorH * 0.7, 0.44, p.pastels[0]!);
        batch.box(
          b.x + side * b.w * 0.18,
          floorH * 0.7,
          bz,
          b.w * 0.5,
          0.04,
          0.5,
          p.roofs.pavillon,
        );
      }
      return;
    }

    case 'villa': {
      // Aile basse à toit plat, terrasse sur le côté jardin, pergola.
      const side = r(2) < 0.5 ? -1 : 1;
      const ww = Math.min(0.9, b.w * 0.5);
      const wx = b.x + side * (b.w / 2 + ww / 2 - 0.05);
      const wd = b.d * 0.62;
      const wz = b.z - f.s * (b.d - wd) * 0.3;
      batch.box(wx, 0, wz, ww, floorH * 0.95, wd, p.walls.villa);
      batch.box(wx, floorH * 0.95, wz, ww + 0.12, 0.05, wd + 0.12, p.trim);
      const tz = b.z - f.s * (b.d / 2 + 0.35);
      batch.box(b.x, 0, tz, b.w * 0.8, 0.05, 0.6, p.stone);
      for (const dx of [-0.35, 0.35])
        batch.box(b.x + dx * b.w, 0.05, tz - f.s * 0.25, 0.04, floorH * 0.85, 0.04, p.trim);
      batch.box(b.x, 0.05 + floorH * 0.85, tz - f.s * 0.05, b.w * 0.78, 0.035, 0.5, p.trim);
      chimney(
        batch,
        b.x + side * -b.w * 0.25,
        b.z,
        b.h + roofHeight(b) * 0.3,
        b.h + roofHeight(b) * 1.05,
        0.2,
        p,
      );
      batch.box(b.x, 0, f.z + f.s * 0.9, b.w * 1.1, 0.16, 0.12, p.tree);
      return;
    }

    case 'immeuble': {
      // Soubassement en pierre et corniche ; toit à la Mansart ou toit plat encombré.
      batch.box(b.x, 0, b.z, b.w + 0.02, floorH * 0.98, b.d + 0.02, p.stone);
      batch.box(b.x, floorH * 0.98, b.z, b.w + 0.05, 0.035, b.d + 0.05, p.trim);
      batch.box(b.x, b.h - 0.05, b.z, b.w + 0.08, 0.06, b.d + 0.08, p.trim);
      if (b.roof === 'mansard') {
        const dormers = Math.max(1, Math.floor(b.w / 0.55));
        const pitch = b.w / dormers;
        for (let i = 0; i < dormers; i++) {
          const x = b.x - b.w / 2 + (i + 0.5) * pitch;
          gablet(
            batch,
            x,
            b.h + 0.02,
            f.z - f.s * 0.12,
            0.17,
            0.13,
            0.14,
            p.trim,
            p.roofs.immeuble,
          );
        }
        const stacks = b.w > 1.6 ? 2 : 1;
        for (let i = 0; i < stacks; i++) {
          const x = b.x + (stacks === 1 ? 0 : (i === 0 ? -1 : 1) * b.w * 0.3);
          batch.box(x, b.h + 0.2, b.z, 0.26, 0.28, 0.12, p.brick);
        }
        return;
      }
      if (pal.lush) {
        // Acrotère de brique et chaperon de pierre, comme sur le modèle.
        parapet(batch, top, wallAverage(b, pal), 0.08, 0.05);
        parapet(batch, { ...top, h: top.h + 0.08 }, p.stone, 0.015, 0.06);
      } else {
        parapet(batch, top, p.stone, 0.08, 0.05);
      }
      if (toon && r(40) < 0.45) roofGarden(batch, top, p, b.id);
      // Cage d'escalier, climatiseurs, et parfois le château d'eau en bois sur pilotis.
      const sx = b.x + (r(2) - 0.5) * b.w * 0.4;
      batch.box(
        sx,
        b.h,
        b.z - f.s * b.d * 0.15,
        0.42,
        0.32,
        0.36,
        pal.lush ? wallAverage(b, pal) : p.stone,
      );
      if (pal.lush) batch.box(sx, b.h + 0.32, b.z - f.s * b.d * 0.15, 0.45, 0.02, 0.39, p.stone);
      const units = 2 + Math.floor(r(3) * 3);
      for (let i = 0; i < units; i++) {
        const ux = b.x + (r(10 + i) - 0.5) * b.w * 0.7;
        const uz = b.z + (r(20 + i) - 0.5) * b.d * 0.5;
        batch.box(ux, b.h, uz, 0.24, 0.13, 0.18, p.quay);
        batch.box(ux, b.h + 0.13, uz, 0.14, 0.02, 0.1, p.iron);
      }
      if (b.floors >= 4 && r(4) < 0.45) {
        const tx = b.x - (sx - b.x) * 0.8;
        const tz = b.z + f.s * b.d * 0.12;
        for (const [lx, lz] of [
          [-0.14, -0.14],
          [0.14, -0.14],
          [-0.14, 0.14],
          [0.14, 0.14],
        ] as const) {
          batch.box(tx + lx, b.h, tz + lz, 0.03, 0.26, 0.03, p.iron);
        }
        batch.box(tx, b.h + 0.24, tz, 0.4, 0.03, 0.4, p.iron);
        // Château d'eau en bois cerclé de fer, chapeau conique (comme le modèle Blender).
        batch.cylinder(tx, b.h + 0.27, tz, 0.2, 0.36, 0x8a6440, 14);
        for (let k = 0; k < 4; k++)
          batch.cylinder(tx, b.h + 0.3 + k * 0.09, tz, 0.205, 0.01, p.iron, 14);
        batch.cone(tx, b.h + 0.63, tz, 0.22, 0.15, p.iron, 14);
      }
      return;
    }

    case 'residence': {
      // Acrotère, local d'ascenseur sur le toit, marquise d'entrée, antennes.
      parapet(batch, top, p.trim);
      if (toon && r(40) < 0.45) roofGarden(batch, top, p, b.id);
      batch.box(b.x + (r(2) - 0.5) * b.w * 0.4, b.h, b.z, 0.42, 0.26, 0.34, p.stone);
      batch.box(b.x, floorH * 0.82, f.z + f.s * 0.2, Math.min(0.8, b.w * 0.4), 0.05, 0.42, p.trim);
      if (r(3) < 0.6) batch.box(b.x + b.w * 0.3, b.h, b.z + b.d * 0.2, 0.03, 0.4, 0.03, p.lamp);
      return;
    }

    case 'tour': {
      // Couronne au sommet, socle vitré élargi, marquise.
      for (const part of b.parts) parapet(batch, part, p.trim, 0.12, 0.08);
      batch.box(top.x, top.y0 + top.h + 0.12, top.z, top.w * 0.55, 0.3, top.d * 0.55, p.stone);
      const base = b.parts[0]!;
      // Socle : en pierre dans le rendu réaliste, vitré ailleurs.
      batch.box(
        base.x,
        0,
        base.z,
        base.w + 0.3,
        floorH * 1.4,
        base.d + 0.3,
        pal.lush ? p.stone : p.glass,
      );
      batch.box(base.x, floorH * 1.4, base.z, base.w + 0.36, 0.05, base.d + 0.36, p.trim);
      if (toon) {
        // Hélisurface sur la couronne : disque sombre, cercle jaune.
        const y = top.y0 + top.h + 0.42;
        const radius = Math.min(top.w, top.d) * 0.22;
        batch.cylinder(top.x, y, top.z, radius, 0.03, 0x3a3f4f, 20);
        batch.cylinder(top.x, y + 0.03, top.z, radius * 0.7, 0.005, 0xf2c230, 20);
        batch.cylinder(top.x, y + 0.036, top.z, radius * 0.6, 0.005, 0x3a3f4f, 20);
      }
      return;
    }

    case 'hotel': {
      // Acrotère, grande marquise, enseigne de toit sans texte (les mots coûtent cher).
      parapet(batch, top, p.trim, 0.09);
      if (toon && r(40) < 0.45) roofGarden(batch, top, p, b.id);
      const mw = Math.min(1.4, b.w * 0.5);
      const marquee = pal.lush
        ? (pickFor(DISTRICT_STYLE[b.district].awnings, b.id, 9) ?? p.awnings[0]!)
        : p.awnings[0]!;
      batch.box(b.x, floorH * 0.85, f.z + f.s * 0.3, mw, 0.07, 0.6, marquee);
      for (const dx of [-mw / 2 + 0.05, mw / 2 - 0.05])
        batch.box(b.x + dx, 0, f.z + f.s * 0.56, 0.04, floorH * 0.85, 0.04, p.trim);
      if (pal.lush) return;
      const sx = b.x + (r(2) - 0.5) * b.w * 0.3;
      for (const dx of [-0.35, 0.35])
        batch.box(sx + dx, b.h, f.z - f.s * 0.2, 0.04, 0.4, 0.04, p.lamp);
      batch.box(sx, b.h + 0.4, f.z - f.s * 0.2, 0.9, 0.3, 0.05, p.awnings[0]!);
      return;
    }

    case 'motel': {
      // Coursive à l'étage tout le long de la façade, poteaux, enseigne de bord de route.
      const cz = f.z + f.s * 0.22;
      batch.box(b.x, floorH, cz, b.w, 0.05, 0.44, p.trim);
      batch.box(b.x, b.h, cz, b.w + 0.1, 0.04, 0.5, p.roofs.motel);
      for (let x = b.x - b.w / 2 + 0.1; x < b.x + b.w / 2; x += 0.7)
        batch.box(x, 0, cz + f.s * 0.2, 0.035, b.h, 0.035, p.trim);
      batch.box(b.x, floorH + 0.05, cz + f.s * 0.21, b.w, 0.08, 0.015, p.trim);
      const sx = b.x + (r(2) < 0.5 ? -1 : 1) * (b.w / 2 - 0.2);
      batch.box(sx, 0, f.z + f.s * 1.1, 0.06, 1.25, 0.06, p.lamp);
      batch.box(
        sx,
        1.0,
        f.z + f.s * 1.1,
        0.7,
        0.32,
        0.07,
        p.awnings[Math.floor(r(3) * p.awnings.length)] ?? p.awnings[0]!,
      );
      return;
    }

    case 'entrepot': {
      // Lanterneaux sur le toit, quai de chargement, bureau accolé.
      const roofH = roofHeight(b);
      const vents = Math.max(2, Math.floor(b.w / 1.6));
      for (let i = 0; i < vents; i++) {
        const x = b.x - b.w / 2 + ((i + 0.5) * b.w) / vents;
        batch.box(x, b.h + roofH * 0.7, b.z, 0.32, 0.18, 0.32, p.stone);
      }
      batch.box(b.x, 0, f.z + f.s * 0.18, b.w * 0.82, 0.18, 0.36, p.quay);
      const ox = b.x + (r(2) < 0.5 ? -1 : 1) * (b.w / 2 - 0.5);
      batch.box(ox, 0, f.z + f.s * 0.2, 0.9, Math.min(b.h * 0.7, 0.75), 0.4, p.walls.residence);
      return;
    }
  }
}
