export const REAL_DAY_MS = 24 * 60 * 60 * 1000;

/** Horloge du jeu : le temps réel, ou une version accélérée pour les essais. */
export interface GameClock {
  /** Instant du début du jour 0, en millisecondes. */
  startMs: number;
  /** Durée d'un jour de jeu. Temps réel : 24 heures. */
  msPerDay: number;
}

export function realClock(startMs: number): GameClock {
  return { startMs, msPerDay: REAL_DAY_MS };
}

/** Horloge de debug : un jour de jeu dure `secondsPerDay` secondes. */
export function debugClock(startMs: number, secondsPerDay: number): GameClock {
  if (secondsPerDay <= 0) throw new Error('La durée du jour doit être positive');
  return { startMs, msPerDay: secondsPerDay * 1000 };
}

/** Numéro du jour en cours (0 le premier jour). */
export function dayAt(clock: GameClock, nowMs: number): number {
  return Math.max(0, Math.floor((nowMs - clock.startMs) / clock.msPerDay));
}

/** Avancement dans le jour en cours, de 0 à 1. */
export function dayProgress(clock: GameClock, nowMs: number): number {
  const elapsed = Math.max(0, nowMs - clock.startMs);
  return (elapsed % clock.msPerDay) / clock.msPerDay;
}

/** Nombre de jours entiers à faire passer pour rattraper l'horloge. */
export function daysToCatchUp(clock: GameClock, nowMs: number, currentDay: number): number {
  return Math.max(0, dayAt(clock, nowMs) - currentDay);
}
