/**
 * Comptes joueurs (décision du propriétaire : compte obligatoire ; e-mail et mot de passe, lien
 * magique, Google, Apple). Appels directs au service de comptes de Supabase, sans bibliothèque.
 * La session (jetons) est gardée sur l'appareil ; le mot de passe ne l'est jamais.
 */

export type OAuthProvider = 'google' | 'apple';

export interface AuthSession {
  accessToken: string;
  refreshToken: string;
  /** Fin de validité du jeton d'accès, en millisecondes. */
  expiresAt: number;
  email: string;
  userId: string;
}

export type AuthError =
  | 'invalid'
  | 'unconfirmed'
  | 'exists'
  | 'weak'
  | 'rate'
  | 'provider'
  | 'email'
  | 'network'
  | 'unknown';

const STORE_KEY = 'mb-auth';
const URL_BASE = import.meta.env.VITE_MB_URL ?? '';
const KEY = import.meta.env.VITE_MB_KEY ?? '';

export function authAvailable(): boolean {
  return URL_BASE !== '' && KEY !== '';
}

/** Adresse de retour après un lien reçu par e-mail ou une connexion Google ou Apple. */
function returnUrl(): string {
  return `${location.origin}${location.pathname}`;
}

function load(): AuthSession | null {
  try {
    const raw = localStorage.getItem(STORE_KEY);
    return raw ? (JSON.parse(raw) as AuthSession) : null;
  } catch {
    return null;
  }
}

function save(session: AuthSession | null): void {
  try {
    if (session) localStorage.setItem(STORE_KEY, JSON.stringify(session));
    else localStorage.removeItem(STORE_KEY);
  } catch {
    /* Stockage indisponible : la session ne durera que le temps de la page. */
  }
  current = session;
}

let current: AuthSession | null = load();

export function currentSession(): AuthSession | null {
  return current;
}

interface TokenReply {
  access_token?: string;
  refresh_token?: string;
  expires_in?: number;
  user?: { id: string; email?: string };
  id?: string;
  email?: string;
  error?: string;
  error_code?: string;
  error_description?: string;
  msg?: string;
  code?: number;
}

function errorOf(reply: TokenReply, status: number): AuthError {
  const text =
    `${reply.error_code ?? ''} ${reply.error ?? ''} ${reply.error_description ?? ''} ${reply.msg ?? ''}`.toLowerCase();
  if (status === 429 || text.includes('rate')) return 'rate';
  if (text.includes('not confirmed')) return 'unconfirmed';
  if (text.includes('already') || text.includes('exists')) return 'exists';
  if (text.includes('password') && (text.includes('weak') || text.includes('least'))) return 'weak';
  if (text.includes('provider') || text.includes('not enabled')) return 'provider';
  if (text.includes('email') && (text.includes('invalid') || text.includes('format')))
    return 'email';
  if (text.includes('invalid') || text.includes('credentials')) return 'invalid';
  return 'unknown';
}

async function call(
  path: string,
  body: unknown,
  token?: string,
  method = 'POST',
): Promise<{ ok: boolean; reply: TokenReply; status: number }> {
  try {
    const response = await fetch(`${URL_BASE}/auth/v1/${path}`, {
      method,
      headers: {
        apikey: KEY,
        Authorization: `Bearer ${token ?? KEY}`,
        'Content-Type': 'application/json',
      },
      body: body === undefined ? undefined : JSON.stringify(body),
    });
    const text = await response.text();
    const reply = (text ? JSON.parse(text) : {}) as TokenReply;
    return { ok: response.ok, reply, status: response.status };
  } catch {
    return { ok: false, reply: {}, status: 0 };
  }
}

function sessionFrom(reply: TokenReply): AuthSession | null {
  if (!reply.access_token || !reply.refresh_token || !reply.user) return null;
  return {
    accessToken: reply.access_token,
    refreshToken: reply.refresh_token,
    expiresAt: Date.now() + (reply.expires_in ?? 3600) * 1000,
    email: reply.user.email ?? '',
    userId: reply.user.id,
  };
}

export type AuthResult =
  { ok: true; session: AuthSession | null } | { ok: false; error: AuthError };

function fail(status: number, reply: TokenReply): AuthResult {
  return { ok: false, error: status === 0 ? 'network' : errorOf(reply, status) };
}

/** Inscription : un e-mail de confirmation est envoyé (session nulle jusqu'à la confirmation). */
export async function signUp(email: string, password: string): Promise<AuthResult> {
  const { ok, reply, status } = await call(
    `signup?redirect_to=${encodeURIComponent(returnUrl())}`,
    { email, password },
  );
  if (!ok) return fail(status, reply);
  const session = sessionFrom(reply);
  if (session) save(session);
  return { ok: true, session };
}

export async function signIn(email: string, password: string): Promise<AuthResult> {
  const { ok, reply, status } = await call('token?grant_type=password', { email, password });
  if (!ok) return fail(status, reply);
  const session = sessionFrom(reply);
  if (session) save(session);
  return session ? { ok: true, session } : { ok: false, error: 'unknown' };
}

/** Lien magique : un lien de connexion est envoyé par e-mail (le compte est créé au besoin). */
export async function sendMagicLink(email: string): Promise<AuthResult> {
  const { ok, reply, status } = await call(`otp?redirect_to=${encodeURIComponent(returnUrl())}`, {
    email,
    create_user: true,
  });
  return ok ? { ok: true, session: null } : fail(status, reply);
}

/** Mot de passe oublié : un lien pour en choisir un nouveau est envoyé par e-mail. */
export async function sendReset(email: string): Promise<AuthResult> {
  const { ok, reply, status } = await call(
    `recover?redirect_to=${encodeURIComponent(returnUrl())}`,
    { email },
  );
  return ok ? { ok: true, session: null } : fail(status, reply);
}

/** Nouveau mot de passe, après le lien « mot de passe oublié ». */
export async function setPassword(password: string): Promise<AuthResult> {
  const token = await accessToken();
  if (!token) return { ok: false, error: 'invalid' };
  const { ok, reply, status } = await call('user', { password }, token, 'PUT');
  return ok ? { ok: true, session: current } : fail(status, reply);
}

/** Modes de connexion Google et Apple ouverts dans le projet. */
export async function providersEnabled(): Promise<Record<OAuthProvider, boolean>> {
  try {
    const response = await fetch(`${URL_BASE}/auth/v1/settings`, { headers: { apikey: KEY } });
    const settings = (await response.json()) as { external?: Record<string, boolean> };
    return {
      google: settings.external?.google === true,
      apple: settings.external?.apple === true,
    };
  } catch {
    return { google: false, apple: false };
  }
}

/** Connexion Google ou Apple : la page part chez le fournisseur et revient ici. */
export function startOAuth(provider: OAuthProvider): void {
  location.href = `${URL_BASE}/auth/v1/authorize?provider=${provider}&redirect_to=${encodeURIComponent(returnUrl())}`;
}

/**
 * Au retour d'un lien e-mail ou de Google / Apple, les jetons sont dans l'adresse (#access_token=…).
 * Renvoie le type de retour (« recovery » pour un nouveau mot de passe) ou une erreur.
 */
export async function consumeRedirect(): Promise<{ type: string | null; error: AuthError | null }> {
  const hash = location.hash.startsWith('#') ? location.hash.slice(1) : '';
  const params = new URLSearchParams(hash);
  if (!params.has('access_token') && !params.has('error') && !params.has('error_description'))
    return { type: null, error: null };
  history.replaceState(null, '', `${location.pathname}${location.search}`);
  if (!params.has('access_token')) {
    return {
      type: null,
      error: errorOf({ error_description: params.get('error_description') ?? '' }, 400),
    };
  }
  const token = params.get('access_token')!;
  const { ok, reply } = await call('user', undefined, token, 'GET');
  if (!ok || !(reply.id ?? reply.user?.id)) return { type: null, error: 'invalid' };
  save({
    accessToken: token,
    refreshToken: params.get('refresh_token') ?? '',
    expiresAt: Date.now() + Number(params.get('expires_in') ?? 3600) * 1000,
    email: reply.email ?? reply.user?.email ?? '',
    userId: (reply.id ?? reply.user?.id)!,
  });
  return { type: params.get('type'), error: null };
}

/** Jeton d'accès valide (renouvelé s'il expire bientôt), ou null s'il faut se reconnecter. */
export async function accessToken(): Promise<string | null> {
  if (!current) return null;
  if (current.expiresAt - Date.now() > 60_000) return current.accessToken;
  if (!current.refreshToken) {
    save(null);
    return null;
  }
  const { ok, reply, status } = await call('token?grant_type=refresh_token', {
    refresh_token: current.refreshToken,
  });
  if (!ok) {
    // Réseau coupé : on garde la session pour réessayer ; jeton refusé : il faut se reconnecter.
    if (status !== 0) save(null);
    return status === 0 ? current.accessToken : null;
  }
  const session = sessionFrom(reply);
  if (session) save(session);
  return session?.accessToken ?? null;
}

export async function signOut(): Promise<void> {
  const token = current?.accessToken;
  save(null);
  if (token) await call('logout', {}, token);
}
