export type ThemeId = 'cadastre' | 'nuit';

/** Jetons de couleur d'un thème. Chaque thème doit définir tous les jetons. */
export interface ThemeTokens {
  desk: string;
  paper: string;
  sheet: string;
  ink: string;
  inkSoft: string;
  rule: string;
  stamp: string;
  money: string;
  highlight: string;
  mine: string;
  onInk: string;
}

export const THEME_IDS: readonly ThemeId[] = ['cadastre', 'nuit'];

export const THEMES: Record<ThemeId, ThemeTokens> = {
  cadastre: {
    desk: '#dfe6ef',
    paper: '#eef2f8',
    sheet: '#ffffff',
    ink: '#141b33',
    inkSoft: '#4a5268',
    rule: '#c9d1de',
    stamp: '#c8323c',
    money: '#1f7a4d',
    highlight: '#f4d35e',
    mine: '#2c5fc4',
    onInk: '#ffffff',
  },
  nuit: {
    desk: '#07090e',
    paper: '#10141d',
    sheet: '#1a202c',
    ink: '#e8ebf2',
    inkSoft: '#a2a9b9',
    rule: '#333b4b',
    stamp: '#ff6b5b',
    money: '#52c48d',
    highlight: '#f5c518',
    mine: '#6f97ff',
    onInk: '#10141d',
  },
};

export function isThemeId(value: unknown): value is ThemeId {
  return value === 'cadastre' || value === 'nuit';
}

/** Choisit le thème de départ : choix enregistré, sinon réglage sombre de l'appareil. */
export function detectTheme(stored: string | null, prefersDark: boolean): ThemeId {
  if (isThemeId(stored)) return stored;
  return prefersDark ? 'nuit' : 'cadastre';
}

function cssName(token: string): string {
  return '--' + token.replace(/[A-Z]/g, (c) => '-' + c.toLowerCase());
}

/** Variables CSS d'un thème, par exemple { '--ink-soft': '#4a5268' }. */
export function themeCssVariables(id: ThemeId): Record<string, string> {
  const out: Record<string, string> = {};
  for (const [token, value] of Object.entries(THEMES[id])) out[cssName(token)] = value;
  return out;
}

export function applyTheme(id: ThemeId, root: HTMLElement = document.documentElement): void {
  for (const [name, value] of Object.entries(themeCssVariables(id))) {
    root.style.setProperty(name, value);
  }
  root.dataset.theme = id;
  root.style.colorScheme = id === 'nuit' ? 'dark' : 'light';
  document.querySelector('meta[name="theme-color"]')?.setAttribute('content', THEMES[id].paper);
}
