import type { BuildingType, DistrictId, Rect, RoofKind } from '../model';

/**
 * Agrandissement de la ville par rapport au plan de référence. Le plan est dessiné en pixels
 * (900 × 600) ; à l'échelle 1, 1 pixel = 0,2 unité = 2 mètres. Les quartiers grandissent, mais les
 * îlots, les rues et les avenues gardent leur taille réelle : la ville compte donc plus d'îlots.
 */
export const CITY_SCALE = 4;
export const WORLD_SCALE = 0.2 * CITY_SCALE;
export const worldX = (px: number): number => (px - 450) * WORLD_SCALE;
export const worldZ = (py: number): number => (py - 300) * WORLD_SCALE;

/** Demi-largeur d'une avenue, en unités (20 m de large). */
const AVENUE_HALF = 1;
/** Sur le plan, les avenues font 10 pixels : on garde leur axe, pas leur largeur agrandie. */
const AVENUE_PX = 10;
const lowX = (px: number): number => worldX(px - AVENUE_PX / 2) + AVENUE_HALF;
const highX = (px: number): number => worldX(px + AVENUE_PX / 2) - AVENUE_HALF;
const lowZ = (py: number): number => worldZ(py - AVENUE_PX / 2) + AVENUE_HALF;
const highZ = (py: number): number => worldZ(py + AVENUE_PX / 2) - AVENUE_HALF;

/** Rectangle d'un quartier : ses bords s'arrêtent au bord des avenues qui l'entourent. */
function planRect(x: number, y: number, w: number, h: number): Rect {
  return { x0: lowX(x), z0: lowZ(y), x1: highX(x + w), z1: highZ(y + h) };
}

/** Avenue relevée sur le plan : même axe, largeur réelle constante. */
function avenueRect(x: number, y: number, w: number, h: number, horizontal: boolean): Rect {
  if (horizontal) {
    const z = worldZ(y + h / 2);
    return { x0: lowX(x), x1: highX(x + w), z0: z - AVENUE_HALF, z1: z + AVENUE_HALF };
  }
  const x0 = worldX(x + w / 2);
  return { x0: x0 - AVENUE_HALF, x1: x0 + AVENUE_HALF, z0: lowZ(y), z1: highZ(y + h) };
}

export interface TypeChoice {
  type: BuildingType;
  weight: number;
  floors: [number, number];
}

export interface DistrictDef {
  id: DistrictId;
  /** Code de section cadastrale. */
  code: string;
  rect: Rect;
  /** Taille visée d'un îlot (largeur est-ouest, profondeur nord-sud). */
  blockW: number;
  blockD: number;
  /** Largeur visée d'une parcelle sur rue. */
  lot: number;
  types: TypeChoice[];
  /** Part des parcelles bâties. */
  density: number;
  /** Part des îlots transformés en parc. */
  park: number;
  streetTrees: boolean;
  priceMult: number;
  /** Loyer par jour, en part du prix. */
  rentRate: number;
  /** Risque de coups bas de 0 (protégé) à 5. */
  risk: number;
}

