export interface TypeSpec {
  /** Hauteur d'un étage, en unités. */
  floorH: number;
  /** Part de la largeur de parcelle occupée. */
  fillW: [number, number];
  /** Part de la profondeur de parcelle occupée. */
  fillD: [number, number];
  /** Recul par rapport à la rue. */
  setback: number;
  roof: RoofKind;
  /**
   * Prix de base du type, en ducats (document de conception : maison 300 000, motel 600 000,
   * immeuble 1 000 000, hôtel 5 000 000 ; les autres sont des valeurs par défaut, voir
   * docs/QUESTIONS.md). Prix réel = base × quartier × emplacement × taille.
   */
  basePrice: number;
}

