function hash(n: number, salt: number): number {
  let h = Math.imul(n ^ (salt * 2654435761), 2246822519);
  h = Math.imul(h ^ (h >>> 13), 3266489917);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}

/** Accumule des faces planes : positions (repère du jeu), normales, coordonnées de texture. */
class Builder {
  positions: number[] = [];
  normals: number[] = [];
  uvs: number[] = [];
  indices: number[] = [];

  constructor(private readonly scale: number) {}

  /** Polygone plan (3 ou 4 points, en cm dans le repère Blender), sens trigonométrique. */
  face(points: number[][]): void {
    const [a, b, c] = points as [number[], number[], number[]];
    const ux = b[0]! - a[0]!;
    const uy = b[1]! - a[1]!;
    const uz = b[2]! - a[2]!;
    const vx = c[0]! - a[0]!;
    const vy = c[1]! - a[1]!;
    const vz = c[2]! - a[2]!;
    let nx = uy * vz - uz * vy;
    let ny = uz * vx - ux * vz;
    let nz = ux * vy - uy * vx;
    const len = Math.hypot(nx, ny, nz);
    if (len < 1e-6) return;
    nx /= len;
    ny /= len;
    nz /= len;
    // Projection « boîte », comme dans Blender : l'axe dominant de la normale choisit le plan.
    const ax = Math.abs(nx);
    const ay = Math.abs(ny);
    const az = Math.abs(nz);
    const base = this.positions.length / 3;
    for (const p of points) {
      const [x, y, z] = p as [number, number, number];
      this.positions.push(x * CM, z * CM, -y * CM);
      this.normals.push(nx, nz, -ny);
      const s = this.scale * 0.01;
      if (ax >= ay && ax >= az) this.uvs.push(y * s, z * s);
      else if (ay >= az) this.uvs.push(x * s, z * s);
      else this.uvs.push(x * s, y * s);
    }
    this.indices.push(base, base + 1, base + 2);
    if (points.length === 4) this.indices.push(base, base + 2, base + 3);
  }

  get triangles(): number {
    return this.indices.length / 3;
  }

  geometry(): THREE.BufferGeometry {
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(this.positions, 3));
    g.setAttribute('normal', new THREE.Float32BufferAttribute(this.normals, 3));
    g.setAttribute('uv', new THREE.Float32BufferAttribute(this.uvs, 2));
    g.setIndex(this.indices);
    return g;
  }
}

/** Boîte : faces visibles d'en haut et de face seulement (comme à l'export). */
function addBox(b: Builder, c: ArrayLike<number>): void {
  const [x0, y0, z0, x1, y1, z1] = [c[0]!, c[1]!, c[2]!, c[3]!, c[4]!, c[5]!];
  b.face([
    [x0, y0, z0],
    [x1, y0, z0],
    [x1, y0, z1],
    [x0, y0, z1],
  ]);
  if (!(y1 <= 120 && y0 < 90))
    b.face([
      [x1, y1, z0],
      [x0, y1, z0],
      [x0, y1, z1],
      [x1, y1, z1],
    ]);
  b.face([
    [x0, y1, z0],
    [x0, y0, z0],
    [x0, y0, z1],
    [x0, y1, z1],
  ]);
  b.face([
    [x1, y0, z0],
    [x1, y1, z0],
    [x1, y1, z1],
    [x1, y0, z1],
  ]);
  b.face([
    [x0, y0, z1],
    [x1, y0, z1],
    [x1, y1, z1],
    [x0, y1, z1],
  ]);
}

const GLASSES = new Set(['vitre', 'mur_rideau']);

/**
 * Finition Liquid Glass des murs, sans toucher aux formes : couleurs un peu plus franches, et un
 * liseré de lumière laiteuse sur les bords des volumes (reflet rasant, plus fort vers le haut).
 */
/** Détails par pixel (salissures, relief des textures) : vue Rue seulement. */
const LG_DETAIL = { value: 1 };

function liquidGlass(material: THREE.MeshStandardMaterial): void {
  material.onBeforeCompile = (shader) => {
    shader.uniforms.lgDetail = LG_DETAIL;
    shader.vertexShader = shader.vertexShader
      .replace(
        '#include <common>',
        `#include <common>
        varying vec3 vLgWorld;
        varying float vLgHeight;`,
      )
      .replace(
        '#include <project_vertex>',
        `#include <project_vertex>
        #ifdef USE_BATCHING
          vLgWorld = (modelMatrix * batchingMatrix * vec4(transformed, 1.0)).xyz;
        #elif defined(USE_INSTANCING)
          vLgWorld = (modelMatrix * instanceMatrix * vec4(transformed, 1.0)).xyz;
        #else
          vLgWorld = (modelMatrix * vec4(transformed, 1.0)).xyz;
        #endif
        vLgHeight = transformed.y;`,
      );
    shader.fragmentShader = shader.fragmentShader
      .replace(
        '#include <common>',
        `#include <common>
        varying vec3 vLgWorld;
        varying float vLgHeight;
        uniform float lgDetail;
        float lgHash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
        float lgNoise(vec2 p) {
          vec2 i = floor(p); vec2 f = fract(p); f = f * f * (3.0 - 2.0 * f);
          return mix(mix(lgHash(i), lgHash(i + vec2(1, 0)), f.x),
                     mix(lgHash(i + vec2(0, 1)), lgHash(i + vec2(1, 1)), f.x), f.y);
        }`,
      )
      .replace(
        '#include <color_fragment>',
        `#include <color_fragment>
        float lgLum = dot(diffuseColor.rgb, vec3(0.2126, 0.7152, 0.0722));
        diffuseColor.rgb = max(mix(vec3(lgLum), diffuseColor.rgb, 1.15), 0.0);
        // Vécu des façades (contre l'effet « carton ») : 1 unité = 10 m.
        float lgAlong = vLgWorld.x + vLgWorld.z;
        // Vue Quartier : sans salissures (invisibles de haut, coûteuses par pixel).
        if (lgDetail > 0.5) {
        // Coulures verticales, étirées vers le bas.
        float lgStreak = lgNoise(vec2(lgAlong * 9.0, vLgWorld.y * 0.9));
        // Taches et variations de teinte, à grande échelle.
        float lgBlotch = lgNoise(vec2(lgAlong * 1.3, vLgWorld.y * 1.1)) * 0.6
          + lgNoise(vec2(lgAlong * 4.0 + 7.0, vLgWorld.y * 3.0)) * 0.4;
        float lgDirt = 0.9 + 0.1 * lgStreak + (lgBlotch - 0.5) * 0.14;
        // Pied de façade encrassé (éclaboussures, pollution), sur les 4 premiers mètres.
        lgDirt *= mix(0.78, 1.0, smoothstep(0.0, 0.4, vLgHeight));
        diffuseColor.rgb *= lgDirt;
        }
        // Légère chaleur de la lumière en haut, froideur en bas.
        diffuseColor.rgb *= mix(vec3(0.95, 0.97, 1.02), vec3(1.02, 1.01, 0.98), smoothstep(0.0, 3.0, vLgHeight));`,
      )
      .replace(
        '#include <opaque_fragment>',
        `// Recoins : faces tournées vers le bas ou à l'horizontale, près du sol, plus sombres.
        vec3 lgN = normalize((vec4(normal, 0.0) * viewMatrix).xyz);
        outgoingLight *= mix(0.86, 1.0, clamp(lgN.y * 0.5 + 0.5, 0.0, 1.0));
        // Modelé : faces au soleil plus franches, faces à l'ombre plus profondes (le volume se lit).
        float lgSun = dot(lgN, normalize(vec3(-80.0, 75.0, 55.0)));
        outgoingLight *= mix(0.74, 1.1, smoothstep(-0.6, 0.8, lgSun));
        float lgFacing = clamp(dot(normal, normalize(vViewPosition)), 0.0, 1.0);
        float lgRim = pow(1.0 - lgFacing, 3.0);
        outgoingLight += vec3(0.86, 0.92, 1.0) * lgRim * 0.18;
        #include <opaque_fragment>`,
      );
  };
  material.customProgramCacheKey = () => 'nyc-liquid-glass-2';
}

/** Matériaux du jeu à partir du catalogue : textures neutres teintées par instance. */
function makeMaterials(): THREE.MeshStandardMaterial[] {
  const loader = new THREE.TextureLoader();
  const texture = (file: string, color: boolean): THREE.Texture | null => {
    const url = TEXTURES[`./models/nyc/tex/${file}.jpg`];
    if (!url) return null;
    const t = loader.load(url);
    t.wrapS = t.wrapT = THREE.RepeatWrapping;
    t.colorSpace = color ? THREE.SRGBColorSpace : THREE.NoColorSpace;
    t.anisotropy = 4;
    return t;
  };
  return CATALOG.materials.map((m) => {
    const material = new THREE.MeshStandardMaterial({
      color: m.texture || m.paint ? 0xffffff : new THREE.Color(m.color),
      roughness: m.rough,
      metalness: m.metal,
    });
    if (m.texture) {
      // Essai Riviera : plus de brique, les murs de brique prennent la texture d'enduit lisse.
      const file = m.name === 'mur_brique' ? 'mur_enduit' : m.name;
      material.map = texture(file, true);
      material.normalMap = texture(`${file}_nor`, false);
      material.normalScale.set(1.5, 1.5);
    }
    if (m.emissive) {
      material.emissive = new THREE.Color(m.emissive);
      material.emissiveIntensity = m.emissiveIntensity;
    }
    // Vitres : sans reflet du ciel dans le jeu, le noir de Blender paraît troué ; un bleu-gris
    // un peu brillant les fait lire comme des vitres.
    if (GLASSES.has(m.name)) {
      // Essai Riviera : vitres plus claires, qui renvoient le ciel.
      material.color = new THREE.Color(m.name === 'vitre' ? 0x6f8fae : 0x7d9cbb);
      material.metalness = 0.35;
      material.roughness = 0.2;
    }
    // Toits plats : gris laiteux au lieu du goudron sombre (Liquid Glass).
    if (m.name === 'toit') material.color = new THREE.Color(2.3, 2.35, 2.45);
    if (!GLASSES.has(m.name)) liquidGlass(material);
    material.name = `nyc-${m.name}`;
    return material;
  });
}

export class NycBuildings {
  readonly group = new THREE.Group();
  private prototypes: Prototype[] = [];
  private pools: InstancePool[] = [];
  private materials: THREE.MeshStandardMaterial[] = [];
  /** Bâtiments posés en complet, par numéro de bâtiment. */
  private placed = new Map<number, Placed>();
  /** Bâtiments du jeu actuellement remplacés par un vrai modèle. */
  shown = new Set<number>();
  /** Silhouettes (vues dézoomées), posées une fois pour toute la ville. */
  private farReady = false;
  private farModels: FarModel[] = [];
  private farPools: { walls: InstancePool; roofs: InstancePool }[] = [];
  private readonly farIds = new Map<number, { slot: Slot; proto: Prototype; roof: boolean }[]>();
  private ready = false;
  private lastX = Infinity;
  private lastZ = Infinity;
  private lastRadius = 0;
  private lastTarget = 0;

  constructor(
    private readonly city: City,
    private readonly statusOf: (b: Building) => BuildingStatus,
    private readonly onChange: (shown: Set<number>) => void,
    private readonly night = false,
  ) {
    this.group.name = 'nyc-buildings';
    void this.load();
  }

  private async load(): Promise<void> {
    const data = new Int16Array(await (await fetch(BIN_URL)).arrayBuffer());
    const specs = CATALOG.materials;
    const id = (name: string): number => specs.findIndex((m) => m.name === name);
    const GLASS = id('vitre');
    const LIT = id('fenetre_allumee');
    const BLINDS = [id('store_clair'), id('store_sombre')];

    // Géométries de chaque variante, par matériau.
    /**
     * Version allégée (vue Quartier, au-delà du premier plan) : mêmes volumes et fenêtres
     * creusées, sans les pièces de quelques centimètres ni les cadres et stores des fenêtres.
     */
    const SMALL = 25;
    const small = (c: ArrayLike<number>): boolean => {
      const d = [Math.abs(c[3]! - c[0]!), Math.abs(c[4]! - c[1]!), Math.abs(c[5]! - c[2]!)].sort(
        (a, b) => a - b,
      );
      return d[1]! < SMALL;
    };
    const buildVariant = (v: (typeof CATALOG.variants)[number], lite: boolean) => {
      const builders = new Map<number, Builder>();
      const of = (m: number): Builder => {
        let b = builders.get(m);
        if (!b) builders.set(m, (b = new Builder(specs[m]?.scale ?? 1)));
        return b;
      };
      let i = v.start;
      while (i < v.end) {
        const kind = data[i]!;
        const m = data[i + 1]!;
        if (kind === 1) {
          const c = data.subarray(i + 2, i + 8);
          if (!lite || !small(c)) addBox(of(m), c);
          i += 8;
        } else if (kind === 2) {
          // Fenêtre allégée : tableaux, appui, vitre, cadre, traverse, store éventuel.
          const [x0, zs, x1, zt, y, trim, k] = Array.from(data.subarray(i + 2, i + 9)) as [
            number,
            number,
            number,
            number,
            number,
            number,
            number,
          ];
          const wall = of(m);
          wall.face([
            [x0, 0, zs],
            [x0, y, zs],
            [x0, y, zt],
            [x0, 0, zt],
          ]);
          wall.face([
            [x1, y, zs],
            [x1, 0, zs],
            [x1, 0, zt],
            [x1, y, zt],
          ]);
          wall.face([
            [x0, 0, zs],
            [x1, 0, zs],
            [x1, y, zs],
            [x0, y, zs],
          ]);
          of(k === 5 ? LIT : GLASS).face([
            [x0, y, zs],
            [x1, y, zs],
            [x1, y, zt],
            [x0, y, zt],
          ]);
          if (lite) {
            i += 9;
            continue;
          }
          const t = 7;
          const yf = y - 2;
          const frame = of(trim);
          for (const [a, b, c, d] of [
            [x0, x1, zs, zs + t],
            [x0, x1, zt - t, zt],
            [x0, x0 + t, zs, zt],
            [x1 - t, x1, zs, zt],
          ] as const)
            frame.face([
              [a, yf, c],
              [b, yf, c],
              [b, yf, d],
              [a, yf, d],
            ]);
          const zm = (zs + zt) / 2;
          frame.face([
            [x0, yf - 1, zm - 4],
            [x1, yf - 1, zm - 4],
            [x1, yf - 1, zm + 4],
            [x0, yf - 1, zm + 4],
          ]);
          if (k < 4) {
            const drop = 0.3 + ((k * 0.17) % 0.6);
            const zb = zt - t - (zt - zs) * drop;
            of(BLINDS[k % 2]!).face([
              [x0 + t, y - 0.5, zb],
              [x1 - t, y - 0.5, zb],
              [x1 - t, y - 0.5, zt - t],
              [x0 + t, y - 0.5, zt - t],
            ]);
          }
          i += 9;
        } else {
          const n = data[i + 2]!;
          if (lite) {
            // Forme quelconque : omise si elle est petite (pieds, mâts, rampes).
            let x0 = 1e9,
              y0 = 1e9,
              z0 = 1e9,
              x1 = -1e9,
              y1 = -1e9,
              z1 = -1e9;
            for (let t = 0; t < n * 3; t++) {
              const o = i + 3 + t * 3;
              x0 = Math.min(x0, data[o]!);
              x1 = Math.max(x1, data[o]!);
              y0 = Math.min(y0, data[o + 1]!);
              y1 = Math.max(y1, data[o + 1]!);
              z0 = Math.min(z0, data[o + 2]!);
              z1 = Math.max(z1, data[o + 2]!);
            }
            if (small([x0, y0, z0, x1, y1, z1])) {
              i += 3 + n * 9;
              continue;
            }
          }
          const b = of(m);
          for (let t = 0; t < n; t++) {
            const o = i + 3 + t * 9;
            b.face([
              [data[o]!, data[o + 1]!, data[o + 2]!],
              [data[o + 3]!, data[o + 4]!, data[o + 5]!],
              [data[o + 6]!, data[o + 7]!, data[o + 8]!],
            ]);
          }
          i += 3 + n * 9;
        }
      }
      return builders;
    };
    const built = CATALOG.variants.map((v) => buildVariant(v, false));
    const builtLite = CATALOG.variants.map((v) => buildVariant(v, true));

    // Un lot (un ordre de dessin) par modèle et par matière.
    this.materials = makeMaterials();
    const pool = (g: THREE.BufferGeometry, m: number): InstancePool => {
      const p = new InstancePool(g, this.materials[m]!, this.group);
      this.pools.push(p);
      return p;
    };
    this.prototypes = CATALOG.variants.map((v, n) => {
      const builders = built[n]!;
      const [minX, minY, maxX, maxY] = v.box as [number, number, number, number];
      const tints = new Map<number, THREE.Color>();
      specs.forEach((m, index) => {
        if (m.paint) tints.set(index, new THREE.Color(v.tints[m.name] ?? '#cccccc'));
      });
      const parts: Part[] = [];
      let triangles = 0;
      builders.forEach((b, m) => {
        triangles += b.triangles;
        parts.push({ material: m, pool: pool(b.geometry(), m) });
      });
      const partsLite: Part[] = [];
      let trianglesLite = 0;
      builtLite[n]!.forEach((b, m) => {
        if (b.triangles === 0) return;
        trianglesLite += b.triangles;
        partsLite.push({ material: m, pool: pool(b.geometry(), m) });
      });
      return {
        index: n,
        name: v.name,
        family: v.family as Family,
        height: v.height,
        width: (maxX - minX) * CM,
        depth: Math.max(1, maxY) * CM,
        centerX: ((minX + maxX) / 2) * CM,
        front: Math.max(0, -minY) * CM,
        tints,
        parts,
        triangles,
        lite: { parts: partsLite, triangles: trianglesLite },
      };
    });
    this.placeFar(data);
    this.ready = true;
    this.setEnvironment(this.environment);
  }

  /**
   * Toute la ville en bâtiments faits main (demande du propriétaire) : la silhouette de chaque
   * bâtiment est posée une fois ; la version complète la remplace près de la caméra.
   */
  private placeFar(data: Int16Array): void {
    const specs = CATALOG.materials;
    const name = (m: number): string => specs[m]?.name ?? '';
    const paint = (m: number): boolean => !!specs[m]?.paint && name(m).startsWith('mur_');
    const roles = {
      paint,
      wallLike: (m: number) => paint(m) || ['allege', 'mur_rideau'].includes(name(m)),
      pitched: (m: number) => ['toit_tuile', 'ardoise'].includes(name(m)),
      curtain: specs.findIndex((m) => m.name === 'mur_rideau'),
    };
    this.farModels = CATALOG.variants.map((v) => buildFar(data, v.start, v.end, roles));
    const plans = this.city.buildings.map((b) => this.plan(b));
    const wallMaterial = farWallMaterial(this.night);
    const roofMaterial = farRoofMaterial(this.night);
    this.farPools = this.farModels.map((m) => {
      const walls = new InstancePool(m.walls, wallMaterial, this.group, 64);
      const roofs = new InstancePool(m.roofs, roofMaterial, this.group, 64);
      this.pools.push(walls, roofs);
      return { walls, roofs };
    });
    const white = new THREE.Color(0xffffff);
    plans.forEach((plan, i) => {
      const b = this.city.buildings[i]!;
      const ids: { slot: Slot; proto: Prototype; roof: boolean }[] = [];
      for (const { proto, matrix } of plan)
        for (const roof of [false, true]) {
          const pools = this.farPools[proto.index]!;
          ids.push({ slot: (roof ? pools.roofs : pools.walls).add(matrix, white), proto, roof });
        }
      this.farIds.set(b.id, ids);
      this.paintFar(b);
    });
    this.farReady = true;
    // Les anciens volumes carrés disparaissent partout.
    this.shown = new Set(this.city.buildings.map((b) => b.id));
    this.onChange(this.shown);
  }

  /** Montre ou masque la silhouette d'un bâtiment. */
  private setFar(id: number, visible: boolean): void {
    for (const { slot } of this.farIds.get(id) ?? [])
      if (visible) slot.pool.show(slot);
      else slot.pool.hide(slot);
  }

  /** Couleurs de la silhouette : mur du quartier, toit de tuile ou d'ardoise, statut. */
  private paintFar(b: Building): void {
    const status = new THREE.Color(STATUS_TINT[this.statusOf(b)] ?? 0xffffff);
    const color = new THREE.Color();
    for (const { slot, proto, roof } of this.farIds.get(b.id) ?? []) {
      const model = this.farModels[proto.index]!;
      if (roof) {
        if (model.roofMaterial === null) color.setHex(0x9aa6b4);
        else if (proto.tints.has(model.roofMaterial))
          this.colorFor(model.roofMaterial, proto, b, color);
        else color.setHex(0x74808f);
      } else if (model.curtain) color.setHex(0x7d9cbb);
      else if (model.wallMaterial === null) color.setHex(0x9aa3ad);
      else this.colorFor(model.wallMaterial, proto, b, color);
      slot.pool.setColor(slot, color.multiply(status));
    }
  }

  /**
   * Vue Quartier et Rue : tous les bâtiments dans le champ de la caméra sont complets (demande
   * du propriétaire) ; vue Ville : silhouettes partout. Mise à jour par différence : seuls les
   * bâtiments qui entrent ou sortent du champ sont posés ou retirés.
   */
  update(camera: THREE.Camera, radius: number, enabled: boolean): void {
    if (!this.ready) return;
    const target = enabled ? radius : 0;
    camera.updateMatrixWorld();
    const key = camera.matrixWorld.elements;
    const moved =
      Math.hypot(key[12]! - this.lastX, key[14]! - this.lastZ) > Math.max(1, radius * 0.04) ||
      Math.abs(key[8]! + key[10]! * 7 - this.lastRadius) > 0.02 ||
      Math.abs(target - this.lastTarget) > 2;
    if (!moved) return;
    this.lastX = key[12]!;
    this.lastZ = key[14]!;
    this.lastRadius = key[8]! + key[10]! * 7;
    this.lastTarget = target;

    // Bâtiments voulus en complet : dans le champ et à moins de `radius`. Au premier plan, le
    // modèle entier ; au-delà, sa version allégée (identique à cette distance).
    const wanted = new Map<number, boolean>();
    if (target > 0) {
      const frustum = new THREE.Frustum().setFromProjectionMatrix(
        new THREE.Matrix4().multiplyMatrices(
          (camera as THREE.PerspectiveCamera).projectionMatrix,
          camera.matrixWorldInverse,
        ),
      );
      const sphere = new THREE.Sphere();
      const cx = key[12]!;
      const cy = key[13]!;
      const cz = key[14]!;
      const near = this.city.buildings
        .map((b) => ({ b, d: Math.hypot(b.x - cx, b.z - cz) }))
        .filter((e) => e.d < target)
        .filter(({ b }) => {
          sphere.center.set(b.x, b.h / 2, b.z);
          sphere.radius = Math.hypot(b.w, b.d, b.h) * 0.6 + 0.5;
          return frustum.intersectsSphere(sphere);
        })
        .sort((a, c) => a.d - c.d);
      let triangles = 0;
      let instances = 0;
      for (const { b, d } of near) {
        const lite = Math.hypot(d, cy - b.h / 2) > DETAIL_DISTANCE;
        const plan = this.plan(b);
        const tri = plan.reduce((n, p) => n + (lite ? p.proto.lite : p.proto).triangles, 0);
        const cost = plan.reduce((n, p) => n + (lite ? p.proto.lite : p.proto).parts.length, 0);
        if (triangles + tri > TRIANGLE_BUDGET || instances + cost > INSTANCE_LIMIT) break;
        triangles += tri;
        instances += cost;
        wanted.set(b.id, lite);
      }
    }
    // Retire ceux qui sortent (ou changent de finesse), pose ceux qui entrent.
    for (const [id, p] of this.placed) {
      if (wanted.get(id) === p.lite) continue;
      for (const { slot } of p.ids) slot.pool.hide(slot);
      this.placed.delete(id);
      if (!wanted.has(id)) this.setFar(id, true);
    }
    for (const [id, lite] of wanted) {
      if (this.placed.has(id)) continue;
      const b = this.city.buildings[id]!;
      const entry: Placed = { building: id, ids: [], triangles: 0, lite };
      for (const { proto, matrix } of this.plan(b)) {
        const version = lite ? proto.lite : proto;
        entry.triangles += version.triangles;
        for (const part of version.parts) {
          const slot = part.pool.add(matrix, WHITE);
          entry.ids.push({ slot, material: part.material, proto });
        }
      }
      this.placed.set(id, entry);
      this.paint(entry, b);
      this.setFar(id, false);
    }
  }

  /** Variante d'une famille : de hauteur proche de celle du bâtiment, un peu de hasard. */
  private pick(b: Building, family: Family, salt: number, targetMeters: number): Prototype | null {
    const options = this.prototypes
      .filter((p) => p.family === family)
      .map((p) => ({ p, score: Math.abs(Math.log(p.height / Math.max(3, targetMeters))) }))
      .sort((a, c) => a.score - c.score);
    if (options.length === 0) return null;
    const n = Math.min(options.length, 5);
    return options[Math.floor(hash(b.id, salt) * n)]!.p;
  }

  /** Rangée de variantes couvrant la largeur w ; renvoie aussi l'étirement commun. */
  private rowFor(b: Building, w: number, salt: number): { protos: Prototype[]; stretch: number } {
    const families = FAMILIES[b.type];
    const protos: Prototype[] = [];
    let used = 0;
    for (let i = 0; i < 12; i++) {
      const family = families[Math.floor(hash(b.id * 31 + i, salt + 11) * families.length)]!;
      const p = this.pick({ ...b, id: b.id * 31 + i }, family, salt, b.h * 10 * 1.4);
      if (!p) continue;
      if (used > 0 && used + p.width / 2 > w) break;
      protos.push(p);
      used += p.width;
      if (used >= w) break;
    }
    return { protos, stretch: used > 0 ? w / used : 1 };
  }

  /**
   * Maquette d'un bâtiment (application Biens) : ses modèles complets, à ses couleurs, centrés sur
   * l'origine et façade vers +z. Les matières sont celles de la ville, avec la teinte posée.
   */
  modelOf(b: Building): THREE.Group | null {
    if (this.prototypes.length === 0) return null;
    const group = new THREE.Group();
    const back = new THREE.Matrix4()
      .makeRotationY(b.facing === 'north' ? -Math.PI : 0)
      .multiply(new THREE.Matrix4().makeTranslation(-b.x, 0, -b.z));
    const color = new THREE.Color();
    for (const { proto, matrix } of this.plan(b))
      for (const part of proto.parts) {
        const base = part.pool.material as THREE.MeshStandardMaterial;
        this.colorFor(part.material, proto, b, color);
        const key = `${base.uuid}:${color.getHexString()}`;
        let material = this.modelMaterials.get(key);
        if (!material) {
          material = base.clone();
          material.onBeforeCompile = base.onBeforeCompile;
          material.customProgramCacheKey = base.customProgramCacheKey;
          material.color.multiply(color);
          this.modelMaterials.set(key, material);
        }
        const mesh = new THREE.Mesh(part.pool.geometry, material);
        mesh.matrixAutoUpdate = false;
        mesh.matrix.copy(back).multiply(matrix);
        group.add(mesh);
      }
    return group;
  }
  private readonly modelMaterials = new Map<string, THREE.MeshStandardMaterial>();

  /** Modèles et positions pour un bâtiment du jeu (repère du monde). */
  private plan(b: Building): { proto: Prototype; matrix: THREE.Matrix4 }[] {
    const out: { proto: Prototype; matrix: THREE.Matrix4 }[] = [];
    // Parcelle en repère local : façade côté +z, largeur le long de x.
    const w = b.w;
    const d = b.d;
    const base = new THREE.Matrix4()
      .makeTranslation(b.x, 0, b.z)
      .multiply(new THREE.Matrix4().makeRotationY(b.facing === 'north' ? Math.PI : 0));
    const place = (
      proto: Prototype,
      cx: number,
      facadeZ: number,
      sx: number,
      sy: number,
      sz: number,
      back: boolean,
    ): void => {
      const m = base
        .clone()
        .multiply(new THREE.Matrix4().makeTranslation(cx, 0, facadeZ))
        .multiply(new THREE.Matrix4().makeRotationY(back ? Math.PI : 0))
        .multiply(new THREE.Matrix4().makeScale(sx, sy, sz))
        .multiply(new THREE.Matrix4().makeTranslation(-proto.centerX, 0, 0));
      out.push({ proto, matrix: m });
    };
    if (!ROWS.has(b.type)) {
      const proto = this.pick(b, FAMILIES[b.type][0]!, 3, b.h * 10 * 1.6);
      if (!proto) return out;
      const front = Math.min(proto.front, d * 0.25);
      if (b.type === 'pavillon' || b.type === 'villa') {
        // Maison posée au milieu de son jardin, à taille réelle.
        const s = Math.min(1.25, w / (proto.width + 0.2), (d - front) / (proto.depth + 0.2));
        place(proto, 0, Math.min(d / 2 - front, (proto.depth * s) / 2 + 0.3), s, s, s, false);
      } else {
        const sx = Math.min(1.5, Math.max(0.75, w / proto.width));
        const sz = Math.min(1.5, Math.max(0.75, (d - front) / proto.depth));
        const sy = b.type === 'tour' ? Math.min(1.3, Math.max(0.9, (sx + sz) / 2)) : 1;
        place(proto, 0, d / 2 - front, sx, sy, sz, false);
      }
      return out;
    }
    // Rangées dos à dos : sur la rue, et sur la cour si la parcelle est assez profonde.
    const front = this.rowFor(b, w, 3);
    const depth = Math.max(...front.protos.map((p) => p.depth), 0.1);
    const rows = d > depth * 1.6 ? [false, true] : [false];
    const rowDepth = d / rows.length;
    for (const back of rows) {
      const row = back ? this.rowFor(b, w, 7) : front;
      let x = -w / 2;
      for (const proto of row.protos) {
        const width = proto.width * row.stretch;
        const lead = Math.min(proto.front, 0.25);
        const sz = Math.min(1.25, (rowDepth - lead) / proto.depth);
        const facade = back ? -(d / 2 - lead) : d / 2 - lead;
        place(proto, x + width / 2, facade, row.stretch, 1, sz, back);
        x += width;
      }
    }
    return out;
  }

  /** Couleur d'un mur peint : palette du quartier, même pâté et même modèle = même couleur. */
  private colorFor(material: number, proto: Prototype, b: Building, out: THREE.Color): THREE.Color {
    const role = CATALOG.materials[material]!.name as Role;
    const choices = (DISTRICT_PALETTE[b.district] ?? WARM)[role];
    if (choices && proto.tints.has(material)) {
      const roleSalt = role.length * 7 + role.charCodeAt(5);
      const k = Math.floor(hash(this.blockOf(b) * 131 + proto.index, roleSalt) * choices.length);
      return out.setHex(choices[k]!);
    }
    return out.setHex(0xffffff);
  }

  private paint(entry: Placed, b: Building): void {
    const status = new THREE.Color(STATUS_TINT[this.statusOf(b)] ?? 0xffffff);
    const color = new THREE.Color();
    for (const { slot, material, proto } of entry.ids)
      slot.pool.setColor(slot, this.colorFor(material, proto, b, color).multiply(status));
  }

  /** Numéro du pâté qui contient le bâtiment (mis en cache). */
  private readonly blocks = new Map<number, number>();
  private blockOf(b: Building): number {
    let k = this.blocks.get(b.id);
    if (k === undefined) {
      k = this.city.blocks.findIndex(
        ({ rect: r }) => b.x >= r.x0 && b.x <= r.x1 && b.z >= r.z0 && b.z <= r.z1,
      );
      this.blocks.set(b.id, k);
    }
    return k;
  }

  /** À rappeler après un achat ou une vente : les teintes de statut changent. */
  refreshStatuses(): void {
    for (const p of this.placed.values()) {
      const b = this.city.buildings[p.building];
      if (b) this.paint(p, b);
    }
    if (this.farReady) for (const b of this.city.buildings) this.paintFar(b);
  }

  /** Vue Rue : relief des textures et salissures ; vue Quartier : matières simplifiées. */
  setDetail(on: boolean): void {
    if (LG_DETAIL.value === (on ? 1 : 0)) return;
    LG_DETAIL.value = on ? 1 : 0;
    // Le relief reste chargé (pas de recompilation, donc pas d'à-coup au changement de vue) :
    // seule son intensité change.
    for (const material of this.materials)
      if (material.normalMap) material.normalScale.setScalar(on ? 1.5 : 0);
  }

  /** Ombres portées des bâtiments : de près seulement (de haut, elles coûtent un second dessin). */
  setShadows(on: boolean): void {
    // Ombres portées des bâtiments faits main retirées (fluidité) : l'ombre des recoins les
    // remplace. Les silhouettes non plus.
    void on;
  }

  /** Vitres qui renvoient le ciel (Liquid Glass) : reçoit le reflet préparé par la vue. */
  setEnvironment(environment: THREE.Texture | null): void {
    CATALOG.materials.forEach((m, i) => {
      const material = this.materials[i];
      if (!material || !GLASSES.has(m.name) || !environment) return;
      material.envMap = environment;
      material.envMapIntensity = 1.4;
      material.color = new THREE.Color(m.name === 'vitre' ? 0x8fa9c2 : 0x9cb8d0);
      material.metalness = 0.75;
      material.roughness = 0.06;
      material.needsUpdate = true;
    });
    this.environment = environment;
  }
  private environment: THREE.Texture | null = null;

  dispose(): void {
    for (const pool of this.pools) pool.dispose();
    for (const m of this.materials) {
      m.map?.dispose();
      m.normalMap?.dispose();
      m.dispose();
    }
  }
}
