import * as THREE from 'three';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
import type { City, Monument } from '../model';

/**
 * Monuments de Saint-Profit-sur-Mer (retour du propriétaire) : hôtel de ville, gare centrale,
 * phare et stade. Faits de formes simples, fusionnées en un seul maillage par monument.
 * 1 unité = 10 m. Chaque monument est construit au centre de son square.
 */

type Part = THREE.BufferGeometry;

function colored(geometry: Part, hex: number): Part {
  const g = geometry.index ? geometry.toNonIndexed() : geometry;
  const c = new THREE.Color(hex);
  const colors = new Float32Array(g.getAttribute('position').count * 3);
  for (let i = 0; i < colors.length; i += 3) colors.set([c.r, c.g, c.b], i);
  g.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  g.deleteAttribute('uv');
  return g;
}

const box = (w: number, h: number, d: number, x: number, y: number, z: number, hex: number) => {
  const g = new THREE.BoxGeometry(w, h, d);
  g.translate(x, y + h / 2, z);
  return colored(g, hex);
};

const cyl = (
  top: number,
  bottom: number,
  h: number,
  x: number,
  y: number,
  z: number,
  hex: number,
  segments = 16,
  open = false,
) => {
  const g = new THREE.CylinderGeometry(top, bottom, h, segments, 1, open);
  g.translate(x, y + h / 2, z);
  return colored(g, hex);
};

/** Prisme triangulaire (fronton, toit à deux pentes), le long de x. */
const gable = (w: number, h: number, d: number, x: number, y: number, z: number, hex: number) => {
  const shape = new THREE.Shape([
    new THREE.Vector2(-d / 2, 0),
    new THREE.Vector2(d / 2, 0),
    new THREE.Vector2(0, h),
  ]);
  const g = new THREE.ExtrudeGeometry(shape, { depth: w, bevelEnabled: false });
  g.rotateY(Math.PI / 2);
  g.translate(x - w / 2, y, z);
  return colored(g, hex);
};

const STONE = 0xece4d2;
const WHITE = 0xf6f4ee;
const SLATE = 0x5a6474;
const GLASS = 0x8fb7d4;

/** Hôtel de ville : corps à colonnade, fronton, tour de l'horloge, drapeau. */
function cityHall(): Part[] {
  const parts: Part[] = [
    box(8.2, 0.35, 5.2, 0, 0, 0, 0xd9d1bf),
    box(7.4, 2.4, 4, 0, 0.35, -0.3, STONE),
    box(7.6, 0.25, 4.2, 0, 2.75, -0.3, WHITE),
    gable(7.6, 0.9, 4.2, 0, 3, -0.3, SLATE),
    // Portique : marches, six colonnes, fronton.
    box(4.6, 0.12, 1.6, 0, 0.35, 2.2, WHITE),
    box(4.4, 0.25, 1.3, 0, 2.5, 2.15, WHITE),
    gable(4.4, 0.75, 1.3, 0, 2.75, 2.15, WHITE),
  ];
  for (let i = 0; i < 6; i++)
    parts.push(cyl(0.13, 0.15, 2.05, -1.9 + i * 0.76, 0.45, 2.45, WHITE, 10));
  // Tour de l'horloge, cadran et toit en pointe.
  parts.push(box(1.5, 2.6, 1.5, 0, 3.0, -0.6, STONE), box(1.7, 0.2, 1.7, 0, 5.6, -0.6, WHITE));
  const face = new THREE.CylinderGeometry(0.45, 0.45, 0.06, 20);
  face.rotateX(Math.PI / 2);
  face.translate(0, 4.4, 0.18);
  parts.push(colored(face, WHITE));
  parts.push(cyl(0, 1.15, 1.3, 0, 5.8, -0.6, SLATE, 4));
  // Mât et drapeau.
  parts.push(
    cyl(0.03, 0.03, 1.4, 0, 7.1, -0.6, 0x3a3f4a, 6),
    box(0.6, 0.38, 0.03, 0.31, 8.05, -0.6, 0x2c5fc4),
  );
  // Fenêtres hautes de la façade.
  for (let i = 0; i < 8; i++) {
    const x = -3.2 + i * 0.92;
    if (Math.abs(x) < 2.3) continue;
    parts.push(box(0.42, 1.2, 0.05, x, 0.9, 1.72, 0x2a3d50));
  }
  return parts;
}

/** Gare centrale : bâtiment de façade, grande halle à verrière voûtée, horloge. */
function station(): Part[] {
  const hall = new THREE.CylinderGeometry(2.4, 2.4, 9, 20, 1, true, 0, Math.PI);
  hall.rotateZ(Math.PI / 2);
  hall.rotateX(-Math.PI / 2);
  hall.translate(0, 1.6, -0.8);
  const parts: Part[] = [
    box(9.6, 0.25, 5.6, 0, 0, -0.8, 0xbfc3c8),
    box(9.2, 1.6, 4.8, 0, 0.25, -0.8, 0xd8d2c4),
    colored(hall, GLASS),
    // Arceaux métalliques de la verrière.
  ];
  for (let i = 0; i < 7; i++) {
    const ring = new THREE.TorusGeometry(2.42, 0.06, 4, 16, Math.PI);
    ring.rotateY(Math.PI / 2);
    ring.translate(-4.2 + i * 1.4, 1.6, -0.8);
    parts.push(colored(ring, 0x3a4250));
  }
  // Façade monumentale côté rue, grande baie en arc et horloge.
  parts.push(box(9.6, 3.6, 1, 0, 0.25, 2.1, STONE), box(9.8, 0.3, 1.2, 0, 3.85, 2.1, WHITE));
  const arch = new THREE.CylinderGeometry(1.5, 1.5, 0.08, 20, 1, false, 0, Math.PI);
  arch.rotateX(Math.PI / 2);
  arch.rotateZ(Math.PI / 2);
  arch.rotateY(Math.PI / 2);
  arch.translate(0, 2.0, 2.62);
  parts.push(colored(arch, GLASS), box(3, 1.75, 0.08, 0, 0.25, 2.62, GLASS));
  parts.push(
    box(1.4, 1.8, 1.2, 3.9, 3.85, 2.1, STONE),
    cyl(0, 0.95, 0.9, 3.9, 5.65, 2.1, SLATE, 4),
  );
  const clock = new THREE.CylinderGeometry(0.42, 0.42, 0.06, 20);
  clock.rotateX(Math.PI / 2);
  clock.translate(3.9, 4.8, 2.73);
  parts.push(colored(clock, WHITE));
  return parts;
}

/** Phare : socle de pierre, tour rayée rouge et blanc, galerie, lanterne vitrée, maison du gardien. */
function lighthouse(): Part[] {
  const parts: Part[] = [cyl(1.3, 1.45, 0.5, 0, 0, 0, 0xcfc6b2, 20)];
  const bands = 6;
  for (let i = 0; i < bands; i++) {
    const r0 = 0.82 - (i / bands) * 0.27;
    const r1 = 0.82 - ((i + 1) / bands) * 0.27;
    parts.push(cyl(r1, r0, 1, 0, 0.5 + i, 0, i % 2 === 0 ? 0xd2343c : WHITE, 18));
  }
  const top = 0.5 + bands;
  parts.push(
    cyl(0.85, 0.85, 0.12, 0, top, 0, 0x2b2f38, 18),
    cyl(0.42, 0.42, 0.75, 0, top + 0.12, 0, 0xffe7a0, 14),
    cyl(0, 0.55, 0.55, 0, top + 0.87, 0, 0xd2343c, 14),
    box(1.8, 0.9, 1.3, 1.9, 0.5, 0.4, WHITE),
    gable(1.9, 0.6, 1.4, 1.9, 1.4, 0.4, 0xb5523b),
  );
  return parts;
}

/** Stade : enceinte ovale, gradins en pente, pelouse et projecteurs. */
function stadium(): Part[] {
  const sx = 1;
  const sz = 0.68;
  const oval = (g: Part): Part => g.scale(sx, 1, sz);
  const outer = oval(new THREE.CylinderGeometry(6, 6, 1.7, 40, 1, true));
  outer.translate(0, 0.85, 0);
  const stands = oval(new THREE.CylinderGeometry(5.9, 4.2, 1.6, 40, 1, true));
  stands.translate(0, 0.85, 0);
  const pitch = oval(new THREE.CylinderGeometry(4.2, 4.2, 0.06, 40));
  pitch.translate(0, 0.08, 0);
  const parts: Part[] = [
    colored(outer, 0xe8e4dc),
    colored(stands, 0x9aa3b4),
    colored(pitch, 0x5fae45),
    box(5.2, 0.02, 0.06, 0, 0.12, 0, WHITE),
    box(0.06, 0.02, 2.4, 0, 0.12, 0, WHITE),
    box(8.6, 0.12, 0.9, 0, 1.7, -3.7, 0xd2343c),
  ];
  for (const [x, z] of [
    [-5, -3.2],
    [5, -3.2],
    [-5, 3.2],
    [5, 3.2],
  ] as const) {
    parts.push(
      cyl(0.06, 0.08, 3.4, x, 0, z, 0x5d6470, 6),
      box(0.8, 0.35, 0.12, x, 3.3, z, 0xfff6d0),
    );
  }
  return parts;
}

const BUILDERS: Record<Monument['kind'], () => Part[]> = {
  cityhall: cityHall,
  station,
  lighthouse,
  stadium,
};

/** Taille de référence de chaque monument (côté de son emprise, en unités). */
const SPAN: Record<Monument['kind'], number> = {
  cityhall: 9,
  station: 10,
  lighthouse: 5,
  stadium: 12.5,
};

export function buildMonuments(city: City): THREE.Group {
  const group = new THREE.Group();
  group.name = 'monuments';
  const material = new THREE.MeshLambertMaterial({ vertexColors: true, side: THREE.DoubleSide });
  for (const m of city.monuments) {
    const geometry = mergeGeometries(BUILDERS[m.kind]());
    if (!geometry) continue;
    const r = m.rect;
    const side = Math.min(r.x1 - r.x0, r.z1 - r.z0) - 0.8;
    const scale = Math.min(1.2, side / SPAN[m.kind]);
    geometry.scale(scale, scale, scale);
    geometry.computeVertexNormals();
    const mesh = new THREE.Mesh(geometry, material);
    mesh.position.set((r.x0 + r.x1) / 2, 0.06, (r.z0 + r.z1) / 2);
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    mesh.userData.monument = m.kind;
    group.add(mesh);
  }
  return group;
}

/** Point d'attache de l'étiquette d'un monument (au-dessus de lui). */
export function monumentAnchor(m: Monument): { x: number; y: number; z: number } {
  const height: Record<Monument['kind'], number> = {
    cityhall: 8,
    station: 6,
    lighthouse: 8,
    stadium: 4,
  };
  return { x: (m.rect.x0 + m.rect.x1) / 2, y: height[m.kind], z: (m.rect.z0 + m.rect.z1) / 2 };
}
