/** Petites aides pour construire l'interface sans bibliothèque. */
export function el<K extends keyof HTMLElementTagNameMap>(
  tag: K,
  className?: string,
  text?: string,
): HTMLElementTagNameMap[K] {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (text !== undefined) node.textContent = text;
  return node;
}

export function button(className: string, text: string, onClick: () => void): HTMLButtonElement {
  const b = el('button', className, text);
  b.type = 'button';
  b.addEventListener('click', onClick);
  return b;
}

/** Ligne « libellé … valeur » d'un document. */
export function row(label: string, value: string, valueClass = 'amount small'): HTMLDivElement {
  const line = el('div', 'doc-row');
  line.append(el('span', 'doc-label', label), el('span', valueClass, value));
  return line;
}
