import type { City } from '../city/model';
import { propertyValue } from '../economy';
import { CONDITION_FACTOR } from './facts';
import type { Condition, GameState, Letter, LetterKind, Upkeep } from './types';

/**
 * Marchand de biens : état des biens possédés, usure avec le temps, rénovation et revente.
 * Un bien a trois états, comme les annonces : à rénover (×0,6), correct (×1), neuf (×1,2).
 * Le prix et le loyer suivent l'état. Les valeurs ci-dessous sont des réglages par défaut
 * (voir docs/QUESTIONS.md).
 */

/** Jours réels pour qu'un bien perde un état faute de travaux. */
export const WEAR_DAYS = 45;

/** Travaux possibles : état visé, coût en part de la valeur « état correct », durée en jours. */
export const RENOVATION: Partial<Record<Condition, { to: Condition; rate: number; days: number }>> =
  {
    renovate: { to: 'fair', rate: 0.3, days: 2 },
    fair: { to: 'new', rate: 0.17, days: 3 },
  };

const DOWNGRADE: Partial<Record<Condition, Condition>> = { new: 'fair', fair: 'renovate' };

type LetterAdder = (state: GameState, kind: LetterKind, params?: Letter['params']) => GameState;

/** Suivi d'un bien possédé ; un bien acheté avant cette règle est réputé en état correct. */
export function upkeepOf(state: GameState, id: number): Upkeep {
  return state.upkeep[String(id)] ?? { condition: 'fair', since: state.player.day, works: null };
}

export type RenovationRefusal = 'not_owned' | 'best' | 'busy' | 'no_cash';

export interface RenovationQuote {
  to: Condition | null;
  cost: number;
  days: number;
  /** Valeur du bien après les travaux, au cours du jour. */
  valueAfter: number;
  refusal: RenovationRefusal | null;
}

/** Devis des travaux sur un bien possédé. */
export function renovationQuote(state: GameState, id: number): RenovationQuote {
  const property = state.player.properties.find((p) => p.id === String(id));
  if (!property) return { to: null, cost: 0, days: 0, valueAfter: 0, refusal: 'not_owned' };
  const upkeep = upkeepOf(state, id);
  const step = RENOVATION[upkeep.condition];
  const value = propertyValue(property, state.player.day);
  const fairValue = value / CONDITION_FACTOR[upkeep.condition];
  if (!step) return { to: null, cost: 0, days: 0, valueAfter: value, refusal: 'best' };
  const cost = Math.round((fairValue * step.rate) / 100) * 100;
  const valueAfter = fairValue * CONDITION_FACTOR[step.to];
  let refusal: RenovationRefusal | null = null;
  if (upkeep.works) refusal = 'busy';
  else if (state.player.cash < cost) refusal = 'no_cash';
  return { to: step.to, cost, days: step.days, valueAfter, refusal };
}

/** Lance les travaux : payés tout de suite, finis au bout de quelques jours, sans loyer pendant. */
export function renovate(
  state: GameState,
  city: City,
  id: number,
  addLetter: LetterAdder,
): GameState {
  const quote = renovationQuote(state, id);
  if (quote.refusal || !quote.to) throw new Error(`Travaux refusés : ${quote.refusal}`);
  const upkeep = upkeepOf(state, id);
  const next: GameState = {
    ...state,
    player: { ...state.player, cash: state.player.cash - quote.cost },
    ledger: { ...state.ledger, renovation: state.ledger.renovation + quote.cost },
    upkeep: {
      ...state.upkeep,
      [String(id)]: { ...upkeep, works: { to: quote.to, doneDay: state.player.day + quote.days } },
    },
  };
  return addLetter(next, 'worksStarted', {
    ref: city.buildings[id]?.ref ?? String(id),
    amount: quote.cost,
    days: quote.days,
  });
}

/** Change l'état d'un bien possédé : sa valeur et son loyer suivent. */
function setCondition(state: GameState, id: string, to: Condition): GameState {
  const upkeep = state.upkeep[id];
  if (!upkeep) return state;
  const ratio = CONDITION_FACTOR[to] / CONDITION_FACTOR[upkeep.condition];
  return {
    ...state,
    player: {
      ...state.player,
      properties: state.player.properties.map((p) =>
        p.id === id ? { ...p, baseValue: p.baseValue * ratio, baseRent: p.baseRent * ratio } : p,
      ),
    },
    upkeep: { ...state.upkeep, [id]: { condition: to, since: state.player.day, works: null } },
  };
}

/** Pas de loyer pendant les travaux (multiplicateurs de loyer, comme pour les coups bas). */
export function worksRentModifiers(state: GameState, rentDay: number): Record<string, number> {
  const modifiers: Record<string, number> = {};
  for (const [id, upkeep] of Object.entries(state.upkeep)) {
    if (upkeep.works && upkeep.works.doneDay >= rentDay) modifiers[id] = 0;
  }
  return modifiers;
}

/** Suite quotidienne : fin des travaux, usure des biens, oubli des biens vendus ou saisis. */
export function dailyUpkeep(state: GameState, city: City, addLetter: LetterAdder): GameState {
  const day = state.player.day;
  const owned = new Set(state.player.properties.map((p) => p.id));
  let next: GameState = {
    ...state,
    upkeep: Object.fromEntries(Object.entries(state.upkeep).filter(([id]) => owned.has(id))),
  };
  for (const [id, upkeep] of Object.entries(next.upkeep)) {
    const ref = city.buildings[Number(id)]?.ref ?? city.plots[Number(id) - 100_000]?.ref ?? id;
    if (upkeep.works && upkeep.works.doneDay <= day) {
      next = setCondition(next, id, upkeep.works.to);
      next = addLetter(next, 'worksDone', { ref, condition: upkeep.works.to });
      continue;
    }
    const worse = DOWNGRADE[upkeep.condition];
    if (!upkeep.works && worse && day - upkeep.since >= WEAR_DAYS) {
      next = setCondition(next, id, worse);
      next = addLetter(next, 'wear', { ref, condition: worse });
    }
  }
  return next;
}
