import { readSetting, writeSetting } from './storage';

/**
 * Sons, vibrations et notifications (grosse mise à jour, point 7). Les sons sont fabriqués par le
 * navigateur (Web Audio) : aucun fichier, donc aucune question de licence. Chaque réglage se coupe
 * dans les Paramètres.
 */

export type Sound = 'coins' | 'stamp' | 'ping' | 'tick';
export type FeedbackSetting = 'sound' | 'vibration' | 'daylight';

const DEFAULTS: Record<FeedbackSetting, boolean> = { sound: true, vibration: true, daylight: true };

export function feedbackOn(setting: FeedbackSetting): boolean {
  const saved = readSetting(`mb-${setting}`);
  return saved === null ? DEFAULTS[setting] : saved === '1';
}

export function setFeedback(setting: FeedbackSetting, on: boolean): void {
  writeSetting(`mb-${setting}`, on ? '1' : '0');
}

let audio: AudioContext | null = null;

function context(): AudioContext | null {
  if (audio) return audio;
  const Ctor =
    window.AudioContext ??
    (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
  if (!Ctor) return null;
  try {
    audio = new Ctor();
  } catch {
    return null;
  }
  return audio;
}

/** Note brève : fréquence, début, durée, volume, forme. */
function tone(
  ctx: AudioContext,
  freq: number,
  at: number,
  length: number,
  volume: number,
  type: OscillatorType = 'sine',
): void {
  const osc = ctx.createOscillator();
  const gain = ctx.createGain();
  osc.type = type;
  osc.frequency.setValueAtTime(freq, at);
  gain.gain.setValueAtTime(0.0001, at);
  gain.gain.exponentialRampToValueAtTime(volume, at + 0.01);
  gain.gain.exponentialRampToValueAtTime(0.0001, at + length);
  osc.connect(gain).connect(ctx.destination);
  osc.start(at);
  osc.stop(at + length + 0.02);
}

/** Coup sourd (tampon) : bruit filtré très court. */
function thud(ctx: AudioContext, at: number): void {
  const length = 0.12;
  const buffer = ctx.createBuffer(1, Math.ceil(ctx.sampleRate * length), ctx.sampleRate);
  const data = buffer.getChannelData(0);
  for (let i = 0; i < data.length; i++)
    data[i] = (Math.random() * 2 - 1) * (1 - i / data.length) ** 3;
  const source = ctx.createBufferSource();
  source.buffer = buffer;
  const filter = ctx.createBiquadFilter();
  filter.type = 'lowpass';
  filter.frequency.value = 420;
  const gain = ctx.createGain();
  gain.gain.value = 0.9;
  source.connect(filter).connect(gain).connect(ctx.destination);
  source.start(at);
  tone(ctx, 90, at, 0.12, 0.25, 'sine');
}

export function play(sound: Sound): void {
  if (!feedbackOn('sound')) return;
  const ctx = context();
  if (!ctx) return;
  if (ctx.state === 'suspended') void ctx.resume();
  const now = ctx.currentTime + 0.01;
  switch (sound) {
    case 'coins':
      tone(ctx, 1568, now, 0.12, 0.12, 'triangle');
      tone(ctx, 2093, now + 0.07, 0.18, 0.1, 'triangle');
      tone(ctx, 2637, now + 0.15, 0.22, 0.07, 'triangle');
      break;
    case 'stamp':
      thud(ctx, now);
      break;
    case 'ping':
      tone(ctx, 880, now, 0.18, 0.1);
      tone(ctx, 1320, now + 0.1, 0.25, 0.08);
      break;
    case 'tick':
      tone(ctx, 1200, now, 0.05, 0.06, 'square');
      break;
  }
}

export function vibrate(pattern: number | number[]): void {
  if (!feedbackOn('vibration')) return;
  try {
    navigator.vibrate?.(pattern);
  } catch {
    /* Vibration indisponible : rien à faire. */
  }
}

/** Notifications du téléphone : autorisées par le joueur, envoyées seulement quand le jeu est en arrière-plan. */
export function notificationsSupported(): boolean {
  return typeof Notification !== 'undefined';
}

export function notificationsOn(): boolean {
  return notificationsSupported() && Notification.permission === 'granted';
}

export async function askNotifications(): Promise<boolean> {
  if (!notificationsSupported()) return false;
  try {
    return (await Notification.requestPermission()) === 'granted';
  } catch {
    return false;
  }
}

export async function notify(title: string, body: string): Promise<void> {
  if (!notificationsOn() || !document.hidden) return;
  const options = { body, icon: 'icon-192.png', badge: 'icon-192.png', tag: title };
  try {
    const registration = await navigator.serviceWorker?.getRegistration();
    if (registration) await registration.showNotification(title, options);
    else new Notification(title, options);
  } catch {
    /* Notification refusée par le navigateur. */
  }
}

/** Petit service worker sans cache : il permet les notifications sur téléphone (application installée). */
export function registerWorker(): void {
  if (!('serviceWorker' in navigator)) return;
  void navigator.serviceWorker.register('sw.js').catch(() => undefined);
}
