const ZOOMS: readonly ZoomLevel[] = ['city', 'district', 'street'];
/**
 * Onglets du bas (décision du propriétaire) : la Ville, un Téléphone qui réunit les applications
 * (Clients, Banque, Profil, Courrier) et les Paramètres. Une application ouverte est un « onglet »
 * du Téléphone : `ui.tab` vaut alors son nom.
 */
type App =
  | 'clients'
  | 'messages'
  | 'bank'
  | 'properties'
  | 'profile'
  | 'mail'
  | 'news'
  | 'auctions'
  | 'quests';
type Tab = 'map' | 'phone' | 'settings' | App | 'admin';
const TABS: readonly Tab[] = ['map', 'phone', 'settings'];
const APPS: readonly App[] = [
  'clients',
  'properties',
  'auctions',
  'quests',
  'messages',
  'bank',
  'mail',
  'profile',
  'news',
];
const isApp = (tab: Tab): tab is App => (APPS as readonly string[]).includes(tab);
const ADMIN_KEY = 'main-basse-admin';

