import * as THREE from 'three';

/**
 * Lot d'exemplaires d'une même pièce (un modèle de bâtiment, une matière) : un InstancedMesh,
 * donc un seul ordre de dessin pour tous les exemplaires, sur tous les navigateurs. (Le
 * BatchedMesh, essayé avant, demande une fonction que Safari sur iPhone n'a pas : il envoyait
 * alors un ordre de dessin par pièce, des centaines de milliers par image.)
 *
 * Les exemplaires restent tassés au début du tableau : en retirer un déplace le dernier à sa
 * place, et la poignée de ce dernier suit.
 */
export interface Slot {
  pool: InstancePool;
  index: number;
  /** Faux quand l'exemplaire est retiré de l'affichage (il garde sa position et sa couleur). */
  live: boolean;
  matrix: THREE.Matrix4;
  color: THREE.Color;
}

export class InstancePool {
  mesh: THREE.InstancedMesh;
  private slots: Slot[] = [];

  constructor(
    readonly geometry: THREE.BufferGeometry,
    readonly material: THREE.Material,
    private readonly group: THREE.Group,
    capacity = 16,
  ) {
    this.mesh = this.make(capacity);
  }

  private make(capacity: number): THREE.InstancedMesh {
    const mesh = new THREE.InstancedMesh(this.geometry, this.material, capacity);
    mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    mesh.instanceColor = new THREE.InstancedBufferAttribute(new Float32Array(capacity * 3), 3);
    mesh.instanceColor.setUsage(THREE.DynamicDrawUsage);
    mesh.count = 0;
    mesh.visible = false;
    // Les bâtiments posés sont déjà choisis dans le champ de la caméra.
    mesh.frustumCulled = false;
    mesh.receiveShadow = true;
    this.group.add(mesh);
    return mesh;
  }

  /** Place assurée pour n exemplaires : le maillage est refait plus grand si besoin. */
  private reserve(n: number): void {
    const capacity = this.mesh.instanceMatrix.count;
    if (n <= capacity) return;
    let next = capacity;
    while (next < n) next *= 2;
    const old = this.mesh;
    this.mesh = this.make(next);
    (this.mesh.instanceMatrix.array as Float32Array).set(old.instanceMatrix.array);
    (this.mesh.instanceColor!.array as Float32Array).set(old.instanceColor!.array);
    this.mesh.count = old.count;
    this.mesh.visible = old.count > 0;
    this.group.remove(old);
    old.dispose();
  }

  /** Nouvel exemplaire (affiché). */
  add(matrix: THREE.Matrix4, color: THREE.Color): Slot {
    const slot: Slot = {
      pool: this,
      index: -1,
      live: false,
      matrix: matrix.clone(),
      color: color.clone(),
    };
    this.show(slot);
    return slot;
  }

  /** Remet un exemplaire retiré à l'affichage. */
  show(slot: Slot): void {
    if (slot.live) return;
    this.reserve(this.slots.length + 1);
    slot.index = this.slots.length;
    slot.live = true;
    this.slots.push(slot);
    this.mesh.setMatrixAt(slot.index, slot.matrix);
    this.mesh.setColorAt(slot.index, slot.color);
    this.mesh.count = this.slots.length;
    this.mesh.visible = true;
    this.mesh.instanceMatrix.needsUpdate = true;
    this.mesh.instanceColor!.needsUpdate = true;
  }

  /** Retire un exemplaire de l'affichage (il peut revenir avec show). */
  hide(slot: Slot): void {
    if (!slot.live) return;
    const last = this.slots.pop()!;
    if (last !== slot) {
      last.index = slot.index;
      this.slots[slot.index] = last;
      this.mesh.setMatrixAt(last.index, last.matrix);
      this.mesh.setColorAt(last.index, last.color);
    }
    slot.live = false;
    slot.index = -1;
    this.mesh.count = this.slots.length;
    this.mesh.visible = this.slots.length > 0;
    this.mesh.instanceMatrix.needsUpdate = true;
    this.mesh.instanceColor!.needsUpdate = true;
  }

  setColor(slot: Slot, color: THREE.Color): void {
    slot.color.copy(color);
    if (!slot.live) return;
    this.mesh.setColorAt(slot.index, color);
    this.mesh.instanceColor!.needsUpdate = true;
  }

  dispose(): void {
    this.group.remove(this.mesh);
    this.mesh.dispose();
    this.geometry.dispose();
  }
}
