import * as THREE from 'three';

/**
 * Silhouette des bâtiments faits main, pour les vues dézoomées (retour du propriétaire : « en
 * dézoomant, les bâtiments sont légèrement floutés, une silhouette pour fluidifier »). Même
 * volume, même couleur, mêmes rangées de fenêtres que le modèle détaillé, mais en volumes
 * simples : fenêtres peintes aux bords fondus, toits en pente, retraits des tours, et un voile
 * de distance qui adoucit l'ensemble.
 *
 * Repère d'entrée : celui des fichiers (Blender, cm). Repère de sortie : celui du jeu.
 */

const CM = 0.001;

export interface FarModel {
  walls: THREE.BufferGeometry;
  roofs: THREE.BufferGeometry;
  /** Mur peint principal (sa teinte colore la silhouette), ou null. */
  wallMaterial: number | null;
  /** Toit en pente (tuile, ardoise), ou null pour un toit plat. */
  roofMaterial: number | null;
  /** Tour de verre. */
  curtain: boolean;
  triangles: number;
}

const median = (values: number[]): number => {
  if (values.length === 0) return 0;
  const s = [...values].sort((a, b) => a - b);
  return s[Math.floor(s.length / 2)]!;
};

/** Écart typique entre valeurs distinctes (pas de la grille), 0 s'il n'y en a qu'une. */
const step = (values: number[], tolerance: number): number => {
  const u = [...new Set(values.map((v) => Math.round(v / tolerance) * tolerance))].sort(
    (a, b) => a - b,
  );
  const gaps = u.slice(1).map((v, i) => v - u[i]!);
  return median(gaps.filter((g) => g > tolerance));
};

type Six = [number, number, number, number, number, number];

export function buildFar(
  data: Int16Array,
  start: number,
  end: number,
  roles: {
    paint: (m: number) => boolean;
    wallLike: (m: number) => boolean;
    pitched: (m: number) => boolean;
    curtain: number;
  },
): FarModel {
  const boxes: { m: number; c: Six }[] = [];
  const windows: { x: number; zs: number; w: number; h: number }[] = [];
  let roofMaterial: number | null = null;
  let ridge = 0;
  let i = start;
  while (i < end) {
    const kind = data[i]!;
    const m = data[i + 1]!;
    if (kind === 1) {
      boxes.push({ m, c: Array.from(data.subarray(i + 2, i + 8)) as Six });
      i += 8;
    } else if (kind === 2) {
      const [x0, zs, x1, zt] = Array.from(data.subarray(i + 2, i + 6)) as number[];
      windows.push({ x: (x0! + x1!) / 2, zs: zs!, w: x1! - x0!, h: zt! - zs! });
      i += 9;
    } else {
      const n = data[i + 2]!;
      if (roles.pitched(m)) {
        roofMaterial = m;
        for (let t = 0; t < n * 3; t++) ridge = Math.max(ridge, data[i + 3 + t * 3 + 2]!);
      }
      i += 3 + n * 9;
    }
  }
  const curtain = boxes.some(({ m }) => m === roles.curtain);

  // Volumes : les grosses pièces pleines (étages des tours), sinon l'enveloppe des murs.
  const big = boxes.filter(
    ({ m, c }) => roles.wallLike(m) && c[3] - c[0] > 250 && c[4] - c[1] > 250 && c[5] - c[2] > 250,
  );
  const walls = boxes.filter(({ m, c }) => roles.wallLike(m) && c[5] - c[2] > 150);
  const pieces: Six[] = big.map((b) => b.c);
  if (pieces.length === 0 && walls.length > 0) {
    const tops = walls.map((b) => b.c[5]).sort((a, b) => b - a);
    pieces.push([
      Math.min(...walls.map((b) => b.c[0])),
      Math.max(0, Math.min(...walls.map((b) => b.c[1]))),
      0,
      Math.max(...walls.map((b) => b.c[3])),
      Math.max(...walls.map((b) => b.c[4])),
      tops[Math.min(tops.length - 1, Math.floor(tops.length * 0.15))]!,
    ]);
  }

  // Mur peint principal : le plus étendu.
  const area = new Map<number, number>();
  for (const { m, c } of boxes)
    if (roles.paint(m)) area.set(m, (area.get(m) ?? 0) + (c[3] - c[0]) * (c[5] - c[2]));
  let wallMaterial: number | null = null;
  let best = 0;
  area.forEach((a, m) => {
    if (a > best) [best, wallMaterial] = [a, m];
  });

  // Grille de fenêtres (avec des valeurs de repli quand une seule colonne ou un seul étage).
  const height = Math.max(0, ...pieces.map((p) => p[5]));
  const tower = windows.length === 0 && height > 2500;
  const hasGrid = windows.length > 0 || tower;
  const bay = tower
    ? curtain
      ? 150
      : 170
    : step(
        windows.map((w) => w.x),
        40,
      ) || 255;
  const floor = tower
    ? 340
    : step(
        windows.map((w) => w.zs),
        40,
      ) || 310;
  const any = windows.length > 0;
  const xFirst = any ? Math.min(...windows.map((w) => w.x)) : bay / 2;
  const zFirst = any ? median(windows.map((w) => w.zs)) : 2 * floor + 95;
  const zLow = any ? Math.min(...windows.map((w) => w.zs)) : zFirst;
  const zHigh = any ? Math.max(...windows.map((w) => w.zs)) : height - floor;
  const winW = any ? Math.min(0.8, median(windows.map((w) => w.w)) / bay) : 0.8;
  const winH = any
    ? Math.min(0.85, median(windows.map((w) => w.h)) / floor)
    : curtain
      ? 0.92
      : 0.72;
  const v0 = (zLow - zFirst) / floor;
  const rows = hasGrid ? Math.round((zHigh - zLow) / floor) + 1 : 0;

  const W = {
    pos: [] as number[],
    nor: [] as number[],
    uv: [] as number[],
    win: [] as number[],
    idx: [] as number[],
  };
  const R = { pos: [] as number[], nor: [] as number[], uv: [] as number[], idx: [] as number[] };

  const wall = (pts: number[][], n: [number, number, number]): void => {
    const base = W.pos.length / 3;
    const front = Math.abs(n[1]) > 0.5;
    for (const [x, y, z] of pts as [number, number, number][]) {
      W.pos.push(x * CM, z * CM, -y * CM);
      W.nor.push(n[0], n[2], -n[1]);
      const along = front ? x : y;
      const first = front ? xFirst : tower ? bay / 2 : 220;
      const width = front || tower ? bay : 340;
      W.uv.push((along - first) / width + 0.5, (z - zFirst) / floor);
      const side = !front && !tower;
      W.win.push(
        hasGrid ? (side ? 0.3 : winW) : 0,
        hasGrid ? (side ? 0.5 : winH) : 0,
        v0,
        v0 + rows,
      );
    }
    if (pts.length === 4) W.idx.push(base, base + 1, base + 2, base, base + 2, base + 3);
    else W.idx.push(base, base + 1, base + 2);
  };
  const roof = (pts: number[][], n: [number, number, number]): void => {
    const base = R.pos.length / 3;
    for (const [x, y, z] of pts as [number, number, number][]) {
      R.pos.push(x * CM, z * CM, -y * CM);
      R.nor.push(n[0], n[2], -n[1]);
      R.uv.push(x * 0.004, y * 0.004);
    }
    R.idx.push(base, base + 1, base + 2, base, base + 2, base + 3);
  };

  for (const [x0, y0, z0, x1, y1, z1] of pieces) {
    wall(
      [
        [x0, y0, z0],
        [x1, y0, z0],
        [x1, y0, z1],
        [x0, y0, z1],
      ],
      [0, -1, 0],
    );
    wall(
      [
        [x1, y1, z0],
        [x0, y1, z0],
        [x0, y1, z1],
        [x1, y1, z1],
      ],
      [0, 1, 0],
    );
    wall(
      [
        [x0, y1, z0],
        [x0, y0, z0],
        [x0, y0, z1],
        [x0, y1, z1],
      ],
      [-1, 0, 0],
    );
    wall(
      [
        [x1, y0, z0],
        [x1, y1, z0],
        [x1, y1, z1],
        [x1, y0, z1],
      ],
      [1, 0, 0],
    );
    if (roofMaterial === null)
      roof(
        [
          [x0, y0, z1],
          [x1, y0, z1],
          [x1, y1, z1],
          [x0, y1, z1],
        ],
        [0, 0, 1],
      );
  }

  // Toit en pente des maisons : faîtage le long de la façade, pignons de la couleur des murs.
  if (roofMaterial !== null && pieces.length > 0) {
    const [x0, y0, , x1, y1, z1] = pieces[0]!;
    const top = Math.max(ridge, z1 + 100);
    const ym = (y0 + y1) / 2;
    const o = 40;
    const slope = (top - z1) / ((y1 - y0) / 2);
    const lo = z1 - o * slope;
    const ny = 1 / Math.hypot(1, 1 / slope);
    const nz = Math.sqrt(1 - ny * ny);
    roof(
      [
        [x0 - o, y0 - o, lo],
        [x1 + o, y0 - o, lo],
        [x1 + o, ym, top],
        [x0 - o, ym, top],
      ],
      [0, -nz, ny],
    );
    roof(
      [
        [x1 + o, y1 + o, lo],
        [x0 - o, y1 + o, lo],
        [x0 - o, ym, top],
        [x1 + o, ym, top],
      ],
      [0, nz, ny],
    );
    wall(
      [
        [x0, y1, z1],
        [x0, y0, z1],
        [x0, ym, top],
      ],
      [-1, 0, 0],
    );
    wall(
      [
        [x1, y0, z1],
        [x1, y1, z1],
        [x1, ym, top],
      ],
      [1, 0, 0],
    );
  }

  const walls3 = new THREE.BufferGeometry();
  walls3.setAttribute('position', new THREE.Float32BufferAttribute(W.pos, 3));
  walls3.setAttribute('normal', new THREE.Float32BufferAttribute(W.nor, 3));
  walls3.setAttribute('uv', new THREE.Float32BufferAttribute(W.uv, 2));
  walls3.setAttribute('aWin', new THREE.Float32BufferAttribute(W.win, 4));
  walls3.setIndex(W.idx);
  const roofs3 = new THREE.BufferGeometry();
  roofs3.setAttribute('position', new THREE.Float32BufferAttribute(R.pos, 3));
  roofs3.setAttribute('normal', new THREE.Float32BufferAttribute(R.nor, 3));
  roofs3.setAttribute('uv', new THREE.Float32BufferAttribute(R.uv, 2));
  roofs3.setIndex(R.idx);
  return {
    walls: walls3,
    roofs: roofs3,
    wallMaterial,
    roofMaterial,
    curtain,
    triangles: (W.idx.length + R.idx.length) / 3,
  };
}

/**
 * Voile de distance commun aux murs et aux toits : la silhouette s'adoucit en s'éloignant, vers
 * la couleur du ciel (laiteuse le jour, sombre la nuit).
 */
const haze = (night: boolean): string => `
  float farHaze = smoothstep(20.0, 260.0, length(vViewPosition));
  outgoingLight = mix(outgoingLight, ${
    night
      ? 'vec3(0.05, 0.065, 0.1)'
      : 'vec3(0.80, 0.85, 0.90) * (0.6 + 0.4 * dot(outgoingLight, vec3(0.33)))'
  }, farHaze * 0.35);
  #include <opaque_fragment>`;

/** Matériau des silhouettes : couleur de l'instance, fenêtres peintes aux bords fondus. */
export function farWallMaterial(night: boolean): THREE.MeshStandardMaterial {
  const material = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.9 });
  material.onBeforeCompile = (shader) => {
    shader.vertexShader = shader.vertexShader
      .replace(
        '#include <common>',
        `#include <common>\nattribute vec4 aWin;\nvarying vec4 vWin;\nvarying vec2 vGrid;`,
      )
      .replace('#include <uv_vertex>', `#include <uv_vertex>\nvWin = aWin;\nvGrid = uv;`);
    shader.fragmentShader = shader.fragmentShader
      .replace('#include <common>', `#include <common>\nvarying vec4 vWin;\nvarying vec2 vGrid;`)
      .replace(
        '#include <color_fragment>',
        `#include <color_fragment>
        vec2 cell = fract(vGrid);
        // Bords fondus (léger flou) : au moins un pixel et demi, plus large de loin.
        vec2 soft = max(fwidth(vGrid) * 1.5, vec2(0.04));
        float halfW = vWin.x * 0.5;
        float inX = smoothstep(0.5 - halfW - soft.x, 0.5 - halfW + soft.x, cell.x)
          * (1.0 - smoothstep(0.5 + halfW - soft.x, 0.5 + halfW + soft.x, cell.x));
        float inY = smoothstep(0.0, soft.y * 2.0, cell.y) * (1.0 - smoothstep(vWin.y - soft.y, vWin.y + soft.y, cell.y));
        float rowsIn = smoothstep(vWin.z - 0.05, vWin.z, vGrid.y) * (1.0 - smoothstep(vWin.w - 0.05, vWin.w, vGrid.y));
        float glass = inX * inY * rowsIn * step(0.001, vWin.x);
        float lit = step(0.9, fract(sin(dot(floor(vGrid), vec2(12.9898, 78.233))) * 43758.5453));
        vec3 pane = ${night ? 'mix(vec3(0.05, 0.07, 0.1), vec3(1.0, 0.78, 0.45), lit)' : 'vec3(0.56, 0.67, 0.78)'};
        diffuseColor.rgb = mix(diffuseColor.rgb, pane, glass * 0.9);`,
      )
      .replace('#include <opaque_fragment>', haze(night));
  };
  material.customProgramCacheKey = () => `nyc-far-walls-${night ? 'night' : 'day'}`;
  return material;
}

export function farRoofMaterial(night: boolean): THREE.MeshStandardMaterial {
  const material = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.95 });
  material.onBeforeCompile = (shader) => {
    shader.fragmentShader = shader.fragmentShader.replace(
      '#include <opaque_fragment>',
      haze(night),
    );
  };
  material.customProgramCacheKey = () => `nyc-far-roofs-${night ? 'night' : 'day'}`;
  return material;
}
