import * as THREE from 'three';
import grainUrl from './textures/ground-detail.jpg';

/**
 * Grain de matière pour les surfaces sans texture (sol, garniture des toits, ferronneries) : une
 * fine texture projetée selon les trois axes du monde. Elle casse les aplats sans coûter de
 * géométrie ni de coordonnées de texture.
 */

let texture: THREE.Texture | null = null;

function grainTexture(): THREE.Texture {
  if (texture) return texture;
  texture = new THREE.TextureLoader().load(grainUrl);
  texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
  texture.colorSpace = THREE.NoColorSpace;
  return texture;
}

/**
 * Ajoute le grain à un matériau éclairé à couleurs par sommet.
 * `scale` : répétitions par unité du monde ; `amount` : force du grain, de 0 à 1.
 */
export function withGrain<T extends THREE.MeshLambertMaterial | THREE.MeshStandardMaterial>(
  material: T,
  scale: number,
  amount: number,
  key: string,
): T {
  const detail = grainTexture();
  material.onBeforeCompile = (shader) => {
    shader.uniforms.uGrain = { value: detail };
    shader.vertexShader = shader.vertexShader
      .replace(
        '#include <common>',
        '#include <common>\nvarying vec3 vGrainPos;\nvarying vec3 vGrainNormal;',
      )
      .replace(
        '#include <worldpos_vertex>',
        `#include <worldpos_vertex>
vec4 grainWorld = vec4(transformed, 1.0);
#ifdef USE_INSTANCING
grainWorld = instanceMatrix * grainWorld;
#endif
vGrainPos = (modelMatrix * grainWorld).xyz;
vec3 grainN = mat3(modelMatrix) * objectNormal;
vGrainNormal = dot(grainN, grainN) > 1e-6 ? normalize(grainN) : vec3(0.0, 1.0, 0.0);`,
      );
    shader.fragmentShader = shader.fragmentShader
      .replace(
        '#include <common>',
        '#include <common>\nuniform sampler2D uGrain;\nvarying vec3 vGrainPos;\nvarying vec3 vGrainNormal;',
      )
      .replace(
        '#include <color_fragment>',
        `#include <color_fragment>
  vec3 gw = abs(vGrainNormal);
  gw /= max(gw.x + gw.y + gw.z, 1e-4);
  float g = texture2D(uGrain, vGrainPos.zy * ${scale.toFixed(3)}).r * gw.x
    + texture2D(uGrain, vGrainPos.xz * ${scale.toFixed(3)}).r * gw.y
    + texture2D(uGrain, vGrainPos.xy * ${scale.toFixed(3)}).r * gw.z;
  float broad = texture2D(uGrain, vGrainPos.xz * ${(scale * 0.08).toFixed(4)}).r;
  diffuseColor.rgb *= mix(1.0, (g / 0.78) * mix(0.92, 1.08, broad / 0.78), ${amount.toFixed(2)});`,
      );
  };
  material.customProgramCacheKey = () => `grain-${key}`;
  return material;
}
