import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import type { Building, BuildingStatus, City } from '../model';
import { isBrick, lookOf } from './facadeMaterial';
import { withGrain } from './grain';
import { wallHex } from './staticScene';
import { DISTRICT_STYLE, pickFor, type CityPalette } from './palette';
import modulesUrl from './models/modules.glb?url';

/**
 * Graphismes « haut » : les bâtiments proches de la caméra sont habillés de pièces modélisées
 * dans Blender (tools/blender/modules.py), avec l'ombre des recoins déjà cuite : fenêtres en
 * relief, volets, portes, vitrines et auvents, corniches, escaliers de secours, climatiseurs,
 * châteaux d'eau, cheminées, balcons. Une pièce = un maillage instancié = un appel de dessin.
 * Les fenêtres dessinées par le shader des façades s'effacent sur les façades ainsi habillées.
 */

/** Rayon habillé autour du point visé, en unités (1 unité = 10 m) : environ 40 bâtiments. */
export const HIGH_RADIUS = 7;
/** Les pièces sont modélisées en mètres. */
const METER = 0.1;
/** Déplacement du point visé au-delà duquel on rhabille la zone. */
const REBUILD_STEP = 3;

type ModuleName =
  | 'win_frame'
  | 'win_stone'
  | 'win_modern'
  | 'shutters'
  | 'door'
  | 'shop'
  | 'shop_glass'
  | 'awning'
  | 'band'
  | 'fire_escape'
  | 'ac'
  | 'balcony'
  | 'bay_wall'
  | 'bay_trim'
  | 'pilaster'
  | 'stone_band'
  | 'balcony_rail'
  | 'oriel_wall'
  | 'oriel_trim'
  | 'oriel_cap'
  | 'cornice'
  | 'glass';

const CAPACITY: Record<ModuleName, number> = {
  win_frame: 9000,
  win_stone: 7000,
  win_modern: 5000,
  shutters: 5000,
  door: 600,
  shop: 1200,
  shop_glass: 1200,
  awning: 1200,
  band: 4000,
  fire_escape: 1500,
  ac: 1500,
  balcony: 2500,
  bay_wall: 6000,
  bay_trim: 6000,
  pilaster: 3000,
  stone_band: 600,
  balcony_rail: 2500,
  oriel_wall: 600,
  oriel_trim: 600,
  oriel_cap: 300,
  cornice: 1500,
  glass: 14000,
};

/** Travée des façades sobres (tools/blender/modules.py), en mètres ; pas de la grille, en unités. */
const BAY_W = 2.4;
const BAY_H = 3.2;
const OPEN_W = 1.15;
const OPEN_H = 1.75;
const SILL = 0.95;
export const SOBER_PITCH = 0.26;

const SHADOW_CASTERS = new Set<ModuleName>([
  'bay_wall',
  'oriel_wall',
  'balcony_rail',
  'awning',
  'shop',
  'balcony',
]);

/** Dimensions de l'ouverture des fenêtres modélisées, en mètres. */
const WIN_W = 1.15;
const WIN_H = 1.75;

function hash01(a: number, b: number): number {
  let h = (a * 374761393 + b * 668265263) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}

interface Placement {
  matrix: THREE.Matrix4;
  color: THREE.Color;
}

export class HighDetail {
  readonly group = new THREE.Group();
  /** Centre de la zone habillée, partagé avec le shader des façades. */
  readonly center = new THREE.Vector2(1e9, 1e9);
  private meshes = new Map<ModuleName, THREE.InstancedMesh>();
  private ready = false;
  private readonly index: Building[];

  constructor(
    city: City,
    private readonly palette: CityPalette,
    private readonly onRebuild: (center: THREE.Vector2) => void,
    environment: THREE.Texture | null = null,
    private readonly statusOf: (b: Building) => BuildingStatus = () => 'none',
  ) {
    this.index = city.buildings;
    const night = palette.litRatio > 0;
    // Double face : certaines pièces sont posées en miroir (escaliers de secours).
    const plain = new THREE.MeshLambertMaterial({ vertexColors: true, side: THREE.DoubleSide });
    const lit = palette.lush ? withGrain(plain, 4, 0.3, 'modules') : plain;
    const glass = night
      ? new THREE.MeshBasicMaterial({ color: 0xffffff })
      : new THREE.MeshStandardMaterial({
          color: 0xffffff,
          roughness: 0.08,
          metalness: 0.65,
          envMap: environment,
          envMapIntensity: 1.2,
        });
    const shopGlass = new THREE.MeshBasicMaterial({ color: night ? 0xffd28a : 0xf3dcb4 });
    new GLTFLoader().load(modulesUrl, (gltf) => {
      const geometries = new Map<string, THREE.BufferGeometry>();
      gltf.scene.traverse((o) => {
        if (o instanceof THREE.Mesh) {
          const g = (o.geometry as THREE.BufferGeometry).clone();
          g.scale(METER, METER, METER);
          geometries.set(o.name, g);
        }
      });
      const plane = new THREE.PlaneGeometry(1, 1);
      plane.translate(0, 0.5, 0);
      for (const name of Object.keys(CAPACITY) as ModuleName[]) {
        const geometry = name === 'glass' ? plane : geometries.get(name);
        if (!geometry) continue;
        const material = name === 'glass' ? glass : name === 'shop_glass' ? shopGlass : lit;
        const mesh = new THREE.InstancedMesh(geometry, material, CAPACITY[name]);
        mesh.count = 0;
        // Seuls les gros volumes projettent une ombre : la passe d'ombre redessine tout ce qui en porte.
        mesh.castShadow = SHADOW_CASTERS.has(name);
        mesh.receiveShadow = true;
        mesh.frustumCulled = false;
        this.meshes.set(name, mesh);
        this.group.add(mesh);
      }
      this.ready = true;
      this.center.set(1e9, 1e9);
    });
  }

  /** Rhabille la zone autour du point visé quand il s'est assez déplacé. */
  update(x: number, z: number, show: boolean): void {
    this.group.visible = show && this.ready;
    if (!this.ready || !show) {
      if (this.center.x < 1e8) {
        this.center.set(1e9, 1e9);
        this.onRebuild(this.center);
      }
      return;
    }
    if (Math.hypot(x - this.center.x, z - this.center.y) < REBUILD_STEP) return;
    this.center.set(x, z);
    this.rebuild();
    this.onRebuild(this.center);
  }

  dispose(): void {
    this.meshes.forEach((m) => {
      m.geometry.dispose();
      m.dispose();
    });
  }

  /** Bâtiments remplacés par un vrai modèle : pas de pièces dessus. */
  private skip = new Set<number>();

  /** Fixe les bâtiments à ne plus habiller (remplacés par les bâtiments faits main). */
  setSkip(ids: Set<number>): void {
    this.skip = ids;
    this.refresh();
  }

  /** Vrai si ce bâtiment est habillé par les pièces (même règle que le shader des façades). */
  covers(b: Building): boolean {
    return (
      !this.skip.has(b.id) && Math.hypot(b.x - this.center.x, b.z - this.center.y) < HIGH_RADIUS
    );
  }

  /** Rhabille la zone : à rappeler quand les statuts des bâtiments changent. */
  refresh(): void {
    if (this.ready && this.center.x < 1e8) this.rebuild();
  }

  private rebuild(): void {
    const out = new Map<ModuleName, Placement[]>();
    const put = (name: ModuleName, matrix: THREE.Matrix4, hex = 0xffffff): void => {
      let list = out.get(name);
      if (!list) out.set(name, (list = []));
      if (list.length < CAPACITY[name]) list.push({ matrix, color: new THREE.Color(hex) });
    };
    for (const b of this.index) if (this.covers(b)) this.dress(b, put);
    this.meshes.forEach((mesh, name) => {
      const list = out.get(name) ?? [];
      list.forEach((p, i) => {
        mesh.setMatrixAt(i, p.matrix);
        mesh.setColorAt(i, p.color);
      });
      mesh.count = list.length;
      mesh.instanceMatrix.needsUpdate = true;
      if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
    });
  }

  /** Pièces d'un bâtiment. Façade principale côté rue ; toit selon son type. */
  private dress(
    b: Building,
    put: (name: ModuleName, m: THREE.Matrix4, hex?: number) => void,
  ): void {
    const p = this.palette;
    const night = p.litRatio > 0;
    const look = lookOf(b);
    const style = DISTRICT_STYLE[b.district];
    const floorH = b.h / b.floors;
    const south = b.facing === 'south';
    const frontZ = b.z + ((south ? 1 : -1) * b.d) / 2;
    const rot = new THREE.Quaternion().setFromAxisAngle(
      new THREE.Vector3(0, 1, 0),
      south ? 0 : Math.PI,
    );
    // Rendu coloré : menuiseries et appuis blancs, vitres bleu ciel.
    const toon = p.style === 'toon';
    const frame = toon ? p.trim : (pickFor(style.frames, b.id, 5) ?? 0xffffff);
    const stone = toon ? p.trim : night ? 0x5a5866 : 0xffffff;
    const dim = (hex: number): number =>
      night ? new THREE.Color(hex).multiplyScalar(0.35).getHex() : hex;
    /** Matrice d'une pièce posée en (x, y) sur la façade avant, mise à l'échelle (sx, sy, sz). */
    const onFront = (x: number, y: number, sx = 1, sy = 1, sz = 1, out = 0): THREE.Matrix4 =>
      new THREE.Matrix4().compose(
        new THREE.Vector3(x, y, frontZ + (south ? out : -out)),
        rot,
        new THREE.Vector3(sx, sy, sz),
      );

    if (b.type === 'tour' || b.type === 'entrepot') return;
    if (p.lush && (b.type === 'immeuble' || b.type === 'hotel' || b.type === 'residence')) {
      this.dressSober(b, put, onFront);
      return;
    }

    // Grille des fenêtres : la même que celle du shader, pour que les façades s'enchaînent.
    const house = b.type === 'pavillon' || b.type === 'villa' || b.type === 'motel';
    const margin = 0.06;
    const usable = b.w - 2 * margin;
    const cols = Math.max(1, Math.floor(usable / (house ? 0.62 : 0.42)));
    const colW = usable / cols;
    const winW = 2 * (house ? 0.17 : 0.2) * colW;
    const winH = 0.52 * floorH;
    const sx = winW / (WIN_W * METER);
    const sy = winH / (WIN_H * METER);
    const colX = (c: number): number => b.x - b.w / 2 + margin + (c + 0.5) * colW;
    const doorCol = Math.floor(cols / 2);
    const hasShop = b.shop && !house;
    const lastFloor = b.parts[0] ? Math.round(b.parts[0].h / floorH) : b.floors;

    for (let f = 0; f < lastFloor; f++) {
      const ground = f === 0;
      if (ground && (hasShop || !house)) continue;
      for (let c = 0; c < cols; c++) {
        if (ground && c === doorCol) continue;
        const x = colX(c);
        const y = f * floorH + 0.28 * floorH;
        const lit = night && hash01(b.id * 31 + f, c) < p.litRatio;
        const glassHex = night
          ? lit
            ? p.lit
            : 0x1a2030
          : toon
            ? p.glass
            : hash01(b.id + c, f) < 0.5
              ? 0x8fa4b8
              : 0x6f849a;
        put('glass', onFront(x, y, winW, winH, 1, 0.003), glassHex);
        if (look.classic || toon) {
          put('win_frame', onFront(x, y, sx, sy), dim(frame));
          if (b.type === 'immeuble') put('win_stone', onFront(x, y, sx, sy), stone);
        } else {
          put('win_modern', onFront(x, y, sx, sy), 0xffffff);
        }
        if (look.shutter !== null) put('shutters', onFront(x, y, sx, sy), dim(look.shutter));
        if (b.type === 'immeuble' && !ground && hash01(b.id * 7 + f, c) < 0.12) {
          put('ac', onFront(x, y - 0.002, 1, 1, 1, 0.005), 0xffffff);
        }
        if (
          (b.type === 'hotel' || b.type === 'residence') &&
          !ground &&
          (f + c) % 2 === 0 &&
          c % 2 === 0
        ) {
          put('balcony', onFront(x, f * floorH + 0.02, winW / 0.24, 1, 1), 0xffffff);
        }
      }
    }

    // Rez-de-chaussée : boutiques avec vitrine et auvent, ou porte d'entrée.
    if (hasShop) {
      const bays = Math.min(3, Math.max(1, Math.round(b.w / 0.3)));
      const bayW = b.w / bays;
      for (let i = 0; i < bays; i++) {
        const x = b.x - b.w / 2 + (i + 0.5) * bayW;
        const m = onFront(x, 0, bayW / 0.3, floorH / 0.39, 1);
        put('shop', m, 0xffffff);
        put('shop_glass', m, night ? 0xffd28a : 0xffffff);
        put(
          'awning',
          onFront(x, 0, (bayW * 0.93) / 0.28, floorH / 0.39, 1),
          dim(pickFor(style.awnings, b.id + i, 9) ?? 0x2a2f2d),
        );
      }
    } else {
      put(
        'door',
        onFront(colX(doorCol), 0, Math.min(1.4, colW / 0.13), floorH / (house ? 0.3 : 0.34), 1),
        dim(frame),
      );
    }

    // Bandeau de pierre au-dessus du rez-de-chaussée des immeubles (la corniche reste à la garniture).
    if (b.type === 'immeuble') put('band', onFront(b.x, floorH, b.w / 0.1, 1, 1), stone);

    // Escalier de secours sur les immeubles de brique.
    const brick = isBrick(look.wall);
    if (b.type === 'immeuble' && brick && cols >= 3 && b.floors >= 3 && hash01(b.id, 77) < 0.65) {
      const first = Math.floor(hash01(b.id, 78) * (cols - 1));
      const ex = (colX(first) + colX(first + 1)) / 2;
      const span = colW * 1.8;
      for (let f = 1; f < b.floors; f++) {
        const flip = f % 2 === 0 ? -1 : 1;
        put(
          'fire_escape',
          onFront(ex, f * floorH + 0.22 * floorH, (flip * span) / 0.26, floorH / 0.34, 1),
          0xffffff,
        );
      }
    }
  }

  /**
   * Immeuble sobre à relief, exactement comme le prototype (tools/blender/prototype-sobre.py) :
   * travées de mur enduit percées de fenêtres en creux, cadre blanc à croisillon, appui et linteau
   * de pierre ; pilastres et balcons filants en fer forgé, ou bow-window central ; bandeaux de
   * pierre tous les deux étages ; corniche à consoles ; vitrines et auvents au rez-de-chaussée.
   */
  private dressSober(
    b: Building,
    put: (name: ModuleName, m: THREE.Matrix4, hex?: number) => void,
    onFront: (
      x: number,
      y: number,
      sx?: number,
      sy?: number,
      sz?: number,
      out?: number,
    ) => THREE.Matrix4,
  ): void {
    const p = this.palette;
    const night = p.litRatio > 0;
    const style = DISTRICT_STYLE[b.district];
    const floorH = b.h / b.floors;
    const floors = b.parts[0] ? Math.round(b.parts[0].h / floorH) : b.floors;
    const wall = wallHex(p, b, this.statusOf(b));
    const trim = night ? 0x6a6e7c : 0xffffff;
    const margin = 0.06;
    const usable = b.w - 2 * margin;
    const cols = Math.max(1, Math.floor(usable / SOBER_PITCH));
    const colW = usable / cols;
    const colX = (c: number): number => b.x - b.w / 2 + margin + (c + 0.5) * colW;
    const sx = colW / (BAY_W * METER);
    const sy = floorH / (BAY_H * METER);
    const openW = OPEN_W * METER * sx;
    const openH = OPEN_H * METER * sy;
    const sill = SILL * METER * sy;
    const withOriel = cols >= 4 && hash01(b.id, 61) < 0.45;
    const withBalconies = !withOriel && hash01(b.id, 62) < 0.6;
    const underOriel = (c: number): boolean => withOriel && Math.abs(colX(c) - b.x) < colW * 0.9;

    for (let f = 0; f < floors; f++) {
      const y = f * floorH;
      if (f === 0 && b.shop) continue;
      for (let c = 0; c < cols; c++) {
        if (f > 0 && underOriel(c)) continue;
        const x = colX(c);
        const m = onFront(x, y, sx, sy);
        put('bay_wall', m, wall);
        if (f === 0 && c === Math.floor(cols / 2)) {
          put('door', onFront(x, 0, Math.min(1.4, colW / 0.13), floorH / 0.34, 1, 0.022), trim);
          continue;
        }
        put('bay_trim', m, trim);
        const lit = night && hash01(b.id * 31 + f, c) < p.litRatio;
        const glass = night
          ? lit
            ? p.lit
            : 0x1a2030
          : hash01(b.id + c, f) < 0.5
            ? 0x8fa4b8
            : 0x6f849a;
        put('glass', onFront(x, y + sill, openW, openH, 1, 0.003), glass);
        if (f > 0 && hash01(b.id * 7 + f, c) < 0.1) {
          put('ac', onFront(x, y + sill - 0.002, 1, 1, 1, 0.027), 0xffffff);
        }
        if (withBalconies && f % 2 === 1) {
          put('balcony_rail', onFront(x, y + sill, sx, 1, 1), trim);
        }
      }
      if (f > 0 && withBalconies) {
        for (let c = 0; c <= cols; c += 2) {
          put('pilaster', onFront(b.x - b.w / 2 + margin + c * colW, y, 1, sy, 1), trim);
        }
      }
      if (f > 0 && f % 2 === 0) put('stone_band', onFront(b.x, y, b.w / 0.1, 1, 1), trim);
      if (f > 0 && withOriel) {
        const m = onFront(b.x, y, sx, sy);
        put('oriel_wall', m, wall);
        put('oriel_trim', m, trim);
      }
    }
    if (withOriel) {
      put('oriel_cap', onFront(b.x, floorH - 0.025, sx, 1, 1), trim);
      put('oriel_cap', onFront(b.x, floors * floorH - floorH * 0.12, sx, 1, 1), trim);
    }

    // Rez-de-chaussée commerçant : vitrines, bandeau d'enseigne, auvents aux couleurs du quartier.
    if (b.shop) {
      const bays = Math.max(1, Math.round(b.w / 0.3));
      const bayW = b.w / bays;
      for (let i = 0; i < bays; i++) {
        const x = b.x - b.w / 2 + (i + 0.5) * bayW;
        const m = onFront(x, 0, bayW / 0.3, floorH / 0.39, 1);
        put('shop', m, 0xffffff);
        put('shop_glass', m, night ? 0xffd28a : 0xffffff);
        const awning = pickFor(style.awnings, b.id + i, 9) ?? 0x2a2f2d;
        put(
          'awning',
          onFront(x, 0, (bayW * 0.93) / 0.28, floorH / 0.39, 1),
          night ? new THREE.Color(awning).multiplyScalar(0.35).getHex() : awning,
        );
      }
    }
    put('stone_band', onFront(b.x, floorH, b.w / 0.1, 1.5, 1.2), trim);

    // Corniche à consoles, une tous les 3,5 m.
    const segments = Math.max(2, Math.round(b.w / 0.35));
    const segW = b.w / segments;
    for (let i = 0; i < segments; i++) {
      put(
        'cornice',
        onFront(b.x - b.w / 2 + (i + 0.5) * segW, floors * floorH, segW / 0.1, 1, 1, 0.022),
        trim,
      );
    }
  }
}
