import {
  botPlayDay,
  daysToCatchUp,
  debugClock,
  netWorth,
  newPlayer,
  type BotProfile,
  type DayReport,
  type PlayerState,
} from '../economy';

/** Simulation de debug : un joueur simulé vit sa partie en accéléré. */
export interface Simulation {
  profile: BotProfile;
  player: PlayerState;
  netWorth: number;
  lastReport: DayReport | null;
}

const PROFILES: readonly BotProfile[] = ['occasionnel', 'lambda', 'assidu'];
const MAX_DAYS_PER_TICK = 30;

/**
 * Lance la simulation si l'adresse contient `?sim` (ou `?sim=assidu`, `?sim=occasionnel`).
 * `&speed=0.5` règle la durée d'un jour en secondes (1 par défaut).
 */
export function startSimulation(search: string, onDay: () => void): Simulation | null {
  const params = new URLSearchParams(search);
  if (!params.has('sim')) return null;
  const asked = params.get('sim');
  const profile = PROFILES.find((p) => p === asked) ?? 'lambda';
  const seconds = Number(params.get('speed'));
  const clock = debugClock(Date.now(), seconds > 0 ? seconds : 1);
  const simulation: Simulation = {
    profile,
    player: newPlayer(),
    netWorth: newPlayer().cash,
    lastReport: null,
  };
  window.setInterval(() => {
    const due = Math.min(
      MAX_DAYS_PER_TICK,
      daysToCatchUp(clock, Date.now(), simulation.player.day),
    );
    if (due === 0) return;
    for (let i = 0; i < due; i++) {
      const step = botPlayDay(simulation.player, { profile, incidents: true });
      simulation.player = step.state;
      simulation.lastReport = step.report;
    }
    simulation.netWorth = netWorth(simulation.player);
    onDay();
  }, 200);
  return simulation;
}
