import {
  activeLoans,
  loansOf,
  advanceDay,
  buyProperty,
  creditTerms,
  netWorth,
  newPlayer,
  portfolioValue,
  totalDebt,
} from './engine';
import { averageCommission } from './hunting';
import { CALM_MARKET, crashMarket, growth } from './market';
import { RULES, type EconomyRules } from './rules';
import { marginalRate } from './tax';
import type { DayReport, PlayerState } from './types';

/**
 * Joueur simulé « sans stratégie abusée » : il chasse, achète le bien le plus cher que son
 * apport permet et garde une réserve. Sert aux tests de non-régression et à l'équilibrage.
 * Reproduit docs/reference/simulation-economie.js.
 */
export type BotProfile = 'occasionnel' | 'lambda' | 'assidu';

export const BOT_PROFILES: Record<BotProfile, { missionsPerDay: number; playsEvery: number }> = {
  occasionnel: { missionsPerDay: 2, playsEvery: 2 },
  lambda: { missionsPerDay: 4, playsEvery: 1 },
  assidu: { missionsPerDay: 6, playsEvery: 1 },
};

/** Prix de base du catalogue, du studio à l'hôtel. */
export const CATALOG_PRICES: readonly number[] = [
  50_000, 150_000, 300_000, 600_000, 1_000_000, 5_000_000,
];
export const CATALOG_RENT_RATE = 0.04;
const CASH_RESERVE = 5000;

export interface BotOptions {
  profile: BotProfile;
  days: number;
  /** Jour de début d'un krach, ou rien. */
  crashDay?: number;
  /** Vrai : le joueur subit des coups bas (−5 % de loyers après l'immunité de 3 jours). */
  incidents?: boolean;
}

export interface BotDay {
  day: number;
  cash: number;
  value: number;
  debt: number;
  netWorth: number;
  properties: number;
  creditLevel: number;
  report: DayReport;
}

/** Fait jouer une journée au joueur simulé et renvoie son nouvel état. */
export function botPlayDay(
  state: PlayerState,
  options: Omit<BotOptions, 'days'>,
  rules: EconomyRules = RULES,
): { state: PlayerState; report: DayReport } {
  const profile = BOT_PROFILES[options.profile];
  const day = state.day + 1;
  const plays = (day - 1) % profile.playsEvery === 0;
  const market =
    options.crashDay === undefined ? CALM_MARKET : crashMarket(day, options.crashDay, rules);
  const ownedBefore = state.properties.length;

  const result = advanceDay(
    state,
    {
      commissions: plays ? profile.missionsPerDay * averageCommission(day, rules) : 0,
      rentModifier: options.incidents && day > 3 ? 0.95 : 1,
      market,
    },
    rules,
  );
  let next = result.state;
  if (!plays) return { state: next, report: result.report };

  const terms = creditTerms(next.creditLevel, rules);
  if (activeLoans(next) >= terms.maxLoans) return { state: next, report: result.report };

  const due = loansOf(next).reduce((sum, l) => sum + l.dailyPayment, 0);
  const { rent, charges, agency } = result.report;
  const netRent = rent - charges - agency;
  const value = portfolioValue(next, market, rules);
  const agencyRate = ownedBefore + 1 >= rules.agencyFromProperties ? rules.agencyRate : 0;
  const keptAfterTax = 1 - marginalRate(netRent, rules.incomeTax);
  const wealthRate = marginalRate(value, rules.wealthTax);

  for (let i = CATALOG_PRICES.length - 1; i >= 0; i--) {
    const price = CATALOG_PRICES[i]! * growth(day, rules) * market.price;
    // Le joueur n'achète pas un bien qui lui coûterait plus en impôts qu'il ne rapporte.
    const dailyGain =
      price * CATALOG_RENT_RATE * (1 - rules.chargesRate - agencyRate) * keptAfterTax -
      price * wealthRate;
    if (dailyGain <= 0) continue;
    if (next.cash - (CASH_RESERVE + 2 * due) >= price * terms.downPaymentRate) {
      next = buyProperty(
        next,
        { id: `bot-${day}`, price, rentRate: CATALOG_RENT_RATE },
        market,
        rules,
      );
      break;
    }
  }
  return { state: next, report: result.report };
}

/** Simule un joueur sur plusieurs jours et renvoie un relevé par jour. */
export function simulateBot(options: BotOptions, rules: EconomyRules = RULES): BotDay[] {
  let state = newPlayer(rules);
  const days: BotDay[] = [];
  for (let i = 0; i < options.days; i++) {
    const result = botPlayDay(state, options, rules);
    state = result.state;
    const market =
      options.crashDay === undefined
        ? CALM_MARKET
        : crashMarket(state.day, options.crashDay, rules);
    days.push({
      day: state.day,
      cash: state.cash,
      value: portfolioValue(state, market, rules),
      debt: totalDebt(state),
      netWorth: netWorth(state, market, rules),
      properties: state.properties.length,
      creditLevel: state.creditLevel,
      report: result.report,
    });
  }
  return days;
}
