import { DISTRICTS } from '../city/data/layout';
import type { DistrictId } from '../city/model';
import { DEFAULT_SEED } from '../city/gen/city';
import type { GameState } from './types';

/**
 * Événements de ville (demande du propriétaire : « faire vivre la ville »). Un événement change les
 * prix et les loyers d'un quartier, ou de toute la ville, pendant quelques jours. Il est annoncé
 * dans la Gazette avant de commencer. Deux sources :
 *  - automatiques : un par semaine de jeu, tirés de la ville (identiques pour tous les joueurs),
 *    et un krach rare ;
 *  - créés par le propriétaire du jeu dans l'onglet Admin.
 * Valeurs par défaut, voir docs/QUESTIONS.md.
 */

export type EventKind =
  'metro' | 'factory' | 'festival' | 'gentrify' | 'scandal' | 'crash' | 'boom';

export interface CityEvent {
  id: string;
  kind: EventKind;
  /** Quartier touché, ou null pour toute la ville. */
  district: DistrictId | null;
  /** Jour où la Gazette l'annonce. */
  announceDay: number;
  startDay: number;
  /** Dernier jour d'effet (inclus). */
  endDay: number;
  /** Effet au plus fort, en multiplicateur (1,2 = +20 %). */
  price: number;
  rent: number;
  source: 'auto' | 'admin';
}

/** Catalogue : effet au plus fort, durée par défaut, portée. */
export const EVENT_KINDS: Record<
  EventKind,
  { price: number; rent: number; days: number; city: boolean; notice: number }
> = {
  metro: { price: 1.2, rent: 1.1, days: 12, city: false, notice: 3 },
  factory: { price: 0.8, rent: 0.88, days: 10, city: false, notice: 2 },
  festival: { price: 1, rent: 1.35, days: 3, city: false, notice: 2 },
  gentrify: { price: 1.15, rent: 1.08, days: 14, city: false, notice: 2 },
  scandal: { price: 0.85, rent: 0.95, days: 6, city: false, notice: 1 },
  crash: { price: 0.65, rent: 0.75, days: 40, city: true, notice: 3 },
  boom: { price: 1.12, rent: 1.05, days: 10, city: true, notice: 2 },
};

const LOCAL_KINDS: readonly EventKind[] = ['metro', 'factory', 'festival', 'gentrify', 'scandal'];
/** Un événement automatique par période de 7 jours ; krach : 1 chance sur 20 par période. */
export const AUTO_PERIOD = 7;
export const CRASH_ODDS = 0.05;

function hash(...parts: number[]): number {
  let h = 2166136261;
  for (const p of parts) {
    h ^= Math.floor(p) >>> 0;
    h = Math.imul(h, 16777619) >>> 0;
  }
  h = Math.imul(h ^ (h >>> 15), 2246822519) >>> 0;
  h = Math.imul(h ^ (h >>> 13), 3266489917) >>> 0;
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}

/** Quartiers où un événement peut tomber (pas la Zone 1 ni la Résidence des débutants). */
const EVENT_DISTRICTS: DistrictId[] = DISTRICTS.map((d) => d.id).filter(
  (d) => d !== 'zone1' && d !== 'premierpas',
);

/** Événements automatiques autour d'un jour (graine : l'horloge de la ville, la même pour tous). */
export function autoEvents(citySeed: number, day: number): CityEvent[] {
  const districts = EVENT_DISTRICTS;
  const out: CityEvent[] = [];
  const first = Math.max(1, Math.floor((day - 45) / AUTO_PERIOD));
  const last = Math.floor((day + 10) / AUTO_PERIOD);
  for (let k = first; k <= last; k++) {
    const crash = k >= 8 && hash(citySeed, k, 91) < CRASH_ODDS;
    const kind: EventKind = crash
      ? 'crash'
      : hash(citySeed, k, 5) < 0.12
        ? 'boom'
        : LOCAL_KINDS[Math.floor(hash(citySeed, k, 7) * LOCAL_KINDS.length)]!;
    const spec = EVENT_KINDS[kind];
    const startDay = k * AUTO_PERIOD + Math.floor(hash(citySeed, k, 11) * 4);
    out.push({
      id: `auto-${k}`,
      kind,
      district: spec.city ? null : districts[Math.floor(hash(citySeed, k, 13) * districts.length)]!,
      announceDay: startDay - spec.notice,
      startDay,
      endDay: startDay + spec.days - 1,
      price: spec.price,
      rent: spec.rent,
      source: 'auto',
    });
  }
  return out;
}

/** Tous les événements connus de la partie : automatiques et créés par l'Admin. */
export function cityEvents(state: GameState, day: number): CityEvent[] {
  // Graine fixe de la ville : les mêmes événements pour tous, quels que soient les réglages d'horloge.
  const auto = state.eventsOff ? [] : autoEvents(DEFAULT_SEED, day);
  return [...auto, ...(state.adminEvents ?? [])];
}

/**
 * Force d'un événement un jour donné, de 0 à 1 : monte sur le premier quart, tient, puis redescend
 * sur le dernier quart (un krach chute vite et se reprend lentement).
 */
export function intensity(event: CityEvent, day: number): number {
  if (day < event.startDay || day > event.endDay) return 0;
  const length = event.endDay - event.startDay + 1;
  const t = (day - event.startDay + 0.5) / length;
  const rise = event.kind === 'crash' ? 0.2 : 0.25;
  const fall = event.kind === 'crash' ? 0.6 : 0.25;
  if (t < rise) return t / rise;
  if (t > 1 - fall) return (1 - t) / fall;
  return 1;
}

/** Multiplicateurs de prix et de loyer d'un quartier, un jour donné (effets cumulés). */
export function districtEffect(
  events: readonly CityEvent[],
  district: DistrictId,
  day: number,
): { price: number; rent: number } {
  let price = 1;
  let rent = 1;
  for (const e of events) {
    if (e.district !== null && e.district !== district) continue;
    const k = intensity(e, day);
    if (k <= 0) continue;
    price *= 1 + (e.price - 1) * k;
    rent *= 1 + (e.rent - 1) * k;
  }
  return { price, rent };
}

/** Événements en cours ou annoncés, pour la Gazette et l'Admin, les plus proches d'abord. */
export function visibleEvents(events: readonly CityEvent[], day: number): CityEvent[] {
  return events
    .filter((e) => e.announceDay <= day && e.endDay >= day)
    .sort((a, b) => a.startDay - b.startDay);
}
