import type { GameState } from './types';

/**
 * Enchères en direct (grosse mise à jour, point 2). Les biens saisis par la banque, ceux perdus
 * pour inactivité et quelques biens mis en vente par la banque chaque jour partent aux enchères.
 * Une enchère dure 10 minutes réelles ; une mise dans la dernière minute la prolonge d'une minute.
 * Le gagnant paie comptant. Valeurs par défaut, voir docs/QUESTIONS.md.
 */

export type AuctionSource = 'bank' | 'seized' | 'inactive';
export type AuctionStatus = 'open' | 'won' | 'lost' | 'void';

export interface Auction {
  id: number;
  buildingId: number;
  source: AuctionSource;
  startPrice: number;
  /** Mise la plus haute, ou null s'il n'y en a pas encore. */
  topBid: number | null;
  /** Nom de celui qui mène. */
  topName: string | null;
  /** Vrai si c'est le joueur qui mène (ou qui a gagné). */
  leading: boolean;
  /** Vrai si le joueur a misé sur cette enchère. */
  bidder?: boolean;
  bids: number;
  endsAtMs: number;
  status: AuctionStatus;
  /** Hors ligne seulement : mise maximale cachée du concurrent. */
  rivalMax?: number;
  rivalName?: string;
}

/** Durée d'une enchère, prolongation sur une mise de dernière minute, hausse minimale. */
export const AUCTION_MS = 10 * 60_000;
export const EXTEND_MS = 60_000;
export const MIN_RAISE = 0.05;
/** Mise de départ : part de la valeur du bien. */
export const START_RATIO = 0.7;
/** Biens mis aux enchères par la banque chaque jour, et enchères ouvertes au plus. */
export const BANK_PER_DAY = 2;
export const MAX_OPEN = 6;
/** Une enchère terminée reste affichée ce temps-là. */
export const SHOW_ENDED_MS = 15 * 60_000;

export function roundPrice(value: number): number {
  return Math.max(100, Math.round(value / 100) * 100);
}

/** Plus petite mise acceptée. */
export function minBid(auction: Pick<Auction, 'topBid' | 'startPrice'>): number {
  return auction.topBid === null
    ? auction.startPrice
    : roundPrice(Math.ceil(auction.topBid * (1 + MIN_RAISE)));
}

export function isOpen(auction: Auction, nowMs: number): boolean {
  return auction.status === 'open' && nowMs < auction.endsAtMs;
}

/** Nouvelle fin d'enchère après une mise : prolongée si la mise tombe dans la dernière minute. */
export function extendedEnd(endsAtMs: number, nowMs: number): number {
  return Math.max(endsAtMs, nowMs + EXTEND_MS);
}

export type BidRefusal = 'closed' | 'low' | 'no_cash' | 'leading';

export function bidRefusal(
  state: GameState,
  auction: Auction | undefined,
  amount: number,
  nowMs: number,
): BidRefusal | null {
  if (!auction || !isOpen(auction, nowMs)) return 'closed';
  if (auction.leading && auction.topBid !== null) return 'leading';
  if (!Number.isFinite(amount) || amount < minBid(auction)) return 'low';
  if (state.player.cash < amount) return 'no_cash';
  return null;
}

/**
 * Hors ligne : le joueur mise, puis le concurrent répond aussitôt s'il le peut (mise automatique
 * jusqu'à son maximum caché).
 */
export function placeLocalBid(auction: Auction, amount: number, nowMs: number): Auction {
  let next: Auction = {
    ...auction,
    topBid: amount,
    topName: null,
    leading: true,
    bidder: true,
    bids: auction.bids + 1,
    endsAtMs: extendedEnd(auction.endsAtMs, nowMs),
  };
  const answer = minBid(next);
  if (auction.rivalMax !== undefined && answer <= auction.rivalMax) {
    next = {
      ...next,
      topBid: answer,
      topName: auction.rivalName ?? null,
      leading: false,
      bids: next.bids + 1,
    };
  }
  return next;
}

/** Enchères qui méritent un badge : celles où le joueur s'est fait dépasser. */
export function outbidCount(state: GameState, nowMs: number): number {
  return (state.auctions ?? []).filter((a) => isOpen(a, nowMs) && a.bidder === true && !a.leading)
    .length;
}
