import type { City, Plot } from '../city/model';
import { growth, RULES } from '../economy';
import type { GameState, Letter, LetterKind } from './types';

/**
 * Promoteur : acheter un terrain de la Zone 1, y lancer un chantier, puis louer ou revendre ce
 * qui a été construit. Réglages par défaut, à équilibrer (voir docs/QUESTIONS.md).
 */

/** Les biens construits ont un identifiant à part, au-delà de ceux des bâtiments de la ville. */
export const PLOT_ID_BASE = 100_000;

/** Prix du terrain à bâtir, en ducats le mètre carré (500, haut de la fourchette, × 0,4 pour la Zone 1). */
export const LAND_PRICE_PER_M2 = 200;
/** Loyer quotidien d'un programme livré, en part de sa valeur. */
export const BUILT_RENT_RATE = 0.04;

export type ProjectKind = 'houses' | 'apartments';

export const PROJECTS: Record<
  ProjectKind,
  { m2PerUnit: number; costPerUnit: number; valuePerUnit: number; days: number }
> = {
  houses: { m2PerUnit: 400, costPerUnit: 230_000, valuePerUnit: 360_000, days: 6 },
  apartments: { m2PerUnit: 800, costPerUnit: 820_000, valuePerUnit: 1_200_000, days: 10 },
};

export const PROJECT_KINDS: readonly ProjectKind[] = ['houses', 'apartments'];

type LetterAdder = (state: GameState, kind: LetterKind, params?: Letter['params']) => GameState;

export function plotPropertyId(index: number): string {
  return String(PLOT_ID_BASE + index);
}

export function plotIndexOf(propertyId: string | number): number | null {
  const n = Number(propertyId) - PLOT_ID_BASE;
  return Number.isInteger(n) && n >= 0 ? n : null;
}

export function plotArea(plot: Plot): number {
  return Math.round((plot.rect.x1 - plot.rect.x0) * (plot.rect.z1 - plot.rect.z0) * 100);
}

export function landPrice(plot: Plot, day: number): number {
  return Math.round((plotArea(plot) * LAND_PRICE_PER_M2 * growth(day, RULES)) / 1000) * 1000;
}

export type PlotStatus = 'free' | 'owned' | 'building' | 'built' | 'taken';

export function plotStatus(state: GameState, index: number): PlotStatus {
  const entry = state.plots[String(index)];
  if (entry) {
    if (entry.works) return 'building';
    if (state.player.properties.some((p) => p.id === plotPropertyId(index))) return 'built';
    // Programme livré puis vendu (ou saisi) : le terrain appartient désormais à quelqu'un d'autre.
    return entry.built ? 'taken' : 'owned';
  }
  return state.othersPlots?.includes(index) ? 'taken' : 'free';
}

export interface ProjectQuote {
  kind: ProjectKind;
  units: number;
  cost: number;
  value: number;
  days: number;
  refusal: 'too_small' | 'no_cash' | 'not_owned' | null;
}

/** Devis d'un programme sur un terrain : nombre de logements, coût, valeur à la livraison. */
export function projectQuote(
  state: GameState,
  city: City,
  index: number,
  kind: ProjectKind,
): ProjectQuote {
  const plot = city.plots[index];
  const rule = PROJECTS[kind];
  const units = plot ? Math.floor(plotArea(plot) / rule.m2PerUnit) : 0;
  const g = growth(state.player.day, RULES);
  const cost = Math.round((units * rule.costPerUnit * g) / 1000) * 1000;
  const value = Math.round((units * rule.valuePerUnit * g) / 1000) * 1000;
  let refusal: ProjectQuote['refusal'] = null;
  if (plotStatus(state, index) !== 'owned') refusal = 'not_owned';
  else if (units < 1) refusal = 'too_small';
  else if (state.player.cash < cost) refusal = 'no_cash';
  return { kind, units, cost, value, days: rule.days, refusal };
}

/** Achète un terrain nu, comptant. */
export function buyPlot(
  state: GameState,
  city: City,
  index: number,
  addLetter: LetterAdder,
): GameState {
  const plot = city.plots[index];
  if (!plot) throw new Error('Terrain introuvable');
  if (plotStatus(state, index) !== 'free') throw new Error('Terrain indisponible');
  const price = landPrice(plot, state.player.day);
  if (state.player.cash < price) throw new Error('Trésorerie insuffisante');
  const next: GameState = {
    ...state,
    player: { ...state.player, cash: state.player.cash - price },
    ledger: { ...state.ledger, land: state.ledger.land + price },
    plots: { ...state.plots, [String(index)]: { paid: price, works: null } },
  };
  return addLetter(next, 'plotBought', { ref: plot.ref, amount: price, area: plotArea(plot) });
}

/** Lance un chantier : payé d'avance, livré au bout de quelques jours. */
export function startProject(
  state: GameState,
  city: City,
  index: number,
  kind: ProjectKind,
  addLetter: LetterAdder,
): GameState {
  const quote = projectQuote(state, city, index, kind);
  if (quote.refusal) throw new Error(`Chantier refusé : ${quote.refusal}`);
  const entry = state.plots[String(index)]!;
  const next: GameState = {
    ...state,
    player: { ...state.player, cash: state.player.cash - quote.cost },
    ledger: { ...state.ledger, construction: state.ledger.construction + quote.cost },
    plots: {
      ...state.plots,
      [String(index)]: {
        ...entry,
        works: {
          kind,
          units: quote.units,
          doneDay: state.player.day + quote.days,
          startDay: state.player.day,
        },
      },
    },
  };
  return addLetter(next, 'buildStarted', {
    ref: city.plots[index]!.ref,
    kind,
    units: quote.units,
    amount: quote.cost,
    days: quote.days,
  });
}

/** Suite quotidienne : les chantiers terminés deviennent des biens neufs, à louer. */
export function dailyDevelopment(state: GameState, city: City, addLetter: LetterAdder): GameState {
  const day = state.player.day;
  let next = state;
  for (const [key, entry] of Object.entries(state.plots)) {
    if (!entry.works || entry.works.doneDay > day) continue;
    const index = Number(key);
    const plot = city.plots[index];
    const rule = PROJECTS[entry.works.kind];
    const value = entry.works.units * rule.valuePerUnit * growth(day, RULES);
    const id = plotPropertyId(index);
    next = {
      ...next,
      player: {
        ...next.player,
        properties: [
          ...next.player.properties,
          // Valeur du jour de livraison ; la hausse du marché s'applique ensuite comme pour tout bien.
          { id, buyDay: day, baseValue: value, baseRent: value * BUILT_RENT_RATE, loan: null },
        ],
      },
      plots: { ...next.plots, [key]: { ...entry, built: entry.works, works: null } },
      upkeep: { ...next.upkeep, [id]: { condition: 'new', since: day, works: null } },
      // Programme livré vide : les candidats locataires arrivent dès le lendemain.
      tenancy: { ...next.tenancy, [id]: { tenant: null, candidates: [] } },
      propertyStats: { ...next.propertyStats, [id]: { paid: entry.paid, rent: 0 } },
    };
    next = addLetter(next, 'buildDone', {
      ref: plot?.ref ?? key,
      kind: entry.works.kind,
      units: entry.works.units,
    });
  }
  return next;
}

/** Programme construit (ou en cours) sur un terrain, pour l'affichage. */
export function plotProgram(state: GameState, index: number) {
  const entry = state.plots[String(index)];
  return entry?.works ?? entry?.built ?? null;
}
