import { CITY_BOUNDS, districtDef } from '../city/data/layout';
import { METRO_STATIONS } from '../city/data/metro';
import type { City, Prop, Rect } from '../city/model';
import type { GameState, Position, Trip, TravelMode, Vehicle } from './types';

/**
 * Déplacements dans la ville. Visiter un bien ou commettre un coup bas demande d'être sur place ;
 * le reste se fait à distance. Les durées sont en heures de jeu : 24 heures font un jour.
 */

/** Distance d'un bout à l'autre de la ville, en suivant les rues (unités du monde). */
export const CROSSING = CITY_BOUNDS.x1 - CITY_BOUNDS.x0 + (CITY_BOUNDS.z1 - CITY_BOUNDS.z0);

/**
 * Vitesses réelles en ville, en km/h (1 unité = 10 m, donc 1 km/h = 100 unités par heure).
 * Le métro roule vite, mais il faut l'attendre et marcher jusqu'aux stations.
 */
export const SPEED_KMH: Record<TravelMode, number> = { walk: 5, bike: 15, car: 30, metro: 35 };
const UNITS_PER_KM = 100;
/** Attente moyenne sur le quai, en heures (5 minutes). */
export const METRO_WAIT_HOURS = 5 / 60;
export const METRO_FARE = 20;
export const VEHICLE_COST: Record<Vehicle, number> = { bike: 1500, car: 25_000 };
/** Trajet le plus court possible : quelques minutes de jeu. */
const MIN_HOURS = 0.05;
const AT_SITE = 0.5;

export const TRAVEL_MODES: readonly TravelMode[] = ['walk', 'bike', 'metro', 'car'];

export function distance(a: Prop, b: Prop): number {
  return Math.abs(a.x - b.x) + Math.abs(a.z - b.z);
}

function center(rect: Rect): Prop {
  return { x: (rect.x0 + rect.x1) / 2, z: (rect.z0 + rect.z1) / 2 };
}

/** Point de départ d'un nouveau joueur : la Résidence Premier Pas, réservée aux débutants. */
export function startPosition(): Position {
  return { ...center(districtDef('premierpas').rect), buildingId: null };
}

export function buildingPoint(city: City, buildingId: number): Prop | null {
  const b = city.buildings[buildingId];
  return b ? { x: b.x, z: b.z } : null;
}

function nearestStation(p: Prop): Prop {
  let best = METRO_STATIONS[0]!;
  for (const s of METRO_STATIONS) if (distance(p, s) < distance(p, best)) best = s;
  return best;
}

function hoursFor(mode: TravelMode, dist: number): number {
  return dist / (SPEED_KMH[mode] * UNITS_PER_KM);
}

export type TravelRefusal = 'vehicle' | 'no_cash' | 'here' | 'busy' | 'useless';

export interface TripPlan {
  mode: TravelMode;
  hours: number;
  cost: number;
  /** Étapes du trajet ; le premier point est le départ. */
  path: Prop[];
  /** Durée de chaque étape, en heures. */
  legs: number[];
  refusal: TravelRefusal | null;
}

/** Calcule un trajet sans l'effectuer : durée, coût, tracé et raison d'un éventuel refus. */
export function planTrip(state: GameState, from: Prop, to: Prop, mode: TravelMode): TripPlan {
  let path: Prop[];
  let legs: number[];
  let cost = 0;
  if (mode === 'metro') {
    const a = nearestStation(from);
    const b = nearestStation(to);
    path = [from, a, b, to];
    legs = [
      hoursFor('walk', distance(from, a)),
      METRO_WAIT_HOURS + hoursFor('metro', distance(a, b)),
      hoursFor('walk', distance(b, to)),
    ];
    cost = METRO_FARE;
  } else {
    // On suit les rues : d'abord est-ouest, puis nord-sud.
    const corner = { x: to.x, z: from.z };
    path = [from, corner, to];
    legs = [hoursFor(mode, distance(from, corner)), hoursFor(mode, distance(corner, to))];
  }
  const hours = Math.max(
    MIN_HOURS,
    legs.reduce((sum, h) => sum + h, 0),
  );
  let refusal: TravelRefusal | null = null;
  if (distance(from, to) < AT_SITE) refusal = 'here';
  else if (state.visiting) refusal = 'busy';
  else if ((mode === 'bike' || mode === 'car') && !state.vehicles.includes(mode))
    refusal = 'vehicle';
  else if (mode === 'metro' && path[1]!.x === path[2]!.x && path[1]!.z === path[2]!.z)
    refusal = 'useless';
  // Marcher reste gratuit et toujours possible, même avec un solde négatif.
  else if (cost > 0 && state.player.cash < cost) refusal = 'no_cash';
  return { mode, hours, cost, path, legs, refusal };
}

/** Position du joueur à un instant donné, en route ou non. */
export function positionAt(state: GameState, nowMs: number): Prop {
  const trip = state.travel;
  if (!trip) return { x: state.position.x, z: state.position.z };
  if (nowMs >= trip.arriveMs) return trip.path[trip.path.length - 1]!;
  const total = trip.legs.reduce((sum, h) => sum + h, 0) || 1;
  let left =
    ((Math.max(nowMs, trip.departMs) - trip.departMs) / (trip.arriveMs - trip.departMs)) * total;
  for (let i = 0; i < trip.legs.length; i++) {
    const leg = trip.legs[i]!;
    const a = trip.path[i]!;
    const b = trip.path[i + 1]!;
    if (left <= leg || i === trip.legs.length - 1) {
      const t = leg > 0 ? Math.min(1, left / leg) : 1;
      return { x: a.x + (b.x - a.x) * t, z: a.z + (b.z - a.z) * t };
    }
    left -= leg;
  }
  return trip.path[trip.path.length - 1]!;
}

/** Part du trajet effectuée, de 0 à 1. */
export function tripProgress(trip: Trip, nowMs: number): number {
  const span = trip.arriveMs - trip.departMs;
  return span <= 0 ? 1 : Math.min(1, Math.max(0, (nowMs - trip.departMs) / span));
}

/**
 * Durée réelle d'un trajet (décision du propriétaire : des déplacements presque instantanés).
 * Les vitesses gardent leur ordre (voiture et métro avant la marche), mais traverser toute la
 * ville à pied ne prend plus que TRAVEL_MAX_MS.
 */
export const TRAVEL_MIN_MS = 1500;
export const TRAVEL_MAX_MS = 10_000;
/** Durée de jeu (en heures) d'une traversée complète à pied : elle vaut TRAVEL_MAX_MS. */
const CROSSING_WALK_HOURS = CROSSING / (SPEED_KMH.walk * UNITS_PER_KM);

export function travelMs(hours: number): number {
  const share = Math.min(1, hours / CROSSING_WALK_HOURS);
  return Math.round(TRAVEL_MIN_MS + share * (TRAVEL_MAX_MS - TRAVEL_MIN_MS));
}

/** Le joueur se trouve devant ce bâtiment (et n'est pas en route). */
export function isOnSite(state: GameState, buildingId: number): boolean {
  return !state.travel && state.position.buildingId === buildingId;
}

/** Part vers un bâtiment. Un trajet en cours est interrompu et repart de l'endroit atteint. */
export function startTravel(
  state: GameState,
  city: City,
  buildingId: number,
  mode: TravelMode,
  nowMs: number,
): GameState {
  const to = buildingPoint(city, buildingId);
  if (!to) throw new Error('Bâtiment introuvable');
  if (isOnSite(state, buildingId)) throw new Error('Déjà sur place');
  const from = positionAt(state, nowMs);
  const trip = planTrip(state, from, to, mode);
  if (trip.refusal) throw new Error(`Trajet refusé : ${trip.refusal}`);
  return {
    ...state,
    player: { ...state.player, cash: state.player.cash - trip.cost },
    ledger: { ...state.ledger, transport: state.ledger.transport + trip.cost },
    position: { ...from, buildingId: null },
    travel: {
      buildingId,
      mode,
      path: trip.path,
      legs: trip.legs,
      departMs: nowMs,
      arriveMs: nowMs + travelMs(trip.hours),
    },
  };
}

/** Termine le trajet en cours si l'heure d'arrivée est passée. */
export function settleTravel(state: GameState, nowMs: number): GameState {
  const trip = state.travel;
  if (!trip || nowMs < trip.arriveMs) return state;
  const end = trip.path[trip.path.length - 1]!;
  return { ...state, travel: null, position: { ...end, buildingId: trip.buildingId } };
}

/** Le joueur s'arrête là où il est. */
export function stopTravel(state: GameState, nowMs: number): GameState {
  if (!state.travel) return state;
  return { ...state, travel: null, position: { ...positionAt(state, nowMs), buildingId: null } };
}

export function buyVehicle(state: GameState, vehicle: Vehicle): GameState {
  if (state.vehicles.includes(vehicle)) throw new Error('Déjà acheté');
  const cost = VEHICLE_COST[vehicle];
  if (state.player.cash < cost) throw new Error('Trésorerie insuffisante');
  return {
    ...state,
    player: { ...state.player, cash: state.player.cash - cost },
    ledger: { ...state.ledger, transport: state.ledger.transport + cost },
    vehicles: [...state.vehicles, vehicle],
  };
}
