import type { BuildingType, DistrictId } from '../model';
import type { ThemeId } from '../../theme/themes';

/** Couleurs de la scène 3D pour un thème. Valeurs hexadécimales 0xRRGGBB. */
export interface CityPalette {
  /** Rendu photographique (textures) ou rendu coloré façon jeu de ville (couleurs unies). */
  style: 'photo' | 'toon';
  /** Rendu réaliste du niveau haut : arbres touffus, squares à bassin, clôtures, moins de voitures. */
  lush?: boolean;
  background: number;
  ground: number;
  road: number;
  sidewalk: number;
  park: number;
  water: number;
  edge: number;
  marking: number;
  /** Lignes jaunes au centre des avenues. */
  centerLine: number;
  /** Bordure des trottoirs. */
  curb: number;
  /** Fond des îlots : jardins des maisons, cours des immeubles. */
  yard: number;
  courtyard: number;
  /** Ombre portée des bâtiments : couleur et opacité. */
  shadow: { color: number; opacity: number };
  wall: number;
  /** Teinte des façades par type : pierre, brique, enduit, verre. Restent claires et sobres. */
  walls: Record<BuildingType, number>;
  /** Façades des maisons et petits immeubles : une teinte par bâtiment, parmi celles-ci. */
  pastels: number[];
  /** Volets et portes d'entrée. */
  shutters: number[];
  /** Tôles des entrepôts et leurs bardages : une teinte par bâtiment. */
  industrialRoofs: number[];
  industrialWalls: number[];
  /** Corniches, encadrements, auvents. */
  trim: number;
  /** Murs-rideaux des tours : verre et montants. */
  curtain: number;
  mullion: number;
  /** Ferronnerie : escaliers de secours, garde-corps, réservoirs. */
  iron: number;
  /** Cheminées, soubassements. */
  brick: number;
  stone: number;
  /** Plage, quais du port. */
  sand: number;
  quay: number;
  glass: number;
  /** Fenêtres éclairées : couleur et part des fenêtres allumées. */
  lit: number;
  litRatio: number;
  door: number;
  tree: number;
  trunk: number;
  lamp: number;
  cars: number[];
  awnings: number[];
  roofs: Record<BuildingType, number>;
  districts: Record<DistrictId, number>;
  status: { mine: number; sale: number; incident: number; rival: number };
  selection: number;
  /** Lumière : ciel, sol, soleil. */
  light: { sky: number; ground: number; hemi: number; sun: number };
  /** Couleur du soleil (par défaut : blanc chaud le jour, bleu la nuit). */
  sunColor?: number;
}

