/** Choix déterministe dans une liste, selon l'identifiant d'un bâtiment. */
export function pickFor<T>(list: readonly T[], id: number, salt: number): T | undefined {
  if (list.length === 0) return undefined;
  return list[((id * 2654435761 + salt * 40503) >>> 0) % list.length];
}

