/**
 * Rendu coloré, façon jeu de ville : sol vert, trottoirs clairs, routes gris-bleu, ciel bleu,
 * lumière franche. Construit à partir du thème choisi ; la nuit, tout est assombri.
 */
export function toonPalette(base: CityPalette): CityPalette {
  const night = base.litRatio > 0;
  const k = (hex: number, f = 0.32): number => {
    if (!night) return hex;
    const r = Math.round(((hex >> 16) & 255) * f);
    const g = Math.round(((hex >> 8) & 255) * f);
    const b = Math.round((hex & 255) * f);
    return (r << 16) | (g << 8) | b;
  };
  return {
    ...base,
    style: 'toon',
    background: night ? base.background : 0xa9d8ff,
    ground: k(0x7cc95a),
    road: k(0x6e7385, 0.45),
    sidewalk: k(0xece6da),
    curb: k(0xd3ccbd),
    park: k(0x5fae45),
    water: k(0x4fb3e8, 0.45),
    yard: k(0x7cc95a),
    courtyard: k(0x8fd16a),
    marking: k(0xffffff, 0.6),
    centerLine: k(0xf2c230, 0.6),
    glass: night ? 0x1a2433 : 0x5aa9e6,
    trim: k(0xffffff, 0.55),
    tree: k(0x54b948, 0.4),
    trunk: k(0x8a5a3c, 0.4),
    cars: [0xe63946, 0xf2c230, 0x2e86de, 0xffffff, 0x2a9d8f, 0xf4a261, 0x6a4c93, 0x3a3f4f].map(
      (c) => k(c, 0.5),
    ),
    awnings: [0xe63946, 0x2a9d8f, 0xf4a261, 0x2e86de, 0x6a4c93].map((c) => k(c, 0.5)),
    light: night ? base.light : { sky: 0xdff0ff, ground: 0x9bc77a, hemi: 0.72, sun: 1.1 },
  };
}

/**
 * Rendu réaliste du niveau « haut », d'après le modèle validé par le propriétaire
 * (tools/blender/prototype-ultime.py) : pelouses, trottoirs clairs, asphalte, menuiseries
 * blanc cassé, pierre crème, vitres sombres, soleil chaud de fin d'après-midi.
 */
export function realPalette(base: CityPalette): CityPalette {
  const night = base.litRatio > 0;
  const k = (hex: number, f = 0.3): number => {
    if (!night) return hex;
    const r = Math.round(((hex >> 16) & 255) * f);
    const g = Math.round(((hex >> 8) & 255) * f);
    const b = Math.round((hex & 255) * f);
    return (r << 16) | (g << 8) | b;
  };
  return {
    ...base,
    style: 'photo',
    lush: true,
    // Murs : la brique et la pierre gardent leur couleur photographiée.
    walls: Object.fromEntries(
      Object.keys(base.walls).map((t) => [t, night ? 0x6a6e7c : 0xf6f4f0]),
    ) as CityPalette['walls'],
    // Essai « Riviera » (image de l'accueil) : brume dorée, verts d'olivier, mer bleu profond.
    background: night ? base.background : 0xf7ecdc,
    ground: k(0x93b468),
    road: k(0x75726c, 0.5),
    sidewalk: k(0xe8dfcf),
    curb: k(0xd3c8b4),
    park: k(0x86ab5c),
    yard: k(0x93b468),
    courtyard: k(0xc9bea6),
    water: k(0x2c7cad, 0.45),
    shadow: night ? base.shadow : { color: 0x3a4f7a, opacity: 0.26 },
    sunColor: night ? undefined : 0xffcf98,
    marking: k(0xf2f2ee, 0.6),
    centerLine: k(0xe5b31f, 0.6),
    trim: night ? 0x8f9ab5 : 0xfbf6ec,
    stone: night ? 0x5a5866 : 0xecdec4,
    glass: night ? 0x1a2433 : 0x35536e,
    curtain: night ? base.curtain : 0x2f5d7e,
    mullion: night ? base.mullion : 0xdadde0,
    tree: k(0x3f7d3a, 0.4),
    trunk: k(0x6a4a34, 0.4),
    cars: [0xb3261e, 0xf2f2f0, 0xe8b923, 0x2b4f9e, 0x2f6b4f, 0xb9bec6, 0x1d2026].map((c) =>
      k(c, 0.5),
    ),
    // Liquid Glass : lumière laiteuse, ombres plus claires et teintées de bleu.
    // Ciel bleu en lumière d'appoint (ombres bleutées), soleil doré plus franc.
    light: night ? base.light : { sky: 0xdde8ff, ground: 0xc9b493, hemi: 0.95, sun: 1.55 },
  };
}
