import * as THREE from 'three';
import type { Building, BuildingPart, BuildingStatus, City, Rect } from '../model';
import { Batch } from './batch';
import { facadeMaterial, lookOf, setLooks, styledLook } from './facadeMaterial';
import { DISTRICT_STYLE, pickFor, TOON_ROOFS, TOON_WALLS } from './palette';
import type { CityPalette } from './palette';

export interface StaticScene {
  /** Tout ce qui ne change pas : sol, eau, routes, îlots. */
  ground: THREE.Group;
  /** Bâtiments, toits et arêtes : ce groupe s'aplatit quand on dézoome. */
  buildings: THREE.Group;
  /**
   * Volumes cliquables, par zone de la ville : chaque zone est un maillage à part, que la carte
   * graphique ignore quand il est hors de l'écran.
   */
  pickMeshes: THREE.InstancedMesh[];
  /** Volumes affichés, dans le même ordre que pickMeshes (pour les recolorer). */
  renderMeshes: THREE.InstancedMesh[];
  /** Pour chaque zone, l'identifiant du bâtiment de chacun de ses volumes. */
  partOwners: number[][];
  edges: THREE.LineSegments;
  /** Couleurs des quartiers sur les îlots : visibles seulement de loin. */
  districtTint: THREE.Mesh;
  /** Ombres portées, par zone : visibles quand les bâtiments ont leur vraie hauteur. */
  shadows: THREE.Group;
  shadowMaterial: THREE.MeshBasicMaterial;
  /** Matériau des façades, pour lui indiquer les tuiles habillées en graphismes haut. */
  facade: THREE.Material;
  /**
   * Masque à l'affichage les bâtiments donnés (remplacés par de vrais modèles), sans les
   * retirer du toucher : leurs volumes invisibles restent sélectionnables.
   */
  hideBuildings: (ids: Set<number>) => void;
  /** Sol (chaussées, trottoirs, îlots) : reçoit les vraies ombres en graphismes haut. */
  surface: THREE.Mesh;
}

/** Hauteur des trottoirs au-dessus de la chaussée. */
export const CURB_HEIGHT = 0.05;
/** Direction du soleil (vers la lumière), partagée avec l'éclairage de la vue 3D. */
export const SUN_POSITION = { x: -80, y: 75, z: 55 } as const;

/** Ombre d'un volume au sol : son empreinte étirée à l'opposé du soleil, selon sa hauteur. */
function pushShadow(batch: Batch, part: BuildingPart, hex: number): void {
  const top = part.y0 + part.h;
  const dx = (-SUN_POSITION.x / SUN_POSITION.y) * top;
  const dz = (-SUN_POSITION.z / SUN_POSITION.y) * top;
  const x0 = part.x - part.w / 2;
  const x1 = part.x + part.w / 2;
  const z0 = part.z - part.d / 2;
  const z1 = part.z + part.d / 2;
  const y = CURB_HEIGHT + 0.012;
  // Le soleil vient de l'ouest et du sud : l'ombre part vers l'est et le nord. Deux bandes.
  batch.freeQuad([x1, y, z0], [x1 + dx, y, z0 + dz], [x1 + dx, y, z1 + dz], [x1, y, z1], hex);
  batch.freeQuad([x0, y, z0], [x1, y, z0], [x1 + dx, y, z0 + dz], [x0 + dx, y, z0 + dz], hex);
}

/** Arêtes d'un pavé, ajoutées à un tableau de positions pour THREE.LineSegments. */
export function pushBoxEdges(part: BuildingPart, out: number[], grow = 0): void {
  const x0 = part.x - part.w / 2 - grow;
  const x1 = part.x + part.w / 2 + grow;
  const z0 = part.z - part.d / 2 - grow;
  const z1 = part.z + part.d / 2 + grow;
  const y0 = part.y0;
  const y1 = part.y0 + part.h + grow;
  const corners: [number, number][] = [
    [x0, z0],
    [x1, z0],
    [x1, z1],
    [x0, z1],
  ];
  for (let i = 0; i < 4; i++) {
    const a = corners[i]!;
    const b = corners[(i + 1) % 4]!;
    out.push(a[0], y0, a[1], b[0], y0, b[1]);
    out.push(a[0], y1, a[1], b[0], y1, b[1]);
    out.push(a[0], y0, a[1], a[0], y1, a[1]);
  }
}

export function gableGeometry(): THREE.BufferGeometry {
  // Toit à deux pans : base 1 × 1, hauteur 1, faîtage le long de l'axe x.
  const v = {
    a: [-0.5, 0, -0.5],
    b: [0.5, 0, -0.5],
    c: [0.5, 0, 0.5],
    d: [-0.5, 0, 0.5],
    e: [-0.5, 1, 0],
    f: [0.5, 1, 0],
  } as const;
  const tris = [
    v.a,
    v.e,
    v.f,
    v.a,
    v.f,
    v.b,
    v.d,
    v.c,
    v.f,
    v.d,
    v.f,
    v.e,
    v.a,
    v.d,
    v.e,
    v.b,
    v.f,
    v.c,
  ];
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.Float32BufferAttribute(tris.flat(), 3));
  geometry.computeVertexNormals();
  return geometry;
}

function pyramidGeometry(topRatio: number): THREE.BufferGeometry {
  // Base carrée 1 × 1, hauteur 1. topRatio = 0 : pyramide ; > 0 : toit à la Mansart.
  const geometry = new THREE.CylinderGeometry(
    Math.SQRT1_2 * topRatio,
    Math.SQRT1_2,
    1,
    4,
    1,
  ).toNonIndexed();
  geometry.rotateY(Math.PI / 4);
  geometry.translate(0, 0.5, 0);
  geometry.computeVertexNormals();
  return geometry;
}

/** Débord des toits à pans, en part de la largeur des murs. */
export const ROOF_OVERHANG = 1.16;

/** Hauteur du toit au-dessus des murs. Les pentes sont un peu exagérées, comme une maquette. */
export function roofHeight(b: Building): number {
  const span = Math.min(b.w, b.d);
  if (b.type === 'entrepot') return span * 0.14;
  if (b.roof === 'gable') return span * 0.5;
  if (b.roof === 'hip') return span * 0.38;
  if (b.roof === 'mansard') return 0.3;
  return 0;
}

/** Côté d'une zone de rendu, en unités : la ville en compte une douzaine. */
const REGION_SIZE = 100;

/** Regroupe les bâtiments par zone carrée de la ville. */
function regionsOf(city: City): Building[][] {
  const regions = new Map<string, Building[]>();
  for (const b of city.buildings) {
    const key = `${Math.floor(b.x / REGION_SIZE)}:${Math.floor(b.z / REGION_SIZE)}`;
    const list = regions.get(key);
    if (list) list.push(b);
    else regions.set(key, [b]);
  }
  return [...regions.values()];
}

function insetRect(r: Rect, by: number): Rect {
  return { x0: r.x0 + by, z0: r.z0 + by, x1: r.x1 - by, z1: r.z1 - by };
}

/** Retire la face du dessous d'un pavé (deux triangles de moins par bâtiment). */
function withoutBottom(box: THREE.BoxGeometry): THREE.BufferGeometry {
  const g = box.toNonIndexed();
  const pos = g.getAttribute('position');
  const nor = g.getAttribute('normal');
  const keepPos: number[] = [];
  const keepNor: number[] = [];
  for (let i = 0; i < pos.count; i += 3) {
    if (nor.getY(i) < -0.5) continue;
    for (let k = 0; k < 3; k++) {
      keepPos.push(pos.getX(i + k), pos.getY(i + k), pos.getZ(i + k));
      keepNor.push(nor.getX(i + k), nor.getY(i + k), nor.getZ(i + k));
    }
  }
  const out = new THREE.BufferGeometry();
  out.setAttribute('position', new THREE.Float32BufferAttribute(keepPos, 3));
  out.setAttribute('normal', new THREE.Float32BufferAttribute(keepNor, 3));
  return out;
}

/** Couleur des murs d'un bâtiment selon son statut. */
export function wallHex(palette: CityPalette, building: Building, status: BuildingStatus): number {
  if (status !== 'none') return palette.status[status];
  // Chaque façade a sa nuance : deux voisins ne sont jamais tout à fait identiques.
  const shade = 0.93 + ((building.id * 37) % 17) / 200;
  const night = palette.litRatio > 0;
  const look = lookOf(building);
  let base: number;
  if (palette.style === 'toon') {
    // Rendu coloré : chaque façade prend une couleur vive (ou douce) de son quartier.
    const tint = pickFor(TOON_WALLS[building.district], building.id, 3) ?? 0xffffff;
    const own = building.type === 'pavillon' || building.type === 'villa';
    const hex = own ? (pickFor(TOON_WALLS[building.district], building.id, 8) ?? tint) : tint;
    base = night ? new THREE.Color(hex).multiplyScalar(0.32).getHex() : hex;
    return new THREE.Color(base).multiplyScalar(0.97 + ((building.id * 37) % 7) / 200).getHex();
  }
  if (look.painted) {
    // Façade peinte : la couleur du quartier, assombrie la nuit.
    const tint = pickFor(DISTRICT_STYLE[building.district].walls, building.id, 3) ?? palette.wall;
    base = night ? new THREE.Color(tint).multiplyScalar(0.32).getHex() : tint;
  } else if (building.type === 'entrepot') {
    base = palette.industrialWalls[(building.id * 31) % palette.industrialWalls.length]!;
  } else {
    base = palette.walls[building.type];
  }
  return new THREE.Color(base).multiplyScalar(shade).getHex();
}

export function buildStaticScene(
  city: City,
  palette: CityPalette,
  statusOf: (building: Building) => BuildingStatus,
): StaticScene {
  const ground = new THREE.Group();
  const flat = new THREE.MeshBasicMaterial({ vertexColors: true, side: THREE.DoubleSide });

  // La carte s'arrête avec la ville (demande du propriétaire : pas de terrain vide autour) :
  // une presqu'île entièrement bâtie, entourée par la mer à perte de vue.
  const b = city.bounds;
  const spanX = (b.x1 - b.x0) * 2.5;
  const spanZ = (b.z1 - b.z0) * 3;
  const base = new THREE.Mesh(
    new THREE.PlaneGeometry(spanX, spanZ),
    new THREE.MeshBasicMaterial({ color: palette.water }),
  );
  base.rotation.x = -Math.PI / 2;
  base.position.set((b.x0 + b.x1) / 2, -0.03, (b.z0 + b.z1) / 2);
  ground.add(base);

  // Terre ferme de la ville, avec une bande de quai tout autour ; puis chaussées et îlots.
  const surface = new Batch();
  const shore = 2.5;
  surface.floor(b.x0 - shore, b.z0 - shore, b.x1 + shore, city.coastZ, -0.022, palette.quay);
  surface.floor(b.x0 - 0.6, b.z0 - 0.6, b.x1 + 0.6, city.coastZ, -0.021, palette.ground);
  for (const d of city.districts) {
    surface.floor(d.rect.x0, d.rect.z0, d.rect.x1, d.rect.z1, 0, palette.road);
  }
  for (const road of city.roads) {
    if (road.kind === 'avenue') {
      surface.floor(road.rect.x0, road.rect.z0, road.rect.x1, road.rect.z1, 0, palette.road);
    }
  }
  // Îlots : trottoir surélevé avec sa bordure, puis jardins (maisons) ou cours (immeubles).
  // La couleur du quartier n'apparaît que sur le plan de la ville, dans un calque à part.
  const tint = new Batch();
  for (const block of city.blocks) {
    const r = block.rect;
    surface.box(
      (r.x0 + r.x1) / 2,
      0,
      (r.z0 + r.z1) / 2,
      r.x1 - r.x0,
      CURB_HEIGHT,
      r.z1 - r.z0,
      palette.sidewalk,
    );
    const inner = insetRect(r, 0.3);
    const residential = block.district === 'tilleuls' || block.district === 'privilege';
    const ground =
      block.kind === 'park' ? palette.park : residential ? palette.yard : palette.courtyard;
    surface.floor(inner.x0, inner.z0, inner.x1, inner.z1, CURB_HEIGHT + 0.004, ground);
    if (block.kind !== 'park') {
      tint.floor(
        inner.x0,
        inner.z0,
        inner.x1,
        inner.z1,
        CURB_HEIGHT + 0.008,
        palette.districts[block.district],
      );
    }
  }
  // Squares du rendu réaliste : allées en croix et bassin au centre.
  if (palette.lush) {
    const monumentAt = (rect: Rect): boolean =>
      city.monuments.some((m) => m.rect.x0 === rect.x0 && m.rect.z0 === rect.z0);
    for (const block of city.blocks) {
      if (block.kind !== 'park' || monumentAt(block.rect)) continue;
      const r = insetRect(block.rect, 0.3);
      const cx = (r.x0 + r.x1) / 2;
      const cz = (r.z0 + r.z1) / 2;
      const y = CURB_HEIGHT + 0.006;
      surface.floor(cx - 0.09, r.z0, cx + 0.09, r.z1, y, palette.sidewalk);
      surface.floor(r.x0, cz - 0.09, r.x1, cz + 0.09, y, palette.sidewalk);
      const radius = Math.min(r.x1 - r.x0, r.z1 - r.z0) * 0.16;
      if (radius < 0.35) continue;
      surface.cylinder(cx, y, cz, radius, 0.05, palette.stone, 24);
      surface.disc(cx, cz, radius * 0.88, y + 0.052, palette.water, 24);
      surface.cylinder(cx, y, cz, 0.05, 0.16, palette.stone, 10);
    }
  }
  const districtTint = tint.toMesh(
    new THREE.MeshBasicMaterial({
      vertexColors: true,
      side: THREE.DoubleSide,
      transparent: true,
      depthWrite: false,
    }),
  );
  ground.add(districtTint);
  // Front de mer et port.
  for (const r of city.seafront.gardens) surface.floor(r.x0, r.z0, r.x1, r.z1, 0.02, palette.park);
  for (const r of city.seafront.promenade) {
    surface.floor(r.x0, r.z0, r.x1, r.z1, 0.03, palette.sidewalk);
  }
  for (const r of city.seafront.beach) surface.floor(r.x0, r.z0, r.x1, r.z1, 0.02, palette.sand);
  for (const r of city.quays) surface.floor(r.x0, r.z0, r.x1, r.z1, 0.04, palette.quay);
  // Ronds-points : bordure claire, îlot central planté.
  for (const p of city.roundabouts) {
    surface.disc(p.x, p.z, 0.72, 0.06, palette.sidewalk);
    surface.disc(p.x, p.z, 0.6, 0.07, palette.park);
  }
  const surfaceMesh = surface.toMesh(flat);
  // Normales du sol : nécessaires à l'éclairage et au grain des graphismes haut.
  surfaceMesh.geometry.computeVertexNormals();
  ground.add(surfaceMesh);

  // Ombres portées des bâtiments, projetées à l'opposé du soleil, par zone (hors écran : ignorées).
  const shadowMaterial = new THREE.MeshBasicMaterial({
    vertexColors: true,
    side: THREE.DoubleSide,
    transparent: true,
    opacity: palette.shadow.opacity,
    depthWrite: false,
  });
  const shadows = new THREE.Group();
  for (const region of regionsOf(city)) {
    const shade = new Batch();
    for (const b of region)
      for (const part of b.parts) pushShadow(shade, part, palette.shadow.color);
    const mesh = shade.toMesh(shadowMaterial);
    mesh.geometry.computeBoundingSphere();
    mesh.renderOrder = 1;
    shadows.add(mesh);
  }
  ground.add(shadows);

  // Bateaux amarrés le long des quais : coque sombre, cabine claire.
  if (city.boats.length > 0) {
    const boats = new Batch();
    for (const b of city.boats) {
      boats.box(b.x, 0, b.z, 1.1, 0.35, b.length, palette.edge);
      boats.box(b.x, 0.35, b.z - b.length * 0.1, 0.8, 0.3, b.length * 0.35, palette.walls.villa);
    }
    ground.add(boats.toMesh(flat));
  }

  // Rivière : ruban qui suit la ligne centrale, puis ponts là où une route la traverse.
  const water = new Batch();
  const curve = new THREE.CatmullRomCurve3(city.river.map((p) => new THREE.Vector3(p.x, 0, p.z)));
  const steps = 160;
  let previous: { lx: number; lz: number; rx: number; rz: number } | null = null;
  const half = city.riverHalfWidth;
  for (let i = 0; i <= steps; i++) {
    const p = curve.getPointAt(i / steps);
    const t = curve.getTangentAt(i / steps);
    const side = {
      lx: p.x - t.z * half,
      lz: p.z + t.x * half,
      rx: p.x + t.z * half,
      rz: p.z - t.x * half,
    };
    if (previous) waterQuad(water, previous, side, 0.07, palette.water);
    previous = side;
  }
  const bridges = new Batch();
  const samples = curve.getSpacedPoints(400);
  for (const road of city.roads) {
    const r = road.rect;
    let min = Infinity;
    let max = -Infinity;
    for (const s of samples) {
      const near = s.x > r.x0 - half && s.x < r.x1 + half && s.z > r.z0 - half && s.z < r.z1 + half;
      if (!near) continue;
      const along = road.horizontal ? s.x : s.z;
      min = Math.min(min, along - half - 0.4);
      max = Math.max(max, along + half + 0.4);
    }
    if (min > max) continue;
    if (road.horizontal) bridges.floor(min, r.z0, max, r.z1, 0.1, palette.road);
    else bridges.floor(r.x0, min, r.x1, max, 0.1, palette.road);
  }
  ground.add(water.toMesh(flat));
  if (!bridges.isEmpty) ground.add(bridges.toMesh(flat));

  // Parcelles à bâtir de la Zone 1 : contours en pointillés.
  const plotLines: number[] = [];
  for (const plot of city.plots) {
    const r = insetRect(plot.rect, 0.35);
    plotLines.push(r.x0, 0.07, r.z0, r.x1, 0.07, r.z0, r.x1, 0.07, r.z0, r.x1, 0.07, r.z1);
    plotLines.push(r.x1, 0.07, r.z1, r.x0, 0.07, r.z1, r.x0, 0.07, r.z1, r.x0, 0.07, r.z0);
  }
  if (plotLines.length > 0) {
    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute('position', new THREE.Float32BufferAttribute(plotLines, 3));
    const lines = new THREE.LineSegments(
      geometry,
      new THREE.LineDashedMaterial({
        color: palette.edge,
        dashSize: 0.5,
        gapSize: 0.4,
        transparent: true,
        opacity: 0.6,
      }),
    );
    lines.computeLineDistances();
    ground.add(lines);
  }

  // Bâtiments, par zone : un maillage instancié pour les volumes, trois pour les toits.
  const buildings = new THREE.Group();
  const pickMeshes: THREE.InstancedMesh[] = [];
  const renderMeshes: THREE.InstancedMesh[] = [];
  const partOwners: number[][] = [];
  // Pavé sans face du dessous : la caméra est toujours au-dessus de la ville.
  const boxGeometry = withoutBottom(new THREE.BoxGeometry(1, 1, 1));
  boxGeometry.translate(0, 0.5, 0);
  const lambert = facadeMaterial(palette);
  const night = palette.litRatio > 0;
  const roofGeometries = {
    gable: gableGeometry(),
    hip: pyramidGeometry(0),
    mansard: pyramidGeometry(0.72),
  };
  const matrix = new THREE.Matrix4();
  const color = new THREE.Color();
  const edgePositions: number[] = [];
  const quarterTurn = new THREE.Matrix4().makeRotationY(Math.PI / 2);

  // Pour masquer un bâtiment : ses instances (volumes et toit) et leur matrice d'origine.
  const renderRefs = new Map<
    number,
    { mesh: THREE.InstancedMesh; index: number; matrix: THREE.Matrix4 }[]
  >();
  const refOf = (id: number) => {
    let list = renderRefs.get(id);
    if (!list) renderRefs.set(id, (list = []));
    return list;
  };
  for (const region of regionsOf(city)) {
    const parts: BuildingPart[] = [];
    const owners: number[] = [];
    for (const b of region) {
      for (const part of b.parts) {
        parts.push(part);
        owners.push(b.id);
      }
    }
    const regionBox = boxGeometry.clone();
    setLooks(
      regionBox,
      owners.map((id) => {
        const b = city.buildings[id]!;
        return {
          look: styledLook(b, palette),
          seed: b.id,
          floorH: b.h / b.floors,
          south: b.facing === 'south',
        };
      }),
      night,
    );
    const mesh = new THREE.InstancedMesh(regionBox, lambert, parts.length);
    parts.forEach((part, i) => {
      const owner = city.buildings[owners[i]!]!;
      matrix.makeScale(part.w, part.h, part.d);
      matrix.setPosition(part.x, part.y0, part.z);
      mesh.setMatrixAt(i, matrix);
      mesh.setColorAt(i, color.setHex(wallHex(palette, owner, statusOf(owner))));
      refOf(owner.id).push({ mesh, index: i, matrix: matrix.clone() });
      pushBoxEdges(part, edgePositions);
    });
    mesh.instanceMatrix.needsUpdate = true;
    if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
    mesh.computeBoundingSphere();
    mesh.computeBoundingBox();
    buildings.add(mesh);
    // Double invisible des volumes, pour le toucher : il garde ses matrices même quand un
    // bâtiment est masqué à l'affichage (le lancer de rayon ignore la visibilité).
    const pick = new THREE.InstancedMesh(regionBox, lambert, parts.length);
    pick.instanceMatrix.copy(mesh.instanceMatrix);
    pick.visible = false;
    pick.computeBoundingSphere();
    pick.computeBoundingBox();
    buildings.add(pick);
    pickMeshes.push(pick);
    renderMeshes.push(mesh);
    partOwners.push(owners);

    for (const kind of ['gable', 'hip', 'mansard'] as const) {
      const list = region.filter((b) => b.roof === kind);
      if (list.length === 0) continue;
      const roofGeometry = roofGeometries[kind].clone();
      setLooks(
        roofGeometry,
        list.map((b) => ({ look: styledLook(b, palette), seed: b.id, floorH: 0 })),
        night,
      );
      const roofs = new THREE.InstancedMesh(roofGeometry, lambert, list.length);
      list.forEach((b, i) => {
        // Toits à pans généreux, qui débordent des murs : la ville a l'air habitée.
        const eave = kind === 'mansard' ? 1 : ROOF_OVERHANG;
        const w = b.w * eave;
        const d = b.d * eave;
        const alongZ = kind === 'gable' && b.d > b.w;
        if (alongZ) matrix.makeScale(d, roofHeight(b), w).premultiply(quarterTurn);
        else matrix.makeScale(w, roofHeight(b), d);
        matrix.setPosition(b.x, b.h, b.z);
        roofs.setMatrixAt(i, matrix);
        refOf(b.id).push({ mesh: roofs, index: i, matrix: matrix.clone() });
        const roofShade = 0.88 + ((b.id * 53) % 13) / 100;
        // Les tuiles et ardoises gardent leur couleur photographiée ; les tôles sont teintées.
        const toonRoofs = palette.style === 'toon' ? TOON_ROOFS[b.type] : undefined;
        const roofHex = toonRoofs
          ? night
            ? new THREE.Color(pickFor(toonRoofs, b.id, 6)!).multiplyScalar(0.35).getHex()
            : pickFor(toonRoofs, b.id, 6)!
          : b.type === 'entrepot'
            ? palette.industrialRoofs[(b.id * 13) % palette.industrialRoofs.length]!
            : night
              ? 0x9aa3bd
              : 0xffffff;
        roofs.setColorAt(i, color.setHex(roofHex).multiplyScalar(roofShade));
      });
      roofs.instanceMatrix.needsUpdate = true;
      if (roofs.instanceColor) roofs.instanceColor.needsUpdate = true;
      roofs.computeBoundingSphere();
      roofs.userData.roof = true;
      buildings.add(roofs);
    }
  }

  const edgeGeometry = new THREE.BufferGeometry();
  edgeGeometry.setAttribute('position', new THREE.Float32BufferAttribute(edgePositions, 3));
  const edges = new THREE.LineSegments(
    edgeGeometry,
    new THREE.LineBasicMaterial({
      color: palette.edge,
      transparent: true,
      opacity: 0.4,
      depthWrite: false,
    }),
  );
  buildings.add(edges);

  let hidden = new Set<number>();
  const zero = new THREE.Matrix4().makeScale(0, 0, 0);
  const touched = new Set<THREE.InstancedMesh>();
  const hideBuildings = (ids: Set<number>): void => {
    for (const id of hidden) {
      if (ids.has(id)) continue;
      for (const r of renderRefs.get(id) ?? []) {
        r.mesh.setMatrixAt(r.index, r.matrix);
        touched.add(r.mesh);
      }
    }
    for (const id of ids) {
      if (hidden.has(id)) continue;
      for (const r of renderRefs.get(id) ?? []) {
        r.mesh.setMatrixAt(r.index, zero);
        touched.add(r.mesh);
      }
    }
    for (const mesh of touched) mesh.instanceMatrix.needsUpdate = true;
    touched.clear();
    hidden = new Set(ids);
  };

  return {
    renderMeshes,
    hideBuildings,
    ground,
    buildings,
    pickMeshes,
    partOwners,
    edges,
    districtTint,
    shadows,
    shadowMaterial,
    facade: lambert,
    surface: surfaceMesh,
  };
}

function waterQuad(
  batch: Batch,
  a: { lx: number; lz: number; rx: number; rz: number },
  b: { lx: number; lz: number; rx: number; rz: number },
  y: number,
  hex: number,
): void {
  batch.freeQuad([a.lx, y, a.lz], [a.rx, y, a.rz], [b.rx, y, b.rz], [b.lx, y, b.lz], hex);
}
