import type { GameState, MessageKind, TenantMessage, TenantCandidate } from './types';

/**
 * Messages des locataires (demande du propriétaire) : chaque locataire peut écrire au joueur pour
 * n'importe quel souci. Pour l'instant : arrivée dans les lieux, retard de loyer (avec promesse de
 * régler les deux loyers le mois suivant), règlement du retard, petits soucis du quotidien. La
 * porte est ouverte à d'autres échanges (réponses, demandes de travaux, négociations).
 */

/** Messages gardés au plus. */
export const MAX_MESSAGES = 120;
/** Les messages de plus de 30 jours de jeu s'effacent seuls (valeur par défaut, à valider). */
export const MESSAGE_KEEP_DAYS = 30;

/** Retire les messages trop anciens. */
export function pruneMessages(state: GameState): GameState {
  const day = state.player.day;
  const messages = state.messages ?? [];
  const kept = messages.filter((m) => day - m.day <= MESSAGE_KEEP_DAYS);
  return kept.length === messages.length ? state : { ...state, messages: kept };
}

/** Supprime une conversation (demande du propriétaire). */
export function deleteThread(state: GameState, key: string): GameState {
  return {
    ...state,
    messages: (state.messages ?? []).filter((m) => `${m.propertyId}:${m.tenantId}` !== key),
  };
}

export function addMessage(
  state: GameState,
  propertyId: string,
  tenant: Pick<TenantCandidate, 'id' | 'title' | 'surname'>,
  kind: MessageKind,
  params: Record<string, string | number> = {},
): GameState {
  const message: TenantMessage = {
    id: state.nextMessageId ?? 1,
    day: state.player.day,
    propertyId,
    tenantId: tenant.id,
    title: tenant.title,
    surname: tenant.surname,
    kind,
    params,
    read: false,
  };
  const counters = state.counters ?? {};
  return pruneMessages({
    ...state,
    counters: { ...counters, [`msg.${kind}`]: (counters[`msg.${kind}`] ?? 0) + 1 },
    nextMessageId: message.id + 1,
    messages: [message, ...(state.messages ?? [])].slice(0, MAX_MESSAGES),
  });
}

/** Une conversation par locataire (bien + locataire), la plus récente d'abord. */
export interface Thread {
  key: string;
  propertyId: string;
  tenantId: number;
  title: TenantMessage['title'];
  surname: string;
  messages: TenantMessage[];
  unread: number;
}

export function threadsOf(state: GameState): Thread[] {
  const threads = new Map<string, Thread>();
  for (const m of state.messages ?? []) {
    const key = `${m.propertyId}:${m.tenantId}`;
    let thread = threads.get(key);
    if (!thread) {
      thread = {
        key,
        propertyId: m.propertyId,
        tenantId: m.tenantId,
        title: m.title,
        surname: m.surname,
        messages: [],
        unread: 0,
      };
      threads.set(key, thread);
    }
    thread.messages.push(m);
    if (!m.read) thread.unread++;
  }
  for (const thread of threads.values()) thread.messages.reverse();
  return [...threads.values()];
}

export function unreadMessages(state: GameState): number {
  return (state.messages ?? []).filter((m) => !m.read).length;
}

/** Marque une conversation comme lue. */
export function readThread(state: GameState, key: string): GameState {
  return {
    ...state,
    messages: (state.messages ?? []).map((m) =>
      `${m.propertyId}:${m.tenantId}` === key ? { ...m, read: true } : m,
    ),
  };
}
