import { districtDef } from '../city/data/layout';
import type { Building } from '../city/model';
import { growth, RULES } from '../economy';
import type { BuildingFacts, Condition, Defect } from './types';

/** Tirage déterministe en [0, 1[ propre à un bâtiment et à un usage. */
export function roll(seed: number, buildingId: number, salt: number): number {
  let h = (seed ^ Math.imul(buildingId + 1, 374761393) ^ Math.imul(salt + 1, 668265263)) | 0;
  h = Math.imul(h ^ (h >>> 15), 2246822519);
  h = Math.imul(h ^ (h >>> 13), 3266489917);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}

export const CONDITION_FACTOR: Record<Condition, number> = { renovate: 0.6, fair: 1, new: 1.2 };
const OVERPRICE = 0.2;

/** Caractéristiques d'un bien : état, défaut caché, valeur réelle, prix affiché, loyer. */
export function buildingFacts(building: Building, seed: number, day: number): BuildingFacts {
  const c = roll(seed, building.id, 1);
  const condition: Condition = c < 0.25 ? 'renovate' : c < 0.8 ? 'fair' : 'new';
  const d = roll(seed, building.id, 2);
  const defect: Defect = d < 0.12 ? 'damp' : d < 0.24 ? 'noisy' : d < 0.4 ? 'overpriced' : 'none';
  const fairValue =
    Math.round((building.price * CONDITION_FACTOR[condition] * growth(day, RULES)) / 1000) * 1000;
  const askingPrice =
    defect === 'overpriced' ? Math.round((fairValue * (1 + OVERPRICE)) / 1000) * 1000 : fairValue;
  const rent = Math.round((fairValue * districtDef(building.district).rentRate) / 10) * 10;
  return { condition, defect, fairValue, askingPrice, rent };
}
