import * as THREE from 'three';
import type { Building } from '../model';
import { DISTRICT_STYLE, pickFor, type CityPalette } from './palette';
import atlasUrl from './textures/city-atlas.jpg';
import reliefUrl from './textures/city-atlas-relief.jpg';
import heightUrl from './textures/city-atlas-height.jpg';

/**
 * Façades et toitures photographiques. Une seule planche de textures (voir textures/CREDITS.md)
 * et un seul matériau pour tous les bâtiments : chaque volume dit quelle case utiliser pour ses
 * murs et pour son toit. Les fenêtres des murs sans fenêtres photographiées sont dessinées par le
 * shader : aucune géométrie en plus, quel que soit le niveau de zoom.
 */

/** Cases de la planche, dans l'ordre de scripts/build-atlas.py. */
export const CELL = {
  redBrick: 0,
  paintBrick: 1,
  render: 2,
  ochreBrick: 3,
  roofTiles: 4,
  slate: 5,
  flatRoof: 6,
  corrugated: 7,
  stone: 8,
  officeRibbons: 9,
  darkBrick: 10,
  blondStone: 11,
  brickLit: 12,
  concreteLit: 13,
  piersLit: 14,
  towerNight: 15,
} as const;

/** Vrai pour les façades de brique (escaliers de secours, ferronneries). */
export function isBrick(cell: number): boolean {
  return (
    cell === CELL.redBrick ||
    cell === CELL.paintBrick ||
    cell === CELL.ochreBrick ||
    cell === CELL.darkBrick
  );
}

/** Taille couverte par une répétition de chaque case, en unités du monde (1 unité = 10 m). */
const CELL_SIZE: readonly [number, number][] = [
  [0.2, 0.2],
  [0.2, 0.2],
  [0.4, 0.4],
  [0.2, 0.2],
  [0.3, 0.3],
  [0.3, 0.3],
  [0.5, 0.5],
  [0.3, 0.3],
  [0.4, 0.4],
  [3.6, 3.6],
  [0.2, 0.2],
  [0.35, 0.35],
  [1.7, 1.7],
  [1.6, 1.6],
  [1.8, 1.8],
  [3.6, 3.6],
];

/** Version de nuit d'une case : fenêtres allumées. */
const NIGHT_CELL: Partial<Record<number, number>> = {
  [CELL.officeRibbons]: CELL.towerNight,
};

/** Fenêtres dessinées par le shader : aucune, d'immeuble, de maison, mur-rideau de tour. */
export const WINDOWS = { none: 0, flat: 1, house: 2, curtain: 3 } as const;

export interface Look {
  wall: number;
  top: number;
  windows: number;
  /** Volets : couleur, ou null. */
  shutter: number | null;
  /** Façade peinte ou enduite : prend la couleur du quartier. */
  painted: boolean;
  /** Fenêtres à l'ancienne (pierre, croisillon) ou contemporaines. */
  classic: boolean;
}

function hash01(id: number, salt: number): number {
  return (((id * 2654435761 + salt * 97) >>> 0) % 1000) / 1000;
}

/**
 * Matières d'un bâtiment, selon son type et le caractère de son quartier (modèle validé :
 * tools/blender/prototype-ultime.py) : brique rouge, ocre ou peinte, pierre blonde, enduits pastel
 * des maisons, tuiles, ardoises, murs-rideaux des tours.
 */
export function lookOf(b: Building): Look {
  const style = DISTRICT_STYLE[b.district];
  const shutter = pickFor(style.shutters, b.id, 7) ?? null;
  const base = { shutter: null, painted: false, classic: false };
  // Plus aucune brique (décision du propriétaire) : enduits lisses aux couleurs du quartier, le
  // relief vient de l'architecture (prototype-sobre.py).
  const smooth = CELL.render;
  switch (b.type) {
    case 'tour':
      return hash01(b.id, 1) < 0.75
        ? { ...base, wall: CELL.stone, top: CELL.flatRoof, windows: WINDOWS.curtain }
        : { ...base, wall: CELL.officeRibbons, top: CELL.flatRoof, windows: WINDOWS.none };
    case 'hotel':
    case 'residence':
      return {
        ...base,
        wall: smooth,
        top: CELL.flatRoof,
        windows: WINDOWS.flat,
        painted: true,
        classic: true,
      };
    case 'immeuble':
      return {
        wall: smooth,
        top: b.roof === 'mansard' ? CELL.slate : CELL.flatRoof,
        windows: WINDOWS.flat,
        shutter: null,
        painted: true,
        classic: true,
      };
    case 'pavillon':
      return {
        wall: CELL.render,
        top: CELL.roofTiles,
        windows: WINDOWS.house,
        shutter,
        painted: true,
        classic: true,
      };
    case 'villa':
      return {
        ...base,
        wall: CELL.render,
        top: CELL.slate,
        windows: WINDOWS.house,
        shutter,
        painted: true,
        classic: true,
      };
    case 'motel':
      return {
        ...base,
        wall: CELL.render,
        top: CELL.flatRoof,
        windows: WINDOWS.house,
        painted: true,
      };
    case 'entrepot':
      return { ...base, wall: CELL.corrugated, top: CELL.corrugated, windows: WINDOWS.none };
  }
}

/**
 * Matières d'un bâtiment selon le rendu : en rendu coloré, pas de photo, et des fenêtres
 * dessinées partout (vitrage de tour, fenêtres d'immeuble ou de maison).
 */
export function styledLook(b: Building, palette: CityPalette): Look {
  const look = lookOf(b);
  if (palette.style !== 'toon') return look;
  const windows =
    b.type === 'tour'
      ? WINDOWS.curtain
      : b.type === 'entrepot'
        ? WINDOWS.none
        : b.type === 'pavillon' || b.type === 'villa' || b.type === 'motel'
          ? WINDOWS.house
          : WINDOWS.flat;
  return { ...look, windows };
}

/** Remplit les attributs par volume d'un maillage instancié (murs, toit, fenêtres, volets). */
export function setLooks(
  geometry: THREE.BufferGeometry,
  entries: { look: Look; seed: number; floorH: number; south?: boolean }[],
  night: boolean,
): void {
  const a = new Float32Array(entries.length * 4);
  const b = new Float32Array(entries.length * 4);
  const c = new THREE.Color();
  entries.forEach((e, i) => {
    const wall = night ? (NIGHT_CELL[e.look.wall] ?? e.look.wall) : e.look.wall;
    // Le sens de la façade principale est rangé avec la graine : +1000 si elle donne au sud.
    a.set([wall, e.look.top, e.look.windows, (e.seed % 997) + (e.south ? 1000 : 0)], i * 4);
    if (e.look.shutter === null) b.set([-1, -1, -1, e.floorH], i * 4);
    else {
      c.setHex(e.look.shutter);
      b.set([c.r, c.g, c.b, e.floorH], i * 4);
    }
  });
  geometry.setAttribute('aLook', new THREE.InstancedBufferAttribute(a, 4));
  geometry.setAttribute('aLook2', new THREE.InstancedBufferAttribute(b, 4));
}

let atlas: THREE.Texture | null = null;

function atlasTexture(): THREE.Texture {
  if (atlas) return atlas;
  // Texture blanche le temps du chargement : la ville s'affiche tout de suite, puis se texture.
  const placeholder = new THREE.DataTexture(new Uint8Array([255, 255, 255, 255]), 1, 1);
  placeholder.needsUpdate = true;
  atlas = placeholder;
  new THREE.TextureLoader().load(atlasUrl, (texture) => {
    texture.colorSpace = THREE.SRGBColorSpace;
    texture.anisotropy = 4;
    texture.generateMipmaps = true;
    texture.minFilter = THREE.LinearMipmapLinearFilter;
    for (const uniforms of materialsUniforms) uniforms.uAtlas.value = texture;
    atlas = texture;
  });
  return atlas;
}

const materialsUniforms = new Set<{
  uAtlas: { value: THREE.Texture };
  uRelief: { value: THREE.Texture };
  uHeight: { value: THREE.Texture };
  uReliefLook: { value: THREE.Vector3 };
}>();

/**
 * Force du relief : x = accentuation des normales, y = profondeur des joints en unités du monde
 * (décalage de parallaxe), z = assombrissement des joints (0 à 1).
 */
export const RELIEF_LOOK = new THREE.Vector3(2.2, 0, 0);

/** Change la force du relief de toutes les façades (réglage et essais). */
export function setReliefLook(normal: number, depth: number, joints: number): void {
  RELIEF_LOOK.set(normal, depth, joints);
  for (const uniforms of materialsUniforms) uniforms.uReliefLook.value.copy(RELIEF_LOOK);
}

let height: THREE.Texture | null = null;

/** Hauteur des matières (joints bas, briques hautes), rangée comme la planche de couleurs. */
function heightTexture(): THREE.Texture {
  if (height) return height;
  const top = new THREE.DataTexture(new Uint8Array([255, 255, 255, 255]), 1, 1);
  top.needsUpdate = true;
  height = top;
  new THREE.TextureLoader().load(heightUrl, (texture) => {
    texture.colorSpace = THREE.NoColorSpace;
    texture.minFilter = THREE.LinearMipmapLinearFilter;
    for (const uniforms of materialsUniforms) uniforms.uHeight.value = texture;
    height = texture;
  });
  return height;
}

let relief: THREE.Texture | null = null;

/** Relief des matières (normal maps), rangé comme la planche de couleurs. */
function reliefTexture(): THREE.Texture {
  if (relief) return relief;
  const flat = new THREE.DataTexture(new Uint8Array([128, 128, 255, 255]), 1, 1);
  flat.needsUpdate = true;
  relief = flat;
  new THREE.TextureLoader().load(reliefUrl, (texture) => {
    texture.colorSpace = THREE.NoColorSpace;
    texture.anisotropy = 4;
    texture.minFilter = THREE.LinearMipmapLinearFilter;
    for (const uniforms of materialsUniforms) uniforms.uRelief.value = texture;
    relief = texture;
  });
  return relief;
}

/** Rayon habillé par les graphismes haut (voir highDetail.ts), en unités. */
const HIGH_RADIUS = 7;

/**
 * Indique au shader le centre de la zone habillée par les graphismes haut : les façades
 * principales des bâtiments de cette zone perdent leurs fenêtres dessinées.
 */
export function setHighCenter(material: THREE.Material, center: THREE.Vector2): void {
  const uniforms = (material.userData as { uniforms?: { uHighCenter: { value: THREE.Vector2 } } })
    .uniforms;
  uniforms?.uHighCenter.value.copy(center);
}

/** Matériau des bâtiments : murs et toits texturés, fenêtres et volets dessinés au besoin. */
export function facadeMaterial(palette: CityPalette): THREE.MeshStandardMaterial {
  // Matériau à reflets doux : la lumière rasante fait ressortir le relief des briques et tuiles.
  const material = new THREE.MeshStandardMaterial({
    color: 0xffffff,
    roughness: 0.82,
    metalness: 0,
  });
  const toon = palette.style === 'toon';
  const uniforms = {
    uAtlas: { value: atlasTexture() },
    uRelief: { value: reliefTexture() },
    uHeight: { value: heightTexture() },
    uReliefLook: { value: RELIEF_LOOK.clone() },
    uCellSize: { value: CELL_SIZE.map(([w, h]) => new THREE.Vector2(w, h)) },
    uGlass: { value: new THREE.Color(palette.glass) },
    uLit: { value: new THREE.Color(palette.lit) },
    uLitRatio: { value: palette.litRatio },
    uNight: { value: palette.litRatio > 0 ? 1 : 0 },
    uHighCenter: { value: new THREE.Vector2(1e9, 1e9) },
    uTrim: { value: new THREE.Color(palette.trim) },
    uRoofTint: { value: new THREE.Color(palette.litRatio > 0 ? 0x4a4d58 : 0xd2d0cb) },
    uStone: { value: new THREE.Color(palette.stone) },
    uCurtain: { value: new THREE.Color(palette.curtain) },
    uMullion: { value: new THREE.Color(palette.mullion) },
  };
  materialsUniforms.add(uniforms);
  material.userData.uniforms = uniforms;
  material.onBeforeCompile = (shader) => {
    Object.assign(shader.uniforms, uniforms);
    shader.vertexShader = shader.vertexShader
      .replace(
        '#include <common>',
        `#include <common>
attribute vec4 aLook;
attribute vec4 aLook2;
varying vec2 vFacadeUV;
varying float vTop;
varying float vY;
varying float vFaceW;
varying vec4 vLook;
varying vec4 vLook2;
varying vec2 vCenterXZ;
varying float vFaceNZ;`,
      )
      .replace(
        '#include <begin_vertex>',
        `#include <begin_vertex>
vec3 iScale = vec3(1.0);
#ifdef USE_INSTANCING
iScale = vec3(length(instanceMatrix[0].xyz), length(instanceMatrix[1].xyz), length(instanceMatrix[2].xyz));
#endif
vLook = aLook;
vLook2 = aLook2;
vY = position.y * iScale.y;
vFaceNZ = normal.z;
vCenterXZ = vec2(1e6);
#ifdef USE_INSTANCING
vCenterXZ = instanceMatrix[3].xz;
#endif
if (normal.y > 0.3) {
  vTop = 1.0;
  vFacadeUV = vec2(position.x * iScale.x, position.z * iScale.z + position.y * iScale.y);
  vFaceW = iScale.x;
} else if (abs(normal.x) > abs(normal.z)) {
  vTop = 0.0;
  vFacadeUV = vec2(position.z * iScale.z * sign(normal.x), vY);
  vFaceW = iScale.z;
} else {
  vTop = 0.0;
  vFacadeUV = vec2(-position.x * iScale.x * sign(normal.z), vY);
  vFaceW = iScale.x;
}`,
      );
    shader.fragmentShader = shader.fragmentShader
      .replace(
        '#include <common>',
        `#include <common>
uniform sampler2D uAtlas;
uniform sampler2D uRelief;
uniform sampler2D uHeight;
uniform vec3 uReliefLook;
vec2 atlasUv(float cell, vec2 raw) {
  vec2 inner = fract(raw);
  float col = mod(cell, 4.0);
  float row = floor(cell / 4.0);
  return vec2((col + 0.004 + inner.x * 0.992) / 4.0, (3.0 - row + 0.004 + inner.y * 0.992) / 4.0);
}
// Repère de surface tiré des dérivées à l'écran (sans tangentes dans la géométrie).
vec3 facadeRelief(vec3 n, vec3 viewPos, vec2 uv, vec3 mapN) {
  vec3 dp1 = dFdx(viewPos);
  vec3 dp2 = dFdy(viewPos);
  vec2 duv1 = dFdx(uv);
  vec2 duv2 = dFdy(uv);
  vec3 dp2perp = cross(dp2, n);
  vec3 dp1perp = cross(n, dp1);
  vec3 t = dp2perp * duv1.x + dp1perp * duv2.x;
  vec3 b = dp2perp * duv1.y + dp1perp * duv2.y;
  float invmax = inversesqrt(max(max(dot(t, t), dot(b, b)), 1e-12));
  return normalize(mat3(t * invmax, b * invmax, n) * mapN);
}
uniform vec2 uCellSize[16];
uniform vec3 uGlass;
uniform vec3 uLit;
uniform float uLitRatio;
uniform float uNight;
uniform vec3 uTrim;
uniform vec3 uRoofTint;
uniform vec3 uStone;
uniform vec3 uCurtain;
uniform vec3 uMullion;
uniform vec2 uHighCenter;
varying vec2 vCenterXZ;
varying float vFaceNZ;
varying vec2 vFacadeUV;
varying float vTop;
varying float vY;
varying float vFaceW;
varying vec4 vLook;
varying vec4 vLook2;
float facadeHash(vec3 p) {
  return fract(sin(dot(p, vec3(12.9898, 78.233, 37.719))) * 43758.5453);
}`,
      )
      .replace(
        '#include <map_fragment>',
        `{
  float floorH = vLook2.w;
#if ${toon ? 1 : 0}
  // Rendu coloré : pas de photo, une couleur unie un peu plus claire vers le haut.
  if (vTop < 0.5) diffuseColor.rgb *= mix(0.9, 1.04, clamp(vY / 4.0, 0.0, 1.0));
#else
  float cell = vTop > 0.5 ? vLook.y : vLook.x;
  int ci = int(cell + 0.5);
  vec2 cs = uCellSize[0];
  for (int k = 0; k < 16; k++) { if (k == ci) cs = uCellSize[k]; }
  vec2 raw = vFacadeUV / cs;
  vec2 rawDx = dFdx(raw);
  vec2 rawDy = dFdy(raw);
  float joint = 1.0;
  if (uReliefLook.y > 0.0) {
    // Parallaxe : selon l'angle de vue, la texture glisse comme si les joints étaient en retrait.
    vec3 p = -vViewPosition;
    vec3 dpx = dFdx(p);
    vec3 dpy = dFdy(p);
    vec3 gn = normalize(cross(dpx, dpy));
    vec2 dux = dFdx(vFacadeUV);
    vec2 duy = dFdy(vFacadeUV);
    vec3 t = normalize(dpx * duy.y - dpy * dux.y);
    vec3 b = normalize(dpy * dux.x - dpx * duy.x);
    vec3 v = normalize(vViewPosition);
    if (dot(gn, v) < 0.0) gn = -gn;
    vec3 vt = vec3(dot(v, t), dot(v, b), max(dot(v, gn), 0.25));
    vec2 stepUv = -(vt.xy / vt.z) * uReliefLook.y / cs / 6.0;
    vec2 q = raw;
    float layer = 1.0;
    for (int k = 0; k < 6; k++) {
      float hh = textureGrad(uHeight, atlasUv(cell, q), rawDx * 0.248, rawDy * 0.248).r;
      if (hh >= layer) break;
      q += stepUv;
      layer -= 1.0 / 6.0;
    }
    raw = q;
  }
  vec2 auv = atlasUv(cell, raw);
  joint = textureGrad(uHeight, auv, rawDx * 0.248, rawDy * 0.248).r;
  vec4 tex = textureGrad(uAtlas, auv, rawDx * 0.248, rawDy * 0.248);
  tex.rgb *= mix(1.0, 0.35 + 0.65 * joint, uReliefLook.z);
  facadeAuv = auv;
  facadeRaw = raw;
  facadeRawDx = rawDx;
  facadeRawDy = rawDy;
  facadeTextured = true;
  diffuseColor.rgb *= tex.rgb * 1.12;
  // Toit plat : béton gris clair, comme le modèle, quelle que soit la couleur de la façade.
  if (vTop > 0.5 && ci == ${CELL.flatRoof}) {
    diffuseColor.rgb = tex.rgb * uRoofTint * 1.12;
    facadePaint = true;
  }
  // Façades photographiées aux fenêtres allumées, la nuit.
  if (uNight > 0.5 && vTop < 0.5 && cell > 11.5) facadeGlow += tex.rgb * 0.55;
#endif
  if (vTop < 0.5 && floorH > 0.0) {
    // Ombre douce au pied des murs.
    diffuseColor.rgb *= mix(0.72, 1.0, smoothstep(0.0, 0.45, vY));
    // Façade principale d'un bâtiment habillé par les pièces modélisées : les vraies fenêtres
    // remplacent celles du shader.
    bool covered = distance(vCenterXZ, uHighCenter) < ${HIGH_RADIUS.toFixed(1)};
    bool front = vLook.w >= 1000.0 ? vFaceNZ > 0.5 : vFaceNZ < -0.5;
    float uu = vFacadeUV.x + vFaceW * 0.5;
    float fl0 = floor(vY / floorH);
    float fv0 = fract(vY / floorH);
    if (vLook.z > 2.5) {
      // Tour : mur-rideau, montants à chaque étage et tous les 1,6 m, reflet du ciel plus clair en haut.
#if ${toon ? 1 : 0}
      bool mullion = fv0 < 0.1 || mod(uu, 0.36) < 0.035;
#else
      bool mullion = fv0 < 0.07 || mod(uu, 0.16) < 0.014;
#endif
      if (mullion) {
        diffuseColor.rgb = ${toon ? 'uTrim' : 'uMullion'};
        facadePaint = true;
      } else {
#if ${toon ? 1 : 0}
        diffuseColor.rgb *= mix(0.82, 1.18, fv0);
#else
        diffuseColor.rgb = uCurtain * mix(0.7, 1.35, fv0) * mix(0.9, 1.1, facadeHash(vec3(floor(uu / 0.16), fl0, 3.0)));
        facadePaint = true;
#endif
        if (facadeHash(vec3(fl0, floor(uu / 0.16), vLook.w)) < uLitRatio) {
          diffuseColor.rgb = uLit;
          facadePaint = true;
          facadeGlow += uLit * 0.6;
        }
      }
    } else if (vLook.z > 0.5) {
#if ${toon ? 1 : 0}
      // Angles et bandeaux d'étage blancs.
      if (uu < 0.045 || uu > vFaceW - 0.045 || (fv0 < 0.06 && fl0 > 0.5)) {
        diffuseColor.rgb = uTrim;
        facadePaint = true;
      }
#else
      // Bandeau de pierre tous les deux étages.
      if (fv0 < 0.045 && fl0 > 0.5 && mod(fl0, 2.0) < 0.5) {
        diffuseColor.rgb = uStone;
        facadePaint = true;
      }
#endif
      if (!(covered && front)) {
        bool house = vLook.z > 1.5;
        float margin = 0.06;
        float usable = vFaceW - 2.0 * margin;
        // Fenêtres refaites (retour du propriétaire) : plus grandes, moins serrées, cadre blanc,
        // meneau et traverse, vitre qui renvoie le ciel.
        float pitch = house ? 0.62 : ${toon ? '0.42' : '0.36'};
        float cols = max(1.0, floor(usable / pitch));
        float u = uu - margin;
        float cu = u / (usable / cols);
        float c = floor(cu);
        float fu = fract(cu) - 0.5;
        bool across = u > 0.0 && u < usable;
        float wBot = ${toon ? '0.28' : '0.2'};
        float wTop = ${toon ? '0.8' : '0.84'};
        bool inside = across && fv0 > wBot && fv0 < wTop;
        float halfW = house ? 0.19 : ${toon ? '0.22' : '0.3'};
        if (inside && abs(fu) < halfW) {
          float h = facadeHash(vec3(fl0, c, vLook.w + vFaceW));
          bool lit = h < uLitRatio;
          float gy = (fv0 - wBot) / (wTop - wBot);
          float edge = ${toon ? '0.035' : '0.045'};
          bool frame = abs(fu) > halfW - edge || gy < 0.05 || gy > 0.95
            || abs(fu) < 0.018 || abs(gy - 0.7) < 0.022;
#if ${toon ? 1 : 0}
          vec3 glass = lit ? uLit : uGlass * mix(0.8, 1.25, gy);
#else
          // Vitre : bleu profond en bas, ciel en haut, un reflet en biais, creux dans les angles.
          vec3 glass = lit ? uLit : uGlass * mix(0.8, 1.45, gy) * mix(0.94, 1.06, h);
          float refl = (uLitRatio > 0.0 ? 0.0 : 1.0) * smoothstep(0.25, 1.0, gy) * 0.55;
          vec3 skyRefl = vec3(0.76, 0.87, 0.98);
          glass = mix(glass, skyRefl, refl);
          float streak = smoothstep(0.08, 0.0, abs(fu * 1.6 + gy - 0.95));
          if (!lit) glass += vec3(0.22, 0.25, 0.28) * streak * (uLitRatio > 0.0 ? 0.2 : 1.0);
          if (!lit && (gy > 0.9 || fu < -halfW + edge + 0.03)) glass *= 0.62;
          if (!lit && !frame) facadeGlow += skyRefl * refl * 0.2;
#endif
          diffuseColor.rgb = frame ? uTrim : glass;
          facadePaint = true;
          if (lit && !frame) facadeGlow += uLit * 0.6;
        } else if (inside && vLook2.r >= 0.0 && abs(fu) < halfW + 0.13) {
          diffuseColor.rgb = vLook2.rgb;
          facadePaint = true;
        } else if (across && fv0 > wBot - 0.045 && fv0 <= wBot && abs(fu) < halfW + 0.04) {
          // Appui de fenêtre.
          diffuseColor.rgb = ${toon ? 'uTrim' : 'uStone'};
          facadePaint = true;
        }
#if ${toon ? 0 : 1}
        else if (!house && across && fv0 >= wTop && fv0 < wTop + 0.06 && abs(fu) < halfW + 0.03) {
          // Linteau de pierre.
          diffuseColor.rgb = uStone;
          facadePaint = true;
        }
#endif
      }
    }
  }
}`,
      )
      .replace(
        '#include <color_fragment>',
        `#if defined( USE_COLOR ) || defined( USE_INSTANCING_COLOR )
  if (!facadePaint) diffuseColor.rgb *= vColor.rgb;
#endif`,
      )
      .replace(
        '#include <normal_fragment_maps>',
        `#include <normal_fragment_maps>
  // Relief des briques, joints, tuiles et tôles : la lumière accroche chaque aspérité.
  if (facadeTextured && !facadePaint) {
    vec3 mapN = textureGrad(uRelief, facadeAuv, facadeRawDx * 0.248, facadeRawDy * 0.248).xyz * 2.0 - 1.0;
    mapN.xy *= uReliefLook.x;
    normal = facadeRelief(normal, -vViewPosition, facadeRaw, mapN);
  }`,
      )
      .replace(
        '#include <emissivemap_fragment>',
        `#include <emissivemap_fragment>
totalEmissiveRadiance += facadeGlow;`,
      )
      .replace(
        'void main() {',
        'void main() {\n  vec3 facadeGlow = vec3(0.0);\n  bool facadePaint = false;\n  vec2 facadeAuv = vec2(0.0);\n  vec2 facadeRaw = vec2(0.0);\n  vec2 facadeRawDx = vec2(0.0);\n  vec2 facadeRawDy = vec2(0.0);\n  bool facadeTextured = false;',
      );
  };
  material.customProgramCacheKey = () => `facade-v9-${toon ? 'toon' : 'photo'}`;
  return material;
}
