import { RULES, type EconomyRules } from './rules';

/** Commission moyenne d'une mission de chasse après `day` jours de réputation. */
function reputationProgress(day: number, rules: EconomyRules): number {
  const { daysToFullReputation } = rules.hunting;
  return Math.min(Math.max(day, 0), daysToFullReputation) / daysToFullReputation;
}

/** Part du prix de vente touchée par le chasseur après `day` jours de réputation. */
export function commissionRate(day: number, rules: EconomyRules = RULES): number {
  const { rateStart, rateFull } = rules.hunting;
  return rateStart + (rateFull - rateStart) * reputationProgress(day, rules);
}

/**
 * Commission de base d'une vente : un pourcentage du prix de vente, sans minimum. Placer une
 * villa rapporte donc bien plus que placer un studio.
 */
export function saleCommission(price: number, day: number, rules: EconomyRules = RULES): number {
  return price * commissionRate(day, rules);
}

export function averageCommission(day: number, rules: EconomyRules = RULES): number {
  const { commissionStart, commissionFull, daysToFullReputation } = rules.hunting;
  const progress = Math.min(Math.max(day, 0), daysToFullReputation) / daysToFullReputation;
  return commissionStart + (commissionFull - commissionStart) * progress;
}
