import type { City, DistrictId } from '../city/model';
import type { GameState } from './types';

/**
 * Objectifs et récompense quotidienne (grosse mise à jour, point 6). Les objectifs se lisent dans
 * la partie (biens, réputation, lettres reçues) ; leur récompense se touche une fois. Aucun
 * avantage payant. Valeurs par défaut, voir docs/QUESTIONS.md.
 */

export interface QuestView {
  id: QuestId;
  progress: number;
  goal: number;
  reward: number;
  done: boolean;
  claimed: boolean;
  /** Titre gagné avec l'objectif, s'il y en a un. */
  title: string | null;
}

export type QuestId =
  | 'firstProperty'
  | 'firstLease'
  | 'missions10'
  | 'repairs3'
  | 'loanRepaid'
  | 'neighbourhood3'
  | 'landlord5'
  | 'districts5'
  | 'auctionWon'
  | 'lawsuitWon'
  | 'builder'
  | 'millionaire'
  | 'landlord15'
  | 'magnate';

interface QuestSpec {
  id: QuestId;
  goal: number;
  reward: number;
  title?: string;
  measure: (state: GameState, city: City, worth: number) => number;
}

const count = (state: GameState, key: string): number => state.counters?.[key] ?? 0;

/** Biens par quartier. */
export function districtCounts(state: GameState, city: City): Map<DistrictId, number> {
  const counts = new Map<DistrictId, number>();
  for (const p of state.player.properties) {
    const b = city.buildings[Number(p.id)];
    if (!b) continue;
    counts.set(b.district, (counts.get(b.district) ?? 0) + 1);
  }
  return counts;
}

const QUESTS: readonly QuestSpec[] = [
  { id: 'firstProperty', goal: 1, reward: 5_000, measure: (s) => s.player.properties.length },
  {
    id: 'firstLease',
    goal: 1,
    reward: 3_000,
    measure: (s) => Object.values(s.tenancy).filter((t) => t.tenant).length,
  },
  { id: 'missions10', goal: 10, reward: 10_000, measure: (s) => s.reputation },
  {
    id: 'repairs3',
    goal: 3,
    reward: 10_000,
    measure: (s) => count(s, 'msg.fixed') + count(s, 'msg.agencyFixed'),
  },
  {
    id: 'loanRepaid',
    goal: 1,
    reward: 20_000,
    measure: (s) => count(s, 'loanRepaid') + count(s, 'earlyRepaid'),
  },
  {
    id: 'neighbourhood3',
    goal: 3,
    reward: 25_000,
    measure: (s, c) => Math.max(0, ...districtCounts(s, c).values()),
  },
  { id: 'landlord5', goal: 5, reward: 50_000, measure: (s) => s.player.properties.length },
  { id: 'districts5', goal: 5, reward: 40_000, measure: (s, c) => districtCounts(s, c).size },
  { id: 'auctionWon', goal: 1, reward: 30_000, measure: (s) => count(s, 'auctionWon') },
  {
    id: 'lawsuitWon',
    goal: 1,
    reward: 30_000,
    measure: (s) => count(s, 'lawsuitWon') + count(s, 'complaintWon'),
  },
  { id: 'builder', goal: 1, reward: 50_000, measure: (s) => count(s, 'buildDone') },
  {
    id: 'millionaire',
    goal: 1_000_000,
    reward: 50_000,
    title: 'millionaire',
    measure: (_s, _c, w) => w,
  },
  {
    id: 'landlord15',
    goal: 15,
    reward: 150_000,
    title: 'landlord',
    measure: (s) => s.player.properties.length,
  },
  {
    id: 'magnate',
    goal: 10_000_000,
    reward: 250_000,
    title: 'magnate',
    measure: (_s, _c, w) => w,
  },
];

export function questList(state: GameState, city: City, worth: number): QuestView[] {
  const claimed = new Set(state.questsClaimed ?? []);
  return QUESTS.map((q) => {
    const progress = Math.max(0, q.measure(state, city, worth));
    return {
      id: q.id,
      progress: Math.min(progress, q.goal),
      goal: q.goal,
      reward: q.reward,
      done: progress >= q.goal,
      claimed: claimed.has(q.id),
      title: q.title ?? null,
    };
  });
}

/** Objectifs atteints dont la récompense attend (pour le badge). */
export function questsReady(state: GameState, city: City, worth: number): number {
  return questList(state, city, worth).filter((q) => q.done && !q.claimed).length;
}

/** Touche la récompense d'un objectif atteint. */
export function claimQuest(state: GameState, city: City, worth: number, id: string): GameState {
  const quest = questList(state, city, worth).find((q) => q.id === id);
  if (!quest || !quest.done || quest.claimed) throw new Error('Objectif non atteint');
  return {
    ...state,
    questsClaimed: [...(state.questsClaimed ?? []), quest.id],
    player: { ...state.player, cash: state.player.cash + quest.reward },
    ledger: { ...state.ledger, commissions: state.ledger.commissions + quest.reward },
  };
}

/** Plus haut titre gagné (le dernier de la liste). */
export function playerTitle(state: GameState): string | null {
  const claimed = new Set(state.questsClaimed ?? []);
  let title: string | null = null;
  for (const q of QUESTS) if (q.title && claimed.has(q.id)) title = q.title;
  return title;
}

/** Jour du calendrier réel (UTC). */
export function calendarDay(nowMs: number): number {
  return Math.floor(nowMs / 86_400_000);
}

/** Récompense quotidienne : 1 000 ducats par jour de série, 7 000 au plus ; un jour manqué remet à 1. */
export const DAILY_BASE = 1_000;
export const DAILY_MAX_STREAK = 7;

export function dailyStatus(
  state: GameState,
  nowMs: number,
): { ready: boolean; streak: number; reward: number } {
  const today = calendarDay(nowMs);
  const ready = state.dailyDay !== today;
  const streak = !ready
    ? (state.dailyStreak ?? 1)
    : state.dailyDay === today - 1
      ? Math.min(DAILY_MAX_STREAK, (state.dailyStreak ?? 0) + 1)
      : 1;
  return { ready, streak, reward: DAILY_BASE * streak };
}

export function claimDaily(state: GameState, nowMs: number): GameState {
  const status = dailyStatus(state, nowMs);
  if (!status.ready) throw new Error('Déjà touchée');
  return {
    ...state,
    dailyDay: calendarDay(nowMs),
    dailyStreak: status.streak,
    player: { ...state.player, cash: state.player.cash + status.reward },
    ledger: { ...state.ledger, commissions: state.ledger.commissions + status.reward },
  };
}

/** Seigneur d'un quartier : celui qui y possède le plus de biens (2 au moins). */
export const LORD_MIN = 2;

export interface Lord {
  district: DistrictId;
  name: string;
  me: boolean;
  count: number;
}

export function districtLords(
  owners: readonly { name: string; buildings: readonly number[]; me?: boolean }[],
  city: City,
): Lord[] {
  const best: Partial<Record<DistrictId, { name: string; count: number; me: boolean }>> = {};
  for (const owner of owners) {
    const counts = new Map<DistrictId, number>();
    for (const id of owner.buildings) {
      const b = city.buildings[id];
      if (b) counts.set(b.district, (counts.get(b.district) ?? 0) + 1);
    }
    for (const [district, n] of counts) {
      if (n >= LORD_MIN && n > (best[district]?.count ?? 0))
        best[district] = { name: owner.name, count: n, me: owner.me === true };
    }
  }
  const lords: Lord[] = [];
  for (const [d, v] of Object.entries(best))
    if (v) lords.push({ district: d as DistrictId, name: v.name, me: v.me, count: v.count });
  return lords;
}
