import * as THREE from 'three';
import type { Building, City, Rect } from '../model';
import { Batch } from './batch';
import { setLooks, styledLook } from './facadeMaterial';
import type { CityPalette } from './palette';
import { gableGeometry, wallHex } from './staticScene';

/**
 * Chantiers et programmes livrés sur les terrains de la Zone 1 : dalle, ossature qui monte avec
 * l'avancement, grue ; puis maisons ou immeubles neufs, aux couleurs « vos biens ».
 */

export interface ProgramView {
  index: number;
  kind: 'houses' | 'apartments';
  units: number;
  /** Avancement du chantier, de 0 à 1 ; 1 et `built` une fois livré. */
  progress: number;
  built: boolean;
}

const FLOOR_H = 0.32;
const KIND = {
  houses: { type: 'pavillon' as const, floors: 2, footprint: 0.75 },
  apartments: { type: 'immeuble' as const, floors: 5, footprint: 0.82 },
};

/** Emprises des bâtiments d'un programme : grille régulière dans le terrain, avec des marges. */
export function unitRects(plot: Rect, units: number, kind: ProgramView['kind']): Rect[] {
  const w = plot.x1 - plot.x0;
  const d = plot.z1 - plot.z0;
  const cols = Math.max(1, Math.round(Math.sqrt((units * w) / d)));
  const rows = Math.max(1, Math.ceil(units / cols));
  const cw = w / cols;
  const rd = d / rows;
  const fill = KIND[kind].footprint;
  const rects: Rect[] = [];
  for (let i = 0; i < units; i++) {
    const c = i % cols;
    const r = Math.floor(i / cols);
    const cx = plot.x0 + (c + 0.5) * cw;
    const cz = plot.z0 + (r + 0.5) * rd;
    const hw = (cw * fill) / 2;
    const hd = (rd * fill) / 2;
    rects.push({ x0: cx - hw, z0: cz - hd, x1: cx + hw, z1: cz + hd });
  }
  return rects;
}

export class DevelopmentLayer {
  readonly group = new THREE.Group();

  constructor(
    private readonly city: City,
    private readonly palette: CityPalette,
    private readonly facade: THREE.Material,
  ) {}

  set(programs: readonly ProgramView[]): void {
    this.clear();
    const p = this.palette;
    const site = new Batch();
    const finished: Building[] = [];
    for (const prog of programs) {
      const plot = this.city.plots[prog.index];
      if (!plot) continue;
      const k = KIND[prog.kind];
      const rects = unitRects(plot.rect, prog.units, prog.kind);
      rects.forEach((r, i) => {
        const w = r.x1 - r.x0;
        const d = r.z1 - r.z0;
        const cx = (r.x0 + r.x1) / 2;
        const cz = (r.z0 + r.z1) / 2;
        const h = k.floors * FLOOR_H;
        if (prog.built) {
          finished.push({
            id: 300_000 + prog.index * 100 + i,
            district: 'zone1',
            type: k.type,
            ref: plot.ref,
            x: cx,
            z: cz,
            w,
            d,
            h,
            floors: k.floors,
            facing: 'south',
            roof: prog.kind === 'houses' ? 'gable' : 'flat',
            parts: [{ x: cx, z: cz, w, d, y0: 0, h }],
            status: 'mine',
            shop: false,
            price: 0,
            rent: 0,
            perks: [],
          });
          return;
        }
        // Chantier : dalle de béton, poteaux et planchers jusqu'à la hauteur atteinte.
        site.box(cx, 0, cz, w + 0.1, 0.05, d + 0.1, p.quay);
        const done = Math.max(1, Math.round(k.floors * prog.progress));
        for (let f = 1; f <= done; f++) {
          site.box(cx, f * FLOOR_H - 0.03, cz, w, 0.03, d, p.stone);
        }
        const top = done * FLOOR_H;
        for (const [sx, sz] of [
          [-1, -1],
          [1, -1],
          [-1, 1],
          [1, 1],
        ] as const) {
          site.box(
            cx + (sx * (w - 0.04)) / 2,
            0.05,
            cz + (sz * (d - 0.04)) / 2,
            0.04,
            top,
            0.04,
            p.stone,
          );
        }
        // Échafaudage côté rue.
        site.box(cx, 0.05, cz + d / 2 + 0.06, w + 0.1, top + 0.1, 0.02, 0xe0a63a);
      });
      if (!prog.built) {
        // Grue jaune au coin du terrain.
        const gx = plot.rect.x0 + 0.4;
        const gz = plot.rect.z0 + 0.4;
        const mast = KIND[prog.kind].floors * FLOOR_H + 0.9;
        site.box(gx, 0, gz, 0.12, mast, 0.12, 0xf2c230);
        site.box(gx + 0.9, mast, gz, 2.4, 0.08, 0.1, 0xf2c230);
        site.box(gx - 0.45, mast - 0.12, gz, 0.4, 0.2, 0.3, p.stone);
      }
    }
    if (!site.isEmpty) {
      const mesh = site.toMesh(new THREE.MeshLambertMaterial({ vertexColors: true }));
      mesh.geometry.computeVertexNormals();
      mesh.castShadow = true;
      this.group.add(mesh);
    }
    if (finished.length > 0) this.addBuildings(finished);
  }

  dispose(): void {
    this.clear();
  }

  private addBuildings(list: Building[]): void {
    const p = this.palette;
    const box = new THREE.BoxGeometry(1, 1, 1);
    box.translate(0, 0.5, 0);
    setLooks(
      box,
      list.map((b) => ({ look: styledLook(b, p), seed: b.id, floorH: FLOOR_H, south: true })),
      p.litRatio > 0,
    );
    const walls = new THREE.InstancedMesh(box, this.facade, list.length);
    const m = new THREE.Matrix4();
    const c = new THREE.Color();
    list.forEach((b, i) => {
      m.makeScale(b.w, b.h, b.d).setPosition(b.x, 0, b.z);
      walls.setMatrixAt(i, m);
      walls.setColorAt(i, c.setHex(wallHex(p, b, 'mine')));
    });
    walls.castShadow = walls.receiveShadow = true;
    this.group.add(walls);
    const houses = list.filter((b) => b.roof === 'gable');
    if (houses.length > 0) {
      const roofGeometry = gableGeometry();
      setLooks(
        roofGeometry,
        houses.map((b) => ({ look: styledLook(b, p), seed: b.id, floorH: 0 })),
        p.litRatio > 0,
      );
      const roofs = new THREE.InstancedMesh(roofGeometry, this.facade, houses.length);
      houses.forEach((b, i) => {
        m.makeScale(b.w * 1.12, Math.min(b.w, b.d) * 0.5, b.d * 1.12).setPosition(b.x, b.h, b.z);
        roofs.setMatrixAt(i, m);
        roofs.setColorAt(i, c.setHex(0xffffff));
      });
      roofs.castShadow = true;
      this.group.add(roofs);
    }
  }

  private clear(): void {
    for (const child of [...this.group.children]) {
      this.group.remove(child);
      if (child instanceof THREE.Mesh) {
        child.geometry.dispose();
        if (!(child instanceof THREE.InstancedMesh)) (child.material as THREE.Material).dispose();
      }
    }
  }
}
