import {
  consumeRedirect,
  currentSession,
  sendMagicLink,
  sendReset,
  setPassword,
  signIn,
  signOut,
  signUp,
  startOAuth,
  providersEnabled,
  type AuthResult,
} from '../game/auth';
import { getLang, LANGS, setLang, t, type Lang, type MessageKey } from '../i18n';
import { applyTheme, THEME_IDS, type ThemeId } from '../theme/themes';
import { button, el } from './dom';
import { feedbackOn, setFeedback } from './feedback';
import { readSetting, writeSetting } from './storage';

/**
 * Page d'accueil (demande du propriétaire) : le nom du jeu, la connexion ou l'inscription (compte
 * obligatoire), les paramètres et les mentions légales. Elle s'affiche avant la ville, sans 3D,
 * pour s'ouvrir vite ; la ville se charge seulement une fois le joueur connecté.
 */

/** Logos officiels des boutons de connexion (chartes Google et Apple pour ces boutons). */
const GOOGLE_LOGO =
  '<svg class="brand" viewBox="0 0 48 48" aria-hidden="true"><path fill="#EA4335" d="M24 9.5c3.54 0 6.71 1.22 9.21 3.6l6.85-6.85C35.9 2.38 30.47 0 24 0 14.62 0 6.51 5.38 2.56 13.22l7.98 6.19C12.43 13.72 17.74 9.5 24 9.5z"/><path fill="#4285F4" d="M46.98 24.55c0-1.57-.15-3.09-.38-4.55H24v9.02h12.94c-.58 2.96-2.26 5.48-4.78 7.18l7.73 6c4.51-4.18 7.09-10.36 7.09-17.65z"/><path fill="#FBBC05" d="M10.53 28.59c-.48-1.45-.76-2.99-.76-4.59s.27-3.14.76-4.59l-7.98-6.19C.92 16.46 0 20.12 0 24c0 3.88.92 7.54 2.56 10.78l7.97-6.19z"/><path fill="#34A853" d="M24 48c6.48 0 11.93-2.13 15.89-5.81l-7.73-6c-2.15 1.45-4.92 2.3-8.16 2.3-6.26 0-11.57-4.22-13.47-9.91l-7.98 6.19C6.51 42.62 14.62 48 24 48z"/></svg>';
const APPLE_LOGO =
  '<svg class="brand" viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M12.152 6.896c-.948 0-2.415-1.078-3.96-1.04-2.04.027-3.91 1.183-4.961 3.014-2.117 3.675-.546 9.103 1.519 12.09 1.013 1.454 2.208 3.09 3.792 3.039 1.52-.065 2.09-.987 3.935-.987 1.831 0 2.35.987 3.96.948 1.637-.026 2.676-1.48 3.676-2.948 1.156-1.688 1.636-3.325 1.662-3.415-.039-.013-3.182-1.221-3.22-4.857-.026-3.04 2.48-4.494 2.597-4.559-1.429-2.09-3.623-2.324-4.39-2.376-2-.156-3.675 1.09-4.61 1.09zM15.53 3.83c.843-1.012 1.4-2.427 1.245-3.83-1.207.052-2.662.805-3.532 1.818-.78.896-1.454 2.338-1.273 3.714 1.338.104 2.715-.688 3.559-1.701"/></svg>';

type View = 'main' | 'login' | 'signup' | 'magic' | 'forgot' | 'reset' | 'settings' | 'legal';
type LegalPage = 'mentions' | 'privacy' | 'terms';

export interface WelcomeOptions {
  theme: ThemeId;
  /** Le joueur entre en ville (déjà connecté). */
  enter: (theme: ThemeId) => void;
}

export async function showWelcome(root: HTMLElement, options: WelcomeOptions): Promise<void> {
  const page = el('div', 'welcome');
  root.replaceChildren(page);
  let theme = options.theme;
  let view: View = 'main';
  let legal: LegalPage = 'mentions';
  let note: { text: string; good: boolean } | null = null;
  let busy = false;
  let email = '';

  const redirect = await consumeRedirect();
  if (redirect.error) note = { text: t(`auth.error.${redirect.error}`), good: false };
  else if (redirect.type === 'recovery') view = 'reset';
  else if (redirect.type) note = { text: t('auth.welcomeBack'), good: true };

  /** Google et Apple côte à côte, pour que l'accueil tienne sans défiler. */
  function oauthRow(): HTMLElement {
    const line = el('div', 'welcome-oauth');
    const google = button('ghost', '', () => oauth('google'));
    google.innerHTML = `${GOOGLE_LOGO}<span>Google</span>`;
    const apple = button('ghost', '', () => oauth('apple'));
    apple.innerHTML = `${APPLE_LOGO}<span>Apple</span>`;
    line.append(google, apple);
    line.setAttribute('aria-label', `${t('auth.google')} · ${t('auth.apple')}`);
    return line;
  }

  /** Google ou Apple : seulement si le mode est ouvert, sinon un message clair. */
  function oauth(provider: 'google' | 'apple'): void {
    void providersEnabled().then((open) => {
      if (open[provider]) startOAuth(provider);
      else {
        note = { text: t('auth.error.provider'), good: false };
        render();
      }
    });
  }

  const go = (next: View): void => {
    view = next;
    note = null;
    render();
  };

  async function run(task: () => Promise<AuthResult>, success: (r: AuthResult) => void) {
    if (busy) return;
    busy = true;
    render();
    const result = await task();
    busy = false;
    if (!result.ok) note = { text: t(`auth.error.${result.error}` as MessageKey), good: false };
    else success(result);
    render();
  }

  function field(type: string, label: string, auto: string, value = ''): HTMLInputElement {
    const input = document.createElement('input');
    input.type = type;
    input.className = 'admin-input welcome-input';
    input.placeholder = label;
    input.setAttribute('aria-label', label);
    input.setAttribute('autocomplete', auto);
    input.value = value;
    if (type === 'email') input.inputMode = 'email';
    return input;
  }

  function form(fields: HTMLElement[], submitLabel: string, submit: () => void): HTMLFormElement {
    const f = document.createElement('form');
    f.className = 'welcome-form';
    f.noValidate = true;
    const send = button('primary home-enter', busy ? t('auth.wait') : submitLabel, () => undefined);
    send.type = 'submit';
    send.disabled = busy;
    f.append(...fields, send);
    f.addEventListener('submit', (e) => {
      e.preventDefault();
      submit();
    });
    return f;
  }

  function title(): HTMLElement[] {
    return [
      el('div', 'ref', t('home.office')),
      el('h1', 'home-title', t('app.name')),
      el('div', 'home-kind', t('home.kind')),
    ];
  }

  function back(): HTMLButtonElement {
    return button('ghost', `‹ ${t('action.back')}`, () => go('main'));
  }

  function mainView(): HTMLElement[] {
    const session = currentSession();
    const items: HTMLElement[] = [...title(), el('p', 'home-tagline', t('welcome.tagline'))];
    if (session) {
      items.push(
        el('p', 'doc-note', t('auth.signedInAs', { email: session.email })),
        button('primary home-enter', t('welcome.enter'), () => options.enter(theme)),
        button('ghost', t('auth.signOut'), () => {
          void signOut().then(() => {
            note = { text: t('auth.signedOut'), good: true };
            render();
          });
        }),
      );
    } else {
      items.push(
        button('primary home-enter', t('auth.login'), () => go('login')),
        button('ghost', t('auth.signup'), () => go('signup')),
        el('div', 'welcome-or', t('auth.or')),
        oauthRow(),
        button('link', t('auth.magic'), () => go('magic')),
      );
    }
    const foot = el('div', 'welcome-foot');
    foot.append(
      button('link', t('welcome.settings'), () => go('settings')),
      button('link', t('welcome.legal'), () => go('legal')),
    );
    items.push(foot);
    return items;
  }

  function loginView(): HTMLElement[] {
    const mail = field('email', t('auth.email'), 'username', email);
    const pass = field('password', t('auth.password'), 'current-password');
    return [
      el('h2', 'card-title', t('auth.login')),
      form([mail, pass], t('auth.loginSubmit'), () => {
        email = mail.value.trim();
        void run(
          () => signIn(email, pass.value),
          () => options.enter(theme),
        );
      }),
      button('link', t('auth.forgot'), () => go('forgot')),
      button('link', t('auth.noAccount'), () => go('signup')),
      back(),
    ];
  }

  function signupView(): HTMLElement[] {
    const mail = field('email', t('auth.email'), 'username', email);
    const pass = field('password', t('auth.passwordNew'), 'new-password');
    const consent = el('label', 'welcome-consent');
    const box = document.createElement('input');
    box.type = 'checkbox';
    consent.append(box, el('span', '', t('auth.consent')));
    const read = button('link', t('welcome.legal'), () => {
      legal = 'terms';
      go('legal');
    });
    return [
      el('h2', 'card-title', t('auth.signup')),
      el('p', 'doc-note', t('auth.signupNote')),
      form([mail, pass, consent], t('auth.signupSubmit'), () => {
        email = mail.value.trim();
        if (!box.checked) {
          note = { text: t('auth.consentNeeded'), good: false };
          render();
          return;
        }
        if (pass.value.length < 8) {
          note = { text: t('auth.error.weak'), good: false };
          render();
          return;
        }
        void run(
          () => signUp(email, pass.value),
          (r) => {
            if (r.ok && r.session) options.enter(theme);
            else note = { text: t('auth.checkMail', { email }), good: true };
          },
        );
      }),
      read,
      back(),
    ];
  }

  function magicView(): HTMLElement[] {
    const mail = field('email', t('auth.email'), 'username', email);
    return [
      el('h2', 'card-title', t('auth.magic')),
      el('p', 'doc-note', t('auth.magicNote')),
      form([mail], t('auth.magicSubmit'), () => {
        email = mail.value.trim();
        void run(
          () => sendMagicLink(email),
          () => (note = { text: t('auth.checkMail', { email }), good: true }),
        );
      }),
      back(),
    ];
  }

  function forgotView(): HTMLElement[] {
    const mail = field('email', t('auth.email'), 'username', email);
    return [
      el('h2', 'card-title', t('auth.forgot')),
      el('p', 'doc-note', t('auth.forgotNote')),
      form([mail], t('auth.forgotSubmit'), () => {
        email = mail.value.trim();
        void run(
          () => sendReset(email),
          () => (note = { text: t('auth.checkMail', { email }), good: true }),
        );
      }),
      back(),
    ];
  }

  function resetView(): HTMLElement[] {
    const pass = field('password', t('auth.passwordNew'), 'new-password');
    return [
      el('h2', 'card-title', t('auth.resetTitle')),
      form([pass], t('auth.resetSubmit'), () => {
        if (pass.value.length < 8) {
          note = { text: t('auth.error.weak'), good: false };
          render();
          return;
        }
        void run(
          () => setPassword(pass.value),
          () => {
            view = 'main';
            note = { text: t('auth.resetDone'), good: true };
          },
        );
      }),
    ];
  }

  function toggle(label: string, on: boolean, flip: () => void): HTMLElement {
    const line = el('div', 'doc-row fps-row');
    const sw = button('switch', '', () => {
      flip();
      render();
    });
    sw.setAttribute('role', 'switch');
    sw.setAttribute('aria-checked', String(on));
    sw.setAttribute('aria-label', label);
    sw.append(el('i'));
    line.append(el('span', 'doc-label', label), sw);
    return line;
  }

  function settingsView(): HTMLElement[] {
    const langs = el('div', 'toggle');
    for (const lang of LANGS) {
      const b = button('chip', lang.toUpperCase(), () => {
        setLang(lang as Lang);
        writeSetting('lang', lang);
        render();
      });
      b.setAttribute('aria-pressed', String(lang === getLang()));
      langs.append(b);
    }
    const themes = el('div', 'toggle');
    for (const id of THEME_IDS) {
      const b = button('chip', t(`theme.${id}`), () => {
        theme = id;
        applyTheme(id);
        writeSetting('theme', id);
        render();
      });
      b.setAttribute('aria-pressed', String(id === theme));
      themes.append(b);
    }
    const quality = el('div', 'seg');
    const current = readSetting('graphics') ?? 'high';
    for (const q of ['low', 'medium', 'high'] as const) {
      const b = button('', t(`profile.graphics.${q}`), () => {
        writeSetting('graphics', q);
        render();
      });
      b.setAttribute('aria-pressed', String(current === q));
      quality.append(b);
    }
    const box = el('div', 'doc');
    box.append(
      el('div', 'ref', t('settings.language')),
      langs,
      el('div', 'ref', t('settings.theme')),
      themes,
      el('div', 'ref', t('profile.graphics')),
      quality,
      toggle(t('feedback.sound'), feedbackOn('sound'), () =>
        setFeedback('sound', !feedbackOn('sound')),
      ),
      toggle(t('feedback.vibration'), feedbackOn('vibration'), () =>
        setFeedback('vibration', !feedbackOn('vibration')),
      ),
      toggle(t('feedback.daylight'), feedbackOn('daylight'), () =>
        setFeedback('daylight', !feedbackOn('daylight')),
      ),
    );
    return [el('h2', 'card-title', t('welcome.settings')), box, back()];
  }

  function legalView(): HTMLElement[] {
    const tabs = el('div', 'seg');
    for (const p of ['mentions', 'privacy', 'terms'] as const) {
      const b = button('', t(`legal.${p}.title`), () => {
        legal = p;
        render();
      });
      b.setAttribute('aria-pressed', String(p === legal));
      tabs.append(b);
    }
    return [el('h2', 'card-title', t('welcome.legal')), tabs, legalText(legal), back()];
  }

  function render(): void {
    const sheet = el('section', 'home-sheet welcome-sheet');
    const views: Record<View, () => HTMLElement[]> = {
      main: mainView,
      login: loginView,
      signup: signupView,
      magic: magicView,
      forgot: forgotView,
      reset: resetView,
      settings: settingsView,
      legal: legalView,
    };
    const items = views[view]();
    if (note)
      items.splice(
        view === 'main' ? 3 : 1,
        0,
        el('p', `doc-note ${note.good ? 'good' : 'warn'}`, note.text),
      );
    sheet.append(...items);
    page.replaceChildren(sheet);
    page.dataset.view = view;
  }

  render();
}

/** Texte d'une page légale : « ## » ouvre un titre, une ligne vide sépare les paragraphes. */
export function legalText(page: LegalPage): HTMLElement {
  const box = el('div', 'doc legal');
  for (const block of t(`legal.${page}.body` as MessageKey).split('\n\n')) {
    if (block.startsWith('## ')) box.append(el('h3', 'legal-title', block.slice(3)));
    else box.append(el('p', 'doc-note', block));
  }
  return box;
}
