export interface Actions {
  visit: (buildingId: number) => void;
  propose: (clientId: number, buildingId: number) => void;
  buy: (buildingId: number, cash: boolean) => void;
  sell: (buildingId: number) => void;
  repay: (buildingId: number) => void;
  locate: (building: Building) => void;
  seeDistrict: (client: Client) => void;
  dirty: (buildingId: number, kind: DirtyKind) => void;
  deny: (incidentId: number) => void;
  complain: (incidentId: number) => void;
  camera: (buildingId: number) => void;
  renovate: (buildingId: number) => void;
  buyPlot: (plot: number) => void;
  locatePlot: (plot: number) => void;
  build: (plot: number, kind: ProjectKind) => void;
  /** Niveau de graphismes choisi sur cet appareil. */
  quality: () => 'low' | 'medium' | 'high';
  setQuality: (quality: 'low' | 'medium' | 'high') => void;
  /** Compteur d'images par seconde sur la carte. */
  showFps: () => boolean;
  setShowFps: (on: boolean) => void;
  /** Langue et thème : réglés depuis le Profil (la barre du haut ne les montre plus). */
  setLang: (lang: Lang) => void;
  themeLabel: () => string;
  nextTheme: () => void;
  closeCard: () => void;
  openProperties: () => void;
  /** Signaler un problème (en ligne seulement). */
  report?: (category: string, message: string) => Promise<boolean>;
  adminMode: () => { on: boolean; online: boolean; available: boolean };
  setAdminMode: (on: boolean, code?: string) => Promise<boolean>;
  /** Liste des biens à vendre : filtre par type et tri. */
  listingFilter: () => ListingFilter;
  setListingFilter: (filter: ListingFilter) => void;
  closeListings: () => void;
  /** Classement et amis (chargés à part : en ligne, ils viennent du serveur). */
  social: () => Social | null;
  friend: (code: string, add: boolean) => void;
  showFriend: (friend: FriendView) => void;
  /** Page des locataires d'un bien possédé (identifiant du bien, bâtiment ou programme). */
  openTenants: (propertyId: string) => void;
  deleteThread: (key: string) => void;
  answerIssue: (propertyId: string, choice: IssueChoice) => void;
  setAgency: (on: boolean) => void;
  bid: (auctionId: number, amount: number) => void;
  claimQuest: (id: string) => void;
  claimDaily: () => void;
  tenant: (propertyId: string, candidateId: number, choice: 'accept' | 'haggle' | 'reject') => void;
  openLawsuit: (propertyId: string) => void;
  closeLawsuit: () => void;
  sue: (propertyId: string, articles: string[], evidence: string[], lawyer: boolean) => void;
  /** Absent en ligne : on ne recommence pas une partie partagée. */
  reset?: () => void;
}

