/** Grand document affiché par-dessus la carte : dossier d'achat ou choix du client. */
export type Sheet = 'dossier' | 'propose' | 'dirty';

function plural(base: 'card.floors' | 'clients.daysLeft' | 'clients.missions', count: number) {
  return t(`${base}.${count === 1 ? 'one' : 'other'}` as MessageKey, {
    count: formatNumber(count),
  });
}

export function clientName(client: Pick<Client, 'title' | 'surname'>): string {
  return `${t(`title.${client.title}`)} ${client.surname}`;
}

function refLabel(building: Building): string {
  const [code = '', number = ''] = building.ref.split(' ');
  return t('card.ref', { code, number });
}

/** Fiche d'un bâtiment sélectionné sur la carte : l'essentiel, et les actions possibles. */
export function renderBuildingCard(
  card: HTMLElement,
  state: GameState,
  building: Building,
  openSheet: (sheet: Sheet) => void,
  actions: Actions,
): void {
  const f = facts(state, building);
  const status = statusOf(state, building.id);
  const visited = isVisited(state, building.id);
  const owned = isOwned(state, building.id);
  const listed = isListed(state, building.id);
  const close = button('close', '×', actions.closeCard);
  close.setAttribute('aria-label', t('card.close'));
  const where = el('div', 'card-row');
  where.append(
    el(
      'span',
      'card-where',
      `${t(`district.${building.district}`)} · ${plural('card.floors', building.floors)}`,
    ),
    el('span', `status st-${status}`, t(`card.status.${status}`)),
  );
  const lines: HTMLElement[] = [
    close,
    el('div', 'ref', refLabel(building)),
    el('h2', 'card-title', t(`type.${building.type}`)),
    where,
  ];
  const buttons = el('div', 'card-actions');
  /** Tout se fait à distance (décision du propriétaire) : plus de trajet avant d'agir. */

  if (owned) {
    const property = state.player.properties.find((p) => p.id === String(building.id));
    if (property) {
      const day = currentDay(state);
      lines.push(row(t('card.value'), formatDucats(buildingValue(state, building, day))));
      const lease = tenantLines(state, property.id, actions);
      lines.push(...lease.lines);
      buttons.append(lease.open);
      // Marchand de biens : état du bien, travaux en cours ou devis.
      const upkeep = upkeepOf(state, building.id);
      lines.push(row(t('card.condition'), t(`condition.${upkeep.condition}`), 'doc-value'));
      if (upkeep.works) {
        const left = Math.max(1, upkeep.works.doneDay - day);
        lines.push(
          row(
            t('card.works'),
            t(left === 1 ? 'card.worksValue.one' : 'card.worksValue.other', {
              condition: t(`condition.${upkeep.works.to}`),
              count: left,
            }),
            'doc-value warn',
          ),
        );
      } else {
        const quote = renovationQuote(state, building.id);
        if (quote.to) {
          lines.push(
            row(
              t('card.renovationGain'),
              t('card.renovationGainValue', {
                value: formatDucats(quote.valueAfter),
                count: quote.days,
              }),
              'doc-value',
            ),
          );
          const works = button(
            'primary',
            t('action.renovate', {
              condition: t(`condition.${quote.to}`),
              amount: formatDucats(quote.cost),
            }),
            () => actions.renovate(building.id),
          );
          works.disabled = quote.refusal !== null;
          buttons.append(works);
        }
      }
      const effect = activeEffect(state, building.id, day);
      if (effect) {
        const left = effect.untilDay - day + 1;
        lines.push(
          row(
            t('card.incident'),
            t(left === 1 ? 'card.incidentValue.one' : 'card.incidentValue.other', {
              kind: t(`dirty.kind.${effect.kind}`),
              count: left,
            }),
            'doc-value warn',
          ),
        );
      }
      const incident = openIncident(state, building.id);
      if (incident) {
        lines.push(row(t('card.clues'), formatNumber(incident.clues), 'doc-value'));
        const complain = button(
          'primary',
          t('action.complain', { amount: formatDucats(COMPLAINT_COST) }),
          () => actions.complain(incident.id),
        );
        complain.disabled = state.player.cash < COMPLAINT_COST;
        buttons.append(complain);
        if (incident.kind === 'rumor' && !incident.denied) {
          const deny = button(
            'ghost',
            t('action.deny', { amount: formatDucats(DENIAL_COST) }),
            () => actions.deny(incident.id),
          );
          deny.disabled = state.player.cash < DENIAL_COST;
          buttons.append(deny);
        }
        if (incident.attacker)
          lines.push(row(t('card.attacker'), incident.attacker, 'doc-value warn'));
      }
      if (hasCamera(state, building.id)) {
        lines.push(row(t('card.cameras'), t('card.camerasOn'), 'doc-value'));
      } else {
        const camera = button(
          'ghost',
          t('action.camera', { amount: formatDucats(CAMERA_COST) }),
          () => actions.camera(building.id),
        );
        camera.disabled = state.player.cash < CAMERA_COST;
        buttons.append(camera);
      }
      buttons.append(button('ghost', t('action.sell'), () => actions.sell(building.id)));
    }
  } else {
    lines.push(row(listed ? t('card.asking') : t('card.value'), formatDucats(f.askingPrice)));
    lines.push(row(t('card.rent'), formatPerDay(f.rent)));
    lines.push(
      row(
        t('card.condition'),
        visited ? t(`condition.${f.condition}`) : t('card.unknown'),
        'doc-value',
      ),
    );
    if (visited) lines.push(row(t('card.defect'), t(`defect.${f.defect}`), 'doc-value'));
    if (building.perks.length > 0)
      lines.push(
        row(t('card.location'), building.perks.map((p) => t(`perk.${p}`)).join(' · '), 'doc-value'),
      );
    const rival = rivalOf(state, building.id);
    const otherPlayer = (state.othersOwned ?? []).includes(building.id);
    if (otherPlayer) lines.push(row(t('card.owner'), t('dirty.anotherPlayer'), 'doc-value'));
    if (rival) {
      lines.push(row(t('card.owner'), rival.name, 'doc-value'));
      const pressure = Math.min(FORCED_SALE_PRESSURE, pressureOn(state, building.id));
      lines.push(
        row(
          t('card.pressure'),
          '●'.repeat(pressure) + '○'.repeat(FORCED_SALE_PRESSURE - pressure),
          'stars',
        ),
      );
    }
    const discount = state.discounts[String(building.id)];
    if (listed && discount) {
      lines.push(
        row(
          t('card.forcedSale'),
          t('card.forcedSaleValue', { rate: formatPercent(discount) }),
          'doc-value pos',
        ),
      );
    }
    if ((rival || otherPlayer) && !listed) {
      if (!visited) {
        const scouting = state.visiting?.buildingId === building.id;
        const scout = button('primary', scouting ? t('action.visiting') : t('action.scout'), () =>
          actions.visit(building.id),
        );
        scout.disabled = state.visiting !== null;
        buttons.append(scout);
      } else {
        buttons.append(button('primary', t('action.dirty'), () => openSheet('dirty')));
      }
    }
    if (listed) {
      if (!visited) {
        if (state.visiting?.buildingId === building.id) {
          const busy = button('primary', t('action.visiting'), () => undefined);
          busy.disabled = true;
          buttons.append(busy);
        } else {
          const visit = button('primary', t('action.visit'), () => actions.visit(building.id));
          if (state.visiting) {
            visit.disabled = true;
            visit.title = t('action.visitBusy');
          }
          buttons.append(visit);
        }
      } else {
        buttons.append(button('primary', t('action.propose'), () => openSheet('propose')));
      }
      buttons.append(button('ghost', t('action.dossier'), () => openSheet('dossier')));
    }
  }
  card.replaceChildren(...lines, buttons);
}

/** Onglet Admin du propriétaire : argent, temps, réputation, pour tester sans attendre. */
export function renderAdmin(
  screen: HTMLElement,
  state: GameState,
  run: (command: AdminCommand) => void,
): void {
  const block = (title: string, ...children: HTMLElement[]): HTMLElement[] => {
    const actionsRow = el('div', 'card-actions');
    actionsRow.append(...children);
    return [el('h2', 'section-title', title), actionsRow];
  };
  const status = el('div', 'doc');
  status.append(
    row(t('wallet.balance'), formatDucats(state.player.cash), 'amount'),
    row(t('profile.day'), formatNumber(state.player.day), 'doc-value'),
    row(t('clients.reputation'), plural('clients.missions', state.reputation), 'doc-value'),
    row(t('bank.credit'), formatNumber(state.player.creditLevel), 'doc-value'),
  );
  screen.replaceChildren(
    el('h1', 'screen-title', t('admin.title')),
    el('p', 'doc-note', t('admin.note')),
    status,
    ...block(
      t('admin.cash'),
      ...[10_000, 100_000, 1_000_000, 10_000_000, 100_000_000].map((amount) =>
        button('primary', `+ ${formatDucats(amount)}`, () => run({ type: 'cash', amount })),
      ),
    ),
    ...block(
      t('admin.time'),
      ...[1, 7, 30].map((count) =>
        button('ghost', t('admin.days', { count }), () => run({ type: 'days', count })),
      ),
      button('ghost', t('admin.arrive'), () => run({ type: 'arrive' })),
    ),
    ...block(
      t('admin.player'),
      button('ghost', t('admin.reputation'), () => run({ type: 'reputation', missions: 10 })),
      button('ghost', t('admin.credit'), () => run({ type: 'credit' })),
      button('ghost', t('admin.clean'), () => run({ type: 'clean' })),
    ),
  );
}

/** Durée lisible d'une journée de jeu (30 s, 10 min, 1 h, 24 h). */
export function dayLength(ms: number): string {
  if (ms < 60_000) return t('admin.len.s', { n: Math.round(ms / 1000) });
  if (ms < 3_600_000) return t('admin.len.min', { n: Math.round(ms / 60_000) });
  return t('admin.len.h', { n: Math.round((ms / 3_600_000) * 10) / 10 });
}

/** Nom, lieu et dates d'un événement de ville. */
export function eventLine(e: CityEvent, day: number): { title: string; detail: string } {
  const where = e.district ? t(`district.${e.district}`) : t('event.everywhere');
  const pct = (m: number): string =>
    `${m >= 1 ? '+' : '−'}${Math.round(Math.abs(m - 1) * 100)}\u202f%`;
  const when =
    day < e.startDay
      ? t('event.in', { n: e.startDay - day })
      : t('event.until', { day: t('city.day', { day: e.endDay }) });
  return {
    title: `${t(`event.${e.kind}.title` as MessageKey)} · ${where}`,
    detail: `${when} · ${t('event.prices')} ${pct(e.price)} · ${t('event.rents')} ${pct(e.rent)}`,
  };
}

/**
 * Onglet Admin (propriétaire du jeu) : rythme du temps, sauts dans le temps, événements de ville,
 * crédit de test, signalements. Le même écran sert en ligne et hors ligne.
 */
export function renderDevAdmin(
  screen: HTMLElement,
  state: GameState,
  status: AdminStatus | null,
  online: boolean,
  op: (op: AdminOp) => void,
  legacy: ((command: AdminCommand) => void) | null,
): void {
  const items: HTMLElement[] = [
    el('div', 'ref', t(online ? 'admin.online' : 'admin.offline')),
    el('h1', 'screen-title', t('admin.title')),
  ];
  if (!status) {
    items.push(el('p', 'doc-note', t('admin.loading')));
    screen.replaceChildren(...items);
    return;
  }
  // Temps.
  const time = el('div', 'doc');
  time.append(
    row(
      t('admin.today'),
      `${t('city.day', { day: status.day })} · ${Math.round(status.progress * 100)} %`,
      'doc-value',
    ),
    row(t('admin.dayLength'), dayLength(status.msPerDay), 'doc-value'),
  );
  if (status.players !== undefined)
    time.append(row(t('admin.players'), formatNumber(status.players), 'doc-value'));
  const speeds = el('div', 'card-actions');
  for (const [label, ms] of [
    ['30 s', 30_000],
    ['1 min', 60_000],
    ['10 min', 600_000],
    ['1 h', 3_600_000],
    ['24 h', 86_400_000],
  ] as const) {
    const b = button(status.msPerDay === ms ? 'primary' : 'ghost', label, () =>
      op({ type: 'speed', msPerDay: ms }),
    );
    speeds.append(b);
  }
  const custom = document.createElement('input');
  custom.type = 'number';
  custom.min = '0.1';
  custom.step = '0.1';
  custom.id = 'admin-minutes';
  custom.className = 'admin-input';
  custom.placeholder = t('admin.customMinutes');
  const customRow = el('div', 'card-actions');
  customRow.append(
    custom,
    button('ghost', t('admin.apply'), () => {
      const minutes = Number(custom.value);
      if (minutes > 0) op({ type: 'speed', msPerDay: Math.round(minutes * 60_000) });
    }),
  );
  const jumps = el('div', 'card-actions');
  for (const days of [1, 7, 30])
    jumps.append(
      button('ghost', t('admin.days', { count: days }), () => op({ type: 'jump', days })),
    );
  time.append(
    el('p', 'doc-note', t('admin.speedNote')),
    speeds,
    customRow,
    el('p', 'doc-note', t('admin.jumpNote')),
    jumps,
  );
  items.push(...section(t('admin.time'), time));

  // Événements.
  const all = [
    ...cityEvents(state, status.day).filter((e) => e.source === 'auto'),
    ...status.events,
  ];
  const shown = all
    .filter((e) => e.endDay >= status.day && e.startDay <= status.day + 14)
    .sort((a, b) => a.startDay - b.startDay);
  const events = el('div', 'doc');
  if (shown.length === 0) events.append(el('p', 'doc-note', t('admin.noEvents')));
  for (const e of shown) {
    const line = eventLine(e, status.day);
    const box = el('div', 'admin-event');
    box.append(
      el('b', '', line.title),
      el(
        'span',
        'doc-note',
        `${t(e.source === 'auto' ? 'admin.auto' : 'admin.manual')} · ${line.detail}`,
      ),
    );
    if (e.source === 'admin')
      box.append(button('ghost', t('admin.cancel'), () => op({ type: 'cancelEvent', id: e.id })));
    events.append(box);
  }
  if (!online) {
    events.append(
      button('ghost', t(status.eventsOff ? 'admin.autoOn' : 'admin.autoOff'), () =>
        op({ type: 'eventsOff', off: !status.eventsOff }),
      ),
    );
  }
  items.push(...section(t('admin.events'), events));

  // Enchères et règle d'inactivité.
  const sales = el('div', 'doc');
  sales.append(
    el('p', 'doc-note', t('admin.auctionsNote')),
    button('ghost', t('admin.auctionNow'), () => op({ type: 'auctionNow' })),
  );
  if (online) {
    sales.append(
      row(t('admin.inactivity'), t(status.inactivity ? 'admin.on' : 'admin.off'), 'doc-value'),
      el('p', 'doc-note', t('admin.inactivityNote')),
      button('ghost', t(status.inactivity ? 'admin.inactivityOff' : 'admin.inactivityOn'), () =>
        op({ type: 'inactivity', on: !status.inactivity }),
      ),
    );
  }
  items.push(...section(t('admin.auctions'), sales));

  // Créer un événement.
  const form = el('div', 'doc admin-form');
  const kind = document.createElement('select');
  kind.id = 'admin-kind';
  for (const k of Object.keys(EVENT_KINDS) as EventKind[]) {
    const o = document.createElement('option');
    o.value = k;
    o.textContent = t(`event.${k}.title` as MessageKey);
    kind.append(o);
  }
  const district = document.createElement('select');
  district.id = 'admin-district';
  for (const d of DISTRICTS) {
    if (d.id === 'zone1') continue;
    const o = document.createElement('option');
    o.value = d.id;
    o.textContent = t(`district.${d.id}`);
    district.append(o);
  }
  const syncDistrict = (): void => {
    district.disabled = EVENT_KINDS[kind.value as EventKind].city;
  };
  kind.addEventListener('change', syncDistrict);
  syncDistrict();
  const inDays = document.createElement('input');
  inDays.type = 'number';
  inDays.min = '0';
  inDays.value = '0';
  inDays.id = 'admin-in';
  inDays.className = 'admin-input';
  const length = document.createElement('input');
  length.type = 'number';
  length.min = '1';
  length.id = 'admin-length';
  length.className = 'admin-input';
  length.placeholder = t('admin.lengthDefault');
  form.append(
    el('label', 'doc-note', t('admin.kind')),
    kind,
    el('label', 'doc-note', t('admin.where')),
    district,
    el('label', 'doc-note', t('admin.startIn')),
    inDays,
    el('label', 'doc-note', t('admin.length')),
    length,
    button('primary', t('admin.create'), () => {
      const k = kind.value as EventKind;
      op({
        type: 'addEvent',
        kind: k,
        district: EVENT_KINDS[k].city ? null : (district.value as DistrictId),
        inDays: Math.max(0, Number(inDays.value) || 0),
        days: Number(length.value) || EVENT_KINDS[k].days,
      });
    }),
  );
  items.push(...section(t('admin.newEvent'), form));

  // Tests du joueur.
  const tests = el('div', 'card-actions');
  for (const amount of [100_000, 1_000_000, 10_000_000])
    tests.append(
      button('ghost', `+ ${formatCompact(amount)}`, () => op({ type: 'grant', amount })),
    );
  if (legacy) {
    tests.append(
      button('ghost', t('admin.reputation'), () => legacy({ type: 'reputation', missions: 10 })),
      button('ghost', t('admin.credit'), () => legacy({ type: 'credit' })),
      button('ghost', t('admin.clean'), () => legacy({ type: 'clean' })),
    );
  }
  items.push(...section(t('admin.player'), tests));

  if (status.reports) {
    const reports = el('div', 'doc');
    if (status.reports.length === 0) reports.append(el('p', 'doc-note', t('admin.noReports')));
    for (const r of status.reports) {
      const box = el('div', 'admin-event');
      box.append(
        el(
          'span',
          'ref',
          `${new Date(r.created_at).toLocaleString()} · ${t(`report.cat.${r.category}` as MessageKey)}`,
        ),
        el('p', 'doc-note', r.message),
      );
      reports.append(box);
    }
    items.push(...section(t('admin.reports'), reports));
  }
  screen.replaceChildren(...items);
}

/** Fiche d'un terrain de la Zone 1 : surface, prix, programmes possibles, chantier en cours. */
export function renderPlotCard(
  card: HTMLElement,
  state: GameState,
  city: City,
  index: number,
  actions: Actions,
): void {
  const plot = city.plots[index];
  if (!plot) return;
  const status = plotStatus(state, index);
  const close = button('close', '×', actions.closeCard);
  close.setAttribute('aria-label', t('card.close'));
  const [code = '', number = ''] = plot.ref.split(' ');
  const where = el('div', 'card-row');
  where.append(
    el('span', 'card-where', t('district.zone1')),
    el(
      'span',
      `status st-${status === 'free' ? 'sale' : status === 'taken' ? 'none' : 'mine'}`,
      t(`plot.status.${status}`),
    ),
  );
  const lines: HTMLElement[] = [
    close,
    el('div', 'ref', t('card.ref', { code, number })),
    el('h2', 'card-title', t('plot.title')),
    where,
    row(t('plot.area'), t('plot.areaValue', { area: formatNumber(plotArea(plot)) }), 'doc-value'),
  ];
  const buttons = el('div', 'card-actions');
  const day = currentDay(state);
  if (status === 'free') {
    const price = landPrice(plot, day);
    lines.push(row(t('card.asking'), formatDucats(price)));
    const buy = button('primary', t('plot.buy', { amount: formatDucats(price) }), () =>
      actions.buyPlot(index),
    );
    buy.disabled = state.player.cash < price;
    buttons.append(buy);
  }
  if (status === 'owned') {
    lines.push(el('p', 'doc-note', t('plot.choose')));
    for (const kind of PROJECT_KINDS) {
      const q = projectQuote(state, city, index, kind);
      lines.push(
        row(
          t(`plot.project.${kind}`, { count: q.units }),
          t('plot.projectValue', { value: formatDucats(q.value), count: q.days }),
          'doc-value',
        ),
      );
      const go = button(
        'primary',
        t('plot.build', {
          amount: formatDucats(q.cost),
          project: t(`plot.project.${kind}`, { count: q.units }),
        }),
        () => actions.build(index, kind),
      );
      go.disabled = q.refusal !== null;
      buttons.append(go);
    }
  }
  const program = plotProgram(state, index);
  if (status === 'building' && program) {
    const left = Math.max(1, program.doneDay - day);
    lines.push(
      row(
        t('plot.program'),
        t(`plot.project.${program.kind}`, { count: program.units }),
        'doc-value',
      ),
    );
    lines.push(
      row(
        t('card.works'),
        t(left === 1 ? 'plot.doneIn.one' : 'plot.doneIn.other', { count: left }),
        'doc-value warn',
      ),
    );
  }
  if (status === 'built' && program) {
    const id = plotPropertyId(index);
    const property = state.player.properties.find((p) => p.id === id);
    lines.push(
      row(
        t('plot.program'),
        t(`plot.project.${program.kind}`, { count: program.units }),
        'doc-value',
      ),
    );
    if (property) {
      lines.push(row(t('card.value'), formatDucats(ownedValue(state, city, property.id, day))));
      const lease = tenantLines(state, property.id, actions);
      lines.push(...lease.lines);
      buttons.append(lease.open);
      buttons.append(button('ghost', t('action.sell'), () => actions.sell(Number(id))));
    }
  }
  card.replaceChildren(...lines, buttons);
}

/** Durée en heures de jeu : « 2 j 4 h », « 5 h 30 », « 12 min ». */
export function formatHours(hours: number): string {
  const minutes = Math.max(1, Math.round(hours * 60));
  const days = Math.floor(minutes / 1440);
  const h = Math.floor((minutes % 1440) / 60);
  const m = minutes % 60;
  if (days > 0) return t('time.daysHours', { d: days, h });
  if (h > 0)
    return m > 0
      ? t('time.hoursMinutes', { h, m: String(m).padStart(2, '0') })
      : t('time.hours', { h });
  return t('time.minutes', { m });
}

/** Durée réelle, en version accélérée : « 13 s », « 2 min ». */
export function formatRealMs(ms: number): string {
  const seconds = Math.max(1, Math.ceil(ms / 1000));
  if (seconds < 120) return t('time.seconds', { s: seconds });
  if (seconds < 7200) return t('time.minutes', { m: Math.round(seconds / 60) });
  return t('time.hours', { h: Math.round(seconds / 3600) });
}

