/** Sons, vibrations, jour et nuit, notifications. */
function feedbackChoice(refresh: () => void): HTMLElement {
  const wrap = el('div', '');
  for (const setting of ['sound', 'vibration', 'daylight'] as const) {
    const line = el('div', 'doc-row fps-row');
    const on = feedbackOn(setting);
    const toggle = button('switch', '', () => {
      setFeedback(setting, !on);
      if (setting === 'sound' && !on) play('coins');
      refresh();
    });
    toggle.setAttribute('role', 'switch');
    toggle.setAttribute('aria-checked', String(on));
    toggle.setAttribute('aria-label', t(`feedback.${setting}`));
    toggle.append(el('i'));
    line.append(el('span', 'doc-label', t(`feedback.${setting}`)), toggle);
    wrap.append(line);
  }
  if (!notificationsSupported()) wrap.append(el('p', 'doc-note', t('feedback.notifyUnsupported')));
  else if (notificationsOn()) wrap.append(el('p', 'doc-note', t('feedback.notifyOn')));
  else
    wrap.append(
      button('ghost', t('feedback.notifyAsk'), () => void askNotifications().then(refresh)),
      el('p', 'doc-note', t('feedback.notifyNote')),
    );
  return wrap;
}

