/**
 * Bilan du Profil (retour du propriétaire : regrouper les chiffres) : ce qui est entré, ce qui
 * est sorti, le résultat, et le détail replié des seules lignes non nulles.
 */
function ledgerSummary(l: GameState['ledger'], earned: number, spent: number): HTMLElement {
  const box = el('div', 'doc');
  box.append(
    signedRow(t('profile.earned'), earned),
    signedRow(t('profile.spent'), -spent),
    signedRow(t('profile.result'), earned - spent, 'total'),
  );
  const lines: [string, number][] = [
    [t('profile.commissions'), l.commissions],
    [t('profile.rent'), l.rent],
    [t('profile.sales'), l.sales],
    [t('profile.downPayments'), -l.downPayments],
    [t('profile.loanPayments'), -l.loanPayments],
    [t('profile.charges'), -l.charges],
    [t('profile.agency'), -l.agency],
    [t('profile.taxes'), -l.taxes],
    [t('profile.renovation'), -l.renovation],
    [t('profile.land'), -l.land],
    [t('profile.construction'), -l.construction],
  ];
  const details = document.createElement('details');
  details.className = 'ledger-details';
  details.append(el('summary', '', t('profile.details')));
  for (const [label, amount] of lines)
    if (Math.round(amount) !== 0) details.append(signedRow(label, amount));
  box.append(details);
  return box;
}

/**
 * Application Actualités : la Gazette de Saint-Profit, tirée de la partie. Le marché, le quartier
 * qui vend le plus, la meilleure affaire du jour, les concurrents, et une brève par jour.
 */
export function renderNews(
  screen: HTMLElement,
  state: GameState,
  city: City,
  actions: Actions,
): void {
  const day = currentDay(state);
  const items: HTMLElement[] = [
    el('div', 'ref', t('news.masthead', { day: t('city.day', { day }) })),
    el('h1', 'screen-title', t('news.title')),
  ];
  const article = (kicker: string, title: string, body: string, extra?: HTMLElement): void => {
    const doc = el('article', 'doc news');
    doc.append(el('span', 'ref', kicker), el('h2', 'card-title', title), el('p', 'doc-note', body));
    if (extra) doc.append(extra);
    items.push(doc);
  };
  // Événements de ville : en cours, puis annoncés.
  for (const e of visibleEvents(cityEvents(state, day), day)) {
    const line = eventLine(e, day);
    article(
      t(day < e.startDay ? 'news.kicker.soon' : 'news.kicker.event'),
      line.title,
      t(`event.${e.kind}.body` as MessageKey),
      el('p', 'doc-note', line.detail.charAt(0).toUpperCase() + line.detail.slice(1)),
    );
  }
  // Marché : hausse sur 30 jours.
  const month = (growth(day, RULES) / growth(Math.max(0, day - 30), RULES) - 1) * 100;
  article(
    t('news.kicker.market'),
    t('news.market.title', { pct: month.toLocaleString(undefined, { maximumFractionDigits: 1 }) }),
    t('news.market.body'),
  );
  // Annonces : le quartier qui vend le plus, et la meilleure affaire (rendement).
  const listed = state.listings
    .map((id) => city.buildings[id])
    .filter((b): b is Building => b !== undefined && statusOf(state, b.id) === 'sale');
  const byDistrict = new Map<DistrictId, number>();
  for (const b of listed) byDistrict.set(b.district, (byDistrict.get(b.district) ?? 0) + 1);
  const top = [...byDistrict.entries()].sort((a, b) => b[1] - a[1])[0];
  if (top)
    article(
      t('news.kicker.districts'),
      t('news.district.title', { district: t(`district.${top[0]}`), count: top[1] }),
      t('news.district.body'),
    );
  const best = listed
    .map((b) => ({ b, f: facts(state, b) }))
    .sort((a, c) => c.f.rent / c.f.askingPrice - a.f.rent / a.f.askingPrice)[0];
  if (best)
    article(
      t('news.kicker.deal'),
      t('news.deal.title', {
        type: t(`type.${best.b.type}`),
        district: t(`district.${best.b.district}`),
      }),
      t('news.deal.body', {
        price: formatDucats(best.f.askingPrice),
        rent: formatPerDay(best.f.rent),
      }),
      button('ghost', t('action.locate'), () => actions.locate(best.b)),
    );
  // Concurrents.
  const rival = [...state.rivals].sort((a, b) => b.buildings.length - a.buildings.length)[0];
  if (rival && rival.buildings.length > 0)
    article(
      t('news.kicker.rivals'),
      t('news.rival.title', { name: rival.name, count: rival.buildings.length }),
      t('news.rival.body'),
    );
  // Brève du jour.
  const brief = (day * 7 + 3) % 6;
  article(
    t('news.kicker.brief'),
    t(`news.brief.${brief}.title` as MessageKey),
    t(`news.brief.${brief}.body` as MessageKey),
  );
  screen.replaceChildren(...items);
}

/** Mode développeur : ouvre l'onglet Admin (en ligne, avec le code Admin). */
function devSection(actions: Actions): HTMLElement[] {
  const mode = actions.adminMode();
  if (!mode.available) return [];
  const box = el('div', 'report-form');
  if (mode.on) {
    box.append(button('ghost', t('admin.lock'), () => void actions.setAdminMode(false)));
    return section(t('admin.dev'), box);
  }
  if (!mode.online) {
    box.append(
      el('p', 'doc-note', t('admin.devOffline')),
      button('ghost', t('admin.unlock'), () => void actions.setAdminMode(true)),
    );
    return section(t('admin.dev'), box);
  }
  const code = document.createElement('input');
  code.type = 'password';
  code.id = 'admin-code';
  code.autocomplete = 'off';
  code.placeholder = t('admin.code');
  code.className = 'admin-input';
  const status = el('p', 'doc-note');
  box.append(
    el('p', 'doc-note', t('admin.codeNote')),
    code,
    button('ghost', t('admin.unlock'), () => {
      void actions.setAdminMode(true, code.value.trim()).then((ok) => {
        if (!ok) status.textContent = t('admin.badCode');
      });
    }),
    status,
  );
  return section(t('admin.dev'), box);
}

/** Formulaire « Signaler un problème » (en ligne seulement). */
function reportForm(actions: Actions): HTMLElement | null {
  const send = actions.report;
  if (!send) return null;
  const box = el('div', 'report-form');
  const category = document.createElement('select');
  category.id = 'report-category';
  for (const c of ['bug', 'idea', 'player', 'other']) {
    const o = document.createElement('option');
    o.value = c;
    o.textContent = t(`report.cat.${c}` as MessageKey);
    category.append(o);
  }
  const text = document.createElement('textarea');
  text.id = 'report-text';
  text.rows = 4;
  text.maxLength = 2000;
  text.placeholder = t('report.placeholder');
  const status = el('p', 'doc-note');
  const submit = button('primary', t('report.send'), () => {
    const message = text.value.trim();
    if (message.length < 3) {
      status.textContent = t('report.tooShort');
      return;
    }
    submit.disabled = true;
    void send(category.value, message).then((ok) => {
      submit.disabled = false;
      status.textContent = t(ok ? 'report.sent' : 'report.failed');
      if (ok) text.value = '';
    });
  });
  box.append(el('p', 'doc-note', t('report.note')), category, text, submit, status);
  return box;
}

