/** Une conversation avec un locataire. */
export function renderThread(
  screen: HTMLElement,
  state: GameState,
  city: City,
  key: string,
  actions: Actions,
): void {
  const thread = threadsOf(state).find((th) => th.key === key);
  if (!thread) {
    screen.replaceChildren(el('p', 'doc-note', t('msg.none')));
    return;
  }
  const items: HTMLElement[] = [
    el('div', 'ref', `${placeRef(city, thread.propertyId)} · ${clientName(thread)}`),
  ];
  const list = el('div', 'bubbles');
  let lastDay = -1;
  for (const m of thread.messages) {
    if (m.day !== lastDay) {
      list.append(el('div', 'bubble-day', t('city.day', { day: m.day })));
      lastDay = m.day;
    }
    list.append(el('p', `bubble ${m.kind}`, messageText(m)));
  }
  items.push(list);
  const entry = state.tenancy[thread.propertyId];
  const tenant = entry?.tenant;
  if (tenant && tenant.id === thread.tenantId && entry?.issue) {
    const box = el('div', 'doc issue-box');
    const cost = repairCost(state, thread.propertyId);
    box.append(
      el('div', 'ref', t('issue.title')),
      el('p', 'doc-note', t(`issue.${entry.issue.kind}` as MessageKey)),
      button('primary', t('issue.repair', { amount: formatDucats(cost) }), () =>
        actions.answerIssue(thread.propertyId, 'repair'),
      ),
      button('ghost', t('issue.discount', { pct: Math.round((1 - DISCOUNT) * 100) }), () =>
        actions.answerIssue(thread.propertyId, 'discount'),
      ),
      button('ghost', t('issue.ignore'), () => actions.answerIssue(thread.propertyId, 'ignore')),
      el('p', 'doc-note', t('issue.note')),
    );
    items.push(box);
  }
  if (tenant && tenant.id === thread.tenantId)
    items.push(button('ghost', t('msg.lease'), () => actions.openTenants(thread.propertyId)));
  else items.push(el('p', 'doc-note', t('msg.gone')));
  items.push(button('ghost', t('msg.delete'), () => actions.deleteThread(key)));
  screen.replaceChildren(...items);
}

export function messageText(m: TenantMessage): string {
  const params: Record<string, string | number> = { ...m.params };
  if (typeof m.params.amount === 'number') params.amount = formatDucats(m.params.amount);
  return t(`msg.${m.kind}` as MessageKey, params);
}

export function letterText(letter: Letter): { title: string; body: string; stamp: string } {
  const p = letter.params;
  const params: Record<string, string | number> = { ...p };
  if (typeof p.amount === 'number') params.amount = formatDucats(p.amount);
  if (typeof p.cash === 'number') params.cash = formatDucats(p.cash);
  if (p.title === 'mr' || p.title === 'mrs') {
    params.client = clientName({ title: p.title, surname: String(p.surname ?? '') });
  }
  const variant =
    letter.kind === 'refusal'
      ? `.${String(p.reason)}`
      : letter.kind === 'incident' || letter.kind === 'dirtyDone'
        ? `.${String(p.kind)}`
        : '';
  const bodyKey = `letter.${letter.kind}.body${variant}` as MessageKey;
  return {
    title: t(`letter.${letter.kind}.title` as MessageKey),
    body: t(bodyKey, params),
    stamp: t(`stamp.${letter.kind}` as MessageKey),
  };
}

function stampTone(kind: Letter['kind']): string {
  const bad: Letter['kind'][] = [
    'refusal',
    'seized',
    'expired',
    'tax',
    'incident',
    'complaintLost',
    'trial',
    'auctionLost',
    'auctionVoid',
    'forfeited',
  ];
  if (bad.includes(kind)) return 'bad';
  if (kind === 'unpaidRent' || kind === 'overdue') return 'bad';
  if (kind === 'welcome' || kind === 'leaseEnded') return 'neutral';
  return 'good';
}

export function letterElement(letter: Letter): HTMLElement {
  const text = letterText(letter);
  const doc = el('article', 'doc letter' + (letter.read ? '' : ' unread'));
  const head = el('div', 'doc-row');
  head.append(el('span', 'ref', t('mail.day', { day: letter.day })));
  head.append(el('span', `stamp ${stampTone(letter.kind)}`, text.stamp));
  doc.append(head, el('h2', 'card-title', text.title), el('p', 'doc-body', text.body));
  return doc;
}

/** Onglet Courrier : les lettres reçues, de la plus récente à la plus ancienne. */
export function renderMail(screen: HTMLElement, state: GameState): void {
  const items: HTMLElement[] = [el('h1', 'screen-title', t('mail.title'))];
  if (state.letters.length === 0) items.push(el('p', 'doc-note', t('mail.empty')));
  state.letters.forEach((letter) => items.push(letterElement(letter)));
  screen.replaceChildren(...items);
}

/** Vrai si la proposition serait acceptée : sert aux tests et aux aides de jeu. */
export function wouldAccept(state: GameState, client: Client, building: Building): boolean {
  return evaluateProposal(state, client, building).accepted;
}

/** Temps restant, « 4 min 05 s ». */
export function countdown(ms: number): string {
  const s = Math.max(0, Math.round(ms / 1000));
  const m = Math.floor(s / 60);
  return m > 0 ? `${m} min ${String(s % 60).padStart(2, '0')} s` : `${s} s`;
}

/** Application Enchères : les biens aux enchères, la mise en cours, le compte à rebours. */
export function renderAuctions(
  screen: HTMLElement,
  state: GameState,
  city: City,
  actions: Actions,
  nowMs: number,
): void {
  const items: HTMLElement[] = [el('p', 'doc-note', t('auction.intro'))];
  const list = [...(state.auctions ?? [])].sort((a, b) => {
    const oa = isOpen(a, nowMs) ? 0 : 1;
    const ob = isOpen(b, nowMs) ? 0 : 1;
    return oa - ob || a.endsAtMs - b.endsAtMs;
  });
  if (list.length === 0) items.push(el('p', 'doc-note', t('auction.none')));
  for (const a of list) items.push(auctionCard(state, city, a, actions, nowMs));
  screen.replaceChildren(...items);
}

function auctionCard(
  state: GameState,
  city: City,
  a: Auction,
  actions: Actions,
  nowMs: number,
): HTMLElement {
  const building = city.buildings[a.buildingId];
  const doc = el('article', `doc auction ${a.leading ? 'leading' : ''}`);
  if (!building) return doc;
  const f = facts(state, building);
  const open = isOpen(a, nowMs);
  doc.append(
    el(
      'div',
      'ref',
      `${t(`auction.source.${a.source}` as MessageKey)} · ${placeRef(city, a.buildingId)}`,
    ),
    el('h2', 'card-title', `${t(`type.${building.type}`)} · ${t(`district.${building.district}`)}`),
    row(t('auction.estimate'), formatDucats(f.fairValue)),
    row(t('auction.rent'), formatPerDay(f.rent)),
    row(
      t('auction.top'),
      a.topBid === null
        ? t('auction.noBid', { amount: formatDucats(a.startPrice) })
        : `${formatDucats(a.topBid)} · ${a.leading ? t('auction.you') : (a.topName ?? t('auction.someone'))}`,
      `doc-value${a.leading ? ' good' : ''}`,
    ),
  );
  if (open) {
    const line = row(t('auction.ends'), countdown(a.endsAtMs - nowMs), 'doc-value auction-clock');
    (line.lastElementChild as HTMLElement).dataset.ends = String(a.endsAtMs);
    doc.append(line);
    const next = minBid(a);
    const buttons = el('div', 'card-actions');
    for (const step of [0, 0.1]) {
      const amount = Math.round((next * (1 + step)) / 100) * 100;
      const refusal = bidRefusal(state, a, amount, nowMs);
      const b = button(
        step === 0 ? 'primary' : 'ghost',
        t('auction.bid', { amount: formatDucats(amount) }),
        () => actions.bid(a.id, amount),
      );
      b.disabled = refusal !== null;
      buttons.append(b);
    }
    doc.append(buttons);
    const refusal = bidRefusal(state, a, next, nowMs);
    if (refusal === 'leading') doc.append(el('p', 'doc-note good', t('auction.leadingNote')));
    else if (refusal === 'no_cash') doc.append(el('p', 'doc-note warn', t('auction.cashNote')));
    else if (a.bidder && !a.leading) doc.append(el('p', 'doc-note warn', t('auction.outbid')));
  } else {
    const stamp =
      a.status === 'won' || (a.leading && a.topBid !== null)
        ? t('auction.won')
        : a.topBid === null
          ? t('auction.void')
          : t('auction.lost');
    doc.append(el('p', 'doc-note', stamp));
  }
  doc.append(button('ghost', t('action.locate'), () => actions.locate(building)));
  return doc;
}

/** Application Objectifs : récompense du jour, objectifs, seigneurs des quartiers. */
export function renderQuests(
  screen: HTMLElement,
  state: GameState,
  city: City,
  actions: Actions,
  social: Social | null,
  nowMs: number,
): void {
  const items: HTMLElement[] = [];
  const daily = dailyStatus(state, nowMs);
  const gift = el('div', 'doc');
  gift.append(
    el('div', 'ref', t('daily.title')),
    row(t('daily.streak'), t('daily.streakValue', { count: daily.streak }), 'doc-value'),
  );
  if (daily.ready)
    gift.append(
      button('primary', t('daily.claim', { amount: formatDucats(daily.reward) }), () =>
        actions.claimDaily(),
      ),
    );
  else gift.append(el('p', 'doc-note', t('daily.done')));
  items.push(gift);

  items.push(el('h2', 'section-title', t('quest.section')));
  const quests = questList(state, city, worth(state, city));
  quests.sort((a, b) => Number(a.claimed) - Number(b.claimed) || Number(b.done) - Number(a.done));
  for (const q of quests) {
    const doc = el('div', `doc quest${q.claimed ? ' claimed' : q.done ? ' done' : ''}`);
    const big = q.goal >= 100_000;
    doc.append(
      el('b', 'quest-name', t(`quest.${q.id}` as MessageKey)),
      el(
        'p',
        'doc-note',
        `${big ? formatDucats(q.progress) : formatNumber(q.progress)} / ${big ? formatDucats(q.goal) : formatNumber(q.goal)} · ${t('quest.reward', { amount: formatDucats(q.reward) })}${q.title ? ` · ${t('quest.gainsTitle', { title: t(`title.${q.title}` as MessageKey) })}` : ''}`,
      ),
    );
    const meter = el('div', 'meter');
    const fill = el('i', '');
    fill.style.width = `${Math.round((q.progress / q.goal) * 100)}%`;
    meter.append(fill);
    doc.append(meter);
    if (q.done && !q.claimed)
      doc.append(button('primary', t('quest.claim'), () => actions.claimQuest(q.id)));
    if (q.claimed) doc.append(el('p', 'doc-note good', t('quest.claimed')));
    items.push(doc);
  }

  items.push(el('h2', 'section-title', t('lord.section')));
  const lords = el('div', 'doc');
  const list = social?.lords ?? [];
  if (list.length === 0) lords.append(el('p', 'doc-note', t('lord.none')));
  for (const lord of list)
    lords.append(
      row(
        t(`district.${lord.district}`),
        `${lord.me ? t('social.you') : lord.name} · ${t('lord.count', { count: lord.count })}`,
        `doc-value${lord.me ? ' good' : ''}`,
      ),
    );
  lords.append(el('p', 'doc-note', t('lord.note')));
  items.push(lords);
  screen.replaceChildren(...items);
}
