export const DEFAULT_MS_PER_DAY = 60_000;
export const VISIT_MS = 6000;
const MAX_CLIENTS = 8;
/** Annonces en cours : ce plafond règle aussi le rythme de la chasse (voir tests/pacing.test.ts). */
const MAX_LISTINGS = 120;
/** Part des annonces du jour réservée aux maisons (pavillons et villas). */
const HOUSE_SHARE = 0.5;
const isHouse = (b: Building): boolean => b.type === 'pavillon' || b.type === 'villa';
const MAX_LETTERS = 40;
const MAX_REPORTS = 7;
/** Jours de réputation gagnés par mission réussie : 150 missions pour la commission maximale. */
const REPUTATION_DAYS_PER_MISSION = 0.4;
/** Missions réussies nécessaires pour chaque étoile de chasseur. */
export const STAR_THRESHOLDS: readonly number[] = [6, 20, 45, 90, 150];
/**
 * Budget maximum des clients selon les étoiles : un débutant place des pavillons, pas des tours.
 * Les gros clients (investisseurs, entreprises) se méritent.
 */
export const CLIENT_BUDGET_CAPS: readonly number[] = [
  400_000,
  1_000_000,
  3_000_000,
  8_000_000,
  20_000_000,
  Infinity,
];

