/** Complète une sauvegarde plus ancienne avec les champs ajoutés depuis. */
export function withDefaults(state: GameState): GameState {
  return {
    ...state,
    player: migrateLoans(state.player),
    ledger: { ...EMPTY_LEDGER, ...(state.ledger ?? {}) },
    propertyStats: state.propertyStats ?? {},
    rivals: state.rivals ?? [],
    effects: state.effects ?? [],
    incidents: state.incidents ?? [],
    trials: state.trials ?? [],
    pressure: state.pressure ?? {},
    discounts: state.discounts ?? {},
    suspicion: state.suspicion ?? 0,
    cameras: state.cameras ?? [],
    nextIncidentId: state.nextIncidentId ?? 1,
    position: state.position ?? startPosition(),
    travel: state.travel ?? null,
    vehicles: state.vehicles ?? [],
    upkeep: state.upkeep ?? {},
    plots: state.plots ?? {},
    tenancy: state.tenancy ?? {},
    nextCandidateId: state.nextCandidateId ?? 1,
    // Lettres « Dossier clos » d'avant : retirées du courrier.
    letters: (state.letters ?? []).filter((l) => l.kind !== 'expired'),
    messages: (state.messages ?? []).filter((m) => state.player.day - m.day <= MESSAGE_KEEP_DAYS),
  };
}

/**
 * Jours restants avant que la banque saisisse un bien (0 = saisie à la fin de la journée),
 * ou null si le solde est positif ou qu'aucun bien financé ne peut être saisi.
 */
export function seizureCountdown(state: GameState): number | null {
  const overdue = state.player.overdueDays ?? 0;
  if (state.player.cash >= 0 || overdue === 0) return null;
  // La banque se paie sur les biens : sans bien, rien à saisir.
  if (state.player.properties.length === 0) return null;
  return Math.max(0, RULES.seizureGraceDays - overdue);
}

/** Jours de réputation correspondant aux missions réussies. */
export function reputationDays(state: GameState): number {
  return state.reputation * REPUTATION_DAYS_PER_MISSION;
}

export function currentDay(state: GameState): number {
  return state.player.day;
}

export function isOwned(state: GameState, buildingId: number): boolean {
  return state.player.properties.some((p) => p.id === String(buildingId));
}

export function isListed(state: GameState, buildingId: number): boolean {
  return state.listings.includes(buildingId);
}

export function isVisited(state: GameState, buildingId: number): boolean {
  return state.visited.includes(buildingId);
}

/** Statut affiché sur la carte. */
export function statusOf(state: GameState, buildingId: number): BuildingStatus {
  if (isOwned(state, buildingId)) {
    return activeEffect(state, buildingId, currentDay(state)) ? 'incident' : 'mine';
  }
  if (isListed(state, buildingId)) return 'sale';
  if (state.rivals.some((r) => r.buildings.includes(buildingId))) return 'rival';
  return 'none';
}

/**
 * Caractéristiques d'un bien. En ligne, elles viennent du serveur, qui ne révèle l'état et le
 * défaut qu'après une visite ; hors ligne, elles sont calculées à partir de la graine.
 */
/** Prix et loyer corrigés des événements de ville en cours dans le quartier. */
export function withEvents<F extends { fairValue: number; askingPrice: number; rent: number }>(
  base: F,
  building: Building,
  state: GameState,
  day: number,
): F {
  const effect = districtEffect(cityEvents(state, day), building.district, day);
  if (effect.price === 1 && effect.rent === 1) return base;
  const round = (v: number): number => Math.round(v / 1000) * 1000;
  return {
    ...base,
    fairValue: round(base.fairValue * effect.price),
    askingPrice: round(base.askingPrice * effect.price),
    rent: Math.round((base.rent * effect.rent) / 10) * 10,
  };
}

/** Valeur d'un bien possédé, corrigée des événements de son quartier. */
export function ownedValue(state: GameState, city: City, id: string, day: number): number {
  const property = state.player.properties.find((p) => p.id === id);
  if (!property) return 0;
  const value = propertyValue(property, day);
  const building = city.buildings[Number(id)];
  if (!building || plotIndexOf(id) !== null) return value;
  return value * districtEffect(cityEvents(state, day), building.district, day).price;
}

/** Valeur d'un bien possédé, d'après son bâtiment (même calcul que ownedValue). */
export function buildingValue(state: GameState, building: Building, day: number): number {
  const property = state.player.properties.find((p) => p.id === String(building.id));
  if (!property) return 0;
  return (
    propertyValue(property, day) *
    districtEffect(cityEvents(state, day), building.district, day).price
  );
}

/** Patrimoine net, événements de ville compris (krach, embellie, métro...). */
export function worth(state: GameState, city: City, day = currentDay(state)): number {
  let total = netWorth(state.player);
  for (const p of state.player.properties) {
    total += ownedValue(state, city, p.id, day) - propertyValue(p, day);
  }
  return total;
}

export function facts(state: GameState, building: Building) {
  const remote = state.remoteFacts?.[String(building.id)];
  if (remote) return remote;
  const day = currentDay(state);
  const base = withEvents(buildingFacts(building, state.seed, day), building, state, day);
  const discount = state.discounts[String(building.id)];
  if (!discount) return base;
  // Vente forcée : le concurrent sous pression brade son bien.
  return { ...base, askingPrice: Math.round((base.askingPrice * (1 - discount)) / 1000) * 1000 };
}

/** Vrai si la partie est jouée sur le serveur. */
export function isOnline(state: GameState): boolean {
  return state.remoteFacts !== undefined;
}

function withLetter(state: GameState, kind: LetterKind, params: Letter['params'] = {}): GameState {
  const letter: Letter = {
    id: state.nextLetterId,
    day: currentDay(state),
    kind,
    params,
    read: false,
  };
  const counters = state.counters ?? {};
  return {
    ...state,
    nextLetterId: state.nextLetterId + 1,
    letters: [letter, ...state.letters].slice(0, MAX_LETTERS),
    // Compteurs pour les objectifs : chaque lettre compte un événement de la partie.
    counters: { ...counters, [kind]: (counters[kind] ?? 0) + 1 },
  };
}

/** Prend des éléments répartis sur toute la liste (donc sur toute la ville), pas les premiers. */
function spread<T>(items: readonly T[], count: number): T[] {
  if (items.length <= count) return [...items];
  return Array.from({ length: count }, (_, i) => items[Math.floor((i * items.length) / count)]!);
}

function pick<T>(rng: Rng, items: readonly T[]): T {
  return items[Math.floor(rng() * items.length)]!;
}

/**
 * Crée une fiche client à la portée du chasseur : son budget ne dépasse pas le plafond de ses
 * étoiles. Six fois sur dix, la fiche correspond à un bien réellement à vendre.
 */
function makeClient(state: GameState, city: City, rng: Rng, id: number): Client {
  const day = currentDay(state);
  const cap = clientBudgetCap(state);
  const affordable = (b: Building): boolean => buildingFacts(b, state.seed, day).askingPrice <= cap;
  const listed = state.listings
    .map((bid) => city.buildings[bid])
    .filter((b): b is Building => b !== undefined && affordable(b));
  const pool = city.buildings.filter(affordable);
  // Aucun bien sous le plafond (cas extrême) : les moins chers de la ville, jamais n'importe lequel.
  const fallback = (): Building[] =>
    [...city.buildings].sort((a, b) => a.price - b.price).slice(0, 50);
  const anchor =
    listed.length > 0 && rng() < 0.6
      ? pick(rng, listed)
      : pick(rng, pool.length > 0 ? pool : fallback());
  const price = buildingFacts(anchor, state.seed, day).askingPrice;
  const districts: DistrictId[] = [anchor.district];
  const other = pick(rng, city.districts).id;
  if (other !== anchor.district && other !== 'zone1' && rng() < 0.5) districts.push(other);
  const title: Title = rng() < 0.5 ? 'mr' : 'mrs';
  return {
    id,
    title,
    surname: pick(rng, SURNAMES),
    type: anchor.type,
    districts,
    budget: Math.min(
      Math.round((price * (0.95 + rng() * 0.4)) / 1000) * 1000,
      Math.max(price, Math.floor((cap * 1.1) / 1000) * 1000),
    ),
    createdDay: day,
    deadlineDay: day + 1 + Math.floor(rng() * 3),
  };
}

function addClients(state: GameState, city: City, rng: Rng): GameState {
  const wanted = 3 + Math.floor(rng() * 3);
  const room = Math.max(0, MAX_CLIENTS - state.clients.length);
  let next = state;
  for (let i = 0; i < Math.min(wanted, room); i++) {
    const client = makeClient(next, city, rng, next.nextClientId);
    next = { ...next, clients: [...next.clients, client], nextClientId: next.nextClientId + 1 };
  }
  return next;
}

export function createGame(
  city: City,
  seed: number,
  nowMs: number,
  msPerDay: number = DEFAULT_MS_PER_DAY,
  /** Annonces de départ ; par défaut, celles prévues par la ville. */
  listings?: number[],
): GameState {
  const player = newPlayer();
  let state: GameState = {
    version: 1,
    seed,
    player,
    reputation: 0,
    clients: [],
    listings:
      listings ??
      spread(
        city.buildings.filter((b) => b.status === 'sale'),
        MAX_LISTINGS,
      ).map((b) => b.id),
    visited: [],
    visiting: null,
    letters: [],
    reports: [],
    nextClientId: 1,
    nextLetterId: 1,
    taxLetterSent: false,
    ledger: { ...EMPTY_LEDGER },
    propertyStats: {},
    rivals: [],
    effects: [],
    incidents: [],
    trials: [],
    pressure: {},
    discounts: {},
    suspicion: 0,
    cameras: [],
    nextIncidentId: 1,
    position: startPosition(),
    travel: null,
    vehicles: [],
    upkeep: {},
    plots: {},
    tenancy: {},
    nextCandidateId: 1,
    clock: { startMs: nowMs, msPerDay },
  };
  state = withLetter(seedRivals(state, city), 'welcome', { cash: player.cash });
  return addClients(state, city, createRng(seed));
}

/** Jour indiqué par l'horloge à un instant donné. */
export function clockDay(state: GameState, nowMs: number): number {
  return Math.max(0, Math.floor((nowMs - state.clock.startMs) / state.clock.msPerDay));
}

/** Loyers des biens possédés selon les événements de leur quartier. */
function eventRentModifiers(state: GameState, city: City, day: number): Record<string, number> {
  const events = cityEvents(state, day);
  const out: Record<string, number> = {};
  for (const p of state.player.properties) {
    const b = city.buildings[Number(p.id)];
    if (!b || plotIndexOf(p.id) !== null) continue;
    const rent = districtEffect(events, b.district, day).rent;
    if (rent !== 1) out[p.id] = rent;
  }
  return out;
}

/** Fait passer une journée : loyers, impôts, prêts, clients, annonces et courrier. */
export function nextDay(state: GameState, city: City): GameState {
  const refOf = (id: string): string => placeRef(city, id);
  const rentDay = state.player.day + 1;
  // Les causes se cumulent : coup bas, travaux, et bail (vide, impayé ou loyer négocié).
  const modifiers: Record<string, number> = {};
  for (const source of [
    rentModifiers(state, rentDay),
    worksRentModifiers(state, rentDay),
    tenancyRentModifiers(state, rentDay),
    eventRentModifiers(state, city, rentDay),
  ]) {
    for (const [id, factor] of Object.entries(source))
      modifiers[id] = (modifiers[id] ?? 1) * factor;
  }
  const step = advanceDay(state.player, { rentModifiers: modifiers });
  const propertyStats = { ...state.propertyStats };
  for (const p of state.player.properties) {
    const stats = propertyStats[p.id] ?? { paid: p.baseValue, rent: 0 };
    const earned = propertyRent(p, rentDay) * (modifiers[p.id] ?? 1);
    propertyStats[p.id] = { ...stats, rent: stats.rent + earned };
  }
  const r = step.report;
  let next: GameState = {
    ...state,
    player: step.state,
    propertyStats,
    ledger: {
      ...state.ledger,
      rent: state.ledger.rent + r.rent,
      charges: state.ledger.charges + r.charges,
      agency: state.ledger.agency + r.agency,
      taxes: state.ledger.taxes + r.incomeTax + r.wealthTax,
      loanPayments: state.ledger.loanPayments + r.loanPayments,
    },
    reports: [step.report, ...state.reports].slice(0, MAX_REPORTS),
  };
  // Agence de gestion choisie avant le 6e bien : 8 % des loyers en plus (ensuite, déjà comptés).
  if (state.agency && !agencyIncluded(state, RULES.agencyFromProperties) && r.rent > 0) {
    const fee = r.rent * AGENCY_RATE;
    next = {
      ...next,
      player: { ...next.player, cash: next.player.cash - fee },
      ledger: { ...next.ledger, agency: next.ledger.agency + fee },
    };
  }
  const day = step.state.day;
  const rng = createRng(state.seed + day * 7919);

  for (const id of step.report.loansRepaid)
    next = withLetter(next, 'loanRepaid', { ref: refOf(id) });
  for (const id of step.report.seized) next = withLetter(next, 'seized', { ref: refOf(id) });
  // Les biens saisis partent aux enchères.
  const seizedBuildings = step.report.seized
    .filter((id) => plotIndexOf(id) === null && city.buildings[Number(id)])
    .map((id) => ({ buildingId: Number(id), source: 'seized' as const }));
  if (seizedBuildings.length > 0)
    next = { ...next, auctionQueue: [...(next.auctionQueue ?? []), ...seizedBuildings] };
  // Relance de la banque : chaque jour de solde négatif, avant la saisie.
  const daysLeft = seizureCountdown(next);
  if (daysLeft !== null) {
    next = withLetter(next, 'overdue', {
      amount: -next.player.cash,
      days: daysLeft,
    });
  }
  const taxes = step.report.incomeTax + step.report.wealthTax;
  if (taxes > 0 && !next.taxLetterSent) {
    next = { ...withLetter(next, 'tax', { amount: taxes }), taxLetterSent: true };
  }

  // Les clients partis disparaissent sans lettre (retour du propriétaire : trop de courrier inutile).
  next = { ...next, clients: next.clients.filter((c) => c.deadlineDay >= day) };

  // Le marché bouge : de nouveaux biens sont mis en vente, les plus anciens trouvent preneur.
  const fresh: number[] = [];
  const arrivals = 4 + Math.floor(rng() * 4);
  const houses = city.buildings.filter(isHouse);
  for (let i = 0; i < arrivals * 6 && fresh.length < arrivals; i++) {
    const candidate = pick(rng, rng() < HOUSE_SHARE ? houses : city.buildings).id;
    if (
      !isOwned(next, candidate) &&
      !next.listings.includes(candidate) &&
      !fresh.includes(candidate)
    ) {
      fresh.push(candidate);
    }
  }
  const listings = [...next.listings, ...fresh];
  next = { ...next, listings: listings.slice(Math.max(0, listings.length - MAX_LISTINGS)) };

  const afterAdvance = next;
  next = dailyDirty(next, city, rng, (b) => facts(afterAdvance, b).rent, withLetter);
  next = dailyUpkeep(next, city, withLetter);
  next = dailyDevelopment(next, city, withLetter);
  next = dailyTenancy(next, rng, withLetter, refOf);
  return addClients(next, city, rng);
}

export function startVisit(state: GameState, buildingId: number, nowMs: number): GameState {
  if (state.visiting || isVisited(state, buildingId)) return state;
  return { ...state, visiting: { buildingId, readyAtMs: nowMs + VISIT_MS } };
}

/** Termine la visite en cours si son délai est écoulé. */
export function finishVisit(state: GameState, nowMs: number): GameState {
  if (!state.visiting || nowMs < state.visiting.readyAtMs) return state;
  return {
    ...state,
    visited: [...state.visited, state.visiting.buildingId],
    visiting: null,
  };
}

export interface Proposal {
  accepted: boolean;
  reason?: RefusalReason;
  /** Qualité de la proposition, de 0 à 1. */
  quality: number;
  /** Bonus de rapidité et de bien parfait, en part de la commission. */
  bonus: number;
  commission: number;
}

/** Évalue ce que répondrait un client si on lui proposait ce bien. */
export function evaluateProposal(state: GameState, client: Client, building: Building): Proposal {
  const f = facts(state, building);
  const refuse = (reason: RefusalReason): Proposal => ({
    accepted: false,
    reason,
    quality: 0,
    bonus: 0,
    commission: 0,
  });
  if (building.type !== client.type) return refuse('type');
  if (f.askingPrice > client.budget) return refuse('budget');
  if (f.defect === 'damp') return refuse('damp');

  const inDistrict = client.districts.includes(building.district);
  let quality = 1;
  if (!inDistrict) quality *= 0.75;
  if (f.defect === 'noisy') quality *= 0.7;
  if (f.defect === 'overpriced') quality *= 0.8;
  const perfect = inDistrict && f.defect === 'none';
  const fast = currentDay(state) === client.createdDay;
  const bonus = (perfect ? 0.3 : 0) + (fast ? 0.2 : 0);
  const base = saleCommission(f.askingPrice, reputationDays(state));
  return {
    accepted: true,
    quality,
    bonus,
    commission: Math.round((base * quality * (1 + bonus)) / 10) * 10,
  };
}

/** Propose un bien visité et à vendre à un client. */
export function propose(
  state: GameState,
  city: City,
  clientId: number,
  buildingId: number,
): { state: GameState; result: Proposal } {
  const client = state.clients.find((c) => c.id === clientId);
  const building = city.buildings[buildingId];
  if (!client || !building) throw new Error('Client ou bien introuvable');
  if (!isListed(state, buildingId)) throw new Error("Ce bien n'est pas à vendre");
  if (!isVisited(state, buildingId)) throw new Error("Ce bien n'a pas été visité");
  const result = evaluateProposal(state, client, building);
  const who = { title: client.title, surname: client.surname, ref: building.ref };
  if (!result.accepted) {
    return { state: withLetter(state, 'refusal', { ...who, reason: result.reason ?? '' }), result };
  }
  const paid: GameState = {
    ...state,
    player: addCash(state.player, result.commission),
    reputation: state.reputation + 1,
    ledger: { ...state.ledger, commissions: state.ledger.commissions + result.commission },
    clients: state.clients.filter((c) => c.id !== clientId),
    listings: state.listings.filter((id) => id !== buildingId),
    ...leaveRival(state, buildingId),
  };
  return { state: withLetter(paid, 'commission', { ...who, amount: result.commission }), result };
}

/** Un bien vendu quitte le patrimoine de son ancien propriétaire, et son rabais disparaît. */
function leaveRival(state: GameState, buildingId: number): Pick<GameState, 'rivals' | 'discounts'> {
  const discounts = { ...state.discounts };
  delete discounts[String(buildingId)];
  return {
    rivals: state.rivals.map((r) => ({
      ...r,
      buildings: r.buildings.filter((id) => id !== buildingId),
    })),
    discounts,
  };
}

export interface LoanOffer {
  price: number;
  downPayment: number;
  loan: Loan;
  /** « suspicion » : la banque refuse de prêter à un joueur trop surveillé par la police. */
  refusal: BuyRefusal | 'suspicion' | null;
}

/** Offre de prêt de la banque pour un bien à vendre. */
export function loanOffer(state: GameState, building: Building): LoanOffer {
  const f = facts(state, building);
  const terms = creditTerms(state.player.creditLevel);
  const offer = { id: String(building.id), price: f.askingPrice, rentRate: f.rent / f.askingPrice };
  return {
    price: f.askingPrice,
    downPayment: f.askingPrice * terms.downPaymentRate,
    loan: createLoan(f.askingPrice, terms),
    refusal: state.suspicion >= SUSPICION_LOAN_BLOCK ? 'suspicion' : canBuy(state.player, offer),
  };
}

/** Vrai si le joueur a de quoi payer ce bien comptant. */
export function canPayCash(state: GameState, building: Building): boolean {
  return state.player.cash >= facts(state, building).askingPrice;
}

/** Achète un bien à vendre, avec un prêt ou comptant. */
export function buy(state: GameState, city: City, buildingId: number, cash = false): GameState {
  const building = city.buildings[buildingId];
  if (!building || !isListed(state, buildingId)) throw new Error("Ce bien n'est pas à vendre");
  const f = facts(state, building);
  if (!cash && state.suspicion >= SUSPICION_LOAN_BLOCK) {
    throw new Error('Prêt refusé : joueur trop surveillé');
  }
  const next = takeOwnership(state, building, f.askingPrice, cash);
  return withLetter(next, cash ? 'purchaseCash' : 'purchase', { ref: building.ref });
}

/** Le joueur devient propriétaire du bâtiment, au prix donné (avec prêt ou comptant). */
function takeOwnership(
  state: GameState,
  building: Building,
  price: number,
  cash: boolean,
): GameState {
  const buildingId = building.id;
  const f = facts(state, building);
  const player = buyProperty(
    state.player,
    {
      id: String(buildingId),
      price,
      rentRate: f.rent / price,
      fairValue: f.fairValue,
    },
    undefined,
    undefined,
    cash,
  );
  const downPayment = state.player.cash - player.cash;
  const next: GameState = {
    ...state,
    player,
    ledger: { ...state.ledger, downPayments: state.ledger.downPayments + downPayment },
    propertyStats: {
      ...state.propertyStats,
      [String(buildingId)]: { paid: price, rent: 0 },
    },
    listings: state.listings.filter((id) => id !== buildingId),
    ...leaveRival(state, buildingId),
    // Le bien change de mains : les coups bas en cours s'arrêtent avec l'ancien propriétaire.
    effects: state.effects.filter((e) => e.buildingId !== buildingId),
    visited: isVisited(state, buildingId) ? state.visited : [...state.visited, buildingId],
    // Le bien acheté est vide : des candidats locataires se présentent dès le lendemain.
    tenancy: { ...state.tenancy, [String(buildingId)]: vacantTenancy() },
    // L'état du bien acheté est celui de l'annonce.
    upkeep: {
      ...state.upkeep,
      [String(buildingId)]: { condition: f.condition, since: state.player.day, works: null },
    },
  };
  return next;
}

/**
 * Bien perdu pour inactivité : il part aux enchères. La banque le reprend avec son prêt (le prêt
 * attaché disparaît), le joueur ne touche rien. Valeur par défaut, voir docs/QUESTIONS.md.
 */
export function forfeit(state: GameState, city: City, buildingId: number): GameState {
  const id = String(buildingId);
  const current = migrateLoans(state.player);
  const tenancy = { ...state.tenancy };
  delete tenancy[id];
  const next: GameState = {
    ...state,
    player: {
      ...current,
      properties: current.properties.filter((p) => p.id !== id),
      loans: (current.loans ?? []).filter((l) => l.propertyId !== id),
    },
    tenancy,
  };
  return withLetter(next, 'forfeited', { ref: placeRef(city, id) });
}

/** Enchère remportée : le joueur paie comptant, sinon la vente est annulée. */
export function winAuction(state: GameState, city: City, auction: Auction): GameState {
  const building = city.buildings[auction.buildingId];
  const price = auction.topBid ?? 0;
  if (!building || isOwned(state, building.id)) return state;
  if (state.player.cash < price)
    return withLetter(state, 'auctionVoid', { ref: building.ref, amount: price });
  const next = takeOwnership(state, building, price, true);
  return withLetter(next, 'auctionWon', { ref: building.ref, amount: price });
}

/**
 * Hors ligne, à chaque instant : la banque met des biens aux enchères chaque jour, les biens
 * saisis y partent aussi, et les enchères terminées se règlent.
 */
export function auctionTick(state: GameState, city: City, nowMs: number): GameState {
  let next = state;
  let auctions = state.auctions ?? [];
  let nextId = state.nextAuctionId ?? 1;
  let changed = false;
  const day = state.player.day;
  const busy = new Set(auctions.filter((a) => a.status === 'open').map((a) => a.buildingId));
  const rng = createRng(state.seed + day * 3301 + nextId);
  const open = (buildingId: number, source: AuctionSource, delayMs: number): void => {
    const building = city.buildings[buildingId];
    if (!building || busy.has(buildingId)) return;
    const value = facts(next, building).fairValue;
    const rival = state.rivals.length > 0 ? pick(rng, state.rivals) : null;
    busy.add(buildingId);
    auctions = [
      ...auctions,
      {
        id: nextId++,
        buildingId,
        source,
        startPrice: roundPrice(value * START_RATIO),
        topBid: null,
        topName: null,
        leading: false,
        bids: 0,
        endsAtMs: nowMs + AUCTION_MS + delayMs,
        status: 'open',
        rivalMax: roundPrice(value * (0.75 + rng() * 0.35)),
        rivalName: rival?.name ?? 'SCI Horizon',
      },
    ];
    changed = true;
  };
  for (const item of state.auctionQueue ?? []) open(item.buildingId, item.source, 0);
  if ((state.auctionQueue ?? []).length > 0) {
    next = { ...next, auctionQueue: [] };
    changed = true;
  }
  if ((state.auctionDay ?? -1) < day) {
    for (let i = 0; i < BANK_PER_DAY * 6 && busy.size < MAX_OPEN; i++) {
      if (auctions.filter((a) => a.status === 'open' && a.source === 'bank').length >= MAX_OPEN)
        break;
      const candidate = pick(rng, city.buildings).id;
      if (isOwned(next, candidate) || isListed(next, candidate) || rivalOf(next, candidate))
        continue;
      open(candidate, 'bank', i * 90_000);
      if (auctions.filter((a) => a.source === 'bank' && a.status === 'open').length >= BANK_PER_DAY)
        break;
    }
    next = { ...next, auctionDay: day };
    changed = true;
  }
  // Fin des enchères.
  const settled: Auction[] = [];
  for (const a of auctions) {
    if (a.status !== 'open' || nowMs < a.endsAtMs) {
      settled.push(a);
      continue;
    }
    changed = true;
    if (a.leading && a.bidder) {
      const before = next;
      next = winAuction(next, city, a);
      const won = isOwned(next, a.buildingId) && !isOwned(before, a.buildingId);
      settled.push({ ...a, status: won ? 'won' : 'void' });
    } else {
      if (a.bidder) {
        const building = city.buildings[a.buildingId];
        next = withLetter(next, 'auctionLost', {
          ref: building?.ref ?? '',
          amount: a.topBid ?? 0,
        });
      }
      settled.push({ ...a, status: a.topBid === null ? 'void' : 'lost' });
    }
  }
  const kept = settled.filter((a) => a.status === 'open' || nowMs - a.endsAtMs < SHOW_ENDED_MS);
  if (kept.length !== settled.length) changed = true;
  if (!changed) return state;
  return { ...next, auctions: kept, nextAuctionId: nextId };
}

/** Hors ligne : mise du joueur ; le concurrent répond aussitôt s'il le peut. */
export function bidLocal(
  state: GameState,
  auctionId: number,
  amount: number,
  nowMs: number,
): GameState {
  const auction = (state.auctions ?? []).find((a) => a.id === auctionId);
  const refusal = bidRefusal(state, auction, amount, nowMs);
  if (refusal) throw new Error(refusal);
  return {
    ...state,
    auctions: (state.auctions ?? []).map((a) =>
      a.id === auctionId ? placeLocalBid(a, Math.round(amount), nowMs) : a,
    ),
  };
}

export function sell(state: GameState, city: City, buildingId: number): GameState {
  const property = state.player.properties.find((p) => p.id === String(buildingId));
  const building = { ref: placeRef(city, buildingId) };
  if (!property) throw new Error('Bien introuvable');
  const day = currentDay(state);
  const amount = Math.round(ownedValue(state, city, property.id, day));
  const base = propertyValue(property, day);
  const sold = sellProperty(state.player, property.id);
  // Vente : la valeur du jour, événements du quartier compris.
  const player = { ...sold, cash: sold.cash + (amount - base) };
  const next = {
    ...state,
    player,
    ledger: { ...state.ledger, sales: state.ledger.sales + (player.cash - state.player.cash) },
  };
  return withLetter(next, 'sold', { ref: building.ref, amount });
}

export function repayEarly(state: GameState, city: City, buildingId: number): GameState {
  const building = city.buildings[buildingId];
  const next = { ...state, player: repayLoanEarly(state.player, String(buildingId)) };
  return withLetter(next, 'earlyRepaid', { ref: building?.ref ?? String(buildingId) });
}

/** Référence cadastrale d'un bâtiment de la ville ou d'un programme construit sur un terrain. */
export function placeRef(city: City, id: string | number): string {
  const plot = plotIndexOf(id);
  if (plot !== null) return city.plots[plot]?.ref ?? String(id);
  return city.buildings[Number(id)]?.ref ?? String(id);
}

/** Achète un terrain de la Zone 1. */
export function purchasePlot(state: GameState, city: City, index: number): GameState {
  return buyPlot(state, city, index, withLetter);
}

/** Lance un programme de construction sur un terrain possédé. */
export function build(state: GameState, city: City, index: number, kind: ProjectKind): GameState {
  return startProject(state, city, index, kind, withLetter);
}

/** Lance des travaux de rénovation sur un bien possédé. */
export function renovateProperty(state: GameState, city: City, buildingId: number): GameState {
  return renovate(state, city, buildingId, withLetter);
}

/** Répond à un candidat locataire d'un bien possédé. */
export function answerTenant(
  state: GameState,
  city: City,
  buildingId: number,
  candidateId: number,
  choice: TenantChoice,
): { state: GameState; accepted: boolean } {
  return answerCandidate(
    state,
    String(buildingId),
    candidateId,
    choice,
    withLetter,
    placeRef(city, String(buildingId)),
  );
}

/** Répond au souci signalé par le locataire d'un bien. */
export function answerTenantIssue(
  state: GameState,
  city: City,
  buildingId: number,
  choice: IssueChoice,
): GameState {
  return answerIssue(state, String(buildingId), choice, placeRef(city, String(buildingId)));
}

/** Poursuit en justice le locataire d'un bien qui ne paie pas son loyer. */
export function sue(
  state: GameState,
  city: City,
  buildingId: number,
  articles: readonly string[],
  evidence: readonly string[],
  lawyer: boolean,
): { state: GameState; won: boolean } {
  return sueTenant(
    state,
    String(buildingId),
    articles as Article[],
    evidence as Evidence[],
    lawyer,
    withLetter,
    placeRef(city, String(buildingId)),
    lawsuitFee(state, city, buildingId),
  );
}

/** Honoraires d'avocat pour un procès contre le locataire de ce bien. */
export function lawsuitFee(state: GameState, city: City, buildingId: number): number {
  const id = String(buildingId);
  const tenant = state.tenancy[id]?.tenant;
  const building = city.buildings[buildingId];
  const owed = lawsuitStatus(state, id).owed;
  if (!tenant || !building) return Math.round((owed * 0.4) / 100) * 100;
  return lawyerFee(owed, building.type, building.district, offeredRent(state, id, tenant.factor));
}

/** Commet un coup bas contre le bien d'un concurrent. */
export function dirty(
  state: GameState,
  city: City,
  buildingId: number,
  kind: DirtyKind,
): GameState {
  const building = city.buildings[buildingId];
  if (!building) throw new Error('Bien introuvable');
  return commitDirty(state, city, buildingId, kind, dirtyTarget(state, building), withLetter);
}

/** En ligne : coup bas contre le bien d'un autre joueur. */
export function dirtyOnPlayer(
  state: GameState,
  city: City,
  buildingId: number,
  kind: DirtyKind,
  ownerName: string,
): { state: GameState; attack: PlayerAttack } {
  const building = city.buildings[buildingId];
  if (!building) throw new Error('Bien introuvable');
  return commitDirtyOnPlayer(
    state,
    city,
    buildingId,
    kind,
    dirtyTarget(state, building),
    ownerName,
    withLetter,
  );
}

/** En ligne : la victime reçoit le coup bas d'un autre joueur. */
export function applyAttack(
  state: GameState,
  city: City,
  attack: PlayerAttack & { id: number; attacker: string },
): GameState {
  return receiveAttack(state, city, attack, withLetter);
}

function dirtyTarget(state: GameState, building: Building): DirtyTarget {
  const f = facts(state, building);
  return { rent: f.rent, value: f.askingPrice };
}

/** Ce que coûte un coup bas sur ce bien, ce qu'il fait perdre, et l'amende en cas de procès. */
export function dirtyQuote(
  state: GameState,
  building: Building,
  kind: DirtyKind,
  player = (state.othersOwned ?? []).includes(building.id),
) {
  const target = dirtyTarget(state, building);
  const cost = dirtyCost(kind, target);
  return {
    cost,
    damage: dirtyDamage(kind, target.rent),
    fine: dirtyFine(cost),
    risk: catchRisk(state, kind),
    refusal: canCommit(state, building.id, kind, target, player),
  };
}

/** Porte plainte après un coup bas subi. */
export function fileComplaint(state: GameState, city: City, incidentId: number): GameState {
  return complain(state, city, incidentId, withLetter);
}

/** Installe des caméras sur un bien du joueur. */
export function addCamera(state: GameState, buildingId: number): GameState {
  return installCamera(state, buildingId);
}

export function markLettersRead(state: GameState): GameState {
  if (state.letters.every((l) => l.read)) return state;
  return { ...state, letters: state.letters.map((l) => ({ ...l, read: true })) };
}

export function unreadLetters(state: GameState): number {
  return state.letters.filter((l) => !l.read).length;
}

/** Étoiles de chasseur, de 0 à 5. */
export function reputationStars(state: GameState): number {
  return STAR_THRESHOLDS.filter((needed) => state.reputation >= needed).length;
}

/**
 * Budget maximum des clients que le chasseur attire aujourd'hui. Les plafonds sont ceux du jour 1 :
 * ils suivent la hausse des prix (+0,15 % par jour), sinon plus aucun bien n'y tiendrait.
 */
export function clientBudgetCap(state: GameState): number {
  const base = CLIENT_BUDGET_CAPS[reputationStars(state)] ?? Infinity;
  return base === Infinity
    ? base
    : Math.round((base * growth(currentDay(state), RULES)) / 1000) * 1000;
}

/** Missions qu'il reste à réussir avant la prochaine étoile, ou rien au maximum. */
export function missionsToNextStar(state: GameState): number | null {
  const next = STAR_THRESHOLDS[reputationStars(state)];
  return next === undefined ? null : next - state.reputation;
}
