import * as THREE from 'three';

const BALL = new THREE.IcosahedronGeometry(1, 1).toNonIndexed();

/** Accumule des rectangles et des pavés colorés dans une seule géométrie (un seul appel de dessin). */
export class Batch {
  private readonly positions: number[] = [];
  private readonly colors: number[] = [];
  private readonly color = new THREE.Color();

  get isEmpty(): boolean {
    return this.positions.length === 0;
  }

  /** Quadrilatère quelconque, sommets donnés dans l'ordre du contour. */
  freeQuad(
    a: [number, number, number],
    b: [number, number, number],
    c: [number, number, number],
    d: [number, number, number],
    hex: number,
  ): void {
    this.positions.push(...a, ...b, ...c, ...a, ...c, ...d);
    this.color.setHex(hex);
    for (let i = 0; i < 6; i++) this.colors.push(this.color.r, this.color.g, this.color.b);
  }

  /** Disque horizontal à la hauteur y. */
  disc(cx: number, cz: number, r: number, y: number, hex: number, segments = 20): void {
    this.color.setHex(hex);
    for (let i = 0; i < segments; i++) {
      const a = (i / segments) * Math.PI * 2;
      const b = ((i + 1) / segments) * Math.PI * 2;
      this.positions.push(
        cx,
        y,
        cz,
        cx + Math.cos(b) * r,
        y,
        cz + Math.sin(b) * r,
        cx + Math.cos(a) * r,
        y,
        cz + Math.sin(a) * r,
      );
      for (let k = 0; k < 3; k++) this.colors.push(this.color.r, this.color.g, this.color.b);
    }
  }

  /** Cylindre vertical (réservoir, poteau), posé en y0. */
  cylinder(
    cx: number,
    y0: number,
    cz: number,
    r: number,
    h: number,
    hex: number,
    segments = 10,
  ): void {
    for (let i = 0; i < segments; i++) {
      const a = (i / segments) * Math.PI * 2;
      const b = ((i + 1) / segments) * Math.PI * 2;
      const ax = cx + Math.cos(a) * r;
      const az = cz + Math.sin(a) * r;
      const bx = cx + Math.cos(b) * r;
      const bz = cz + Math.sin(b) * r;
      this.freeQuad([ax, y0, az], [bx, y0, bz], [bx, y0 + h, bz], [ax, y0 + h, az], hex);
    }
    this.disc(cx, cz, r, y0 + h, hex, segments);
  }

  /** Cône (chapeau de réservoir), base en y0. */
  cone(cx: number, y0: number, cz: number, r: number, h: number, hex: number, segments = 12): void {
    for (let i = 0; i < segments; i++) {
      const a = (i / segments) * Math.PI * 2;
      const b = ((i + 1) / segments) * Math.PI * 2;
      this.freeQuad(
        [cx + Math.cos(a) * r, y0, cz + Math.sin(a) * r],
        [cx + Math.cos(b) * r, y0, cz + Math.sin(b) * r],
        [cx, y0 + h, cz],
        [cx, y0 + h, cz],
        hex,
      );
    }
  }

  /** Boule à facettes (buisson, houppier) : icosaèdre subdivisé une fois. */
  ball(cx: number, cy: number, cz: number, r: number, hex: number, squash = 1): void {
    const g = BALL.getAttribute('position');
    this.color.setHex(hex);
    for (let i = 0; i < g.count; i++) {
      this.positions.push(cx + g.getX(i) * r, cy + g.getY(i) * r * squash, cz + g.getZ(i) * r);
      this.colors.push(this.color.r, this.color.g, this.color.b);
    }
  }

  /** Rectangle horizontal à la hauteur y, face vers le haut. */
  floor(x0: number, z0: number, x1: number, z1: number, y: number, hex: number): void {
    this.freeQuad([x0, y, z0], [x0, y, z1], [x1, y, z1], [x1, y, z0], hex);
  }

  /** Rectangle vertical dans un plan z constant. */
  wallAlongX(x0: number, x1: number, z: number, y0: number, y1: number, hex: number): void {
    this.freeQuad([x0, y0, z], [x1, y0, z], [x1, y1, z], [x0, y1, z], hex);
  }

  /** Rectangle vertical dans un plan x constant. */
  wallAlongZ(z0: number, z1: number, x: number, y0: number, y1: number, hex: number): void {
    this.freeQuad([x, y0, z0], [x, y0, z1], [x, y1, z1], [x, y1, z0], hex);
  }

  /** Pavé plein, défini par son centre au sol. */
  box(cx: number, y0: number, cz: number, w: number, h: number, d: number, hex: number): void {
    const x0 = cx - w / 2;
    const x1 = cx + w / 2;
    const z0 = cz - d / 2;
    const z1 = cz + d / 2;
    const y1 = y0 + h;
    // Pas de face du dessous : la caméra est toujours au-dessus de la ville.
    this.floor(x0, z0, x1, z1, y1, hex);
    this.wallAlongX(x0, x1, z0, y0, y1, hex);
    this.wallAlongX(x0, x1, z1, y0, y1, hex);
    this.wallAlongZ(z0, z1, x0, y0, y1, hex);
    this.wallAlongZ(z0, z1, x1, y0, y1, hex);
  }

  toGeometry(): THREE.BufferGeometry {
    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute('position', new THREE.Float32BufferAttribute(this.positions, 3));
    geometry.setAttribute('color', new THREE.Float32BufferAttribute(this.colors, 3));
    return geometry;
  }

  toMesh(material: THREE.Material): THREE.Mesh {
    return new THREE.Mesh(this.toGeometry(), material);
  }
}
