import type { Prop } from '../model';
import { worldX, worldZ } from './layout';

/** Les deux lignes de métro du plan de référence. Le métro est souterrain : la carte le dessine. */
export interface MetroLine {
  id: 'red' | 'blue';
  color: number;
  /** Tracé de la ligne (points du plan de référence). */
  path: Prop[];
  stations: Prop[];
}

const plan = (x: number, y: number): Prop => ({ x: worldX(x), z: worldZ(y) });

/** Stations du plan de référence ; d'autres sont ajoutées le long des lignes. Correspondance au centre. */
export const METRO_LINES: readonly MetroLine[] = [
  {
    id: 'red',
    color: 0xe23b3b,
    path: [
      plan(110, 300),
      plan(280, 300),
      plan(280, 270),
      plan(470, 270),
      plan(470, 300),
      plan(660, 300),
      plan(660, 250),
      plan(800, 250),
    ],
    stations: [plan(110, 300), plan(280, 270), plan(470, 300), plan(660, 300), plan(800, 250)],
  },
  {
    id: 'blue',
    color: 0x2f66d8,
    path: [
      plan(600, 120),
      plan(600, 230),
      plan(470, 230),
      plan(470, 430),
      plan(270, 430),
      plan(270, 470),
    ],
    stations: [plan(600, 120), plan(470, 300), plan(470, 430), plan(270, 470)],
  },
];

/** Écart visé entre deux stations, en unités (environ 700 m). */
const STATION_SPACING = 70;

/** Ajoute des stations régulières le long d'une ligne, entre celles du plan. */
function withIntermediateStations(line: MetroLine): Prop[] {
  const stations = [...line.stations];
  const far = (p: Prop): boolean =>
    stations.every((s) => Math.abs(s.x - p.x) + Math.abs(s.z - p.z) > STATION_SPACING * 0.6);
  for (let i = 0; i < line.path.length - 1; i++) {
    const a = line.path[i]!;
    const b = line.path[i + 1]!;
    const length = Math.abs(b.x - a.x) + Math.abs(b.z - a.z);
    const count = Math.floor(length / STATION_SPACING);
    for (let k = 1; k <= count; k++) {
      const t = k / (count + 1);
      const p = { x: a.x + (b.x - a.x) * t, z: a.z + (b.z - a.z) * t };
      if (far(p)) stations.push(p);
    }
  }
  return stations;
}

/** Toutes les stations, sans doublon (la correspondance compte une fois). */
export const METRO_STATIONS: readonly Prop[] = METRO_LINES.flatMap(withIntermediateStations).filter(
  (s, i, all) => all.findIndex((o) => o.x === s.x && o.z === s.z) === i,
);
