import type { GameState } from '../game/types';
import { formatDucats, formatNumber, getLang, LANGS, t, type Lang } from '../i18n';
import { button, el, row } from './dom';

/** Partie déjà commencée : on propose de la reprendre plutôt que d'en ouvrir une. */
export function hasProgress(state: GameState): boolean {
  return (
    state.player.day > 0 ||
    state.player.properties.length > 0 ||
    state.ledger.commissions > 0 ||
    state.visited.length > 0
  );
}

/** Joueurs prévus par ville (CLAUDE.md : environ 5 000). */
const CITY_PLACES = 5000;

export interface HomeOptions {
  online: boolean;
  buildings: number;
  setLang: (lang: Lang) => void;
  themeLabel: string;
  nextTheme: () => void;
  enter: () => void;
}

/**
 * Page d'accueil : la ville tourne en fond, et le jeu se présente comme un acte de la mairie.
 * Elle s'affiche à chaque lancement ; on entre en ville d'une touche.
 */
export function renderHome(home: HTMLElement, state: GameState, options: HomeOptions): void {
  const resume = hasProgress(state);

  const top = el('div', 'home-top');
  const langs = el('div', 'toggle');
  langs.setAttribute('role', 'group');
  langs.setAttribute('aria-label', t('settings.language'));
  for (const lang of LANGS) {
    const b = button('chip', lang.toUpperCase(), () => options.setLang(lang));
    b.setAttribute('aria-pressed', String(lang === getLang()));
    langs.append(b);
  }
  const theme = button('chip theme-btn', options.themeLabel, options.nextTheme);
  theme.setAttribute('aria-label', `${t('settings.theme')} : ${options.themeLabel}`);
  const settings = el('div', 'settings');
  settings.append(langs, theme);
  top.append(el('span', 'ref', t('home.cityRef')), settings);

  const sheet = el('section', 'home-sheet');
  const office = el('div', 'ref', t('home.office'));
  const title = el('h1', 'home-title', t('app.name'));
  const kind = el('div', 'home-kind', t('home.kind'));
  const tagline = el(
    'p',
    'home-tagline',
    t('home.tagline', { count: formatNumber(options.buildings) }),
  );

  const facts = el('div', 'doc');
  if (resume) {
    facts.append(
      row(t('home.file'), t('home.dayValue', { day: state.player.day }), 'doc-value'),
      row(t('wallet.balance'), formatDucats(state.player.cash), 'doc-value'),
      row(t('bank.properties'), formatNumber(state.player.properties.length), 'doc-value'),
    );
  } else {
    facts.append(
      row(t('home.startCash'), formatDucats(state.player.cash), 'doc-value'),
      row(t('home.immunity'), t('home.immunityValue'), 'doc-value'),
      row(t('home.places'), formatNumber(CITY_PLACES), 'doc-value'),
    );
  }

  const enter = button('primary home-enter', t(resume ? 'home.resume' : 'home.start'), () =>
    options.enter(),
  );
  const foot = el('div', 'ref home-foot', t(options.online ? 'home.online' : 'home.offline'));

  sheet.append(office, title, kind, tagline, facts, enter, foot);
  home.replaceChildren(top, sheet);
}
