import * as THREE from 'three';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
import type { Building, BuildingPart, Car, City, Prop, RoadStrip, Tree } from '../model';
import { Batch } from './batch';
import { carGeometry } from './traffic';
import { isBrick, lookOf } from './facadeMaterial';
import type { CityPalette } from './palette';

/** Côté d'une tuile de détail, en unités. */
export const TILE_SIZE = 16;
const MAX_VISIBLE_TILES = 16;
const MAX_CACHED_TILES = 28;
const MAX_BUILDS_PER_UPDATE = 2;

interface TileContent {
  buildings: Building[];
  trees: Tree[];
  lamps: Prop[];
  cars: Car[];
}

interface LoadedTile {
  group: THREE.Group;
  lastUsed: number;
}

function tileKey(tx: number, tz: number): string {
  return `${tx}:${tz}`;
}

function tileOf(v: number): number {
  return Math.floor(v / TILE_SIZE);
}

/** Petit hachage déterministe en [0, 1[ pour varier les détails sans générateur aléatoire. */
function hash(a: number, b: number, c = 0): number {
  let h = (a * 374761393 + b * 668265263 + c * 2147483647) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}

function colored(geometry: THREE.BufferGeometry, hex: number): THREE.BufferGeometry {
  const g = geometry.index ? geometry.toNonIndexed() : geometry;
  const c = new THREE.Color(hex);
  const count = g.getAttribute('position').count;
  const colors = new Float32Array(count * 3);
  for (let i = 0; i < count; i++) colors.set([c.r, c.g, c.b], i * 3);
  g.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  g.deleteAttribute('uv');
  return g;
}

/** Arbre touffu du rendu réaliste : houppier en quatre masses irrégulières, deux verts. */
function lushTree(palette: CityPalette): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [];
  const trunk = new THREE.CylinderGeometry(0.03, 0.045, 0.34, 6);
  trunk.translate(0, 0.17, 0);
  parts.push(colored(trunk, palette.trunk));
  const dark = new THREE.Color(palette.tree).multiplyScalar(0.72).getHex();
  const masses: [number, number, number, number, number][] = [
    [0, 0.6, 0, 0.3, palette.tree],
    [0.14, 0.5, 0.06, 0.2, dark],
    [-0.13, 0.52, -0.08, 0.21, palette.tree],
    [0.02, 0.76, 0.08, 0.18, dark],
  ];
  masses.forEach(([x, y, z, r, hex], i) => {
    const g = new THREE.IcosahedronGeometry(r, 1);
    // Relief irrégulier : chaque sommet est poussé ou rentré un peu.
    const pos = g.getAttribute('position');
    for (let v = 0; v < pos.count; v++) {
      const k = 1 + (hash(v, i, 3) - 0.5) * 0.28;
      pos.setXYZ(v, pos.getX(v) * k, pos.getY(v) * k, pos.getZ(v) * k);
    }
    g.computeVertexNormals();
    g.translate(x, y, z);
    parts.push(colored(g, hex));
  });
  return mergeGeometries(parts);
}

/**
 * Détails du niveau « Rue » : fenêtres, portes, devantures, balcons, marquages au sol,
 * arbres, lampadaires et voitures. Construits par tuile, à la demande, autour de la caméra.
 */
export class StreetDetails {
  readonly group = new THREE.Group();
  private readonly index = new Map<string, TileContent>();
  private readonly loaded = new Map<string, LoadedTile>();
  private readonly flatMaterial: THREE.MeshBasicMaterial;
  private readonly litMaterial: THREE.MeshLambertMaterial;
  private readonly treeGeometry: THREE.BufferGeometry;
  private readonly lampGeometry: THREE.BufferGeometry;
  private readonly carGeometry: THREE.BufferGeometry;
  private tick = 0;

  constructor(
    private readonly city: City,
    private readonly palette: CityPalette,
    /** En graphismes haut, portes, vitrines et ferronneries viennent des pièces modélisées. */
    private readonly facades = true,
  ) {
    this.flatMaterial = new THREE.MeshBasicMaterial({
      vertexColors: true,
      side: THREE.DoubleSide,
      transparent: true,
    });
    this.litMaterial = new THREE.MeshLambertMaterial({ vertexColors: true, transparent: true });

    // Rendu coloré : houppier rond et lisse, plus gros ; sinon facettes discrètes.
    const toon = palette.style === 'toon';
    const canopy = new THREE.IcosahedronGeometry(toon ? 0.36 : 0.3, toon ? 1 : 0);
    canopy.scale(1, toon ? 1.1 : 1.25, 1);
    canopy.translate(0, toon ? 0.56 : 0.52, 0);
    if (toon) canopy.computeVertexNormals();
    const trunk = new THREE.CylinderGeometry(0.035, 0.045, 0.3, 5);
    trunk.translate(0, 0.15, 0);
    this.treeGeometry = palette.lush
      ? lushTree(palette)
      : mergeGeometries([colored(canopy, palette.tree), colored(trunk, palette.trunk)]);

    const pole = new THREE.BoxGeometry(0.03, 0.5, 0.03);
    pole.translate(0, 0.25, 0);
    const head = new THREE.BoxGeometry(0.12, 0.03, 0.05);
    head.translate(0.045, 0.5, 0);
    this.lampGeometry = mergeGeometries([colored(pole, palette.lamp), colored(head, palette.lamp)]);

    // Voiture profilée, la même que celles qui roulent (voir traffic.ts).
    this.carGeometry = carGeometry(palette);

    const content = (x: number, z: number): TileContent => {
      const key = tileKey(tileOf(x), tileOf(z));
      let entry = this.index.get(key);
      if (!entry) {
        entry = { buildings: [], trees: [], lamps: [], cars: [] };
        this.index.set(key, entry);
      }
      return entry;
    };
    city.buildings.forEach((b) => content(b.x, b.z).buildings.push(b));
    city.trees.forEach((t) => content(t.x, t.z).trees.push(t));
    city.lamps.forEach((l) => content(l.x, l.z).lamps.push(l));
    city.cars.forEach((c) => content(c.x, c.z).cars.push(c));
  }

  get loadedTileCount(): number {
    let visible = 0;
    this.loaded.forEach((tile) => {
      if (tile.group.visible) visible++;
    });
    return visible;
  }

  /** Charge les tuiles proches du point visé et règle l'opacité des détails. */
  update(targetX: number, targetZ: number, radius: number, alpha: number): void {
    this.tick++;
    this.group.visible = alpha > 0.02;
    this.flatMaterial.opacity = alpha;
    this.litMaterial.opacity = alpha;
    if (!this.group.visible) return;

    const wanted: { key: string; tx: number; tz: number; distance: number }[] = [];
    const reach = Math.ceil(radius / TILE_SIZE);
    const cx = tileOf(targetX);
    const cz = tileOf(targetZ);
    for (let tx = cx - reach; tx <= cx + reach; tx++) {
      for (let tz = cz - reach; tz <= cz + reach; tz++) {
        const distance = Math.hypot(
          (tx + 0.5) * TILE_SIZE - targetX,
          (tz + 0.5) * TILE_SIZE - targetZ,
        );
        if (distance <= radius + TILE_SIZE * 0.5) {
          wanted.push({ key: tileKey(tx, tz), tx, tz, distance });
        }
      }
    }
    wanted.sort((a, b) => a.distance - b.distance);
    const keep = new Set(wanted.slice(0, MAX_VISIBLE_TILES).map((w) => w.key));

    let built = 0;
    for (const w of wanted.slice(0, MAX_VISIBLE_TILES)) {
      let tile = this.loaded.get(w.key);
      if (!tile && built < MAX_BUILDS_PER_UPDATE) {
        tile = { group: this.buildTile(w.tx, w.tz), lastUsed: this.tick };
        this.loaded.set(w.key, tile);
        this.group.add(tile.group);
        built++;
      }
      if (tile) tile.lastUsed = this.tick;
    }
    this.loaded.forEach((tile, key) => (tile.group.visible = keep.has(key)));

    if (this.loaded.size > MAX_CACHED_TILES) {
      const oldest = [...this.loaded.entries()].sort((a, b) => a[1].lastUsed - b[1].lastUsed);
      for (const [key, tile] of oldest.slice(0, this.loaded.size - MAX_CACHED_TILES)) {
        this.disposeTile(tile);
        this.loaded.delete(key);
      }
    }
  }

  dispose(): void {
    this.loaded.forEach((tile) => this.disposeTile(tile));
    this.loaded.clear();
    this.flatMaterial.dispose();
    this.litMaterial.dispose();
    this.treeGeometry.dispose();
    this.lampGeometry.dispose();
    this.carGeometry.dispose();
  }

  private disposeTile(tile: LoadedTile): void {
    this.group.remove(tile.group);
    tile.group.traverse((object) => {
      if (object instanceof THREE.Mesh) {
        const shared =
          object.geometry === this.treeGeometry ||
          object.geometry === this.lampGeometry ||
          object.geometry === this.carGeometry;
        if (!shared) object.geometry.dispose();
        if (object instanceof THREE.InstancedMesh) object.dispose();
      }
    });
  }

  private buildTile(tx: number, tz: number): THREE.Group {
    const group = new THREE.Group();
    const content = this.index.get(tileKey(tx, tz));
    const facades = new Batch();
    if (content && this.facades) for (const b of content.buildings) this.addFacades(facades, b);
    this.addMarkings(facades, tx, tz);
    if (!facades.isEmpty) group.add(facades.toMesh(this.flatMaterial));
    if (!content) return group;

    const matrix = new THREE.Matrix4();
    const color = new THREE.Color();
    if (content.trees.length > 0) {
      const mesh = new THREE.InstancedMesh(
        this.treeGeometry,
        this.litMaterial,
        content.trees.length,
      );
      content.trees.forEach((t, i) => {
        matrix.makeScale(t.size, t.size, t.size);
        matrix.setPosition(t.x, 0.05, t.z);
        mesh.setMatrixAt(i, matrix);
      });
      group.add(mesh);
    }
    if (content.lamps.length > 0) {
      const mesh = new THREE.InstancedMesh(
        this.lampGeometry,
        this.litMaterial,
        content.lamps.length,
      );
      content.lamps.forEach((l, i) => {
        matrix.makeTranslation(l.x, 0.03, l.z);
        mesh.setMatrixAt(i, matrix);
      });
      group.add(mesh);
    }
    // Rendu réaliste : une voiture garée sur deux, comme sur le modèle.
    const cars = this.palette.lush
      ? content.cars.filter((c) => hash(Math.round(c.x * 100), Math.round(c.z * 100), 11) < 0.5)
      : content.cars;
    if (cars.length > 0) {
      const mesh = new THREE.InstancedMesh(this.carGeometry, this.litMaterial, cars.length);
      const scale = new THREE.Matrix4();
      cars.forEach((c, i) => {
        // Berlines, camionnettes et quelques camions : la rue n'est pas un parking de modèles réduits.
        const kind = hash(Math.round(c.x * 100), Math.round(c.z * 100), 5);
        const [len, high] = kind > 0.93 ? [1.7, 1.7] : kind > 0.8 ? [1.2, 1.35] : [1, 1];
        if (c.alongX) matrix.identity();
        else matrix.makeRotationY(Math.PI / 2);
        matrix.multiply(scale.makeScale(len, high, 1));
        matrix.setPosition(c.x, 0.01, c.z);
        mesh.setMatrixAt(i, matrix);
        mesh.setColorAt(i, color.setHex(this.palette.cars[c.tint % this.palette.cars.length]!));
      });
      if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
      group.add(mesh);
    }
    return group;
  }

  /** Fenêtres, portes, devantures et balcons d'un bâtiment. */
  private addFacades(batch: Batch, b: Building): void {
    const p = this.palette;
    const floorH = b.h / b.floors;
    const glassFor = (seed: number): number => (hash(b.id, seed) < p.litRatio ? p.lit : p.glass);

    b.parts.forEach((part, partIndex) => {
      const floors = Math.max(1, Math.round(part.h / floorH));
      const firstFloor = Math.round(part.y0 / floorH);
      for (let side = 0; side < 4; side++) {
        const alongX = side < 2;
        const length = alongX ? part.w : part.d;
        const sign = side % 2 === 0 ? -1 : 1;
        const offset = (alongX ? part.d : part.w) / 2 + 0.012;
        const plane = (alongX ? part.z : part.x) + sign * offset;
        const centre = alongX ? part.x : part.z;
        const isFront =
          alongX && ((b.facing === 'north' && sign < 0) || (b.facing === 'south' && sign > 0));
        const put = (a0: number, a1: number, y0: number, y1: number, hex: number): void => {
          if (alongX) batch.wallAlongX(a0, a1, plane, y0, y1, hex);
          else batch.wallAlongZ(a0, a1, plane, y0, y1, hex);
        };

        if (b.type === 'entrepot') {
          if (isFront) {
            const doors = Math.max(1, Math.floor(length / 2.2));
            for (let i = 0; i < doors; i++) {
              const c = centre - length / 2 + ((i + 0.5) * length) / doors;
              put(c - 0.4, c + 0.4, 0, Math.min(0.55, part.h * 0.6), p.door);
            }
          }
          continue;
        }

        // Les fenêtres sont dans la texture des tours, ou dessinées par le shader des façades.
        if (b.type === 'tour') continue;

        const small = b.type === 'pavillon' || b.type === 'villa';
        const usable = length - 0.2;
        const columns = Math.max(1, Math.min(small ? 3 : 40, Math.floor(usable / 0.4)));
        const pitch = usable / columns;
        const doorColumn = Math.floor(columns / 2);
        for (let f = 0; f < floors; f++) {
          const level = firstFloor + f;
          const base = part.y0 + f * floorH;
          const ground = level === 0;
          if (ground && isFront && b.shop) {
            put(centre - usable / 2, centre + usable / 2, 0.04, floorH * 0.66, glassFor(900));
            const awning = p.awnings[Math.floor(hash(b.id, 7) * p.awnings.length)] ?? p.awnings[0]!;
            const outward = plane + sign * 0.07;
            batch.box(centre, floorH * 0.7, outward, usable, 0.04, 0.16, awning);
            // Enseigne muette au-dessus de l'auvent.
            batch.box(
              centre,
              floorH * 0.76,
              plane + sign * 0.02,
              usable * 0.55,
              0.11,
              0.03,
              p.iron,
            );
            continue;
          }
          if (ground && isFront) {
            const x = centre - usable / 2 + (doorColumn + 0.5) * pitch;
            put(x - 0.08, x + 0.08, 0, floorH * 0.72, p.door);
          }
          if (
            isFront &&
            !ground &&
            (b.type === 'hotel' || (b.type === 'immeuble' && f % 2 === 1))
          ) {
            batch.box(
              centre,
              base + floorH * 0.22,
              plane + sign * 0.05,
              usable,
              0.025,
              0.1,
              p.sidewalk,
            );
          }
        }
      }
      if (b.type === 'tour' && partIndex === b.parts.length - 1) {
        this.addRoofUnit(batch, part);
      }
    });

    if (b.type === 'immeuble' && b.floors >= 3) this.addIronwork(batch, b);

    if (b.type === 'villa' && hash(b.id, 3) < 0.45) {
      const z = b.facing === 'north' ? b.z + b.d / 2 + 0.55 : b.z - b.d / 2 - 0.55;
      batch.floor(b.x - 0.45, z - 0.22, b.x + 0.45, z + 0.22, 0.07, p.water);
    }
    if (b.type === 'motel') {
      const z = b.facing === 'north' ? b.z - b.d / 2 - 0.6 : b.z + b.d / 2 + 0.6;
      for (let x = b.x - b.w / 2 + 0.2; x < b.x + b.w / 2 - 0.1; x += 0.32) {
        batch.floor(x, z - 0.28, x + 0.03, z + 0.28, 0.065, p.marking);
      }
    }
  }

  /**
   * Climatiseurs sous certaines fenêtres et escalier de secours sur les façades de brique.
   * Les fenêtres suivent la même grille que le shader des façades.
   */
  private addIronwork(batch: Batch, b: Building): void {
    const p = this.palette;
    const floorH = b.h / b.floors;
    const s = b.facing === 'north' ? -1 : 1;
    const frontZ = b.z + (s * b.d) / 2;
    const margin = 0.06;
    const usable = b.w - 2 * margin;
    const cols = Math.max(1, Math.floor(usable / 0.42));
    const pitch = usable / cols;
    const colX = (c: number): number => b.x - b.w / 2 + margin + (c + 0.5) * pitch;
    for (let f = 1; f < b.floors; f++) {
      for (let c = 0; c < cols; c++) {
        if (hash(b.id, f * 50 + c, 9) < 0.14) {
          batch.box(
            colX(c),
            f * floorH + floorH * 0.18,
            frontZ + s * 0.05,
            0.15,
            0.09,
            0.1,
            p.quay,
          );
        }
      }
    }
    const look = lookOf(b);
    const brick = isBrick(look.wall);
    if (!brick || cols < 3 || hash(b.id, 77) > 0.7) return;
    const first = Math.floor(hash(b.id, 78) * (cols - 1));
    const ex = (colX(first) + colX(first + 1)) / 2;
    const span = pitch * 1.9;
    const zIn = frontZ + s * 0.02;
    const zOut = frontZ + s * 0.25;
    for (let f = 1; f < b.floors; f++) {
      const y = f * floorH;
      batch.box(ex, y, (zIn + zOut) / 2, span, 0.02, 0.23, p.iron);
      batch.box(ex, y + 0.02, zOut, span, 0.1, 0.012, p.iron);
      if (f < b.floors - 1) {
        // Échelle en biais d'une plateforme à l'autre, dans un sens puis dans l'autre.
        const dir = f % 2 === 0 ? 1 : -1;
        const x0 = ex - dir * span * 0.38;
        const x1 = ex + dir * span * 0.38;
        const za = frontZ + s * 0.08;
        const zb = frontZ + s * 0.18;
        batch.freeQuad(
          [x0, y + 0.02, za],
          [x1, y + floorH, za],
          [x1, y + floorH, zb],
          [x0, y + 0.02, zb],
          p.iron,
        );
      }
    }
  }

  /** Local technique sur le toit d'une tour. */
  private addRoofUnit(batch: Batch, part: BuildingPart): void {
    const top = part.y0 + part.h;
    batch.box(part.x, top, part.z, part.w * 0.4, 0.22, part.d * 0.3, this.palette.sidewalk);
    batch.box(
      part.x + part.w * 0.25,
      top,
      part.z + part.d * 0.25,
      0.04,
      0.7,
      0.04,
      this.palette.lamp,
    );
  }

  /** Marquages au sol des routes qui traversent la tuile : axes, voies et passages piétons. */
  private addMarkings(batch: Batch, tx: number, tz: number): void {
    const x0 = tx * TILE_SIZE;
    const z0 = tz * TILE_SIZE;
    const inTile = (x: number, z: number): boolean =>
      x >= x0 && x < x0 + TILE_SIZE && z >= z0 && z < z0 + TILE_SIZE;
    const hex = this.palette.marking;
    const y = 0.012;
    for (const road of this.city.roads) {
      const r = road.rect;
      if (r.x1 < x0 || r.x0 > x0 + TILE_SIZE || r.z1 < z0 || r.z0 > z0 + TILE_SIZE) continue;
      this.markRoad(batch, road, inTile, y, hex);
    }
  }

  private markRoad(
    batch: Batch,
    road: RoadStrip,
    inTile: (x: number, z: number) => boolean,
    y: number,
    hex: number,
  ): void {
    const r = road.rect;
    const start = road.horizontal ? r.x0 : r.z0;
    const end = road.horizontal ? r.x1 : r.z1;
    const mid = road.horizontal ? (r.z0 + r.z1) / 2 : (r.x0 + r.x1) / 2;
    const width = road.horizontal ? r.z1 - r.z0 : r.x1 - r.x0;
    /** Rectangle défini le long de la route (a0..a1) et en travers (c0..c1). */
    const mark = (a0: number, a1: number, c0: number, c1: number, color = hex): void => {
      const ca = (a0 + a1) / 2;
      const cc = (c0 + c1) / 2;
      if (road.horizontal) {
        if (inTile(ca, cc)) batch.floor(a0, c0, a1, c1, y, color);
      } else if (inTile(cc, ca)) batch.floor(c0, a0, c1, a1, y, color);
    };
    const nearCrossing = (a: number): boolean =>
      a - start < 0.9 || end - a < 0.9 || road.crossings.some((c) => Math.abs(c - a) < 1.3);

    if (road.kind === 'avenue') {
      // Double ligne jaune continue au centre, interrompue aux carrefours.
      for (let a = start; a < end; a += 2) {
        const a1 = Math.min(end, a + 2);
        if (nearCrossing(a + 1)) continue;
        mark(a, a1, mid - 0.075, mid - 0.04, this.palette.centerLine);
        mark(a, a1, mid + 0.04, mid + 0.075, this.palette.centerLine);
      }
      for (const lane of [-0.5, 0.5]) {
        for (let a = start + 0.4; a < end - 0.6; a += 1.1) {
          mark(a, a + 0.55, mid + lane - 0.02, mid + lane + 0.02);
        }
      }
      return;
    }

    for (let a = start + 0.3; a < end - 0.5; a += 0.9) {
      if (!nearCrossing(a + 0.22)) mark(a, a + 0.45, mid - 0.02, mid + 0.02);
    }
    // Passage piéton à larges bandes, avec sa ligne d'arrêt.
    const crosswalk = (a: number, towardCrossing: number): void => {
      const usable = width - 0.1;
      const stripes = Math.max(4, Math.floor(usable / 0.17));
      for (let i = 0; i < stripes; i++) {
        const c = mid - usable / 2 + ((i + 0.5) * usable) / stripes;
        mark(a - 0.26, a + 0.26, c - 0.05, c + 0.05);
      }
      const stop = a - towardCrossing * 0.36;
      mark(stop - 0.03, stop + 0.03, mid - usable / 2, mid + usable / 2);
    };
    crosswalk(start + 0.4, -1);
    crosswalk(end - 0.4, 1);
    for (const c of road.crossings) {
      crosswalk(c - 0.95, 1);
      crosswalk(c + 0.95, -1);
    }
  }
}
