import en from './en.json';
import fr from './fr.json';

export type Lang = 'fr' | 'en';
export type MessageKey = keyof typeof fr;

export const LANGS: readonly Lang[] = ['fr', 'en'];
export const dictionaries: Record<Lang, Record<MessageKey, string>> = { fr, en };

const LOCALES: Record<Lang, string> = { fr: 'fr-FR', en: 'en-GB' };

let current: Lang = 'fr';
const listeners = new Set<(lang: Lang) => void>();

export function isLang(value: unknown): value is Lang {
  return value === 'fr' || value === 'en';
}

/** Choisit la langue de départ : choix enregistré, sinon langue de l'appareil, sinon français. */
export function detectLang(stored: string | null, deviceLanguages: readonly string[]): Lang {
  if (isLang(stored)) return stored;
  for (const tag of deviceLanguages) {
    const base = tag.toLowerCase().split('-')[0];
    if (isLang(base)) return base;
  }
  return 'fr';
}

export function getLang(): Lang {
  return current;
}

export function setLang(lang: Lang): void {
  if (lang === current) return;
  current = lang;
  listeners.forEach((fn) => fn(lang));
}

export function onLangChange(fn: (lang: Lang) => void): () => void {
  listeners.add(fn);
  return () => listeners.delete(fn);
}

/** Texte traduit. Les paramètres remplacent les {noms} du message. */
export function t(key: MessageKey, params: Record<string, string | number> = {}, lang = current) {
  const template = dictionaries[lang][key];
  return template.replace(/\{(\w+)\}/g, (match, name: string) =>
    name in params ? String(params[name]) : match,
  );
}

/** Nombre entier au format de la langue : 50 000 en français, 50,000 en anglais. */
export function formatNumber(value: number, lang = current): string {
  return new Intl.NumberFormat(LOCALES[lang], { maximumFractionDigits: 0 })
    .format(Math.round(value))
    .replace(/[\u202f\u00a0]/g, ' ');
}

export function formatDucats(value: number, lang = current): string {
  return t('unit.ducats', { amount: formatNumber(value, lang) }, lang);
}

export function formatPerDay(value: number, lang = current): string {
  return t('unit.perDay', { amount: formatNumber(value, lang) }, lang);
}

/** Montant abrégé pour les étiquettes de carte : 1,7 M en français, 1.7M en anglais. */
export function formatCompact(value: number, lang = current): string {
  if (value >= 1_000_000) {
    const amount = new Intl.NumberFormat(LOCALES[lang], {
      minimumFractionDigits: 1,
      maximumFractionDigits: 1,
    }).format(value / 1_000_000);
    return t('unit.million', { amount }, lang);
  }
  return t('unit.thousand', { amount: formatNumber(value / 1000, lang) }, lang);
}

/** Pourcentage au format de la langue : 2,5 % en français, 2.5% en anglais. */
export function formatPercent(ratio: number, digits = 0, lang = current): string {
  const text = new Intl.NumberFormat(LOCALES[lang], {
    minimumFractionDigits: digits,
    maximumFractionDigits: digits,
  }).format(ratio * 100);
  return lang === 'fr' ? `${text} %` : `${text}%`;
}
