import { districtLords, type Lord } from './quests';
import type { City } from '../city/model';
import { facts, worth } from './game';
import type { GameState } from './types';

/**
 * Classement des fortunes et amis (retour du propriétaire). En ligne, le serveur fournit le
 * classement de la ville et la fiche des amis ; hors ligne, le joueur se mesure aux concurrents.
 * Un code ami fait 8 caractères : le début de l'empreinte du joueur, sans rien révéler d'autre.
 */
export const FRIEND_CODE = /^[0-9a-f]{8}$/;
export const MAX_FRIENDS = 20;

export interface RankEntry {
  name: string;
  netWorth: number;
  /** Code ami (en ligne seulement). */
  code?: string;
  me?: boolean;
  /** Condamnations au casier. */
  convictions?: number;
}

export interface FriendView {
  code: string;
  /** null : aucun joueur avec ce code dans la ville. */
  name: string | null;
  netWorth: number;
  /** Biens possédés (identifiants), pour les montrer sur la carte. */
  properties: number[];
}

export interface Social {
  online: boolean;
  top: RankEntry[];
  /** Rang du joueur (1 = le plus riche), ou null s'il n'est pas encore classé. */
  rank: number | null;
  total: number;
  /** Code ami du joueur (en ligne seulement). */
  code: string | null;
  friends: FriendView[];
  /** Seigneurs des quartiers : le plus gros propriétaire de chaque quartier. */
  lords?: Lord[];
}

export function friendsOf(state: GameState): string[] {
  return state.friends ?? [];
}

export function addFriend(state: GameState, code: string): GameState {
  const clean = code
    .trim()
    .toLowerCase()
    .replace(/[^0-9a-f]/g, '');
  if (!FRIEND_CODE.test(clean)) throw new Error('Code ami invalide');
  const friends = friendsOf(state);
  if (friends.includes(clean)) return state;
  if (friends.length >= MAX_FRIENDS) throw new Error('Trop d’amis');
  return { ...state, friends: [...friends, clean] };
}

export function removeFriend(state: GameState, code: string): GameState {
  return { ...state, friends: friendsOf(state).filter((c) => c !== code) };
}

/** Hors ligne : classement face aux concurrents de la ville (valeur de leurs biens). */
export function localSocial(state: GameState, city: City, playerName: string): Social {
  const entries: RankEntry[] = state.rivals.map((rival) => ({
    name: rival.name,
    netWorth: rival.buildings.reduce((sum, id) => {
      const building = city.buildings[id];
      return building ? sum + facts(state, building).fairValue : sum;
    }, 0),
  }));
  entries.push({
    name: playerName,
    netWorth: worth(state, city),
    me: true,
    convictions: state.counters?.trial ?? 0,
  });
  entries.sort((a, b) => b.netWorth - a.netWorth);
  return {
    online: false,
    top: entries.slice(0, 20),
    rank: entries.findIndex((e) => e.me) + 1,
    total: entries.length,
    code: null,
    friends: [],
    lords: districtLords(
      [
        ...state.rivals.map((r) => ({ name: r.name, buildings: r.buildings })),
        {
          name: playerName,
          buildings: state.player.properties.map((p) => Number(p.id)),
          me: true,
        },
      ],
      city,
    ),
  };
}
