import * as THREE from 'three';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
import type { RoadStrip } from '../model';
import type { CityPalette } from './palette';

/**
 * Voitures (retour du propriétaire : « immobiles et moches »). Un modèle léger mais profilé
 * (capot, pare-brise incliné, coffre, vitres, roues rondes, phares), et une circulation : des
 * voitures qui roulent dans leur voie, autour de l'endroit regardé.
 */

function colored(geometry: THREE.BufferGeometry, hex: number): THREE.BufferGeometry {
  const g = geometry.index ? geometry.toNonIndexed() : geometry;
  const c = new THREE.Color(hex);
  const colors = new Float32Array(g.getAttribute('position').count * 3);
  for (let i = 0; i < colors.length; i += 3) colors.set([c.r, c.g, c.b], i);
  g.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  g.deleteAttribute('uv');
  return g;
}

function profile(points: [number, number][], depth: number, hex: number): THREE.BufferGeometry {
  const shape = new THREE.Shape(points.map(([x, y]) => new THREE.Vector2(x, y)));
  const g = new THREE.ExtrudeGeometry(shape, { depth, bevelEnabled: false, curveSegments: 1 });
  g.translate(0, 0, -depth / 2);
  return colored(g, hex);
}

/**
 * Berline vue de profil, le long de l'axe x (avant vers +x), posée sur y = 0. Les parties
 * blanches prennent la couleur de chaque voiture ; vitres, roues et feux gardent la leur.
 */
export function carGeometry(palette: CityPalette): THREE.BufferGeometry {
  const glass = palette.style === 'toon' ? 0x9fd3f2 : 0x1e2a38;
  const body = profile(
    [
      [-0.21, 0.03],
      [0.21, 0.03],
      [0.215, 0.07],
      [0.17, 0.088],
      [0.075, 0.095],
      [0.025, 0.152],
      [-0.1, 0.154],
      [-0.16, 0.1],
      [-0.212, 0.09],
    ],
    0.17,
    0xffffff,
  );
  const cabin = profile(
    [
      [0.066, 0.1],
      [0.024, 0.145],
      [-0.096, 0.147],
      [-0.148, 0.103],
    ],
    0.176,
    glass,
  );
  const wheels = [-0.13, 0.13].flatMap((x) =>
    [-0.075, 0.075].map((z) => {
      const w = new THREE.CylinderGeometry(0.038, 0.038, 0.032, 7);
      w.rotateX(Math.PI / 2);
      w.translate(x, 0.038, z);
      return colored(w, 0x16181c);
    }),
  );
  const lamp = (x: number, z: number, hex: number): THREE.BufferGeometry => {
    const g = new THREE.BoxGeometry(0.008, 0.016, 0.035);
    g.translate(x, 0.07, z);
    return colored(g, hex);
  };
  const lights = [
    lamp(0.216, 0.055, 0xfff4cc),
    lamp(0.216, -0.055, 0xfff4cc),
    lamp(-0.214, 0.055, 0xd8262f),
    lamp(-0.214, -0.055, 0xd8262f),
  ];
  return mergeGeometries([body, cabin, ...wheels, ...lights])!;
}

interface Mover {
  strip: number;
  /** Position le long de la voie, de 0 à la longueur de la route. */
  t: number;
  /** +1 ou −1 : sens de circulation. */
  dir: number;
  speed: number;
  tint: number;
}

const COUNT = 70;

/** Circulation autour du point regardé : les voitures trop loin renaissent sur une route proche. */
export class Traffic {
  readonly mesh: THREE.InstancedMesh;
  private readonly movers: Mover[] = [];
  private readonly matrix = new THREE.Matrix4();
  private readonly rotation = new THREE.Matrix4();
  private seed = 1;

  constructor(
    private readonly strips: readonly RoadStrip[],
    geometry: THREE.BufferGeometry,
    material: THREE.Material,
    private readonly palette: CityPalette,
  ) {
    this.mesh = new THREE.InstancedMesh(geometry, material, COUNT);
    this.mesh.frustumCulled = false;
    this.mesh.count = 0;
  }

  private random(): number {
    this.seed = (this.seed * 16807) % 2147483647;
    return this.seed / 2147483647;
  }

  private length(strip: RoadStrip): number {
    const r = strip.rect;
    return strip.horizontal ? r.x1 - r.x0 : r.z1 - r.z0;
  }

  /** Point d'une voiture sur sa route : centre de sa voie, à droite dans son sens. */
  private place(m: Mover): { x: number; z: number } {
    const strip = this.strips[m.strip]!;
    const r = strip.rect;
    const lane =
      (strip.horizontal ? r.z1 - r.z0 : r.x1 - r.x0) * (strip.kind === 'avenue' ? 0.3 : 0.22);
    if (strip.horizontal) return { x: r.x0 + m.t, z: (r.z0 + r.z1) / 2 + lane * m.dir };
    return { x: (r.x0 + r.x1) / 2 - lane * m.dir, z: r.z0 + m.t };
  }

  private spawn(m: Mover, cx: number, cz: number, radius: number): boolean {
    for (let tries = 0; tries < 24; tries++) {
      const index = Math.floor(this.random() * this.strips.length);
      const strip = this.strips[index]!;
      const r = strip.rect;
      const nx = Math.max(r.x0, Math.min(cx, r.x1));
      const nz = Math.max(r.z0, Math.min(cz, r.z1));
      if (Math.hypot(nx - cx, nz - cz) > radius * 0.8) continue;
      m.strip = index;
      m.dir = this.random() < 0.5 ? 1 : -1;
      // Au plus près du centre, pour qu'elle apparaisse dans le champ.
      const along = strip.horizontal ? cx - r.x0 : cz - r.z0;
      const len = this.length(strip);
      m.t = Math.max(0, Math.min(len, along + (this.random() - 0.5) * radius * 1.4));
      m.speed = (strip.kind === 'avenue' ? 1.6 : 1.1) * (0.75 + this.random() * 0.5);
      m.tint = Math.floor(this.random() * 8);
      return true;
    }
    return false;
  }

  /** Avance la circulation ; alpha suit le fondu des détails de rue. */
  update(dt: number, cx: number, cz: number, radius: number, visible: boolean): void {
    this.mesh.visible = visible && this.strips.length > 0;
    if (!this.mesh.visible) return;
    const color = new THREE.Color();
    let n = 0;
    while (this.movers.length < COUNT) {
      const m: Mover = { strip: 0, t: 0, dir: 1, speed: 1, tint: 0 };
      if (!this.spawn(m, cx, cz, radius)) break;
      this.movers.push(m);
    }
    for (const m of this.movers) {
      const strip = this.strips[m.strip]!;
      m.t += m.speed * m.dir * dt;
      let p = this.place(m);
      const far = Math.hypot(p.x - cx, p.z - cz) > radius;
      if (far || m.t < 0 || m.t > this.length(strip)) {
        if (!this.spawn(m, cx, cz, radius)) continue;
        p = this.place(m);
      }
      const s = this.strips[m.strip]!;
      const angle = s.horizontal
        ? m.dir > 0
          ? 0
          : Math.PI
        : m.dir > 0
          ? -Math.PI / 2
          : Math.PI / 2;
      this.matrix.copy(this.rotation.makeRotationY(angle));
      this.matrix.setPosition(p.x, 0.012, p.z);
      this.mesh.setMatrixAt(n, this.matrix);
      this.mesh.setColorAt(n, color.setHex(this.palette.cars[m.tint % this.palette.cars.length]!));
      n++;
    }
    this.mesh.count = n;
    this.mesh.instanceMatrix.needsUpdate = true;
    if (this.mesh.instanceColor) this.mesh.instanceColor.needsUpdate = true;
  }

  dispose(): void {
    this.mesh.geometry.dispose();
    this.mesh.dispose();
  }
}
