import type { Bracket } from './rules';

/** Impôt par tranches : chaque part du montant est taxée au taux de sa tranche. */
export function bracketTax(amount: number, brackets: readonly Bracket[]): number {
  let tax = 0;
  let floor = 0;
  for (const bracket of brackets) {
    if (amount > floor) tax += (Math.min(amount, bracket.upTo) - floor) * bracket.rate;
    floor = bracket.upTo;
  }
  return tax;
}

/** Taux de la tranche dans laquelle tombe le montant : ce que coûte un ducat de plus. */
export function marginalRate(amount: number, brackets: readonly Bracket[]): number {
  for (const bracket of brackets) {
    if (amount < bracket.upTo) return bracket.rate;
  }
  return brackets[brackets.length - 1]?.rate ?? 0;
}
