import {
  AVENUES,
  CITY_BOUNDS,
  COAST_Z,
  DISTRICTS,
  RIVER_HALF_WIDTH,
  RIVER_PATH,
  STREET_WIDTH,
  TYPES,
  type DistrictDef,
  type TypeChoice,
} from '../data/layout';
import type {
  Block,
  Building,
  BuildingPart,
  BuildingStatus,
  Car,
  City,
  DistrictId,
  Facing,
  Monument,
  MonumentKind,
  Plot,
  Prop,
  Rect,
  RoadStrip,
  Tree,
  LocationPerk,
} from '../model';
import { between, createRng, type Rng } from './rng';
import { METRO_STATIONS } from '../data/metro';

/**
 * Emplacement (document de conception) : vue mer +30 %, métro +15 %, rue bruyante −15 %, près de
 * l'usine −20 %. Distances en unités de 10 m.
 */
export const LOCATION = {
  sea: { factor: 1.3, within: 4 },
  metro: { factor: 1.15, within: 4 },
  noisy: { factor: 0.85, within: 0.8 },
  factory: { factor: 0.8, within: 8 },
} as const;

const DOCKS = DISTRICTS.find((d) => d.id === 'docks')!.rect;

const rectDistance = (x: number, z: number, r: Rect): number =>
  Math.hypot(Math.max(r.x0 - x, 0, x - r.x1), Math.max(r.z0 - z, 0, z - r.z1));

/** Atouts et défauts d'emplacement d'un bâtiment, et le coefficient qui en découle. */
export function locationOf(
  x: number,
  z: number,
  w: number,
  d: number,
  district: DistrictId,
): { perks: LocationPerk[]; factor: number } {
  const perks: LocationPerk[] = [];
  const b = CITY_BOUNDS;
  const toSea = Math.min(x - b.x0, b.x1 - x, z - b.z0, b.z1 - z, COAST_Z - z);
  if (toSea - d / 2 < LOCATION.sea.within) perks.push('sea');
  if (METRO_STATIONS.some((s) => Math.hypot(s.x - x, s.z - z) < LOCATION.metro.within))
    perks.push('metro');
  const half = { x0: x - w / 2, z0: z - d / 2, x1: x + w / 2, z1: z + d / 2 };
  const near = (r: Rect, m: number) =>
    half.x0 < r.x1 + m && half.x1 > r.x0 - m && half.z0 < r.z1 + m && half.z1 > r.z0 - m;
  if (AVENUES.some((a) => near(a.rect, LOCATION.noisy.within))) perks.push('noisy');
  if (district !== 'docks' && rectDistance(x, z, DOCKS) < LOCATION.factory.within)
    perks.push('factory');
  const factor = perks.reduce((f, p) => f * LOCATION[p].factor, 1);
  return { perks, factor };
}

export const DEFAULT_SEED = 20261111;

/** Distance d'un point à la ligne centrale de la rivière. */
export function distanceToRiver(x: number, z: number, river: readonly Prop[] = RIVER_PATH): number {
  let best = Infinity;
  for (let i = 0; i + 1 < river.length; i++) {
    const a = river[i]!;
    const b = river[i + 1]!;
    const dx = b.x - a.x;
    const dz = b.z - a.z;
    const len2 = dx * dx + dz * dz;
    const t = len2 === 0 ? 0 : Math.max(0, Math.min(1, ((x - a.x) * dx + (z - a.z) * dz) / len2));
    best = Math.min(best, Math.hypot(x - (a.x + t * dx), z - (a.z + t * dz)));
  }
  return best;
}

/**
 * Découpe une longueur en bandes séparées par des rues. Les bandes n'ont pas toutes la même
 * largeur : une vraie ville n'est pas un quadrillage parfait.
 */
function splitSpan(
  start: number,
  end: number,
  target: number,
  rng: Rng,
  jitter = 0.28,
): { from: number; to: number }[] {
  const length = end - start;
  const count = Math.max(1, Math.round((length + STREET_WIDTH) / (target + STREET_WIDTH)));
  const weights = Array.from({ length: count }, () => between(rng, 1 - jitter, 1 + jitter));
  const total = weights.reduce((sum, w) => sum + w, 0);
  const usable = length - (count - 1) * STREET_WIDTH;
  const spans: { from: number; to: number }[] = [];
  let from = start;
  for (const w of weights) {
    const size = (usable * w) / total;
    spans.push({ from, to: from + size });
    from += size + STREET_WIDTH;
  }
  return spans;
}

/** Parcelles le long d'une rue, de largeurs inégales (entre 70 % et 135 % de la largeur visée). */
function splitLots(x0: number, x1: number, lot: number, rng: Rng): [number, number][] {
  const count = Math.max(1, Math.floor((x1 - x0) / lot));
  const weights = Array.from({ length: count }, () => between(rng, 0.7, 1.35));
  const total = weights.reduce((sum, w) => sum + w, 0);
  const lots: [number, number][] = [];
  let from = x0;
  for (const w of weights) {
    const to = from + ((x1 - x0) * w) / total;
    lots.push([from, to]);
    from = to;
  }
  return lots;
}

function pickType(rng: Rng, choices: readonly TypeChoice[]): TypeChoice {
  const total = choices.reduce((sum, c) => sum + c.weight, 0);
  let roll = rng() * total;
  for (const choice of choices) {
    roll -= choice.weight;
    if (roll <= 0) return choice;
  }
  return choices[choices.length - 1]!;
}

function pickStatus(rng: Rng, protectedDistrict: boolean): BuildingStatus {
  const roll = rng();
  if (!protectedDistrict && roll < 0.01) return 'incident';
  if (roll < 0.05) return 'sale';
  if (roll < 0.075) return 'mine';
  return 'none';
}

function makeBuilding(
  rng: Rng,
  def: DistrictDef,
  lot: Rect,
  facing: Facing,
  id: number,
  serial: number,
): Building {
  const choice = pickType(rng, def.types);
  const spec = TYPES[choice.type];
  const lotW = lot.x1 - lot.x0;
  const lotD = lot.z1 - lot.z0;
  let w = lotW * between(rng, spec.fillW[0], spec.fillW[1]);
  let d = lotD * between(rng, spec.fillD[0], spec.fillD[1]);
  if (choice.type === 'tour') w = d = Math.min(w, d);
  const setback = Math.min(spec.setback, Math.max(0, lotD - d));
  const x = (lot.x0 + lot.x1) / 2;
  const z = facing === 'north' ? lot.z0 + setback + d / 2 : lot.z1 - setback - d / 2;
  const [minFloors, maxFloors] = choice.floors;
  const floors = Math.round(minFloors + Math.pow(rng(), 1.6) * (maxFloors - minFloors));
  const h = floors * spec.floorH;

  const parts: BuildingPart[] = [];
  if (choice.type === 'tour' && floors >= 16) {
    const lower = Math.round(floors * between(rng, 0.55, 0.7)) * spec.floorH;
    parts.push({ x, z, w, d, y0: 0, h: lower });
    parts.push({ x, z, w: w * 0.72, d: d * 0.72, y0: lower, h: h - lower });
  } else {
    parts.push({ x, z, w, d, y0: 0, h });
  }

  // Taille : ±15 % au plus selon les étages et l'emprise, pour que deux biens du même type
  // dans le même quartier aient des prix proches.
  const floorShare = maxFloors > minFloors ? (floors - minFloors) / (maxFloors - minFloors) : 0.5;
  const fillShare =
    (w / lotW - spec.fillW[0]) / Math.max(0.01, spec.fillW[1] - spec.fillW[0]) / 2 +
    (d / lotD - spec.fillD[0]) / Math.max(0.01, spec.fillD[1] - spec.fillD[0]) / 2;
  const size = 0.85 + 0.2 * floorShare + 0.1 * Math.min(1, Math.max(0, fillShare));
  const location = locationOf(x, z, w, d, def.id);
  const price = Math.round((spec.basePrice * def.priceMult * size * location.factor) / 1000) * 1000;
  return {
    id,
    district: def.id,
    type: choice.type,
    ref: `${def.code} ${100 + serial}`,
    x,
    z,
    w,
    d,
    h,
    floors,
    facing,
    // La plupart des immeubles ont un toit plat, encombré ; quelques-uns gardent leur toit à la Mansart.
    roof: choice.type === 'immeuble' && rng() < 0.7 ? 'flat' : spec.roof,
    parts,
    status: pickStatus(rng, def.risk === 0),
    shop: choice.type === 'immeuble' && rng() < 0.55,
    price,
    rent: Math.round((price * def.rentRate) / 10) * 10,
    perks: location.perks,
  };
}

/** Arbres et lampadaires le long d'un îlot, voitures garées côté chaussée. */
function furnishBlock(
  rng: Rng,
  rect: Rect,
  streetTrees: boolean,
  trees: Tree[],
  lamps: Prop[],
  cars: Car[],
): void {
  const inset = 0.16;
  for (const z of [rect.z0 + inset, rect.z1 - inset]) {
    for (let x = rect.x0 + 1; x < rect.x1 - 0.8; x += 3.2) {
      if (streetTrees) trees.push({ x, z, size: between(rng, 0.8, 1.15) });
      lamps.push({ x: x + 1.6, z });
    }
  }
  // Voitures garées le long des quatre côtés de l'îlot.
  for (const z of [rect.z0 - 0.2, rect.z1 + 0.2]) {
    for (let x = rect.x0 + 0.7; x < rect.x1 - 0.6; x += 0.62) {
      if (rng() < 0.38) cars.push({ x, z, alongX: true, tint: Math.floor(rng() * 8) });
    }
  }
  for (const x of [rect.x0 - 0.2, rect.x1 + 0.2]) {
    for (let z = rect.z0 + 0.7; z < rect.z1 - 0.6; z += 0.62) {
      if (rng() < 0.3) cars.push({ x, z, alongX: false, tint: Math.floor(rng() * 8) });
    }
  }
}

/** Génère toute la ville à partir d'une graine. Fonction pure : même graine, même ville. */
export function generateCity(seed: number = DEFAULT_SEED): City {
  const rng = createRng(seed);
  const roads: RoadStrip[] = AVENUES.map((a) => ({
    rect: a.rect,
    horizontal: a.horizontal,
    kind: 'avenue',
    crossings: [],
  }));
  const blocks: Block[] = [];
  const plots: Plot[] = [];
  const buildings: Building[] = [];
  const trees: Tree[] = [];
  const lamps: Prop[] = [];
  const cars: Car[] = [];

  for (const def of DISTRICTS) {
    const { rect } = def;
    const columns = splitSpan(rect.x0, rect.x1, def.blockW, rng);
    const rows = splitSpan(rect.z0, rect.z1, def.blockD, rng);
    const columnStreets = columns.slice(0, -1).map((c) => c.to + STREET_WIDTH / 2);
    const rowStreets = rows.slice(0, -1).map((r) => r.to + STREET_WIDTH / 2);
    for (const x of columnStreets) {
      roads.push({
        rect: { x0: x - STREET_WIDTH / 2, z0: rect.z0, x1: x + STREET_WIDTH / 2, z1: rect.z1 },
        horizontal: false,
        kind: 'street',
        crossings: rowStreets,
      });
    }
    for (const z of rowStreets) {
      roads.push({
        rect: { x0: rect.x0, z0: z - STREET_WIDTH / 2, x1: rect.x1, z1: z + STREET_WIDTH / 2 },
        horizontal: true,
        kind: 'street',
        crossings: columnStreets,
      });
    }

    let serial = 0;
    for (const column of columns) {
      for (const row of rows) {
        const block: Rect = { x0: column.from, z0: row.from, x1: column.to, z1: row.to };
        const cx = (block.x0 + block.x1) / 2;
        const cz = (block.z0 + block.z1) / 2;
        const reach = Math.hypot(block.x1 - block.x0, block.z1 - block.z0) / 2;
        if (distanceToRiver(cx, cz) < RIVER_HALF_WIDTH && reach < RIVER_HALF_WIDTH * 1.5) continue;

        const lotCount = Math.max(1, Math.floor((block.x1 - block.x0) / def.lot));
        const lotW = (block.x1 - block.x0) / lotCount;
        // Les deux rangées d'un îlot ne sont pas forcément de même profondeur.
        const midZ = block.z0 + (block.z1 - block.z0) * between(rng, 0.44, 0.56);

        if (def.types.length === 0) {
          blocks.push({ district: def.id, rect: block, kind: 'plots' });
          for (let i = 0; i < lotCount; i++) {
            for (const [z0, z1] of [
              [block.z0, midZ],
              [midZ, block.z1],
            ] as const) {
              serial++;
              plots.push({
                district: def.id,
                rect: { x0: block.x0 + i * lotW, z0, x1: block.x0 + (i + 1) * lotW, z1 },
                ref: `${def.code} ${100 + serial}`,
              });
            }
          }
          continue;
        }

        if (rng() < def.park) {
          blocks.push({ district: def.id, rect: block, kind: 'park' });
          for (let x = block.x0 + 0.9; x < block.x1 - 0.5; x += 1.5) {
            for (let z = block.z0 + 0.9; z < block.z1 - 0.5; z += 1.5) {
              if (rng() < 0.7 && distanceToRiver(x, z) > RIVER_HALF_WIDTH + 0.4) {
                trees.push({
                  x: x + between(rng, -0.4, 0.4),
                  z: z + between(rng, -0.4, 0.4),
                  size: between(rng, 0.9, 1.5),
                });
              }
            }
          }
          continue;
        }

        blocks.push({ district: def.id, rect: block, kind: 'built' });
        furnishBlock(rng, block, def.streetTrees, trees, lamps, cars);
        const firstInBlock = buildings.length;
        for (const facing of ['north', 'south'] as const) {
          for (const [lx0, lx1] of splitLots(block.x0, block.x1, def.lot, rng)) {
            const lot: Rect = {
              x0: lx0,
              x1: lx1,
              z0: facing === 'north' ? block.z0 : midZ,
              z1: facing === 'north' ? midZ : block.z1,
            };
            if (rng() > def.density) continue;
            serial++;
            const building = makeBuilding(rng, def, lot, facing, buildings.length, serial);
            const margin = RIVER_HALF_WIDTH + Math.hypot(building.w, building.d) / 2 + 0.3;
            if (distanceToRiver(building.x, building.z) < margin) continue;
            buildings.push(building);
            if (building.type === 'pavillon' || building.type === 'villa') {
              const gardenZ = facing === 'north' ? lot.z1 - 0.5 : lot.z0 + 0.5;
              trees.push({
                x: between(rng, lot.x0 + 0.4, lot.x1 - 0.4),
                z: gardenZ,
                size: between(rng, 0.7, 1.1),
              });
            }
          }
        }
        // Cours intérieures des îlots de centre-ville : quelques arbres là où il reste de la place.
        const inBlock = buildings.slice(firstInBlock);
        const urban = inBlock.some((b) => b.type === 'immeuble' || b.type === 'hotel');
        if (urban) {
          const wanted = 1 + Math.floor(rng() * 3);
          let planted = 0;
          for (let attempt = 0; attempt < wanted * 4 && planted < wanted; attempt++) {
            const x = between(rng, block.x0 + 0.8, block.x1 - 0.8);
            const z = between(rng, block.z0 + 1, block.z1 - 1);
            const free = inBlock.every(
              (b) => Math.abs(b.x - x) > b.w / 2 + 0.5 || Math.abs(b.z - z) > b.d / 2 + 0.5,
            );
            if (!free) continue;
            trees.push({ x, z, size: between(rng, 0.7, 1.1) });
            planted++;
          }
        }
      }
    }
  }

  // Ronds-points : là où une avenue nord-sud croise une avenue est-ouest.
  const roundabouts: Prop[] = [];
  const avenues = roads.filter((r) => r.kind === 'avenue');
  for (const h of avenues.filter((r) => r.horizontal)) {
    for (const v of avenues.filter((r) => !r.horizontal)) {
      const x = (v.rect.x0 + v.rect.x1) / 2;
      const z = (h.rect.z0 + h.rect.z1) / 2;
      const inside =
        x > h.rect.x0 - 0.5 && x < h.rect.x1 + 0.5 && z > v.rect.z0 - 0.5 && z < v.rect.z1 + 0.5;
      if (inside && distanceToRiver(x, z) > RIVER_HALF_WIDTH + 1.5) {
        roundabouts.push({ x, z });
        trees.push({ x, z, size: 0.9 });
      }
    }
  }

  // Front de mer : jardins, puis promenade plantée, puis plage. Les Docks ont un port à la place.
  const docks = DISTRICTS.find((d) => d.id === 'docks')!.rect;
  const coastFrom = docks.x1 + 1;
  const coastTo = CITY_BOUNDS.x1;
  const lowestAvenue = Math.max(
    ...avenues.filter((r) => r.horizontal && r.rect.x1 > coastFrom).map((r) => r.rect.z1),
  );
  const beach: Rect = { x0: coastFrom, z0: COAST_Z - 5, x1: coastTo, z1: COAST_Z };
  const promenade: Rect = { x0: coastFrom, z0: COAST_Z - 6.4, x1: coastTo, z1: COAST_Z - 5 };
  const gardens: Rect[] = [];
  if (promenade.z0 - lowestAvenue > 3) {
    gardens.push({ x0: coastFrom, z0: lowestAvenue + 0.6, x1: coastTo, z1: promenade.z0 - 0.4 });
    for (let x = coastFrom + 2; x < coastTo - 1; x += 2.6) {
      for (let z = lowestAvenue + 2; z < promenade.z0 - 1.2; z += 3.4) {
        if (rng() < 0.45) {
          trees.push({ x: x + between(rng, -0.6, 0.6), z, size: between(rng, 0.9, 1.4) });
        }
      }
    }
  }
  for (let x = coastFrom + 1; x < coastTo - 0.5; x += 3) {
    trees.push({ x, z: promenade.z0 + 0.25, size: between(rng, 0.8, 1) });
    lamps.push({ x: x + 1.5, z: promenade.z1 - 0.2 });
  }
  const quays: Rect[] = [];
  const boats: { x: number; z: number; length: number }[] = [];
  for (let x = docks.x0 + 8; x < docks.x1 - 6; x += between(rng, 18, 26)) {
    const length = between(rng, 10, 18);
    quays.push({ x0: x - 1.6, z0: COAST_Z - 1, x1: x + 1.6, z1: COAST_Z + length });
    for (const side of [-1, 1]) {
      if (rng() < 0.7) {
        boats.push({
          x: x + side * 3,
          z: COAST_Z + between(rng, 3, length - 2),
          length: between(rng, 3, 6),
        });
      }
    }
  }

  // Monuments : chacun sur un square de son quartier (le plus grand, ou le plus près de la mer
  // pour le phare). Choisis après coup : les bâtiments et leurs numéros ne bougent pas.
  const area = (b: Block): number => (b.rect.x1 - b.rect.x0) * (b.rect.z1 - b.rect.z0);
  const pickPark = (district: DistrictId, score: (b: Block) => number): Block | undefined =>
    blocks
      .filter((b) => b.kind === 'park' && b.district === district)
      .sort((a, b) => score(b) - score(a))[0];
  const monuments: Monument[] = [];
  const wanted: [MonumentKind, DistrictId, (b: Block) => number][] = [
    ['cityhall', 'notables', area],
    ['station', 'offshore', area],
    ['lighthouse', 'rentiers', (b) => b.rect.z1],
    ['stadium', 'activites', area],
  ];
  for (const [kind, district, score] of wanted) {
    const park = pickPark(district, score);
    if (park) monuments.push({ kind, district, rect: { ...park.rect } });
  }
  const onMonument = (p: Prop): boolean =>
    monuments.some(
      (m) =>
        p.x > m.rect.x0 - 0.2 &&
        p.x < m.rect.x1 + 0.2 &&
        p.z > m.rect.z0 - 0.2 &&
        p.z < m.rect.z1 + 0.2,
    );

  const clear = <T extends Prop>(items: T[]): T[] =>
    items.filter((p) => distanceToRiver(p.x, p.z) > RIVER_HALF_WIDTH + 0.3 && !onMonument(p));

  return {
    seed,
    bounds: CITY_BOUNDS,
    districts: DISTRICTS.map((d) => ({ id: d.id, rect: d.rect })),
    roads,
    blocks,
    monuments,
    plots,
    buildings,
    trees: clear(trees),
    lamps: clear(lamps),
    cars: clear(cars),
    river: RIVER_PATH.map((p) => ({ ...p })),
    riverHalfWidth: RIVER_HALF_WIDTH,
    coastZ: COAST_Z,
    seafront: { gardens, promenade: [promenade], beach: [beach] },
    quays,
    boats,
    roundabouts,
  };
}
