import { mountShell } from './app/shell';
import { showWelcome } from './app/welcome';
import { authAvailable, signOut } from './game/auth';
import { readSetting } from './app/storage';
import { detectLang, setLang } from './i18n';
import { applyTheme, detectTheme } from './theme/themes';
import './theme/app.css';

const root = document.getElementById('app');
if (!root) throw new Error('Élément #app introuvable');

setLang(detectLang(readSetting('lang'), navigator.languages ?? [navigator.language]));
const theme = detectTheme(
  readSetting('theme'),
  window.matchMedia('(prefers-color-scheme: dark)').matches,
);
applyTheme(theme);

// Compte obligatoire pour le jeu en ligne : la page d'accueil (connexion, paramètres, mentions
// légales) passe d'abord. Les essais hors ligne (?local, ?sim, ?test) entrent directement.
const query = new URLSearchParams(location.search);
const offline = query.has('local') || query.has('sim') || query.has('test');
if (authAvailable() && !offline) {
  void showWelcome(root, {
    theme,
    enter: (chosen) => void mountShell(root, chosen, { skipHome: true }),
  });
} else void mountShell(root, theme);

// Session expirée côté serveur : on revient à l'accueil pour se reconnecter.
window.addEventListener('mb-auth-required', () => {
  void signOut().then(() => location.reload());
});
